/* MARGA animated explainers. The data lives in src/explainers/*.json (one file per group) and is added to this script at build time. Each step moves a message between two actors (f and t are indexes into actors; equal means the actor does something itself). */
window.MARGA_EXPLAINERS = [];

window.MARGA_EXPLAINERS.push.apply(window.MARGA_EXPLAINERS, [{"id":"dns-lookup","module":"networking","lesson":"networking/dns","title":"How a DNS lookup works","summary":"What happens between typing a name and getting an IP address.","actors":["Browser","Resolver","Root server","TLD server","Authoritative server"],"steps":[{"f":0,"t":0,"l":"Check caches","n":"The browser and the operating system look in their own caches first. If the answer is there and has not expired, the lookup ends here."},{"f":0,"t":1,"l":"Where is app.example.com?","n":"The browser asks the recursive resolver, usually run by your network or ISP, to find the answer on its behalf."},{"f":1,"t":2,"l":"Who handles .com?","n":"The resolver has no cached answer, so it asks a root server. Roots do not know the address, but they know who runs each top-level domain."},{"f":2,"t":1,"l":"Ask the .com servers","n":"The root server replies with a referral to the servers for .com."},{"f":1,"t":3,"l":"Who handles example.com?","n":"The resolver asks a .com server about example.com."},{"f":3,"t":1,"l":"Ask example.com name servers","n":"The TLD server replies with the name servers that are responsible for example.com."},{"f":1,"t":4,"l":"What is app.example.com?","n":"The resolver asks the authoritative server, which holds the real records."},{"f":4,"t":1,"l":"A record: 203.0.113.10 (TTL 300)","n":"The authoritative server answers with the IP address and a TTL. The TTL says how many seconds the answer may be cached."},{"f":1,"t":0,"l":"203.0.113.10","n":"The resolver caches the answer for the TTL and returns it. The browser can now open a connection."}]},{"id":"tcp-handshake","module":"networking","lesson":"networking/latency-mtu-and-network-performance","title":"The TCP three-way handshake","summary":"How two machines agree to talk before any data moves.","actors":["Client","Server"],"steps":[{"f":1,"t":1,"l":"Listening on port 443","n":"The server has a program bound to a port and waiting for connections."},{"f":0,"t":1,"l":"SYN, seq=100","n":"The client sends a SYN packet with a starting sequence number. It means: I want to connect, and I will number my bytes from here."},{"f":1,"t":0,"l":"SYN-ACK, seq=300, ack=101","n":"The server agrees. It acknowledges the client number (ack=101) and sends its own starting sequence number."},{"f":0,"t":1,"l":"ACK, ack=301","n":"The client acknowledges the server number. The connection is now established in both directions."},{"f":0,"t":1,"l":"Data: GET / HTTP/1.1","n":"Application data can flow. Every byte is numbered, so lost packets are noticed and sent again."},{"f":1,"t":0,"l":"ACK + response data","n":"The server acknowledges what it got and sends its reply."},{"f":0,"t":1,"l":"FIN","n":"When finished, one side sends FIN to close its direction. The other side acknowledges, then sends its own FIN."}]},{"id":"tls-handshake","module":"networking","lesson":"networking/http-and-tls","title":"The TLS 1.3 handshake","summary":"How a browser checks who it is talking to and sets up encryption.","actors":["Browser","Web server","Certificate authority"],"steps":[{"f":0,"t":1,"l":"ClientHello + key share","n":"The browser lists the cipher suites it supports and sends its half of a key exchange. It also sends the server name it wants (SNI)."},{"f":1,"t":0,"l":"ServerHello + key share","n":"The server picks a cipher suite and sends its half of the key exchange. Both sides can now work out the same secret keys without ever sending them."},{"f":1,"t":0,"l":"Certificate (encrypted)","n":"From here on the handshake is encrypted. The server sends its certificate, which names the site and carries a signature from a certificate authority."},{"f":0,"t":2,"l":"Is this signature valid?","n":"The browser checks the chain up to a certificate authority it already trusts, the dates, and that the name matches. This check uses built-in trust, not a live call; it is shown here to make the idea visible."},{"f":1,"t":0,"l":"CertificateVerify + Finished","n":"The server proves it holds the private key for the certificate by signing the handshake. Finished confirms nothing was changed on the way."},{"f":0,"t":1,"l":"Finished","n":"The browser confirms the handshake too. The connection is encrypted and the server is identified."},{"f":0,"t":1,"l":"Encrypted HTTP request","n":"Application data now travels encrypted with the session keys. A certificate that expires or does not match is why you see browser warnings."}]},{"id":"pod-scheduling","module":"kubernetes","lesson":"kubernetes/scheduling-and-troubleshooting","title":"What happens when you create a pod","summary":"From kubectl apply to a running container.","actors":["kubectl","API server","etcd","Scheduler","Kubelet"],"steps":[{"f":0,"t":1,"l":"kubectl apply -f pod.yaml","n":"kubectl sends the object to the API server. The API server is the only component that talks to the cluster database."},{"f":1,"t":1,"l":"Authenticate, authorise, validate","n":"The API server checks who you are, whether you may create pods, and whether the object is valid. Admission controllers may change or reject it."},{"f":1,"t":2,"l":"Store the pod","n":"The pod is saved in etcd with no node assigned. Its phase is Pending."},{"f":3,"t":1,"l":"Watch: unscheduled pods?","n":"The scheduler watches the API server for pods that have no node."},{"f":3,"t":3,"l":"Filter and score nodes","n":"The scheduler removes nodes that cannot fit the pod (not enough CPU, taints, affinity) and scores the rest."},{"f":3,"t":1,"l":"Bind pod to node-2","n":"The scheduler writes the chosen node name back through the API server."},{"f":4,"t":1,"l":"Watch: pods for my node","n":"The kubelet on node-2 sees a pod assigned to it."},{"f":4,"t":4,"l":"Pull image, start containers","n":"The kubelet asks the container runtime to pull the image and start the containers, then runs the probes."},{"f":4,"t":1,"l":"Status: Running, Ready","n":"The kubelet reports status back. Once the readiness probe passes, Services start sending traffic to the pod."}]},{"id":"rolling-update","module":"kubernetes","lesson":"kubernetes/pods-and-deployments","title":"A rolling update of a Deployment","summary":"How Kubernetes replaces pods without downtime.","actors":["You","Deployment","New ReplicaSet","Old ReplicaSet","Service"],"steps":[{"f":0,"t":1,"l":"Change image to v2","n":"You update the pod template in the Deployment. Any change to the template starts a rollout."},{"f":1,"t":2,"l":"Create ReplicaSet v2 (0 pods)","n":"The Deployment controller creates a new ReplicaSet for the new template and keeps the old one."},{"f":2,"t":2,"l":"Scale up by maxSurge (1 pod)","n":"With maxSurge 25 percent the new ReplicaSet may add extra pods above the desired count."},{"f":4,"t":2,"l":"Send traffic once Ready","n":"The Service only sends traffic to a new pod after its readiness probe passes. A failing probe stops the rollout here, which protects users."},{"f":1,"t":3,"l":"Scale down by maxUnavailable","n":"Once new pods are ready, the old ReplicaSet is scaled down, never below the minimum available count."},{"f":2,"t":3,"l":"Repeat until v2 is complete","n":"Steps of scale up and scale down repeat until every pod runs the new version and the old ReplicaSet has zero pods."},{"f":0,"t":1,"l":"kubectl rollout undo","n":"The old ReplicaSet is kept so a rollback is fast: scale it back up and scale the new one down."}]},{"id":"terraform-workflow","module":"terraform","lesson":"terraform/iac-and-hcl-basics","title":"The Terraform workflow","summary":"Write, plan, apply, and where state fits in.","actors":["You","Terraform","State file","Cloud API"],"steps":[{"f":0,"t":1,"l":"terraform init","n":"Terraform downloads the providers and modules that the code needs and configures the state backend."},{"f":0,"t":1,"l":"terraform plan","n":"You ask what would change. Terraform reads your code to find the desired state."},{"f":1,"t":2,"l":"Read the recorded state","n":"Terraform loads the state file, which records which real resources it already manages. With a remote backend it also takes a lock."},{"f":1,"t":3,"l":"Refresh: what exists now?","n":"Terraform asks the cloud API for the current settings of the resources in the state, so it notices drift."},{"f":1,"t":1,"l":"Compare and build a plan","n":"Desired state is compared with the real state. The plan lists each resource as create, update in place, replace or destroy."},{"f":1,"t":0,"l":"Plan: 2 to add, 1 to change, 0 to destroy","n":"You review the plan. Read the destroy and replace lines most carefully."},{"f":0,"t":1,"l":"terraform apply (approve)","n":"You approve. Terraform runs the plan in dependency order and in parallel where it can."},{"f":1,"t":3,"l":"Create and update resources","n":"Terraform calls the cloud API for each change."},{"f":1,"t":2,"l":"Save the new state","n":"The results are written to the state file and the lock is released. The state now matches reality again."}]},{"id":"cicd-pipeline","module":"cicd","lesson":"cicd/pipeline-fundamentals","title":"A change travelling through a pipeline","summary":"From a code push to production, and where it can stop.","actors":["Developer","Repository","CI runner","Registry","Production"],"steps":[{"f":0,"t":1,"l":"Push a branch, open a review","n":"The change is pushed and reviewed by a colleague. Branch rules can require passing checks before merging."},{"f":1,"t":2,"l":"Trigger the pipeline","n":"The push starts a pipeline on a runner, a clean machine or container that has only what the job needs."},{"f":2,"t":2,"l":"Lint, unit tests, security scan","n":"Fast checks run first so that obvious problems fail early and cheaply. A failure stops the pipeline and tells the author."},{"f":2,"t":2,"l":"Build the artifact","n":"The code is built once into an artifact, such as a container image, tagged with the commit ID."},{"f":2,"t":3,"l":"Push image: app:3f9c2a1","n":"The artifact goes to a registry. The same artifact is promoted through every environment, never rebuilt."},{"f":2,"t":4,"l":"Deploy to staging, run smoke tests","n":"The artifact is deployed to a staging environment and tested end to end."},{"f":2,"t":4,"l":"Canary: 5 percent of traffic","n":"In production a small share of traffic gets the new version while error rate and latency are watched."},{"f":4,"t":2,"l":"Healthy: promote to 100 percent","n":"If the numbers stay good the rollout continues. If not, the pipeline rolls back automatically."}]},{"id":"linux-boot","module":"linux","lesson":"linux/boot-and-kernel","title":"How a Linux server boots","summary":"From power on to a login prompt.","actors":["Firmware","Bootloader","Kernel","systemd","Services"],"steps":[{"f":0,"t":0,"l":"Power-on self test","n":"The firmware (UEFI or BIOS) checks the hardware, finds memory and devices, and decides which disk to boot from."},{"f":0,"t":1,"l":"Start the bootloader","n":"The firmware loads the bootloader, such as GRUB, from the boot disk. The bootloader can show a menu of kernels."},{"f":1,"t":2,"l":"Load kernel and initramfs","n":"The bootloader loads the chosen kernel and a small temporary filesystem called the initramfs into memory and hands control to the kernel."},{"f":2,"t":2,"l":"Detect hardware, mount root","n":"The kernel starts its drivers. The initramfs holds the drivers needed to find and mount the real root filesystem, for example on LVM or an encrypted disk."},{"f":2,"t":3,"l":"Start PID 1","n":"The kernel starts the first process, systemd, with process ID 1. Every other process is a child of it."},{"f":3,"t":3,"l":"Read units, reach the default target","n":"systemd reads its unit files and works out the order in which to start things so that the target, such as multi-user, is reached."},{"f":3,"t":4,"l":"Start services in parallel","n":"Networking, logging, SSH and your applications start, in parallel where dependencies allow. A failed unit can be seen with systemctl --failed."},{"f":4,"t":3,"l":"Login prompt ready","n":"When the target is reached the machine is up. The command systemd-analyze blame shows which units took the longest."}]},{"id":"linux-permissions","module":"linux","lesson":"linux/users-groups-permissions","title":"How Linux decides if you may open a file","summary":"The checks behind \"Permission denied\".","actors":["Process","Kernel","Path","File owner and mode"],"steps":[{"f":0,"t":1,"l":"open(\"/srv/app/data.txt\", read)","n":"A process asks the kernel to open a file. The kernel acts for the process using its user ID and group IDs."},{"f":1,"t":2,"l":"Walk each directory in the path","n":"To reach the file the process needs the execute (search) bit on every directory along the path: /, /srv and /srv/app. A missing x on one directory is a common cause of denied access."},{"f":2,"t":1,"l":"Directories allow passage","n":"If any directory refuses, the open fails here with Permission denied, before the file itself is even looked at."},{"f":1,"t":3,"l":"Read owner, group and mode","n":"The kernel reads the file owner, group and mode bits, for example 640: owner read and write, group read, others nothing."},{"f":1,"t":1,"l":"Pick one class only","n":"If the user is the owner, only the owner bits apply. Otherwise if the group matches, only the group bits apply. Otherwise the others bits apply. The first match decides."},{"f":1,"t":1,"l":"Other layers: ACLs, SELinux, mounts","n":"Access control lists, SELinux or AppArmor, and read-only mounts can still refuse a request that the mode bits allow."},{"f":1,"t":0,"l":"File descriptor, or EACCES","n":"If every check passes, the process gets a file descriptor. Otherwise it gets the error that programs show as Permission denied. Use namei -l on the path to see each step."}]},{"id":"linux-process","module":"linux","lesson":"linux/processes-and-services","title":"A process starts, runs and is stopped","summary":"fork, exec, signals and why SIGTERM comes before SIGKILL.","actors":["Shell","Kernel","New process","Operator"],"steps":[{"f":0,"t":1,"l":"fork()","n":"The shell asks the kernel to copy itself. The copy, the child, has a new process ID and starts with the same memory contents."},{"f":1,"t":2,"l":"Child process created","n":"The kernel creates the child. The parent shell normally waits for it to finish unless the command ends with an ampersand."},{"f":2,"t":1,"l":"exec(\"/usr/bin/myapp\")","n":"The child asks the kernel to replace its memory with the program myapp. The process ID stays the same but the program is new."},{"f":2,"t":2,"l":"Running: reads, writes, waits","n":"The program runs, opens files, and may spend most of its time waiting for input or the disk. The kernel shares the CPU between processes."},{"f":3,"t":2,"l":"kill PID (SIGTERM)","n":"An operator sends SIGTERM, a polite request to stop. A well-written program catches it, finishes current work, closes files and exits."},{"f":2,"t":2,"l":"Clean up and exit(0)","n":"The program shuts down gracefully. If it ignores SIGTERM it keeps running."},{"f":3,"t":2,"l":"kill -9 PID (SIGKILL)","n":"SIGKILL cannot be caught or ignored: the kernel removes the process at once. Nothing is cleaned up, so use it only after SIGTERM has had time to work."},{"f":1,"t":0,"l":"Exit status to the parent","n":"The kernel tells the parent the exit status. The shell stores it in $?. If a parent never collects it, the child stays as a zombie entry."}]},{"id":"bash-expansion","module":"bash","lesson":"bash/arrays-and-parameter-expansion","title":"How the shell reads a command line","summary":"Why quoting matters: expansion, splitting and globbing.","actors":["You type","Shell","Program"],"steps":[{"f":0,"t":1,"l":"rm $dir/*.log","n":"You type a command containing a variable and a wildcard. The shell, not the program, processes these first."},{"f":1,"t":1,"l":"Expand variables","n":"The shell replaces $dir with its value, for example /var/app logs. If the value contains a space it becomes part of the text."},{"f":1,"t":1,"l":"Split into words","n":"Without quotes the shell splits the result on spaces, so one variable can become two arguments. This is how a path with a space deletes the wrong thing."},{"f":1,"t":1,"l":"Expand wildcards (globbing)","n":"Each word with * or ? is replaced with the matching file names. If nothing matches, bash passes the pattern through unchanged."},{"f":1,"t":2,"l":"Run rm with the final arguments","n":"Only now does the program start. It never sees the variable or the wildcard, only the final list of words."},{"f":1,"t":1,"l":"Safer: rm -- \"$dir\"/*.log","n":"Quote variables so they stay one word, and use -- so a name starting with a dash is not read as an option."},{"f":1,"t":0,"l":"Check with echo or set -x","n":"Put echo in front of a dangerous command, or run with set -x, to see exactly what the shell is about to run."}]},{"id":"bash-pipeline","module":"bash","lesson":"bash/text-processing","title":"A pipeline and its exit codes","summary":"What set -euo pipefail changes.","actors":["Script","curl","jq","wc"],"steps":[{"f":0,"t":0,"l":"set -euo pipefail","n":"The script turns on three safety options: stop on a failing command (-e), treat unset variables as errors (-u), and make a pipeline fail if any part fails (pipefail)."},{"f":0,"t":1,"l":"curl -s $URL | jq .items[] | wc -l","n":"The shell starts all three commands at once and connects the output of each to the input of the next with pipes."},{"f":1,"t":2,"l":"curl sends the response body","n":"Data flows from curl to jq as it arrives. Nothing is stored in a file in between."},{"f":1,"t":1,"l":"curl fails: exit code 22","n":"Suppose the server returns an error and curl exits non-zero. By default a pipeline reports only the exit code of its last command."},{"f":2,"t":3,"l":"jq passes on empty output","n":"jq gets nothing, prints nothing, and exits 0. wc then counts zero lines and exits 0 too."},{"f":3,"t":0,"l":"Without pipefail: status 0","n":"The pipeline looks successful because wc succeeded, and the script carries on with a wrong count of zero."},{"f":3,"t":0,"l":"With pipefail: status 22","n":"The pipeline now returns the failure of curl, and set -e stops the script at that line. Check ${PIPESTATUS[@]} to see every status."}]},{"id":"python-import","module":"python","lesson":"python/basics-and-environments","title":"How Python finds a module","summary":"The import path, virtual environments and the wrong-version problem.","actors":["Your script","Import system","sys.path folders","Virtual environment"],"steps":[{"f":0,"t":1,"l":"import requests","n":"Your script asks to import a module. Python first checks whether it was already imported, which is stored in sys.modules."},{"f":1,"t":1,"l":"Not loaded yet: build the search list","n":"Python uses sys.path, an ordered list of folders: the script folder first, then the standard library, then site-packages."},{"f":1,"t":2,"l":"Look in each folder in order","n":"The first folder that contains requests (a file or a package folder) wins. A file of your own named requests.py next to the script would shadow the real library."},{"f":2,"t":3,"l":"site-packages of the active environment","n":"When a virtual environment is active, its site-packages is on the path, not the system one. That is why a package installed in one environment is missing in another."},{"f":3,"t":1,"l":"Found: version 2.32","n":"Python reads the file, runs it once, and stores the module object in sys.modules for later imports."},{"f":1,"t":0,"l":"Module is ready to use","n":"Your script can now call requests.get. A second import returns the same object quickly without running the file again."},{"f":1,"t":0,"l":"ModuleNotFoundError","n":"If no folder has the module you get this error. Check which python and which pip are in use, and run python -m pip so they match."}]},{"id":"python-retry","module":"python","lesson":"python/http-apis-and-json","title":"An API call with a timeout and retry","summary":"How a robust client treats slow and failing services.","actors":["Your code","HTTP client","API server"],"steps":[{"f":0,"t":1,"l":"get(url, timeout=5)","n":"Always set a timeout. Without one a request can wait forever and hang the whole program."},{"f":1,"t":2,"l":"Send the request","n":"The client opens a connection and sends the HTTP request."},{"f":2,"t":1,"l":"503 Service Unavailable","n":"The server is overloaded and answers with a temporary error. A 503 or a timeout is worth retrying; a 400 or 404 is not."},{"f":1,"t":0,"l":"Raise an exception","n":"raise_for_status turns the bad response into an exception that your try and except block can catch."},{"f":0,"t":0,"l":"Wait 1 s, then 2 s, then 4 s, plus jitter","n":"Wait longer after each failure and add a small random amount. This stops many clients from retrying at the same instant."},{"f":0,"t":1,"l":"Retry, up to a limit","n":"Retry a small, fixed number of times. Only retry operations that are safe to repeat, or that use an idempotency key."},{"f":2,"t":1,"l":"200 OK with data","n":"The server has recovered and the call succeeds."},{"f":1,"t":0,"l":"Give up with a clear error","n":"After the last attempt, raise an error that says what failed and how many times it was tried, so the failure shows up in logs."}]},{"id":"lb-request","module":"networking","lesson":"networking/firewalls-and-load-balancing","title":"A web request through a load balancer","summary":"DNS, TLS, health checks and the path to a healthy server.","actors":["Browser","Load balancer","Server A","Server B","Database"],"steps":[{"f":0,"t":1,"l":"HTTPS request to shop.example.com","n":"After DNS and the TLS handshake, the browser sends its request to the address of the load balancer."},{"f":1,"t":1,"l":"End TLS, pick a healthy target","n":"The load balancer decrypts the request and chooses a backend that is passing its health checks, for example by round robin or least connections."},{"f":1,"t":3,"l":"Health check to Server B fails","n":"Server B did not answer its recent health checks, so it is taken out of rotation and gets no new traffic."},{"f":1,"t":2,"l":"Forward to Server A","n":"The request goes to Server A with headers such as X-Forwarded-For so the application still knows the real client address."},{"f":2,"t":4,"l":"Query the data","n":"The application reads from the database and builds the page."},{"f":4,"t":2,"l":"Rows returned","n":"The database answers. Slow queries here show up as high latency for the user."},{"f":2,"t":1,"l":"200 OK, response body","n":"Server A returns the response to the load balancer."},{"f":1,"t":0,"l":"Encrypted response","n":"The load balancer encrypts the response and returns it. If every backend were unhealthy the user would see a 502 or 503 from the load balancer instead."}]},{"id":"docker-build","module":"docker","lesson":"docker/writing-dockerfiles","title":"How a Docker image is built and cached","summary":"Layers, the build cache and why instruction order matters.","actors":["Dockerfile","Builder","Layer cache","Registry"],"steps":[{"f":0,"t":1,"l":"FROM python:3.12-slim","n":"The builder pulls the base image. Its layers become the bottom of your image."},{"f":1,"t":2,"l":"COPY requirements.txt, then RUN pip install","n":"Copy only the dependency list first. If that file is unchanged, the installed dependencies come straight from the cache."},{"f":2,"t":1,"l":"Cache hit for both layers","n":"The cache key is the instruction plus the content it depends on. Nothing changed, so the slow install step is skipped."},{"f":0,"t":1,"l":"COPY . /app","n":"Now your source code is copied. It changes on every commit, so this layer is rebuilt, and so is every layer after it."},{"f":1,"t":2,"l":"Cache miss from here on","n":"Putting rarely changing steps first and fast changing steps last keeps builds fast. Putting COPY . before pip install would reinstall everything on each change."},{"f":1,"t":1,"l":"CMD sets the start command","n":"CMD and ENTRYPOINT add metadata, not a new filesystem. They say what runs when a container starts."},{"f":1,"t":3,"l":"Push app:3f9c2a1","n":"The image is pushed to the registry. Only layers that the registry does not already have are uploaded."}]},{"id":"docker-run","module":"docker","lesson":"docker/runtimes-oci-and-podman","title":"What docker run does","summary":"From a command to an isolated process.","actors":["docker CLI","Docker daemon","Registry","Container runtime","Kernel"],"steps":[{"f":0,"t":1,"l":"docker run -p 8080:80 nginx","n":"The command line tool sends the request to the Docker daemon, which does the actual work."},{"f":1,"t":1,"l":"Is the image here already?","n":"The daemon looks in its local image store first."},{"f":1,"t":2,"l":"Pull nginx:latest","n":"If it is missing, the daemon pulls the image layers from the registry. A pinned tag is more repeatable than latest."},{"f":1,"t":3,"l":"Create and start the container","n":"The daemon asks the container runtime to create a container from the image, adding a thin writable layer on top."},{"f":3,"t":4,"l":"Namespaces, cgroups, network","n":"The kernel gives the process its own view of processes, network and filesystem (namespaces) and limits on CPU and memory (cgroups)."},{"f":1,"t":4,"l":"Publish host port 8080 to 80","n":"A rule forwards traffic arriving on host port 8080 to port 80 inside the container."},{"f":4,"t":0,"l":"Container running: nginx is PID 1","n":"The container is just a process on the host with restricted views. When that main process exits, the container stops."}]},{"id":"bluegreen-deploy","module":"cicd","lesson":"cicd/deployment-strategies","title":"Blue-green deployment","summary":"Two copies of production and an instant switch.","actors":["Users","Router","Blue (v1)","Green (v2)"],"steps":[{"f":0,"t":1,"l":"All traffic goes to blue","n":"Blue is the live version. Users reach it through a router or load balancer."},{"f":1,"t":2,"l":"100 percent to blue (v1)","n":"The current version serves everything while green does not receive any user traffic."},{"f":1,"t":3,"l":"Deploy v2 to green","n":"The new version is deployed to an identical green environment next to blue, using the same artifact that was tested."},{"f":3,"t":3,"l":"Smoke tests on green","n":"Tests and a few internal users check green with real configuration while no customers are affected."},{"f":1,"t":3,"l":"Switch the router to green","n":"The router moves traffic from blue to green in one change. Plan for database changes that both versions can work with."},{"f":3,"t":0,"l":"Green serves users","n":"Users now get v2. Watch error rate and latency closely during the first minutes."},{"f":1,"t":2,"l":"Rollback: switch back to blue","n":"If something is wrong, switching back is as fast as the switch forward, because blue is still running. Remove blue only after green has proved stable."}]},{"id":"k8s-service","module":"kubernetes","lesson":"kubernetes/services-and-ingress","title":"How a request reaches a pod through a Service","summary":"ClusterIP, endpoints and kube-proxy.","actors":["Client pod","Cluster DNS","Service","kube-proxy rules","Backend pod"],"steps":[{"f":0,"t":1,"l":"Resolve payments.shop.svc","n":"The client pod asks cluster DNS for the name of the Service."},{"f":1,"t":0,"l":"Answer: ClusterIP 10.96.12.7","n":"DNS returns the stable virtual IP of the Service. This address does not belong to any single pod."},{"f":0,"t":2,"l":"Connect to 10.96.12.7:80","n":"The client sends traffic to the Service address, which is the same however many pods exist."},{"f":2,"t":3,"l":"Endpoints are matched by label","n":"The Service selects pods by labels. Only pods whose readiness probe passes are listed as endpoints."},{"f":3,"t":3,"l":"Rules rewrite the destination","n":"On every node kube-proxy (or an eBPF datapath) installs rules that pick one endpoint and change the destination address to that pod."},{"f":3,"t":4,"l":"Forward to 10.244.1.9:8080","n":"The packet reaches one backend pod. The next connection may reach a different pod."},{"f":4,"t":0,"l":"Response returns","n":"The pod answers and the reply returns through the same translation. If a Service has no endpoints, check that its selector matches the pod labels."}]},{"id":"k8s-hpa","module":"kubernetes","lesson":"kubernetes/autoscaling","title":"Autoscaling with the HPA","summary":"How pods are added when load rises.","actors":["Metrics server","HPA controller","Deployment","Scheduler","Cluster autoscaler"],"steps":[{"f":0,"t":0,"l":"Collect CPU use from the kubelets","n":"The metrics server gathers resource usage of every pod. The HPA needs CPU requests to be set, because it works on a percentage of the request."},{"f":1,"t":0,"l":"Read metrics every 15 seconds","n":"The Horizontal Pod Autoscaler asks for current usage of the pods it manages."},{"f":1,"t":1,"l":"Average is 90 percent, target is 60","n":"It computes desired replicas as current replicas times current value divided by target, rounded up. For 4 pods that gives 6."},{"f":1,"t":2,"l":"Scale the Deployment to 6","n":"The HPA changes the replica count. A stabilization window stops it from scaling down too fast after a spike."},{"f":2,"t":3,"l":"Two new pods need nodes","n":"The Deployment creates the pods and the scheduler tries to place them."},{"f":3,"t":4,"l":"Pods stay Pending: no room","n":"If every node is full the pods wait, which is when the cluster autoscaler can add a node."},{"f":4,"t":3,"l":"New node joins, pods run","n":"Adding a node takes minutes, so keep some headroom or scale on a leading signal for sudden traffic."}]},{"id":"terraform-lock","module":"terraform","lesson":"terraform/state","title":"Two engineers apply at once: state locking","summary":"Why remote state needs a lock.","actors":["Engineer A","Engineer B","Remote backend","Cloud API"],"steps":[{"f":0,"t":2,"l":"terraform apply: take the lock","n":"Engineer A starts an apply. Terraform asks the backend for a lock on the state before it reads anything."},{"f":2,"t":0,"l":"Lock granted","n":"The backend records who holds the lock and since when. With a bucket backend a separate lock table or lock file does this."},{"f":1,"t":2,"l":"terraform apply: take the lock","n":"Engineer B starts an apply on the same state a few seconds later."},{"f":2,"t":1,"l":"Refused: state is locked by A","n":"B sees an error with the lock owner and time. Without locking, both would plan from the same old state and one could overwrite the other."},{"f":0,"t":3,"l":"A creates and changes resources","n":"A applies the plan to the cloud API."},{"f":0,"t":2,"l":"Write new state and release the lock","n":"The new state is saved first and then the lock is released."},{"f":1,"t":2,"l":"B tries again and plans from fresh state","n":"B now plans from the updated state, so the plan includes A's changes. Use force-unlock only when you are sure that the first run has died."}]},{"id":"aws-iam","module":"cloud","lesson":"cloud/identity-and-access","title":"How a cloud request is authorised (IAM)","summary":"Identity, policy evaluation and temporary credentials.","actors":["Application","Security token service","IAM policy engine","Storage service"],"steps":[{"f":0,"t":1,"l":"Assume the role \"report-reader\"","n":"Instead of a stored password, the application asks for temporary credentials for a role. The workload identity proves who it is."},{"f":1,"t":0,"l":"Short-lived keys, expire in 1 hour","n":"The token service returns a key, a secret and a session token that expire. Leaked temporary keys are far less harmful than permanent ones."},{"f":0,"t":3,"l":"GetObject reports/may.csv (signed)","n":"The application calls the storage service and signs the request with the temporary credentials."},{"f":3,"t":2,"l":"Ask: may this role do this?","n":"The service asks the policy engine to evaluate the request: who, which action, which resource, and which conditions."},{"f":2,"t":2,"l":"Evaluate all policies","n":"Everything is denied by default. An explicit Deny anywhere wins. Otherwise at least one Allow, from an identity or resource policy, must match."},{"f":2,"t":3,"l":"Allow","n":"The role policy allows s3:GetObject on that bucket prefix, and no deny applies, so the request is permitted."},{"f":3,"t":0,"l":"Object returned, or 403 AccessDenied","n":"With an Allow the data is returned. Otherwise the caller gets AccessDenied, and the audit log records the attempt."}]},{"id":"cloud-autoscale","module":"cloud","lesson":"cloud/compute-and-storage","title":"An auto scaling group reacts to load","summary":"Scale out, health replacement and scale in.","actors":["Load balancer","Monitoring","Auto scaling group","Instances"],"steps":[{"f":0,"t":3,"l":"Traffic rises","n":"More requests per instance push CPU or request count above the target you set."},{"f":1,"t":1,"l":"Alarm: average CPU above 60 percent","n":"Monitoring evaluates the metric over several periods so that a short spike does not trigger a scale-out."},{"f":1,"t":2,"l":"Policy: add 2 instances","n":"A target tracking or step policy tells the group how many instances it should have."},{"f":2,"t":3,"l":"Launch from the template","n":"The group launches instances from a launch template, spread across availability zones."},{"f":3,"t":0,"l":"Pass health checks, join the pool","n":"A new instance receives traffic only after it passes the load balancer health check. A slow start time prevents overload on a cold instance."},{"f":3,"t":2,"l":"One instance fails its check","n":"If an instance becomes unhealthy, the group terminates it and launches a replacement to keep the desired capacity."},{"f":1,"t":2,"l":"Load falls: scale in after a cooldown","n":"Scale in is slower and more careful than scale out. Instances finish in-flight requests (connection draining) before they stop."}]},{"id":"cloud-multi-az","module":"cloud","lesson":"cloud/high-availability-and-disaster-recovery","title":"A zone fails: multi-AZ database failover","summary":"What a standby does and how long the gap lasts.","actors":["Application","DNS endpoint","Primary (zone A)","Standby (zone B)"],"steps":[{"f":0,"t":1,"l":"Connect to db.example.internal","n":"The application always uses one DNS name, never an instance address."},{"f":1,"t":2,"l":"Name points to the primary","n":"In normal operation the name resolves to the primary in zone A."},{"f":2,"t":3,"l":"Replicate every write","n":"A managed multi-AZ database copies each committed write to the standby in another zone, so little or no data is lost."},{"f":2,"t":2,"l":"Zone A fails","n":"A power or network failure takes the primary offline. Detection takes a short time."},{"f":3,"t":3,"l":"Promote the standby","n":"The service decides that the primary is gone and promotes the standby to be the new primary. This often takes one to two minutes."},{"f":1,"t":3,"l":"Name now points to zone B","n":"The DNS record changes. Applications with long-lived DNS caches or open connections may need to reconnect."},{"f":0,"t":3,"l":"Reconnect and retry","n":"Applications must retry with backoff for the gap. A new standby is built in the background to restore redundancy."}]},{"id":"prometheus-alert","module":"observability","lesson":"observability/alerting-and-dashboards","title":"From a metric to a page","summary":"Scrape, store, evaluate, route and notify.","actors":["Application","Prometheus","Alertmanager","On-call engineer"],"steps":[{"f":0,"t":0,"l":"Expose /metrics","n":"The application publishes counters and histograms, such as the total number of requests by status code."},{"f":1,"t":0,"l":"Scrape every 15 seconds","n":"Prometheus pulls the metrics from each target on a schedule and stores them as time series."},{"f":1,"t":1,"l":"Evaluate the alert rule","n":"A rule such as the error ratio above 2 percent for 5 minutes is checked at every evaluation interval. The for clause avoids alerts on brief blips."},{"f":1,"t":2,"l":"Alert is firing","n":"When the rule has been true long enough, Prometheus sends the alert with its labels to Alertmanager."},{"f":2,"t":2,"l":"Group, deduplicate, silence","n":"Alertmanager groups related alerts into one notification, drops duplicates and respects silences and inhibition rules."},{"f":2,"t":3,"l":"Page the on-call","n":"A notification goes to the on-call tool by phone or chat according to routing labels such as team and severity."},{"f":3,"t":2,"l":"Acknowledge, then open the runbook","n":"The engineer acknowledges the page and follows the runbook linked in the alert annotations. Good pages say what users feel and what to check first."}]},{"id":"distributed-trace","module":"observability","lesson":"observability/logs-and-traces","title":"A distributed trace across services","summary":"How one request is followed from service to service.","actors":["Gateway","Orders service","Payments service","Trace backend"],"steps":[{"f":0,"t":0,"l":"Create trace ID 4bf9...","n":"The first service creates a trace ID and a root span that records the start time and the operation name."},{"f":0,"t":1,"l":"Call with a traceparent header","n":"The trace ID and the parent span ID travel in an HTTP header, as in the W3C Trace Context standard."},{"f":1,"t":1,"l":"Orders: new child span","n":"The service starts a child span with the same trace ID and records its own timing and attributes."},{"f":1,"t":2,"l":"Call payments, header passed on","n":"Every hop must pass the header on. One service that drops it breaks the trace into two pieces."},{"f":2,"t":2,"l":"Payments: slow database call, 1.8 s","n":"A child span for the database query shows where the time went. The span shows the problem is in the database call, not in the network."},{"f":0,"t":3,"l":"Spans are exported","n":"Each service sends its finished spans, usually through an OpenTelemetry collector, to the trace backend. Sampling keeps cost down."},{"f":3,"t":3,"l":"Assemble the waterfall","n":"The backend joins spans by trace ID into one waterfall view, so an engineer can click from an alert to the exact slow request."}]},{"id":"log-pipeline","module":"observability","lesson":"observability/log-pipelines","title":"How logs get from an app to a search box","summary":"Collect, parse, ship, index and query.","actors":["Application","Node agent","Log store","Engineer"],"steps":[{"f":0,"t":0,"l":"Write JSON lines to stdout","n":"In containers the application writes one structured event per line to standard output and does not manage log files itself."},{"f":0,"t":1,"l":"The runtime stores the stream","n":"The container runtime saves the output on the node, and an agent such as Fluent Bit tails those files."},{"f":1,"t":1,"l":"Parse and add labels","n":"The agent parses each line and adds labels such as namespace, pod and version. Drop secrets and personal data here before they leave the node."},{"f":1,"t":2,"l":"Ship in batches with retries","n":"The agent sends batches to the log store and buffers on disk if the store is slow, so a short outage does not lose logs."},{"f":2,"t":2,"l":"Index and keep for 14 days","n":"The store indexes the data and applies retention. Indexing every field is costly, so many stores index only labels."},{"f":3,"t":2,"l":"Query: error and trace ID","n":"During an incident the engineer searches by label and time range, and by trace ID to find the logs for one request."},{"f":2,"t":3,"l":"Matching lines returned","n":"Results come back in time order. A good log line has a level, a message, and an ID that links to the trace."}]},{"id":"incident-response","module":"sre","lesson":"sre/incident-response","title":"The life of an incident","summary":"Detect, respond, mitigate, learn.","actors":["Monitoring","On-call","Incident commander","Customers","Team"],"steps":[{"f":0,"t":1,"l":"Alert: checkout errors 8 percent","n":"Monitoring detects the problem from a user-facing signal and pages the on-call engineer."},{"f":1,"t":1,"l":"Acknowledge, assess impact","n":"The on-call checks dashboards, decides how many users are affected, and sets a severity."},{"f":1,"t":2,"l":"Declare an incident, name a commander","n":"For a serious problem, one person takes the role of incident commander. They coordinate and do not debug, so that work stays organised."},{"f":2,"t":4,"l":"Assign roles, open one channel","n":"Operators work the problem, a scribe records the timeline, and a communications lead updates others on a regular schedule."},{"f":4,"t":3,"l":"Post a status update","n":"Customers are told what is known and when to expect the next update, even when the cause is not known yet."},{"f":4,"t":4,"l":"Mitigate first: roll back the release","n":"Stop the harm before finding the root cause. Rollback, failover or turning off a feature flag is usually quicker than a fix."},{"f":1,"t":0,"l":"Confirm recovery on the same graphs","n":"Check that the user-facing signal returns to normal, then resolve the incident and tell customers."},{"f":2,"t":4,"l":"Blameless postmortem, actions with owners","n":"Within days the team writes up the timeline, causes and follow-ups. Good actions change the system, have an owner and a date."}]},{"id":"error-budget-policy","module":"sre","lesson":"sre/slos-and-error-budgets","title":"An error budget decides the release pace","summary":"How a 99.9 percent SLO turns into decisions.","actors":["Users","Monitoring","Error budget","Product team","SRE team"],"steps":[{"f":0,"t":1,"l":"Requests succeed or fail","n":"The SLI is the share of requests that succeed. Monitoring counts good and bad events continuously."},{"f":1,"t":2,"l":"SLO 99.9 percent over 30 days","n":"The target allows 0.1 percent failure, about 43 minutes of full outage or the same number of failed requests."},{"f":2,"t":2,"l":"Budget remaining: 70 percent","n":"The remaining budget is shown on a dashboard. Plenty left means the team can take risk."},{"f":3,"t":2,"l":"Ship features, run experiments","n":"While budget remains, releases and risky changes continue at full speed. Reliability is not an end in itself."},{"f":2,"t":2,"l":"A bad release burns 40 percent","n":"A fast burn rate raises an alert long before the window ends, for example when budget is consumed 14 times faster than allowed."},{"f":2,"t":4,"l":"Budget nearly spent: policy applies","n":"The agreed policy now applies: slow or pause risky launches and put the time into reliability work."},{"f":4,"t":3,"l":"Fix reliability, budget recovers","n":"As the window moves forward and failures fall out of it, the budget recovers and normal release pace returns."}]},{"id":"retry-storm","module":"sre","lesson":"sre/reliability-patterns","title":"A retry storm, and how to stop it","summary":"Why naive retries turn a blip into an outage.","actors":["Clients","Service","Database"],"steps":[{"f":2,"t":2,"l":"Database slows down","n":"A maintenance task makes the database slower. Requests to the service start to time out."},{"f":0,"t":1,"l":"Timeouts: clients retry 3 times","n":"Every client that times out retries immediately. The load on the service becomes up to four times the normal load."},{"f":1,"t":2,"l":"Retries pile onto the database","n":"The extra requests go to the already slow database, so more of them time out."},{"f":2,"t":2,"l":"Overloaded: it cannot recover","n":"Even after the original cause ends, the retry load keeps the database busy. The system stays down on its own load."},{"f":0,"t":1,"l":"Fix: exponential backoff and jitter","n":"Clients wait longer after each failure and add random delay, which spreads the retries out over time."},{"f":1,"t":1,"l":"Fix: retry budget and circuit breaker","n":"Limit retries to a small share of traffic. A circuit breaker stops calling a failing dependency for a short time and fails fast."},{"f":1,"t":0,"l":"Shed load, return 503 early","n":"A service that rejects excess requests quickly protects itself and recovers sooner than one that tries to serve everything."}]},{"id":"ssh-login","module":"linux","lesson":"linux/ssh-and-remote-access","title":"How an SSH login works","summary":"Key exchange, host check and key-based sign-in.","actors":["Your laptop","sshd on the server","PAM and shell"],"steps":[{"f":0,"t":1,"l":"Open TCP port 22","n":"The client connects to the server. Both sides send the protocol version they support."},{"f":1,"t":0,"l":"Server sends its host key","n":"The server proves who it is with its host key. The client compares it with the entry in known_hosts."},{"f":0,"t":0,"l":"Check known_hosts","n":"A new key asks for your confirmation. A changed key triggers a loud warning, because it can mean a different machine or an attack."},{"f":0,"t":1,"l":"Agree on session keys","n":"Both sides run a key exchange and derive keys that only they know. All traffic from now on is encrypted."},{"f":0,"t":1,"l":"Offer your public key","n":"The client offers a public key. The server looks for it in ~/.ssh/authorized_keys of the target user."},{"f":1,"t":0,"l":"Challenge to prove the private key","n":"The server sends a challenge that only the matching private key can sign. The private key never leaves your laptop."},{"f":1,"t":2,"l":"Account and policy checks","n":"PAM checks that the account is valid and not locked, and applies limits. Wrong file permissions on ~/.ssh make the server ignore your key."},{"f":2,"t":0,"l":"Shell starts, session is open","n":"The server starts the login shell for the user. Use ssh -v to see each of these stages when a login fails."}]},{"id":"cron-run","module":"bash","lesson":"bash/safe-automation","title":"A cron job runs, and why it behaves differently","summary":"The small environment of scheduled jobs.","actors":["cron daemon","Shell (sh)","Your script","Mail or log"],"steps":[{"f":0,"t":0,"l":"Every minute: read the crontab","n":"The cron daemon wakes up each minute and checks whether any entry matches the current time."},{"f":0,"t":1,"l":"30 2 * * * /opt/backup.sh","n":"At 02:30 it starts a shell. This is a plain sh with a minimal environment, not your login shell."},{"f":1,"t":1,"l":"Small PATH, no profile files","n":"Your .bashrc and .profile are not read, and PATH is short. A command that works in your terminal can be missing here."},{"f":1,"t":2,"l":"Run the script","n":"Use absolute paths for commands and files, and set the variables the script needs at its top."},{"f":2,"t":2,"l":"Script writes output","n":"Anything printed goes to the owner by mail, or is lost if mail is not set up. Redirect to a log file with >> backup.log 2>&1."},{"f":2,"t":2,"l":"Two runs overlap","n":"If a run is still going when the next one starts, you get two copies. Guard with flock -n /tmp/backup.lock."},{"f":2,"t":3,"l":"Exit status, then alert","n":"Cron does not alert on failure by itself. Have the script report success or failure to a monitoring check."}]},{"id":"exit-codes","module":"bash","lesson":"bash/script-basics","title":"Exit codes and how a script decides what to do","summary":"From a failed command to the exit of the script.","actors":["Script","Command","Shell variables"],"steps":[{"f":0,"t":1,"l":"Run grep -q ready status.txt","n":"Every command ends with an exit status. Zero means success. Any other number means some kind of failure."},{"f":1,"t":2,"l":"Status stored in $?","n":"The shell puts the status of the last command into $?. It changes after every command, so read it at once."},{"f":0,"t":2,"l":"if grep ...; then ...","n":"An if statement tests the exit status directly. You do not need to compare $? to 0."},{"f":1,"t":0,"l":"Status 1 means no match","n":"For grep, 1 means no match and 2 means an error. The meaning of numbers belongs to each program, so read its manual."},{"f":0,"t":0,"l":"set -e stops on an unexpected failure","n":"With set -e the script stops on the first failing command that is not part of a test. It is a safety net, not full error handling."},{"f":0,"t":0,"l":"trap runs the cleanup","n":"A trap on EXIT or ERR removes temp files and reports where the script failed."},{"f":0,"t":2,"l":"exit 3 tells the caller why","n":"Choose clear exit codes and document them. A caller such as cron, CI or another script reads them to decide what to do next."}]},{"id":"python-boto3","module":"python","lesson":"python/cloud-sdks","title":"How boto3 finds credentials and calls AWS","summary":"The credential chain and a signed request.","actors":["Your script","boto3 credential chain","STS or metadata service","AWS API"],"steps":[{"f":0,"t":1,"l":"boto3.client(\"s3\")","n":"You create a client without passing keys. boto3 looks for credentials in a fixed order."},{"f":1,"t":1,"l":"Check environment variables first","n":"AWS_ACCESS_KEY_ID and related variables win if they are set. A forgotten variable can send you to the wrong account."},{"f":1,"t":1,"l":"Then shared files and profiles","n":"Next come ~/.aws/credentials and config, including AWS_PROFILE and SSO profiles."},{"f":1,"t":2,"l":"Then the role of the machine","n":"On EC2, ECS or EKS the chain asks the metadata service or a web identity token for short-lived credentials."},{"f":2,"t":1,"l":"Temporary keys returned","n":"The service returns keys with an expiry time. boto3 refreshes them before they expire."},{"f":0,"t":3,"l":"list_objects_v2 (signed)","n":"The request is signed with the credentials, so the server can check who sent it and that nobody changed it."},{"f":3,"t":0,"l":"Response or ClientError","n":"You get data, or a ClientError with a code such as AccessDenied. Use sts get_caller_identity to see which identity was used."}]},{"id":"python-container-signal","module":"python","lesson":"python/files-and-processes","title":"A Python service in a container and SIGTERM","summary":"Graceful shutdown during a deployment.","actors":["Orchestrator","Container runtime","Python service","In-flight requests"],"steps":[{"f":0,"t":1,"l":"Rolling update: stop the old pod","n":"The orchestrator asks the runtime to stop the container, after it removes it from the load balancer."},{"f":1,"t":2,"l":"SIGTERM to PID 1","n":"The runtime sends SIGTERM to the main process of the container. With a shell wrapper the signal may never reach Python."},{"f":2,"t":2,"l":"Signal handler sets a flag","n":"Register signal.signal(SIGTERM, handler). The handler stops accepting new work and sets a flag."},{"f":2,"t":3,"l":"Finish current requests","n":"The service completes the requests it has already started, and closes connections and files."},{"f":2,"t":2,"l":"Exit with code 0","n":"When the work is done the process exits cleanly, and the container stops quickly."},{"f":1,"t":2,"l":"After the grace period: SIGKILL","n":"If the process is still running when terminationGracePeriodSeconds ends, it is killed at once and requests are cut off."},{"f":0,"t":1,"l":"Use exec form for the entrypoint","n":"Write CMD [\"python\", \"app.py\"] so Python is PID 1 and receives the signal. Add an init such as tini if you spawn children."}]},{"id":"docker-network","module":"docker","lesson":"docker/volumes-and-networking","title":"Container to container networking","summary":"Bridge networks, DNS names and published ports.","actors":["Browser on the host","Published port rule","web container","db container","Embedded DNS"],"steps":[{"f":0,"t":1,"l":"localhost:8080","n":"The browser connects to a port on the host. Docker has a rule that forwards it to a container."},{"f":1,"t":2,"l":"Forward to web:80","n":"The rule rewrites the destination to the IP address of the web container on the bridge network."},{"f":2,"t":4,"l":"Resolve \"db\"","n":"On a user-defined network, containers find each other by name. The built-in DNS server at 127.0.0.11 answers."},{"f":4,"t":2,"l":"db is 172.19.0.3","n":"The name resolves to the current address of the db container. The address can change, so use the name."},{"f":2,"t":3,"l":"Connect to db:5432","n":"The traffic stays inside the network. The database port does not need to be published to the host."},{"f":3,"t":2,"l":"Query result","n":"The database answers. Keeping the database off the host ports means that only the web container can reach it."},{"f":2,"t":0,"l":"HTML response","n":"The web container sends the page back through the published port. On the default bridge network, name lookup does not work, so create your own network."}]},{"id":"docker-multistage","module":"docker","lesson":"docker/slim-images-and-faster-builds","title":"A multi-stage build gives a small image","summary":"Build in one stage, ship only what you need.","actors":["Dockerfile","Build stage","Final stage","Registry"],"steps":[{"f":0,"t":1,"l":"FROM golang:1.23 AS build","n":"The first stage has the full compiler and tools. It can be large, and it never ships."},{"f":1,"t":1,"l":"Download dependencies, compile","n":"Copy go.mod and download modules first so the cache is used, then copy the source and build a static binary."},{"f":0,"t":2,"l":"FROM gcr.io/distroless/static","n":"The second stage starts from a tiny base image with no shell and no package manager."},{"f":1,"t":2,"l":"COPY --from=build /app /app","n":"Only the binary is copied. Compilers, source code and build caches stay behind in the first stage."},{"f":2,"t":2,"l":"USER nonroot, ENTRYPOINT","n":"Run as a non-root user. A smaller image has fewer packages that can have vulnerabilities."},{"f":2,"t":3,"l":"Push 20 MB instead of 900 MB","n":"The registry stores only the final stage. Pulls are faster and scale-out is quicker."},{"f":0,"t":1,"l":"Debug with --target build","n":"docker build --target build gives you the first stage, with all the tools, when you need to investigate."}]},{"id":"canary-release","module":"cicd","lesson":"cicd/deployment-strategies","title":"Canary release with automatic checks","summary":"Send 5 percent of traffic to the new version and watch.","actors":["Pipeline","Router","Stable v1","Canary v2","Metrics"],"steps":[{"f":0,"t":3,"l":"Deploy v2 beside v1","n":"The new version runs next to the stable one. At first it receives no user traffic."},{"f":0,"t":1,"l":"Route 5 percent to v2","n":"The router sends a small share of requests to the canary. Real users and real data test the release."},{"f":4,"t":3,"l":"Compare error rate and latency","n":"Metrics for v2 are compared with v1 over the same period. The comparison matters more than an absolute number."},{"f":0,"t":4,"l":"Gate: healthy for 10 minutes?","n":"The pipeline reads the metrics and decides. Define the pass rule before the release, not during it."},{"f":0,"t":1,"l":"Raise to 25, 50, then 100 percent","n":"If the checks pass, the share grows in steps, with a pause and a check at each step."},{"f":0,"t":1,"l":"Failure: route 0 percent to v2","n":"If errors rise, the router sends all traffic back to v1 at once. Only a small share of users saw the problem."},{"f":0,"t":2,"l":"Retire v1 after a soak period","n":"Keep the old version for a while after 100 percent so that you can roll back quickly."}]},{"id":"pr-checks","module":"cicd","lesson":"cicd/building-a-pipeline","title":"What happens when you open a pull request","summary":"Checks, review and a protected main branch.","actors":["Developer","CI system","Reviewer","Main branch"],"steps":[{"f":0,"t":1,"l":"Open a pull request","n":"The change triggers the pipeline. It runs in a clean environment on the proposed result of the merge."},{"f":1,"t":1,"l":"Lint, unit tests, build","n":"Fast checks run first, so a mistake is reported in minutes and slower checks do not run for nothing."},{"f":1,"t":1,"l":"Security and dependency scans","n":"Scans look for known vulnerabilities and for secrets in the change. A failure blocks the merge."},{"f":1,"t":0,"l":"Report status on the pull request","n":"The developer sees red or green checks and a link to the logs. A flaky test hurts trust, so fix or remove it."},{"f":2,"t":0,"l":"Review the change","n":"A person reads the change for design, risk and clarity. Small changes get better reviews."},{"f":3,"t":1,"l":"Branch protection allows merge","n":"The main branch requires passing checks and an approval. Nobody pushes to it directly."},{"f":1,"t":3,"l":"Build once, release the artifact","n":"After the merge the pipeline builds the artifact once, tags it with the commit, and passes it on to later stages."}]},{"id":"k8s-crashloop","module":"kubernetes","lesson":"kubernetes/debugging-kubernetes-workloads","title":"Why a pod ends in CrashLoopBackOff","summary":"Restarts, back-off and where to look.","actors":["kubelet","Container","Pod status","You"],"steps":[{"f":0,"t":1,"l":"Start the container","n":"The kubelet starts the container with the command and environment from the pod spec."},{"f":1,"t":1,"l":"Process exits with an error","n":"The program stops, for example because a setting is missing or a dependency refuses it. Exit code 1 is an application error, 137 is a kill, often out of memory."},{"f":0,"t":1,"l":"Restart policy: start again","n":"With restartPolicy Always, the kubelet starts the container again."},{"f":0,"t":2,"l":"Wait longer each time","n":"Waits grow: 10 s, 20 s, 40 s up to 5 minutes. The status shows CrashLoopBackOff while it waits."},{"f":3,"t":2,"l":"kubectl describe pod","n":"Events and Last State show the exit code and reason such as OOMKilled or Error."},{"f":3,"t":1,"l":"kubectl logs --previous","n":"The logs of the crashed run show the real error. Plain logs may show the new, empty container."},{"f":3,"t":2,"l":"Fix config, memory or probes","n":"Common causes are a missing variable or secret, a memory limit that is too low, or a liveness probe that kills a slow start. Use a startup probe for slow starts."}]},{"id":"tf-modules-plan","module":"terraform","lesson":"terraform/modules","title":"How Terraform builds a plan","summary":"Configuration, state and the real world compared.","actors":["Configuration","Terraform core","State","Provider and cloud"],"steps":[{"f":0,"t":1,"l":"Read the .tf files and modules","n":"Terraform loads all configuration files in the folder and the modules that they call, and builds a graph of resources."},{"f":1,"t":2,"l":"Load the current state","n":"State is Terraform's record of what it manages: the real IDs and the last known attributes."},{"f":1,"t":3,"l":"Refresh: ask the cloud","n":"The provider reads the real objects. If someone changed a resource by hand, Terraform notices the drift here."},{"f":1,"t":1,"l":"Compare wanted with actual","n":"For each resource it decides: create, update in place, replace or destroy, or no change."},{"f":1,"t":0,"l":"Print the plan","n":"The plan lists every action with the attribute that causes it. Arguments marked \"forces replacement\" need special care."},{"f":1,"t":3,"l":"apply: call the provider in order","n":"Dependencies decide the order. Independent resources are created in parallel."},{"f":1,"t":2,"l":"Save the new state","n":"After each successful change the state is updated, so an interrupted apply can continue from where it stopped."}]},{"id":"tf-drift","module":"terraform","lesson":"terraform/workflows-and-drift","title":"Detecting and fixing drift","summary":"Someone changed production by hand.","actors":["Engineer in the console","Cloud resource","Terraform plan","Team"],"steps":[{"f":0,"t":1,"l":"Open port 22 to the world in the console","n":"During an incident someone changes a security group by hand. The code and the state are not updated."},{"f":2,"t":1,"l":"Scheduled plan reads reality","n":"A nightly terraform plan compares the real security group with the code."},{"f":2,"t":3,"l":"Plan shows an unexpected change","n":"The plan wants to remove the rule. This difference between code and reality is drift."},{"f":3,"t":2,"l":"Decide: keep or revert?","n":"If the change was right, update the code. If it was a shortcut, let Terraform put it back. Do not apply blindly."},{"f":2,"t":1,"l":"Apply or import the change","n":"Applying removes the manual rule. For a new resource created by hand, terraform import brings it under management."},{"f":3,"t":0,"l":"Reduce console access","n":"Give read-only access to most people, and use break-glass roles that are logged."},{"f":3,"t":2,"l":"Alert on drift in a pipeline","n":"A scheduled plan that fails when it finds changes turns drift into a ticket, instead of a surprise."}]},{"id":"vpc-routing","module":"cloud","lesson":"cloud/virtual-networks","title":"Public and private subnets, NAT and the internet","summary":"Which route table sends traffic where.","actors":["Private app server","NAT gateway (public subnet)","Internet gateway","Internet service"],"steps":[{"f":0,"t":0,"l":"App needs to call an update server","n":"The server in the private subnet has only a private address. Nobody on the internet can start a connection to it."},{"f":0,"t":1,"l":"Route table: 0.0.0.0/0 goes to NAT","n":"The private subnet route table sends all non-local traffic to the NAT gateway."},{"f":1,"t":1,"l":"NAT swaps the source address","n":"The NAT gateway replaces the private source address with its own public address and remembers the connection."},{"f":1,"t":2,"l":"Public subnet route: 0.0.0.0/0 to the IGW","n":"The route table of the public subnet points to the internet gateway, which connects the VPC to the internet."},{"f":2,"t":3,"l":"Request leaves the VPC","n":"The internet service sees the public address of the NAT gateway only."},{"f":3,"t":1,"l":"Response returns to NAT","n":"The reply comes back to the NAT gateway, which maps it to the original private address."},{"f":1,"t":0,"l":"Response reaches the app","n":"Outbound works but inbound does not start here. NAT gateways charge by hour and by data, and a VPC endpoint avoids them for cloud services."}]},{"id":"slo-burn-alert","module":"observability","lesson":"observability/alerting-and-dashboards","title":"Multi-window burn rate alerting","summary":"Page fast for big problems, ticket slowly for small ones.","actors":["Error budget","Fast window (1h and 5m)","Slow window (6h and 30m)","On-call","Ticket queue"],"steps":[{"f":0,"t":0,"l":"SLO 99.9 percent, budget 0.1 percent","n":"The budget is the share of requests that may fail in the SLO period. Burn rate says how fast it is being spent."},{"f":0,"t":1,"l":"Burn rate 14.4 for the last hour","n":"At this speed 2 percent of the monthly budget is gone in one hour. The whole budget would be gone in about two days."},{"f":1,"t":1,"l":"Check the 5 minute window too","n":"A short window confirms that the problem is still happening, so the page stops soon after the fix."},{"f":1,"t":3,"l":"Both true: page the on-call","n":"A fast burn needs a human now. The page links to a runbook and the dashboard."},{"f":0,"t":2,"l":"Burn rate 1 to 6 over 6 hours","n":"A slower burn does not need a night call, but it will empty the budget before the month ends."},{"f":2,"t":4,"l":"Open a ticket for the daytime","n":"A ticket is picked up during working hours. This keeps pages for what is urgent and avoids alert fatigue."},{"f":0,"t":3,"l":"Tune with real history","n":"Review thresholds after incidents and false alarms. Alerts should match the SLO, not every cause of trouble."}]},{"id":"chaos-experiment","module":"sre","lesson":"sre/chaos-engineering-and-game-days","title":"Running a chaos experiment safely","summary":"Hypothesis, small blast radius, abort rule.","actors":["Team","Experiment tool","Service","Dashboards"],"steps":[{"f":0,"t":0,"l":"Write a hypothesis","n":"For example: if one of three replicas dies, the success rate stays above 99.9 percent."},{"f":0,"t":3,"l":"Define steady state and abort rule","n":"Pick the metrics that show health, and say in advance when to stop, such as errors above 1 percent for two minutes."},{"f":0,"t":1,"l":"Announce and limit the blast radius","n":"Tell the on-call team. Start in staging, or with one pod or a small share of traffic in production."},{"f":1,"t":2,"l":"Inject the fault: kill a pod","n":"The tool injects one fault at a time, such as killing a pod, adding latency or blocking a dependency."},{"f":3,"t":0,"l":"Watch the dashboards","n":"Someone watches the steady-state metrics during the whole run and keeps a finger on the stop button."},{"f":1,"t":2,"l":"Stop and restore","n":"The experiment ends after the planned time, or earlier if the abort rule is hit. All changes are reverted."},{"f":0,"t":0,"l":"Record the result and fix the gap","n":"If the hypothesis failed, you found a weakness cheaply. Make an action with an owner and repeat the test after the fix."}]},{"id":"ingress-request","module":"networking","lesson":"networking/firewalls-and-load-balancing","title":"An HTTPS request through a Kubernetes ingress","summary":"Load balancer, ingress controller, Service and pod.","actors":["Client","Cloud load balancer","Ingress controller","Service","Pod"],"steps":[{"f":0,"t":1,"l":"https://shop.example.com/api","n":"DNS maps the name to the public address of the cloud load balancer."},{"f":1,"t":2,"l":"Forward to the ingress controller","n":"The load balancer sends traffic to the nodes where the ingress controller pods run."},{"f":2,"t":2,"l":"Terminate TLS, match host and path","n":"The controller uses the certificate from a Secret and matches the host and the path against Ingress rules."},{"f":2,"t":3,"l":"Choose the backend Service","n":"The rule for /api points to the Service named api. A wrong service name or port gives a 503."},{"f":3,"t":4,"l":"Pick a ready pod","n":"The Service sends the request to a pod that passes its readiness probe."},{"f":4,"t":0,"l":"Response travels back","n":"The answer returns along the same path. Each hop adds a little latency and has its own timeout."},{"f":2,"t":2,"l":"Where to look when it fails","n":"A 404 means no rule matched. A 502 or 503 means no healthy backend. Check kubectl describe ingress and the controller logs."}]},{"id":"tcp-teardown","module":"networking","lesson":"networking/latency-mtu-and-network-performance","title":"How a TCP connection closes, and TIME_WAIT","summary":"FIN, ACK and why sockets stay for a while.","actors":["Client","Server"],"steps":[{"f":0,"t":1,"l":"FIN: I have no more to send","n":"The side that finishes first sends a FIN segment. This closes one direction of the connection."},{"f":1,"t":0,"l":"ACK","n":"The other side acknowledges. It can still send data, which is called a half-closed connection."},{"f":1,"t":0,"l":"FIN: I am done as well","n":"When the server has no more data, it sends its own FIN."},{"f":0,"t":1,"l":"ACK: connection is closed","n":"The client acknowledges the last FIN, so both sides know that the connection has ended."},{"f":0,"t":0,"l":"Client waits in TIME_WAIT","n":"The side that closed first keeps the socket for about 60 seconds, so late packets from the old connection cannot confuse a new one."},{"f":1,"t":1,"l":"Server socket is freed","n":"The server frees its socket as soon as it sees the last ACK. Many TIME_WAIT sockets on a busy client are normal."},{"f":0,"t":1,"l":"Reuse connections","n":"If you run out of ports, use keep-alive and connection pools instead of tuning the kernel. Check with ss -s."}]},{"id":"oom-kill","module":"linux","lesson":"linux/processes-memory-and-the-oom-killer","title":"How the OOM killer picks a victim","summary":"Memory pressure, reclaim and the kill.","actors":["Applications","Kernel memory manager","OOM killer","Logs"],"steps":[{"f":0,"t":1,"l":"Programs ask for more memory","n":"A service grows, for example from a leak or a traffic spike. The kernel gives pages when they are touched."},{"f":1,"t":1,"l":"Reclaim: drop cache, use swap","n":"First the kernel frees page cache, which is cheap. It may also swap out cold pages, which is slow."},{"f":1,"t":1,"l":"Nothing left to reclaim","n":"When free memory and swap run out, the kernel cannot satisfy an allocation. Waiting longer will not help."},{"f":1,"t":2,"l":"Call the OOM killer","n":"The OOM killer scores each process by memory use and adjustments, and chooses the one that frees the most memory with the least harm."},{"f":2,"t":0,"l":"SIGKILL to the victim","n":"The chosen process is killed at once with no cleanup. It is often your biggest service, not the one that leaked."},{"f":2,"t":3,"l":"Message in dmesg and journal","n":"Look for \"Out of memory: Killed process\" in dmesg -T or journalctl -k. In containers the cgroup limit gives exit code 137."},{"f":0,"t":1,"l":"Prevent: limits and monitoring","n":"Set memory limits per service, alert on available memory, and find the leak. Adding swap hides a problem, it does not solve it."}]},{"id":"dhcp-lease","module":"networking","lesson":"networking/dhcp-arp-and-the-local-network","title":"How a device gets an IP address with DHCP","summary":"Discover, offer, request, acknowledge, and what happens when the lease runs out.","actors":["New device","DHCP server"],"steps":[{"f":0,"t":0,"l":"No address yet","n":"A device that joins the network has no IP address, so it can only send broadcasts on the local segment."},{"f":0,"t":1,"l":"DISCOVER (broadcast)","n":"The device asks everybody on the segment: is there a DHCP server? It uses 0.0.0.0 as its source address."},{"f":1,"t":0,"l":"OFFER: 10.0.4.57 for 24h","n":"The server picks a free address from its pool and offers it, with a lease time, a mask, a gateway and DNS servers."},{"f":0,"t":1,"l":"REQUEST: I take 10.0.4.57","n":"The device accepts one offer. It is still a broadcast, so that other servers learn their offers were not used."},{"f":1,"t":0,"l":"ACK: lease confirmed","n":"The server records the lease and confirms. The device can now configure its interface with the address and the gateway."},{"f":0,"t":0,"l":"Use the address","n":"The device starts to use the network. If another device already used that address, you would see a conflict, so servers check the pool carefully."},{"f":0,"t":1,"l":"Renew at half the lease","n":"After half of the lease time the device asks the same server to extend the lease, so its address does not change while it stays online."},{"f":1,"t":0,"l":"ACK: lease extended","n":"The server extends the lease. If the server is unreachable, the device tries again later, and after the lease ends it must start from DISCOVER."}]},{"id":"cdn-cache","module":"networking","lesson":"networking/http-and-tls","title":"How a CDN serves a cached page","summary":"Edge cache hit, cache miss, and why headers decide what is stored.","actors":["Browser","CDN edge","Origin server"],"steps":[{"f":0,"t":1,"l":"GET /logo.png","n":"The browser is sent to the nearest edge location, usually by DNS or anycast routing, and asks for the file."},{"f":1,"t":1,"l":"Look up the cache","n":"The edge builds a cache key from the URL, and some headers, and checks whether it holds a fresh copy."},{"f":1,"t":2,"l":"Miss: fetch from origin","n":"The edge does not have the object, so it makes a request to the origin server. Only this first request travels the long way."},{"f":2,"t":1,"l":"200 OK, Cache-Control: max-age=3600","n":"The origin replies with the file and headers. Cache-Control says how long the copy may be reused."},{"f":1,"t":0,"l":"200 OK, X-Cache: MISS","n":"The edge stores the object and returns it. The first visitor sees the slower path."},{"f":0,"t":1,"l":"GET /logo.png (next visitor)","n":"Another user in the same region asks for the same file a minute later."},{"f":1,"t":0,"l":"200 OK, X-Cache: HIT","n":"The edge answers from its cache with no trip to the origin. This lowers latency and the load on the origin."},{"f":1,"t":2,"l":"After 1 hour: conditional request","n":"When the copy is stale, the edge can ask the origin if it changed, using ETag. A 304 means the stored copy is still good."}]},{"id":"bash-trap-cleanup","module":"bash","lesson":"bash/temporary-files-and-atomic-writes","title":"Cleaning up with trap when a script is stopped","summary":"How trap runs your cleanup on exit, on Ctrl+C and on errors.","actors":["Script","Shell","Operating system"],"steps":[{"f":0,"t":1,"l":"trap cleanup EXIT INT TERM","n":"The script registers a function to run when the shell exits or receives an interrupt or terminate signal."},{"f":0,"t":0,"l":"tmp=$(mktemp -d)","n":"The script creates a temporary directory for its work. It is the thing that must be removed at the end."},{"f":0,"t":0,"l":"Do the real work","n":"The script downloads and processes files in the temporary directory. This may take minutes."},{"f":2,"t":1,"l":"User presses Ctrl+C (SIGINT)","n":"The terminal sends SIGINT to the script. Without a trap the script would stop and leave the directory behind."},{"f":1,"t":0,"l":"Run cleanup","n":"Bash calls the registered function before it ends. The function removes the temporary directory and releases locks."},{"f":0,"t":2,"l":"rm -rf \"$tmp\"","n":"The cleanup removes files with a quoted variable. If the variable were empty, an unquoted command could delete the wrong path, so check it first."},{"f":1,"t":2,"l":"Exit with a status","n":"The shell exits with the proper status code. A SIGKILL cannot be trapped, so cleanup may not run in that case."}]},{"id":"auto-rollback","module":"cicd","lesson":"cicd/deployment-strategies","title":"Automatic rollback after a failed health check","summary":"A deploy that watches its own health and returns to the last good version.","actors":["Pipeline","Orchestrator","New version","Monitoring"],"steps":[{"f":0,"t":1,"l":"Deploy version 42","n":"The pipeline asks the orchestrator to roll out the new version, and remembers that version 41 was the last good one."},{"f":1,"t":2,"l":"Start new instances","n":"The orchestrator starts a small share of instances on version 42 and keeps the rest on version 41."},{"f":3,"t":2,"l":"Watch error rate and latency","n":"Monitoring compares the new instances with the old ones over a set time window, using the same signals your SLO uses."},{"f":3,"t":0,"l":"Error rate 4% against 0.1%","n":"The new version is clearly worse than the baseline. This is a failed check, and it does not need a person to notice it."},{"f":0,"t":1,"l":"Roll back to version 41","n":"The pipeline tells the orchestrator to restore the last good version and stops the rollout."},{"f":1,"t":2,"l":"Remove version 42","n":"The new instances are drained and removed. Users on the old instances were never affected much, because the exposure was small."},{"f":0,"t":0,"l":"Mark the release failed","n":"The pipeline marks the change as failed, notifies the owner and links the data. Later, the team fixes the cause and tries again."}]},{"id":"nat-gateway","module":"cloud","lesson":"cloud/virtual-networks","title":"How a private server reaches the internet through NAT","summary":"Route table, NAT gateway, and why the internet cannot start connections back.","actors":["Private server","NAT gateway","Internet host"],"steps":[{"f":0,"t":0,"l":"Needs to download updates","n":"The server has only a private address such as 10.0.2.15, so the internet cannot route replies to it directly."},{"f":0,"t":1,"l":"Route 0.0.0.0/0 sends to NAT","n":"The route table of the private subnet sends all non-local traffic to the NAT gateway in a public subnet."},{"f":1,"t":1,"l":"Rewrite the source address","n":"The gateway replaces the private source with its own public address and records the mapping for this connection."},{"f":1,"t":2,"l":"Request from the public address","n":"The internet host sees only the gateway address. The host does not know the private address of the server."},{"f":2,"t":1,"l":"Response to the gateway","n":"The reply returns to the public address of the gateway, as for any other client."},{"f":1,"t":0,"l":"Translate back and forward","n":"The gateway finds the mapping, restores the private destination, and forwards the reply to the server."},{"f":2,"t":1,"l":"Unsolicited connection from outside","n":"A host that tries to connect to the private server first has no mapping, so the gateway drops it. This is why NAT hides the server."},{"f":1,"t":1,"l":"Watch the data charges","n":"NAT gateways bill by the amount of data processed, so large downloads can cost much. Use endpoints for cloud storage and registries."}]},{"id":"presigned-url","module":"cloud","lesson":"cloud/object-storage-and-data-lifecycle","title":"How a pre-signed URL gives temporary access","summary":"Letting a user upload to a private bucket without sharing credentials.","actors":["Browser","Application","Object storage"],"steps":[{"f":0,"t":1,"l":"I want to upload report.pdf","n":"The user asks the application for permission to upload. The bucket itself stays private."},{"f":1,"t":1,"l":"Check who the user is","n":"The application authenticates the user and decides whether this upload is allowed, and for which path."},{"f":1,"t":2,"l":"Sign a PUT request","n":"Using its own credentials, the application creates a signature for one object key, one method and a short expiry, for example 5 minutes."},{"f":1,"t":0,"l":"Pre-signed URL","n":"The URL contains the signature in its query string. Anybody who holds it can use it until it expires, so treat it like a password."},{"f":0,"t":2,"l":"PUT the file to the URL","n":"The browser sends the file directly to storage. The data does not pass through the application server."},{"f":2,"t":2,"l":"Verify the signature","n":"Storage recomputes the signature and checks the expiry and the permissions of the signer. The request is accepted only if everything matches."},{"f":2,"t":0,"l":"200 OK","n":"The object is stored. After the expiry time the same URL stops working."}]},{"id":"image-pull","module":"docker","lesson":"docker/registries-and-supply-chain","title":"How docker pull downloads only the layers it needs","summary":"Manifest, layers, the local cache, and why base images matter.","actors":["Docker CLI","Docker daemon","Registry"],"steps":[{"f":0,"t":1,"l":"docker pull shop/api:1.8","n":"The CLI sends the request to the daemon, which does the work."},{"f":1,"t":2,"l":"Ask for the manifest of the tag","n":"The daemon asks the registry for the manifest. It lists the layers of the image by digest and the configuration."},{"f":2,"t":1,"l":"Manifest: 5 layers","n":"The registry returns the list. Each layer is identified by a hash of its content, so the same layer has the same ID everywhere."},{"f":1,"t":1,"l":"Compare with the local store","n":"The daemon checks which layer digests are already on disk. Layers from the same base image are likely to be present."},{"f":1,"t":2,"l":"Download the missing layers","n":"Only the two new layers are downloaded, in parallel. Three layers say Already exists."},{"f":1,"t":1,"l":"Verify and unpack","n":"Each layer is checked against its digest, and then unpacked into the storage driver."},{"f":1,"t":0,"l":"Status: Downloaded newer image","n":"The image is ready. A tag can move, so for production deployments use the digest, which never changes."}]},{"id":"readiness-probe","module":"kubernetes","lesson":"kubernetes/probes-metrics-and-logging","title":"Readiness probes and traffic","summary":"How a pod is added to and removed from a Service without dropping requests.","actors":["Kubelet","Pod","Endpoints","Service traffic"],"steps":[{"f":1,"t":1,"l":"Container starts","n":"The application starts, loads its cache and connects to the database. This takes about 20 seconds."},{"f":0,"t":1,"l":"Readiness probe: GET /ready","n":"The kubelet calls the probe on the schedule given in the spec. A failure or timeout means not ready."},{"f":1,"t":0,"l":"503 not ready","n":"The pod answers that it is still starting. It is not in the list of endpoints, so no traffic is sent to it."},{"f":0,"t":1,"l":"Probe again after the period","n":"The kubelet keeps asking. Meanwhile the old pods carry the load."},{"f":1,"t":0,"l":"200 ready","n":"The application has finished starting and the probe succeeds as many times as the success threshold requires."},{"f":0,"t":2,"l":"Add the pod to the endpoints","n":"The pod IP is added to the endpoint list of the Service, and the proxies on every node update their rules."},{"f":3,"t":1,"l":"Requests begin to arrive","n":"Traffic is spread across all ready pods. If the probe later fails, the pod is removed from the list again, without a restart."}]},{"id":"systemd-restart","module":"linux","lesson":"linux/processes-and-services","title":"How systemd restarts a crashing service","summary":"Restart policy, back-off, and the start limit that stops a restart loop.","actors":["systemd","Service process","Journal"],"steps":[{"f":0,"t":1,"l":"Start the service","n":"systemd runs the command from the unit file. With Restart=on-failure it will react to a non-zero exit."},{"f":1,"t":2,"l":"Log the output","n":"Standard output and errors of the process are captured by the journal, so you can read them with journalctl -u name."},{"f":1,"t":0,"l":"Exit with status 1","n":"The process crashes, for example because of a missing config file. systemd sees the exit status."},{"f":0,"t":0,"l":"Wait RestartSec","n":"systemd waits for the configured time before trying again, for example 5 seconds, to avoid a busy loop."},{"f":0,"t":1,"l":"Start again","n":"The service is started again. If the cause is not fixed it fails again. This repeats."},{"f":0,"t":0,"l":"Start limit reached","n":"After StartLimitBurst failures within StartLimitIntervalSec, systemd stops trying and marks the unit as failed."},{"f":0,"t":2,"l":"Read the cause","n":"An operator runs journalctl, fixes the config, and then uses systemctl reset-failed before starting the service again."}]},{"id":"metrics-scrape","module":"observability","lesson":"observability/metrics-and-prometheus","title":"How Prometheus scrapes and stores metrics","summary":"Targets, scrape, storage, query, and why the pull model helps.","actors":["Prometheus","Application","Storage","Grafana"],"steps":[{"f":0,"t":0,"l":"Read the target list","n":"Prometheus knows what to scrape from static config or service discovery, for example from Kubernetes pods."},{"f":0,"t":1,"l":"GET /metrics every 15 s","n":"Prometheus pulls the current values in a text format. The application only needs to expose them."},{"f":1,"t":0,"l":"Counters, gauges, histograms","n":"The reply lists metric names with labels and values, such as http_requests_total{status=\"500\"} 42."},{"f":0,"t":2,"l":"Append samples with a timestamp","n":"Each series gets a new sample. Storage cost grows with the number of series, so labels must have few values."},{"f":0,"t":0,"l":"up = 1 for the target","n":"A successful scrape also sets the up metric, and a failed one sets it to 0. That is how you notice a dead target."},{"f":3,"t":2,"l":"Query: rate(http_requests_total[5m])","n":"Grafana sends a PromQL query. rate turns an ever-growing counter into a per-second value."},{"f":2,"t":3,"l":"Series for the graph","n":"The result is drawn as a graph. Alert rules use the same queries and fire when a condition holds for a given time."}]},{"id":"requests-timeout","module":"python","lesson":"python/http-apis-and-json","title":"Why every HTTP call needs a timeout","summary":"What happens to a script when the server stops answering.","actors":["Script","requests library","API server"],"steps":[{"f":0,"t":1,"l":"requests.get(url)","n":"The script makes a call with no timeout argument. By default the library waits with no limit."},{"f":1,"t":2,"l":"Open connection, send request","n":"The library connects and sends the request over the network."},{"f":2,"t":2,"l":"Server hangs","n":"The server accepts the connection and then stops responding, for example because it is overloaded or a firewall dropped packets."},{"f":1,"t":1,"l":"Wait, and wait","n":"With no timeout the call never returns. The script stays stuck, and a cron job or worker slot is used up for good."},{"f":0,"t":1,"l":"requests.get(url, timeout=(3, 10))","n":"The fix: 3 seconds to connect and 10 seconds to read. The numbers are chosen from what is normal for the service."},{"f":1,"t":0,"l":"raises Timeout","n":"After the limit the library raises an exception. The script can retry with back-off, or report a failure."},{"f":0,"t":0,"l":"Log and continue or fail","n":"The script logs the problem with the URL and the time, and moves on or exits with an error. It does not hang."}]},{"id":"oncall-escalation","module":"sre","lesson":"sre/on-call","title":"How an alert escalates to a person","summary":"Page, acknowledge, escalate and hand over to an incident commander.","actors":["Alert system","Primary on-call","Secondary on-call","Incident commander"],"steps":[{"f":0,"t":0,"l":"SLO burn alert fires","n":"Monitoring decides that users are affected and creates a page, with a link to the runbook and the dashboard."},{"f":0,"t":1,"l":"Page the primary","n":"The paging system calls the primary on-call engineer with a push, a text and a phone call."},{"f":1,"t":0,"l":"Acknowledge","n":"The engineer acknowledges within the target time. This stops the escalation timer, and tells others someone is on it."},{"f":1,"t":1,"l":"Triage and mitigate","n":"The engineer looks at the dashboard and the latest deploy. A rollback might be the fastest mitigation."},{"f":1,"t":2,"l":"Ask for help","n":"The problem is larger than expected, so the engineer pages the secondary, who joins the call."},{"f":1,"t":3,"l":"Declare an incident","n":"Impact is large, so the incident commander takes over coordination, while the engineers continue the technical work."},{"f":3,"t":3,"l":"Keep a timeline and updates","n":"The commander posts status updates on a schedule and writes down decisions. This is the raw material for the postmortem."},{"f":0,"t":0,"l":"If nobody acknowledges","n":"Without an acknowledgement, the system escalates to the secondary after a set time, then to a manager. This is why escalation policies matter."}]},{"id":"tf-import","module":"terraform","lesson":"terraform/import-refactor-and-moved-blocks","title":"Bringing an existing resource under Terraform with import","summary":"Config first, import into state, then plan until there is no diff.","actors":["Engineer","Terraform","Cloud API","State file"],"steps":[{"f":0,"t":0,"l":"A bucket exists but is not managed","n":"Someone created it in the console. Terraform does not know about it, and a plan would try to create a second one."},{"f":0,"t":1,"l":"Write the resource block","n":"The engineer writes configuration for the bucket with its real name. An import block or the import command connects the two."},{"f":1,"t":2,"l":"Read the real resource","n":"During import, Terraform asks the cloud API for the attributes of the existing bucket."},{"f":1,"t":3,"l":"Record it in state","n":"The resource is added to the state under its address. Nothing in the cloud has changed yet."},{"f":0,"t":1,"l":"terraform plan","n":"The plan compares the configuration with the state. Differences show where the code does not match the real settings."},{"f":1,"t":0,"l":"Show a diff","n":"For example, the tags in the code are missing in reality. The engineer adjusts the code until the plan shows no changes."},{"f":0,"t":1,"l":"Review before apply","n":"Only when the plan is clean or shows changes you want do you apply. From now on, changes go through code."}]},{"id":"sec-secret-injection","module":"security","lesson":"security/secrets-management","title":"How an app gets a secret without storing it","summary":"Workload identity, a secrets manager and a short-lived credential.","actors":["Application","Identity service","Secrets manager"],"steps":[{"f":0,"t":0,"l":"Start up with no secret inside","n":"The container image holds no passwords. It only knows where to ask and which identity it runs as."},{"f":0,"t":1,"l":"Prove who I am","n":"The platform gives the pod or function a signed identity token. The app presents it to the identity service."},{"f":1,"t":1,"l":"Check the token","n":"The identity service verifies the signature, the issuer and the audience, and maps the workload to a role."},{"f":1,"t":0,"l":"Short-lived access token","n":"The service returns temporary credentials that expire in about an hour. Nothing long-lived is stored on disk."},{"f":0,"t":2,"l":"Read database/password","n":"The app asks the secrets manager for one secret, using the temporary credentials."},{"f":2,"t":2,"l":"Check the policy and log","n":"The manager checks that this role may read only this secret, then writes an audit record of who read it and when."},{"f":2,"t":0,"l":"Return the secret value","n":"The app keeps the value in memory and connects to the database. A rotation job changes the secret on a schedule."}]},{"id":"sec-pipeline-gates","module":"security","lesson":"security/policy-as-code-and-compliance","title":"Security gates in a pull request","summary":"Scans that run before code can merge.","actors":["Developer","Pipeline","Scanners","Reviewer"],"steps":[{"f":0,"t":1,"l":"Open pull request","n":"The developer pushes a branch and opens a pull request, which triggers the pipeline on a clean, isolated runner."},{"f":1,"t":2,"l":"Scan for secrets","n":"A scanner reads the diff and the history of the branch for keys and tokens. A match stops the pipeline at once."},{"f":1,"t":2,"l":"Scan dependencies and code","n":"Software composition analysis lists known vulnerabilities in libraries. Static analysis flags unsafe code patterns."},{"f":1,"t":2,"l":"Scan Terraform and the image","n":"Infrastructure checks find open firewalls. The image scan reports packages with known fixes."},{"f":2,"t":1,"l":"Report: 1 high with a fix","n":"Results are summarised in the pull request. The policy fails the build for high findings that have a fix."},{"f":0,"t":0,"l":"Fix the finding","n":"The developer updates the library, pushes again and the scans repeat. Small fixes are cheap at this stage."},{"f":3,"t":1,"l":"Review and approve","n":"A reviewer sees green checks, reads the change and approves. The branch rules block merge without both."}]},{"id":"sec-image-signing","module":"security","lesson":"security/supply-chain-sboms-and-provenance","title":"Signing an image and verifying it at deploy time","summary":"From build to a cluster that only runs trusted images.","actors":["Pipeline","Registry","Signing service","Cluster admission"],"steps":[{"f":0,"t":0,"l":"Build the image","n":"The pipeline builds on a clean runner from pinned inputs and records an SBOM."},{"f":0,"t":1,"l":"Push and get a digest","n":"The registry stores the image and returns its digest, a hash of the content that cannot change."},{"f":0,"t":2,"l":"Sign the digest","n":"The pipeline asks the signing service to sign the digest with a key or an identity bound token. The signature is stored next to the image."},{"f":3,"t":1,"l":"Deploy request for the digest","n":"Later, someone applies a deployment. The admission controller looks up the image reference before the pod is created."},{"f":3,"t":2,"l":"Verify signature and policy","n":"The controller checks that the signature is valid and was made by the expected pipeline identity."},{"f":3,"t":3,"l":"Allow or deny","n":"A valid signature lets the pod start. An unsigned or altered image is rejected with a clear message."},{"f":3,"t":0,"l":"Report the denial","n":"The deny event reaches the team. This is how a tampered or untested image is stopped before it runs."}]},{"id":"sec-pod-network-policy","module":"security","lesson":"security/kubernetes-security","title":"How a default deny network policy works","summary":"Blocking all pod traffic, then allowing only what is needed.","actors":["Web pod","Network plugin","API pod","Database pod"],"steps":[{"f":0,"t":2,"l":"Call the API pod","n":"Before any policy exists, every pod can reach every other pod. This is what an attacker relies on after a breach."},{"f":1,"t":1,"l":"Apply default deny","n":"A policy that selects all pods and lists no allowed ingress is applied. The plugin programs rules on every node."},{"f":0,"t":3,"l":"Web pod tries the database","n":"The web pod connects directly to the database. The plugin drops the packet because no rule allows it."},{"f":1,"t":1,"l":"Add an allow rule","n":"The team adds a policy: the API pod may reach the database on port 5432. Everything else stays blocked."},{"f":2,"t":3,"l":"API pod connects","n":"The plugin matches the labels of the source and port. The connection is allowed and works as before."},{"f":0,"t":2,"l":"Web pod calls the API","n":"A second allow rule permits web to API on port 8080. The path the application needs is open."},{"f":1,"t":1,"l":"Everything else is denied","n":"A compromised web pod can now reach only one port on one service, which limits what an attacker can do."}]},{"id":"sec-incident-contain","module":"security","lesson":"security/cloud-incident-playbooks","title":"The first hour of a security incident","summary":"Detect, contain, preserve evidence and start recovery.","actors":["Alert system","On-call","Incident commander","Cloud account"],"steps":[{"f":0,"t":1,"l":"Alert: shell in a production container","n":"A runtime detection fires. It names the pod, the user and the command that started."},{"f":1,"t":1,"l":"Confirm it is real","n":"The on-call checks the deploy log and the audit trail. Nobody has a reason to be in that container."},{"f":1,"t":2,"l":"Declare an incident","n":"The on-call pages the incident commander, who opens a channel, assigns roles and starts a timeline."},{"f":2,"t":3,"l":"Contain without destroying","n":"The commander has the pod isolated with a deny network policy, and the service account token revoked. Pods are not deleted yet."},{"f":1,"t":3,"l":"Preserve evidence","n":"A snapshot of the volume and the pod logs are copied to a protected location for the investigation."},{"f":2,"t":3,"l":"Rotate and rebuild","n":"Secrets the pod could read are rotated. The workload is redeployed from a known good, signed image."},{"f":2,"t":2,"l":"Communicate and review","n":"Stakeholders get updates on a schedule. Afterward the team holds a blameless review and ships the control changes."}]},{"id":"exit-code-pipeline","module":"bash","lesson":"bash/safe-automation","title":"How exit codes and pipefail decide success","summary":"Why a failed step inside a pipe can go unnoticed.","actors":["Script","Command A","Command B"],"steps":[{"f":0,"t":1,"l":"Run: A | B","n":"The shell starts both commands, with the output of A connected to the input of B."},{"f":1,"t":1,"l":"A fails with status 2","n":"The first command hits an error, for example a missing file, and exits with status 2."},{"f":2,"t":2,"l":"B runs on empty input","n":"B receives no data, finishes normally and exits with status 0."},{"f":0,"t":0,"l":"Pipeline status: 0","n":"Without pipefail the pipeline reports the status of the last command only, so the failure of A is hidden."},{"f":0,"t":0,"l":"Add set -o pipefail","n":"With pipefail the pipeline returns the status of the last command that failed, which is 2."},{"f":0,"t":0,"l":"set -e stops the script","n":"Now the script exits at that line instead of going on with bad data. Use it together with checks of results that matter."}]},{"id":"blue-green-switch","module":"cicd","lesson":"cicd/deployment-strategies","title":"Switching traffic with a blue-green deploy","summary":"Two identical environments and a fast, safe switch.","actors":["Pipeline","Router","Blue (live)","Green (new)"],"steps":[{"f":2,"t":2,"l":"Blue serves all users","n":"The current version runs in the blue environment and receives all traffic."},{"f":0,"t":3,"l":"Deploy the new version to green","n":"The pipeline installs the new version in an identical idle environment. Users do not see it."},{"f":0,"t":3,"l":"Smoke tests and warm-up","n":"Automated checks call the green environment directly. Caches are warmed so the first users do not see slow pages."},{"f":0,"t":1,"l":"Switch the router to green","n":"One configuration change sends new requests to green. Existing connections finish on blue."},{"f":1,"t":3,"l":"Watch the metrics","n":"Error rate and latency on green are compared with the blue baseline for several minutes."},{"f":0,"t":1,"l":"If bad, switch back","n":"Rollback is the same single switch in the other direction. Blue is still running and untouched."},{"f":0,"t":2,"l":"Retire blue later","n":"After a safe period, blue is kept as the next idle environment. Database changes must work for both versions."}]},{"id":"vpc-endpoint","module":"cloud","lesson":"cloud/virtual-networks","title":"Reaching cloud storage privately with an endpoint","summary":"Keeping traffic off the internet and off the NAT gateway.","actors":["App in private subnet","Route table","VPC endpoint","Object storage"],"steps":[{"f":0,"t":0,"l":"Needs a file from storage","n":"The application uses the storage API name. DNS resolves it to a private address when an endpoint exists."},{"f":0,"t":1,"l":"Look up the route","n":"The route table has an entry that sends the storage prefix to the endpoint, not to the NAT gateway."},{"f":1,"t":2,"l":"Traffic enters the endpoint","n":"The packet goes through the provider network inside your virtual network. It never touches the public internet."},{"f":2,"t":3,"l":"Request reaches storage","n":"The service receives the request and sees that it comes from the endpoint of your network."},{"f":3,"t":3,"l":"Check the endpoint policy","n":"A policy on the endpoint and one on the bucket both allow only your account. A request for another account bucket is denied."},{"f":3,"t":0,"l":"Response returns the same way","n":"The data comes back through the endpoint. There is no NAT data charge and no public path to monitor."}]},{"id":"docker-healthcheck","module":"docker","lesson":"docker/running-containers-in-production","title":"How a container health check works","summary":"From a probe command to a restart decision.","actors":["Docker daemon","Container","Orchestrator"],"steps":[{"f":1,"t":1,"l":"Application starts","n":"The process starts and needs a few seconds before it can serve requests."},{"f":0,"t":1,"l":"Run the health command","n":"At each interval the daemon runs the command from HEALTHCHECK inside the container, for example a request to /health."},{"f":1,"t":0,"l":"Exit 1: unhealthy","n":"The command fails because the app is not ready. The status is starting during the start period, then counts failures."},{"f":0,"t":0,"l":"Retries reached","n":"After the set number of failures in a row the status changes to unhealthy."},{"f":0,"t":2,"l":"Report the status","n":"The status is visible in docker ps and to the orchestrator, which can stop sending traffic to it."},{"f":2,"t":1,"l":"Replace the container","n":"The orchestrator or a restart policy replaces the unhealthy container. The cause should still be found in the logs."}]},{"id":"k8s-config-reload","module":"kubernetes","lesson":"kubernetes/config-and-secrets","title":"How a ConfigMap change reaches a pod","summary":"Env vars versus mounted files and why pods need a restart sometimes.","actors":["Engineer","API server","Kubelet","Pod"],"steps":[{"f":0,"t":1,"l":"Update the ConfigMap","n":"The engineer applies a changed ConfigMap. The API server stores the new version in etcd."},{"f":2,"t":1,"l":"Watch for changes","n":"The kubelet on each node watches the objects used by its pods and sees the update."},{"f":2,"t":3,"l":"Update mounted files","n":"For a ConfigMap mounted as files, the kubelet refreshes the files after a short delay. A program that reads them again sees the new values."},{"f":3,"t":3,"l":"Environment variables stay old","n":"Values copied into environment variables at start-up do not change. The process keeps what it was given."},{"f":0,"t":1,"l":"Roll the deployment","n":"To apply env changes, the engineer restarts the rollout, or uses a checksum annotation so a change triggers a new revision."},{"f":1,"t":3,"l":"New pods start with new values","n":"Pods are replaced gradually, each reading the current ConfigMap, with readiness checks protecting traffic."}]},{"id":"linux-oom-score","module":"linux","lesson":"linux/processes-memory-and-the-oom-killer","title":"How the kernel chooses which process to kill","summary":"Out of memory, OOM scores and what you can do about it.","actors":["Process","Kernel","Administrator"],"steps":[{"f":0,"t":1,"l":"Ask for more memory","n":"A service keeps allocating memory. The kernel agrees as long as free memory or swap exists."},{"f":1,"t":1,"l":"Memory runs out","n":"No free pages are left and reclaiming cache does not help. The kernel must free memory or stop."},{"f":1,"t":1,"l":"Score every process","n":"The kernel gives each process a badness score based on memory use, adjusted by oom_score_adj."},{"f":1,"t":0,"l":"Kill the highest score","n":"The process with the highest score receives SIGKILL. It has no chance to log or clean up."},{"f":1,"t":2,"l":"Message in dmesg","n":"The kernel logs the victim and the memory state. The administrator finds it with dmesg or the journal."},{"f":2,"t":0,"l":"Fix the cause","n":"Set limits with cgroups, fix the leak, add memory or protect key services with a lower oom_score_adj."}]},{"id":"http-redirect-hsts","module":"networking","lesson":"networking/http-and-tls","title":"HTTP to HTTPS and HSTS","summary":"Why the first request is the weak one.","actors":["Browser","Web server"],"steps":[{"f":0,"t":1,"l":"GET http://shop.example.com","n":"The user types the name without a scheme, so the browser tries plain HTTP first."},{"f":1,"t":0,"l":"301 to https://","n":"The server redirects to HTTPS. This first request travelled unencrypted and could be altered by someone on the path."},{"f":0,"t":1,"l":"GET https://shop.example.com","n":"The browser connects with TLS and verifies the certificate before sending the request."},{"f":1,"t":0,"l":"Strict-Transport-Security header","n":"The response says: always use HTTPS for this name for the next year, including subdomains if you choose."},{"f":0,"t":0,"l":"Remember the rule","n":"The browser stores the HSTS policy. Later visits skip the plain HTTP step completely."},{"f":0,"t":0,"l":"Preload for the first visit","n":"Sites can join a preload list built into browsers, so even the very first visit is protected."}]},{"id":"alert-to-dashboard","module":"observability","lesson":"observability/alerting-and-dashboards","title":"From an alert to the cause","summary":"How metrics, traces and logs work together in an investigation.","actors":["Alert","Engineer","Metrics","Traces","Logs"],"steps":[{"f":0,"t":1,"l":"High error rate on checkout","n":"The alert fires on a symptom: 6 percent of requests fail. It links to a dashboard and a runbook."},{"f":1,"t":2,"l":"Open the dashboard","n":"The graph shows errors began at 14:05, right after a deployment marker. One service stands out."},{"f":1,"t":3,"l":"Open a failing trace","n":"A trace of one failed request shows the time spent. The call to the payment service takes 30 seconds then fails."},{"f":1,"t":4,"l":"Search logs by trace ID","n":"Logs from the payment service for that trace show connection pool exhausted. The cause is clear."},{"f":1,"t":1,"l":"Mitigate first","n":"The engineer rolls back the 14:00 release. The error rate returns to normal within minutes."},{"f":1,"t":1,"l":"Write down the timeline","n":"Notes from the alert, graphs and log lines go into the incident record for the review."}]},{"id":"python-context-manager","module":"python","lesson":"python/files-and-processes","title":"How a with block cleans up","summary":"Files and locks that are closed even when errors occur.","actors":["Your code","with statement","File"],"steps":[{"f":0,"t":1,"l":"with open(path) as f:","n":"The with statement calls the object enter method. For a file this opens it and returns the file object."},{"f":1,"t":2,"l":"File is open","n":"Your block runs using f. The operating system holds a file descriptor until it is released."},{"f":0,"t":0,"l":"An exception is raised","n":"Midway through the block an error occurs, such as a parse failure on a bad line."},{"f":1,"t":2,"l":"exit runs anyway","n":"Python calls the exit method before the exception continues. The file is closed."},{"f":1,"t":0,"l":"Exception continues","n":"The error is passed to the caller or handler, with no leaked file descriptor left behind."},{"f":0,"t":0,"l":"Same idea for locks and connections","n":"Any object with enter and exit works, and contextlib helps you write your own for temporary directories or timers."}]},{"id":"slo-review-meeting","module":"sre","lesson":"sre/slos-and-error-budgets","title":"The weekly reliability review","summary":"Using the error budget to decide what to do next.","actors":["SRE","Product team","Dashboard"],"steps":[{"f":0,"t":2,"l":"Open the SLO dashboard","n":"The review starts with the facts: current availability, budget left and the burn rate of the past week."},{"f":2,"t":0,"l":"62 percent of the budget used","n":"At day 20 of 28, more than half of the budget is spent, and most of it by one incident."},{"f":0,"t":1,"l":"Discuss the cause","n":"The group looks at the incident review. Two action items are still open, one of them a missing alert."},{"f":1,"t":0,"l":"Plan for risky changes","n":"The product team lists releases planned for the next week. One touches the same component."},{"f":0,"t":1,"l":"Decide with the policy","n":"The error budget policy says: slow risky releases and finish reliability work first when more than half is gone."},{"f":0,"t":0,"l":"Record the decision","n":"The decisions and owners are written down, and the next review checks them. The numbers, not opinions, set the pace."}]},{"id":"tf-plan-review","module":"terraform","lesson":"terraform/workflows-and-drift","title":"Reading a plan before you apply","summary":"Spotting replacements and surprises.","actors":["Engineer","Terraform","Reviewer"],"steps":[{"f":0,"t":1,"l":"terraform plan -out=plan.bin","n":"Terraform reads the state and the real resources, then computes the difference to the code."},{"f":1,"t":0,"l":"Plan: 1 to add, 1 to change, 1 to destroy","n":"The summary is the first thing to read. A destroy that you did not expect is a stop sign."},{"f":0,"t":0,"l":"Look for forces replacement","n":"Lines marked forces replacement mean the old resource is deleted and a new one created, which may lose data."},{"f":0,"t":2,"l":"Share the plan in the pull request","n":"The reviewer reads the plan output rather than only the code, and checks names, counts and sensitive changes."},{"f":2,"t":0,"l":"Approve or ask for a change","n":"If the plan shows a surprise, the code changes and a new plan is created. Nothing has been applied yet."},{"f":0,"t":1,"l":"terraform apply plan.bin","n":"Applying the saved plan guarantees that what was reviewed is exactly what runs."}]},{"id":"sec-zero-trust-request","module":"security","lesson":"security/identity-authentication-and-zero-trust","title":"How zero trust checks one request","summary":"Identity, device and policy are checked every time.","actors":["User","Identity-aware proxy","Application"],"steps":[{"f":0,"t":1,"l":"Request a page","n":"The user opens an internal app from a managed laptop. The request goes to the proxy, not straight to the app."},{"f":1,"t":1,"l":"Check identity and device","n":"The proxy verifies the sign-in with a hardware key, the device health, and the session age."},{"f":1,"t":1,"l":"Check the policy","n":"A central policy says which groups may reach this app and from which device state. A failure stops the request here."},{"f":1,"t":2,"l":"Forward with a short-lived token","n":"The proxy passes a signed token that names the user and expires in minutes."},{"f":2,"t":2,"l":"Check permission for the action","n":"The application checks that this user may read this record. The proxy check alone is not enough."},{"f":2,"t":0,"l":"Return the data and log the decision","n":"Every allow and deny is logged, so an investigator can reconstruct who reached what."}]},{"id":"sec-oauth-oidc-login","module":"security","lesson":"security/identity-authentication-and-zero-trust","title":"Sign in with OIDC and call an API","summary":"From login to an access token and a protected call.","actors":["Browser","Identity provider","API"],"steps":[{"f":0,"t":1,"l":"Redirect to sign in","n":"The app sends the user to the identity provider with its client id, scope and a random state value."},{"f":1,"t":1,"l":"Authenticate the user","n":"The user signs in with a passkey. The provider never gives the password to the app."},{"f":1,"t":0,"l":"Return a code","n":"The provider redirects back with a one-time authorization code."},{"f":0,"t":1,"l":"Exchange the code","n":"The app swaps the code, with a proof key, for an ID token and a short-lived access token."},{"f":0,"t":2,"l":"Call the API with the token","n":"The access token is sent in a header, never in the URL."},{"f":2,"t":2,"l":"Validate the token","n":"The API checks signature, issuer, audience, expiry and scope before doing any work."},{"f":2,"t":0,"l":"Return only allowed data","n":"The response contains only what the scope and the user's permissions allow."}]},{"id":"sec-sql-injection","module":"security","lesson":"security/application-security-for-devops","title":"How parameterised queries stop injection","summary":"The same input, treated as text instead of code.","actors":["Attacker","Application","Database"],"steps":[{"f":0,"t":1,"l":"Send a crafted name","n":"The attacker enters x' OR '1'='1 into a search box."},{"f":1,"t":1,"l":"Unsafe version joins strings","n":"The code builds SELECT ... WHERE name = 'x' OR '1'='1' and sends it as text."},{"f":1,"t":2,"l":"Database runs the whole text","n":"The condition is always true, so every row is returned."},{"f":2,"t":0,"l":"Data leaks","n":"The attacker receives all users. This is the harm of injection."},{"f":1,"t":2,"l":"Safe version sends a parameter","n":"The code sends the query with a placeholder and the value separately."},{"f":2,"t":1,"l":"Value is treated as data","n":"The database searches for a user literally named x' OR '1'='1 and finds none."}]},{"id":"sec-policy-rollout","module":"security","lesson":"security/policy-as-code-and-compliance","title":"Rolling out a policy without an outage","summary":"Audit, fix, enforce in stages.","actors":["Security team","Cluster","Service owners"],"steps":[{"f":0,"t":1,"l":"Install the policy in audit mode","n":"The rule reports violations but blocks nothing."},{"f":1,"t":0,"l":"Collect the report","n":"A policy report lists every workload that breaks the rule."},{"f":0,"t":2,"l":"Share the list with owners","n":"Each owner gets their findings with a fix example and a deadline."},{"f":2,"t":2,"l":"Fix or request an exception","n":"Owners fix the manifests. A rare exception needs a reason, an owner and an end date."},{"f":0,"t":1,"l":"Enforce in a test namespace","n":"Enforce mode starts where a failure costs little."},{"f":1,"t":0,"l":"Watch the denials","n":"The team checks denied requests and corrects confusing messages."},{"f":0,"t":1,"l":"Enforce everywhere","n":"Production follows once the denial rate is near zero. Exceptions expire automatically."}]},{"id":"sec-ransomware-recovery","module":"security","lesson":"security/ransomware-resilience-and-recovery","title":"Recovering from ransomware with an immutable backup","summary":"Contain, restore in order, and verify.","actors":["Responders","Backup vault","Production"],"steps":[{"f":0,"t":2,"l":"Isolate affected systems","n":"Network access is cut and tokens are revoked so the attacker cannot spread or delete more."},{"f":0,"t":1,"l":"Confirm the vault is intact","n":"The locked copy in the separate account shows no deletions. Retention is still enforced."},{"f":1,"t":2,"l":"Rebuild identity and DNS first","n":"Directory and name servers are rebuilt from known good images and restored from backup."},{"f":1,"t":2,"l":"Restore databases to a clean point","n":"The restore point is chosen before the first sign of the intrusion."},{"f":0,"t":2,"l":"Redeploy applications from signed builds","n":"Applications are deployed from trusted code, not cleaned in place."},{"f":0,"t":2,"l":"Verify and return users in stages","n":"Checks run on each stage before traffic returns. Credentials are rotated."}]},{"id":"x-linux-permission-check","module":"linux","lesson":"linux/users-groups-permissions","title":"How the kernel checks a file permission","summary":"Owner, group, other and the execute bit on directories.","actors":["Process","Kernel","Filesystem"],"steps":[{"f":0,"t":1,"l":"open(/srv/app/data.txt)","n":"The program asks the kernel to open a file. The call carries the user and group ids of the process."},{"f":1,"t":2,"l":"Walk each directory","n":"The kernel needs execute permission on /, /srv and /srv/app to pass through them."},{"f":2,"t":1,"l":"Read the file mode","n":"The filesystem returns the owner, the group and the permission bits of data.txt."},{"f":1,"t":1,"l":"Pick one class","n":"If the user is the owner, the owner bits are used. Otherwise the group bits, otherwise the other bits."},{"f":1,"t":1,"l":"Compare with the request","n":"Opening for reading needs r. Opening for writing needs w. The decision is made on that one class."},{"f":1,"t":0,"l":"Return a handle or an error","n":"A file descriptor on success, or Permission denied. SELinux can still deny after this step."}]},{"id":"x-linux-boot","module":"linux","lesson":"linux/boot-and-kernel","title":"What happens between power on and a login prompt","summary":"Firmware, boot loader, kernel and systemd.","actors":["Firmware","Boot loader","Kernel","systemd"],"steps":[{"f":0,"t":0,"l":"Power on self test","n":"The firmware checks hardware and finds the boot device."},{"f":0,"t":1,"l":"Load the boot loader","n":"The firmware starts GRUB from the EFI partition."},{"f":1,"t":2,"l":"Load kernel and initramfs","n":"GRUB loads the kernel and a small temporary filesystem with the drivers needed to find the root disk."},{"f":2,"t":2,"l":"Mount the real root","n":"The kernel mounts the root filesystem and drops the initramfs."},{"f":2,"t":3,"l":"Start PID 1","n":"The kernel starts systemd as the first process."},{"f":3,"t":3,"l":"Reach the target","n":"systemd starts services in dependency order until multi-user.target and the login prompt appear."}]},{"id":"x-bash-pipe","module":"bash","lesson":"bash/text-processing","title":"How a pipeline connects commands","summary":"Standard output of one command becomes input of the next.","actors":["Shell","grep","wc"],"steps":[{"f":0,"t":0,"l":"Parse cat log | grep ERROR | wc -l","n":"The shell splits the line at the pipe characters into three commands."},{"f":0,"t":1,"l":"Create pipes and start processes","n":"The shell creates a pipe between each pair and starts all commands at the same time."},{"f":1,"t":1,"l":"grep reads and filters","n":"grep reads lines from its standard input and prints only those that contain ERROR."},{"f":1,"t":2,"l":"Pass matching lines","n":"Matching lines flow through the pipe to wc as they are produced."},{"f":2,"t":2,"l":"Count lines","n":"wc -l counts the lines until the pipe closes."},{"f":2,"t":0,"l":"Return the status","n":"Without pipefail the shell reports only the status of the last command."}]},{"id":"x-bash-quoting","module":"bash","lesson":"bash/advanced-patterns","title":"Why quoting protects a variable","summary":"Word splitting and globbing without quotes.","actors":["Script","Shell expansion","Command"],"steps":[{"f":0,"t":0,"l":"file=\"my report.txt\"","n":"The variable holds one name with a space inside."},{"f":0,"t":1,"l":"Run rm $file","n":"Without quotes the shell expands the variable and then splits it on spaces."},{"f":1,"t":2,"l":"Two arguments arrive","n":"rm receives my and report.txt as separate names and may delete the wrong file."},{"f":0,"t":1,"l":"Run rm \"$file\"","n":"With quotes the expansion stays one word."},{"f":1,"t":2,"l":"One argument arrives","n":"rm receives my report.txt exactly as stored."},{"f":2,"t":0,"l":"Safe result","n":"Quote variables by default. Unquoted use is the exception."}]},{"id":"x-python-venv","module":"python","lesson":"python/basics-and-environments","title":"How a virtual environment isolates packages","summary":"Separate site-packages for each project.","actors":["Developer","venv","pip"],"steps":[{"f":0,"t":1,"l":"python -m venv .venv","n":"A folder is created with its own interpreter link and an empty site-packages."},{"f":0,"t":1,"l":"Activate it","n":"The shell puts .venv/bin first in PATH, so python and pip now point there."},{"f":0,"t":2,"l":"pip install requests","n":"pip reads the active environment and installs into its site-packages."},{"f":2,"t":1,"l":"Packages are stored locally","n":"Nothing is written to the system Python, so other projects are not affected."},{"f":0,"t":2,"l":"pip freeze > requirements.txt","n":"The exact versions are recorded so others can rebuild the same environment."},{"f":0,"t":1,"l":"Delete and recreate","n":"Removing the folder and reinstalling from the file gives a clean copy."}]},{"id":"x-python-retry","module":"python","lesson":"python/http-apis-and-json","title":"Retrying a failed API call with backoff","summary":"Waiting longer after each failure.","actors":["Script","API","Timer"],"steps":[{"f":0,"t":1,"l":"First request","n":"The script sends the request with a timeout."},{"f":1,"t":0,"l":"503 Service Unavailable","n":"The server is busy. The error is temporary, so a retry is allowed."},{"f":0,"t":2,"l":"Wait 1 second plus jitter","n":"A small random delay stops many clients from retrying at the same moment."},{"f":0,"t":1,"l":"Second request","n":"The script sends the same request again after the wait."},{"f":1,"t":0,"l":"503 again","n":"The wait grows to 2 seconds, then 4, up to a limit."},{"f":0,"t":1,"l":"Third request succeeds","n":"The call returns 200. If the limit is reached, the script reports the failure instead of looping forever."}]},{"id":"x-net-tcp-handshake","module":"networking","lesson":"networking/latency-mtu-and-network-performance","title":"How a TCP connection starts and ends","summary":"SYN, SYN-ACK and ACK, then FIN.","actors":["Client","Server"],"steps":[{"f":0,"t":1,"l":"SYN","n":"The client picks a starting sequence number and asks to connect."},{"f":1,"t":0,"l":"SYN-ACK","n":"The server confirms and sends its own starting number."},{"f":0,"t":1,"l":"ACK","n":"The client confirms. The connection is open after one and a half round trips."},{"f":0,"t":1,"l":"Send data","n":"Data is split into segments, numbered and acknowledged."},{"f":0,"t":1,"l":"FIN","n":"One side says it has finished sending."},{"f":1,"t":0,"l":"FIN and ACK","n":"The other side closes too. A firewall that drops these packets leaves half open connections."}]},{"id":"x-net-tls","module":"networking","lesson":"networking/http-and-tls","title":"How TLS protects an HTTPS request","summary":"Certificate check and a shared key.","actors":["Browser","Server","CA"],"steps":[{"f":0,"t":1,"l":"ClientHello","n":"The browser lists the TLS versions and ciphers it supports and the server name."},{"f":1,"t":0,"l":"Certificate","n":"The server sends its certificate chain and chooses a cipher."},{"f":0,"t":2,"l":"Verify the chain","n":"The browser checks that a trusted authority signed the certificate, the name matches and it has not expired."},{"f":0,"t":1,"l":"Key exchange","n":"Both sides compute the same session key without sending it."},{"f":1,"t":0,"l":"Finished","n":"Both confirm the handshake. From now on everything is encrypted."},{"f":0,"t":1,"l":"Send the HTTP request","n":"The request and the response travel encrypted with the session key."}]},{"id":"x-docker-build-cache","module":"docker","lesson":"docker/buildkit-caching-and-multi-arch","title":"How the Docker build cache decides what to rebuild","summary":"Layers are reused until something changes.","actors":["Developer","Builder","Cache"],"steps":[{"f":0,"t":1,"l":"docker build .","n":"The builder reads the Dockerfile from top to bottom."},{"f":1,"t":2,"l":"Check FROM and COPY requirements","n":"The builder asks whether this instruction and its input files match a cached layer."},{"f":2,"t":1,"l":"Cache hit","n":"Unchanged instructions reuse the stored layer, which is almost instant."},{"f":1,"t":1,"l":"Find the first change","n":"You edit app code, so the COPY . layer no longer matches."},{"f":1,"t":1,"l":"Rebuild from there on","n":"Every later instruction runs again, because each layer depends on the one before."},{"f":1,"t":0,"l":"Image ready","n":"Putting rarely changed steps first keeps most of the build cached."}]},{"id":"x-docker-compose-up","module":"docker","lesson":"docker/compose","title":"What docker compose up does","summary":"Network, volumes and ordered startup.","actors":["Compose","Docker engine","Containers"],"steps":[{"f":0,"t":0,"l":"Read compose.yaml","n":"Compose parses services, networks, volumes and dependencies."},{"f":0,"t":1,"l":"Create the network","n":"A project network is created. Services find each other by name."},{"f":0,"t":1,"l":"Create the volumes","n":"Named volumes are created if they do not exist."},{"f":1,"t":2,"l":"Start the database","n":"The database container starts and its health check begins."},{"f":2,"t":1,"l":"Report healthy","n":"When the check passes, services that depend on it with the healthy condition can start."},{"f":1,"t":2,"l":"Start the app","n":"The app connects to db by name and the published port opens on the host."}]},{"id":"x-cicd-pr-flow","module":"cicd","lesson":"cicd/building-a-pipeline","title":"From a pull request to production","summary":"Checks, review, merge and deploy.","actors":["Developer","Pipeline","Reviewer","Production"],"steps":[{"f":0,"t":1,"l":"Open a pull request","n":"The pipeline starts with lint, unit tests and scans."},{"f":1,"t":0,"l":"Report the checks","n":"Failed checks block the merge and show the log."},{"f":0,"t":2,"l":"Ask for review","n":"A reviewer reads the change and the test results."},{"f":2,"t":0,"l":"Approve","n":"Approval and green checks unlock the merge."},{"f":1,"t":1,"l":"Build once on main","n":"The pipeline builds one artifact and stores it with a version."},{"f":1,"t":3,"l":"Deploy the same artifact","n":"The tested artifact is promoted step by step to production with a health check."}]},{"id":"x-cicd-cache","module":"cicd","lesson":"cicd/fast-pipelines-caching-parallelism-monorepos","title":"How a pipeline cache speeds up builds","summary":"Dependencies restored by a key.","actors":["Job","Cache store"],"steps":[{"f":0,"t":0,"l":"Compute the cache key","n":"The key is built from the hash of the lock file, so it changes only when dependencies change."},{"f":0,"t":1,"l":"Ask for the key","n":"The job asks the store for an entry with that key."},{"f":1,"t":0,"l":"Hit: restore the files","n":"The dependencies are unpacked in seconds."},{"f":0,"t":0,"l":"Build and test","n":"Only the project code needs work."},{"f":0,"t":1,"l":"Miss: install and save","n":"On a miss the job installs normally and saves the folder under the new key."},{"f":1,"t":0,"l":"Next run is faster","n":"Never cache secrets or build outputs that must be fresh."}]},{"id":"x-k8s-pod-start","module":"kubernetes","lesson":"kubernetes/pods-and-deployments","title":"What happens when you create a pod","summary":"API server, scheduler and kubelet.","actors":["kubectl","API server","Scheduler","Kubelet"],"steps":[{"f":0,"t":1,"l":"kubectl apply -f pod.yaml","n":"The request is authenticated, authorized and validated."},{"f":1,"t":1,"l":"Store in etcd","n":"The pod object is saved with no node assigned."},{"f":2,"t":1,"l":"Scheduler sees an unassigned pod","n":"It filters nodes by resources and rules, then scores them."},{"f":2,"t":1,"l":"Bind to a node","n":"The scheduler writes the chosen node name into the pod."},{"f":3,"t":1,"l":"Kubelet sees its pod","n":"The kubelet on that node pulls the image and starts the containers."},{"f":3,"t":1,"l":"Report Running","n":"Status goes back to the API server and kubectl get pods shows Running."}]},{"id":"x-k8s-hpa","module":"kubernetes","lesson":"kubernetes/autoscaling","title":"How the horizontal autoscaler adds pods","summary":"Metrics, target and replica count.","actors":["Metrics server","Autoscaler","Deployment"],"steps":[{"f":0,"t":0,"l":"Collect CPU use","n":"The metrics server reports current CPU use of every pod."},{"f":1,"t":0,"l":"Read the average","n":"Every 15 seconds the autoscaler reads the average against the target, for example 60 percent."},{"f":1,"t":1,"l":"Compute replicas","n":"desired = current x (current use / target), rounded up."},{"f":1,"t":2,"l":"Scale the Deployment","n":"The autoscaler changes the replica count within the min and max limits."},{"f":2,"t":2,"l":"New pods start","n":"The scheduler places them if nodes have room. Otherwise a node autoscaler must add a node."},{"f":1,"t":2,"l":"Wait before scaling down","n":"A stabilisation window avoids flapping when load drops for a short time."}]},{"id":"x-tf-remote-state","module":"terraform","lesson":"terraform/state","title":"How remote state and locking protect a team","summary":"One source of truth and one writer at a time.","actors":["Engineer","Terraform","Backend"],"steps":[{"f":0,"t":1,"l":"terraform apply","n":"Terraform starts and needs the current state."},{"f":1,"t":2,"l":"Acquire the lock","n":"The backend records who holds the lock. A second apply waits or fails."},{"f":2,"t":1,"l":"Read the state","n":"The latest state is downloaded from the shared backend."},{"f":1,"t":1,"l":"Plan and apply","n":"Terraform compares code, state and reality and makes the changes."},{"f":1,"t":2,"l":"Write the new state","n":"The updated state is saved with a new version."},{"f":1,"t":2,"l":"Release the lock","n":"Others can now run. Versioning allows a rollback of the state file."}]},{"id":"x-tf-module-use","module":"terraform","lesson":"terraform/modules","title":"How a module is reused","summary":"One definition, many environments.","actors":["Root config","Module","Provider"],"steps":[{"f":0,"t":1,"l":"module \"network\" { source = ... }","n":"The root passes variables such as cidr and name."},{"f":1,"t":1,"l":"Define resources","n":"The module creates a VPC, subnets and routes using those inputs."},{"f":1,"t":2,"l":"Provider creates them","n":"The provider translates resources into API calls."},{"f":1,"t":0,"l":"Return outputs","n":"The module exposes subnet ids as outputs."},{"f":0,"t":0,"l":"Use the outputs","n":"Other modules receive the ids by reference."},{"f":0,"t":1,"l":"Reuse for staging","n":"Another call with other inputs creates a second copy without copied code."}]},{"id":"x-cloud-assume-role","module":"cloud","lesson":"cloud/identity-and-access","title":"How a role gives temporary access","summary":"Assume role and short-lived credentials.","actors":["Application","Security token service","Storage"],"steps":[{"f":0,"t":1,"l":"Request the role","n":"The application proves its identity, for example with its instance profile."},{"f":1,"t":1,"l":"Check the trust policy","n":"The service verifies that this identity may assume this role."},{"f":1,"t":0,"l":"Return temporary keys","n":"Credentials with a short expiry are returned."},{"f":0,"t":2,"l":"Call storage","n":"The application signs the request with the temporary keys."},{"f":2,"t":2,"l":"Check the permission policy","n":"The storage service checks that the role may read this bucket."},{"f":2,"t":0,"l":"Return the data","n":"After expiry the keys stop working, so a leak has a short life."}]},{"id":"x-cloud-lambda","module":"cloud","lesson":"cloud/serverless","title":"What happens when a function is invoked","summary":"Cold start, run and scale out.","actors":["Caller","Function service","Execution environment"],"steps":[{"f":0,"t":1,"l":"Invoke the function","n":"An event or an HTTP request arrives."},{"f":1,"t":1,"l":"Find a free environment","n":"If a warm one is free, the request goes to it and no start-up cost is paid."},{"f":1,"t":2,"l":"Cold start","n":"If none is free, a new environment is created and the code is loaded. This adds latency."},{"f":2,"t":2,"l":"Run the handler","n":"The code runs within the memory and time limits."},{"f":2,"t":0,"l":"Return the result","n":"The response goes back. The environment stays warm for a while."},{"f":1,"t":2,"l":"Scale out","n":"More concurrent requests create more environments, up to the account limit."}]},{"id":"x-obs-trace","module":"observability","lesson":"observability/logs-and-traces","title":"How a distributed trace follows a request","summary":"Trace id passed from service to service.","actors":["Gateway","Order service","Payment service","Trace backend"],"steps":[{"f":0,"t":0,"l":"Create a trace id","n":"The first service creates a trace id and a root span."},{"f":0,"t":1,"l":"Pass the context","n":"The id travels in a request header to the next service."},{"f":1,"t":2,"l":"Pass it again","n":"Each service creates a child span and forwards the same trace id."},{"f":2,"t":2,"l":"Slow database call","n":"The payment service records a span for a 900 ms query."},{"f":0,"t":3,"l":"Export spans","n":"Every service sends its spans to the backend in the background."},{"f":3,"t":3,"l":"Assemble the trace","n":"The backend joins spans by trace id and shows where the time went."}]},{"id":"x-obs-log-pipeline","module":"observability","lesson":"observability/log-pipelines","title":"How logs travel from a container to a search page","summary":"Collect, parse, ship and index.","actors":["Container","Collector","Storage","Search UI"],"steps":[{"f":0,"t":0,"l":"Write JSON to standard output","n":"The app writes one event per line with level, message and request id."},{"f":1,"t":0,"l":"Collector tails the file","n":"An agent on the node reads new lines and adds labels such as pod and namespace."},{"f":1,"t":1,"l":"Parse and filter","n":"Fields are parsed, noisy lines are dropped and secrets are masked."},{"f":1,"t":2,"l":"Ship in batches","n":"Batches are sent with a buffer and retry, so a short outage loses nothing."},{"f":2,"t":2,"l":"Index and store","n":"Events are indexed by time and labels, with a retention period."},{"f":3,"t":2,"l":"Query by request id","n":"An engineer searches one request id and sees all events across services."}]},{"id":"x-sre-error-budget","module":"sre","lesson":"sre/slos-and-error-budgets","title":"How an error budget guides releases","summary":"Spend, watch and decide.","actors":["Team","Monitoring","Release process"],"steps":[{"f":0,"t":0,"l":"Set the SLO","n":"For example 99.9 percent of requests succeed over 30 days."},{"f":1,"t":0,"l":"Measure the SLI","n":"Monitoring computes the good request ratio all the time."},{"f":1,"t":1,"l":"Compute the remaining budget","n":"About 43 minutes of failure per month are allowed at 99.9 percent."},{"f":1,"t":2,"l":"Budget is healthy","n":"The team ships features at normal speed."},{"f":1,"t":2,"l":"Budget is nearly spent","n":"Releases slow down and reliability work takes priority."},{"f":2,"t":0,"l":"Review at the end of the period","n":"The team resets, learns from the burn and adjusts the SLO if needed."}]},{"id":"x-sre-postmortem","module":"sre","lesson":"sre/postmortems-and-toil","title":"From incident to learning","summary":"Timeline, causes and follow up.","actors":["Incident lead","Team","Tracker"],"steps":[{"f":0,"t":0,"l":"Collect the timeline","n":"Alerts, chat messages and deploys are put in time order."},{"f":0,"t":1,"l":"Meet within a few days","n":"A facilitator keeps the review blameless and focuses on systems."},{"f":1,"t":1,"l":"Find contributing causes","n":"The group asks why at each step until it reaches process and design gaps."},{"f":1,"t":2,"l":"Write action items","n":"Each item has an owner, a due date and a way to check it."},{"f":2,"t":0,"l":"Track to completion","n":"Open items are reviewed weekly."},{"f":0,"t":1,"l":"Share the lessons","n":"The write-up is shared, so other teams avoid the same failure."}]},{"id":"x-linux-namespaces","module":"linux","lesson":"linux/namespaces-and-cgroups","title":"What a namespace changes for a process","summary":"How the kernel gives a process its own view of the system.","actors":["Container runtime","Kernel","Process","Host"],"steps":[{"f":0,"t":1,"l":"Create with new namespaces","n":"The runtime asks the kernel to start a process with new pid, mount, network and hostname namespaces, using clone or unshare."},{"f":1,"t":2,"l":"Process starts inside","n":"The process begins running, but the kernel gives it a separate list of process ids, mounts and network interfaces."},{"f":2,"t":2,"l":"Sees itself as pid 1","n":"Inside the pid namespace the first process is pid 1, and it cannot see any process of the host in its own process list."},{"f":2,"t":1,"l":"Lists network interfaces","n":"The network namespace has only the interfaces that were attached to it, such as one virtual interface and the loopback."},{"f":3,"t":1,"l":"Host still sees everything","n":"From the host the same process has a normal pid, and tools like lsns and nsenter can enter its namespaces to debug it."},{"f":0,"t":3,"l":"Enter to debug","n":"nsenter runs a host tool inside the namespaces of the process, which helps when the container image has no tools of its own."}]},{"id":"x-linux-cgroup-throttle","module":"linux","lesson":"linux/namespaces-and-cgroups","title":"Memory limit versus CPU limit in a cgroup","summary":"Why going over memory kills a process but going over CPU only slows it.","actors":["Process","cgroup controller","Kernel scheduler","Monitoring"],"steps":[{"f":0,"t":1,"l":"Runs with limits set","n":"The group has memory.max of 512 MB and a CPU quota of half a core, written as files under /sys/fs/cgroup."},{"f":0,"t":2,"l":"Wants a full core","n":"The process has plenty of work and asks the scheduler for CPU time all the time."},{"f":1,"t":2,"l":"Quota used up","n":"After using its quota in the period, the group is paused until the next period starts, so work is spread out over more time."},{"f":2,"t":3,"l":"nr_throttled rises","n":"cpu.stat counts throttled periods. Latency rises but nothing is killed, which makes this problem easy to miss."},{"f":0,"t":1,"l":"Memory grows past the limit","n":"Memory use reaches memory.max and the kernel cannot reclaim enough pages from the group."},{"f":1,"t":0,"l":"OOM kill, exit 137","n":"The kernel kills a process in the group. The runtime reports exit code 137 and OOMKilled, and memory.events counts the kill."}]},{"id":"x-linux-inode-exhaustion","module":"linux","lesson":"linux/disks-and-filesystems","title":"Out of space with free space","summary":"How a filesystem can refuse new files while df shows free blocks.","actors":["Application","Filesystem","Operator","Cleanup job"],"steps":[{"f":0,"t":1,"l":"Create a session file","n":"The application creates a small file for each user session in one directory."},{"f":1,"t":1,"l":"Allocate an inode","n":"Every file needs an inode (a file record) in addition to data blocks, and the number of inodes is fixed when the filesystem is made."},{"f":0,"t":1,"l":"Millions of small files","n":"Over weeks the directory holds nearly thirteen million tiny files, because the cleanup job has been failing quietly."},{"f":1,"t":0,"l":"No space left on device","n":"All inodes are used, so a new file fails with ENOSPC even though most blocks are free."},{"f":2,"t":1,"l":"Run df -h and df -i","n":"df -h shows 60 percent free, but df -i shows 100 percent of inodes used, which names the real problem."},{"f":2,"t":3,"l":"Remove old files, fix the job","n":"The operator deletes old session files, repairs the cleanup job and adds an alert on inode use."}]},{"id":"x-linux-package-verify","module":"linux","lesson":"linux/package-management","title":"How a package install is verified","summary":"Why apt and dnf check signatures before installing.","actors":["Admin","Package manager","Repository","Local keyring"],"steps":[{"f":0,"t":1,"l":"apt install nginx","n":"The admin asks the package manager to install a package and its dependencies."},{"f":1,"t":2,"l":"Fetch repository metadata","n":"The package manager downloads the signed list of packages and versions, named Release or repomd."},{"f":1,"t":3,"l":"Verify the metadata signature","n":"It checks the signature with the repository public key stored in the local keyring. A bad signature stops everything."},{"f":1,"t":2,"l":"Download the package","n":"Package files are fetched, and their checksums must match the signed metadata."},{"f":1,"t":1,"l":"Check checksums and dependencies","n":"The package manager compares each hash with the signed list and resolves which other packages are needed."},{"f":1,"t":0,"l":"Install and run scripts","n":"Files are unpacked and maintainer scripts run as root, which is why you only trust repositories you have checked."}]},{"id":"x-bash-getopts","module":"bash","lesson":"bash/advanced-patterns","title":"How getopts reads options","summary":"How a script turns -d dir -n into variables.","actors":["Caller","Script","getopts","Variables"],"steps":[{"f":0,"t":1,"l":"rotate.sh -d /tmp -k 7 -n","n":"The caller starts the script with short options. -d and -k take a value, and -n is a flag."},{"f":1,"t":2,"l":"getopts \":d:k:nh\" opt","n":"The option string lists the valid letters. A colon after a letter means that the option needs a value."},{"f":2,"t":3,"l":"Set opt and OPTARG","n":"Each call sets opt to the letter and OPTARG to its value, so the case statement can copy it into a variable."},{"f":1,"t":3,"l":"Store dir, keep and dry","n":"The script assigns the values to local variables and uses defaults for options that were not given."},{"f":2,"t":1,"l":"Unknown option gives ?","n":"If the caller passes -x, getopts sets opt to a question mark and the script prints usage to standard error."},{"f":1,"t":0,"l":"Exit code 64 on bad usage","n":"The script exits with 64, the usage error convention, so callers and pipelines can tell a mistake from a failure."}]},{"id":"x-bash-quoted-array","module":"bash","lesson":"bash/arrays-and-parameter-expansion","title":"Why \"${files[@]}\" matters","summary":"What happens to names with spaces when expanding arrays.","actors":["Script","Array","Shell expansion","Command"],"steps":[{"f":0,"t":1,"l":"files=(\"a b\" c)","n":"The array holds two elements. The first one contains a space."},{"f":0,"t":2,"l":"for f in ${files[@]}","n":"Without quotes the shell expands the array and then splits the result on spaces, so the first name becomes two words."},{"f":2,"t":3,"l":"Loop sees a, b and c","n":"The loop body runs three times, with names that do not exist. A backup or a delete would act on the wrong things."},{"f":0,"t":2,"l":"for f in \"${files[@]}\"","n":"With double quotes each element is kept as one word, whatever characters it contains."},{"f":2,"t":3,"l":"Loop sees \"a b\" and c","n":"The loop runs twice with the real names, so the command acts on exactly the files in the array."},{"f":0,"t":3,"l":"Compare counts","n":"A careful script also compares how many items it found with how many it processed, which catches this kind of error."}]},{"id":"x-bash-pipefail","module":"bash","lesson":"bash/safe-automation","title":"What pipefail changes","summary":"How a failure in the middle of a pipeline is noticed.","actors":["Script","Command one","Command two","Shell status"],"steps":[{"f":0,"t":1,"l":"curl -s url | jq .name","n":"The script downloads data and pipes it to a second command."},{"f":1,"t":1,"l":"curl fails, exit 22","n":"The server returned an error, so curl exits with a failure code and prints nothing useful."},{"f":2,"t":2,"l":"jq reads empty input","n":"jq gets empty input, prints nothing and exits with 0, because an empty input is valid for it."},{"f":3,"t":0,"l":"Default: status 0","n":"Without pipefail the pipeline status is the status of the last command, so the script thinks all is well."},{"f":0,"t":3,"l":"set -o pipefail","n":"With pipefail the pipeline returns the failing status of any command in it, here the 22 from curl."},{"f":3,"t":0,"l":"set -e now stops","n":"Combined with set -e, the script stops at the failed download instead of carrying on with empty data."}]},{"id":"x-bash-cron-env","module":"bash","lesson":"bash/debugging-shell-scripts","title":"Why a script works by hand but not in cron","summary":"How the cron environment differs from your login shell.","actors":["Admin","Login shell","cron","Script"],"steps":[{"f":0,"t":1,"l":"Test in terminal","n":"The admin runs the script by hand. It works because the login shell has a long PATH and the right working directory."},{"f":2,"t":3,"l":"cron starts the script","n":"cron runs the command with a minimal environment: a short PATH, no profile files and the home directory as the current directory."},{"f":3,"t":3,"l":"aws: command not found","n":"The tool lives in /usr/local/bin which is not in cron PATH, so the script fails on its first call."},{"f":3,"t":2,"l":"Output is mailed or lost","n":"cron sends output to local mail or drops it, so nobody sees the error unless the script writes a log."},{"f":0,"t":3,"l":"Reproduce with env -i","n":"Running the script with env -i and a short PATH shows the same error in a terminal."},{"f":0,"t":3,"l":"Fix the script","n":"The admin uses full paths, sets PATH at the top, changes to the script directory and redirects output to a log file."}]},{"id":"x-python-threadpool","module":"python","lesson":"python/concurrency-for-operations","title":"A thread pool running 100 checks","summary":"How a worker limit keeps a script fast and polite.","actors":["Script","Thread pool","Remote service","Results"],"steps":[{"f":0,"t":1,"l":"Submit 100 tasks","n":"The script submits one task for each URL and the pool holds them in a queue."},{"f":1,"t":2,"l":"20 workers call out","n":"Only max_workers tasks run at the same time, so the remote service sees at most 20 requests in parallel."},{"f":2,"t":1,"l":"Replies arrive","n":"Each worker waits for its reply. While it waits it releases the interpreter lock, so other workers can run."},{"f":1,"t":3,"l":"Collect with as_completed","n":"Results are handled as soon as each task finishes, in any order, so slow tasks do not delay fast ones."},{"f":2,"t":1,"l":"One call times out","n":"A task that exceeds its timeout raises an error, and the script records the failure instead of stopping."},{"f":0,"t":3,"l":"Report problems","n":"At the end the script prints how many checks failed and which ones, so nothing is lost silently."}]},{"id":"x-python-asyncio","module":"python","lesson":"python/concurrency-for-operations","title":"asyncio with a semaphore","summary":"How one thread handles many network calls at once.","actors":["Main coroutine","Event loop","Semaphore","Remote service"],"steps":[{"f":0,"t":1,"l":"gather(*tasks)","n":"The program creates one coroutine for each URL and asks the event loop to run them all."},{"f":1,"t":2,"l":"Acquire a slot","n":"Each coroutine waits for the semaphore, which allows at most 50 calls at once."},{"f":2,"t":3,"l":"Send the request","n":"A coroutine that got a slot sends its request and then yields control instead of blocking the thread."},{"f":1,"t":1,"l":"Switch to another task","n":"While one call waits for the network, the loop runs another coroutine, so one thread keeps many calls in flight."},{"f":3,"t":1,"l":"Reply arrives","n":"When the response comes in, the loop resumes the waiting coroutine and releases the semaphore slot."},{"f":1,"t":0,"l":"Exceptions as results","n":"With return_exceptions set, a failed call is returned as a value and does not cancel the others."}]},{"id":"x-python-argparse","module":"python","lesson":"python/writing-command-line-tools","title":"From command line to function call","summary":"How argparse validates input before your code runs.","actors":["User","Shell","argparse","main()"],"steps":[{"f":0,"t":1,"l":"svcctl status web --json","n":"The user types a command with a subcommand, a name and a flag."},{"f":1,"t":2,"l":"Pass argv","n":"The shell splits the line into a list of words, which becomes sys.argv in Python."},{"f":2,"t":2,"l":"Match the subparser","n":"argparse finds the status subcommand, checks that the name is present and converts types such as --timeout to float."},{"f":2,"t":0,"l":"Usage error: exit 2","n":"If something is wrong, argparse prints usage and a clear message to standard error and exits with code 2."},{"f":2,"t":3,"l":"Call main logic","n":"With valid input, your function receives an object with the fields, and the code does not parse text itself."},{"f":3,"t":0,"l":"Result on stdout","n":"The tool prints its result, such as JSON, to standard output and logs to standard error, and returns an exit code."}]},{"id":"x-python-traceback","module":"python","lesson":"python/debugging-python","title":"Reading a traceback from the bottom","summary":"How to find the cause of an exception quickly.","actors":["Developer","Traceback","Source code","Test"],"steps":[{"f":0,"t":1,"l":"Run the script","n":"The script fails and Python prints a traceback with several frames."},{"f":0,"t":1,"l":"Read the last line first","n":"The final line names the error and the value, for example KeyError: qty. It is the answer to what went wrong."},{"f":1,"t":2,"l":"Open the frame above","n":"The line above the error shows the file and line where it happened, and the code is displayed next to it."},{"f":0,"t":2,"l":"Work upwards for context","n":"The frames above show how the program got there, so you can see which input led to the failing line."},{"f":0,"t":3,"l":"Write a failing test","n":"The developer copies the smallest failing input into a test, which proves the bug and guards against its return."},{"f":0,"t":2,"l":"Fix and re-run","n":"The code is changed, for example with a default, and the test and the script now pass."}]},{"id":"x-net-ipv6-slaac","module":"networking","lesson":"networking/ipv6-essentials","title":"How a host gets an IPv6 address","summary":"Router advertisements and stateless autoconfiguration.","actors":["Host","Router","Neighbours","DNS server"],"steps":[{"f":0,"t":0,"l":"Make a link-local address","n":"The interface builds an fe80:: address for itself, which works only on this network segment."},{"f":0,"t":2,"l":"Check the address is unique","n":"The host asks the neighbours whether anyone else uses the address, using ICMPv6 neighbour discovery."},{"f":0,"t":1,"l":"Router solicitation","n":"The host asks any router on the segment to announce itself, instead of waiting for the next periodic message."},{"f":1,"t":0,"l":"Router advertisement","n":"The router replies with the network prefix, usually a /64, the default route and sometimes DNS server addresses."},{"f":0,"t":0,"l":"Build a global address","n":"The host combines the prefix with an interface identifier and now has a routable address, with no server keeping a lease."},{"f":0,"t":3,"l":"Find DNS and go","n":"The host learns DNS servers from the advertisement or DHCPv6, and can open connections over IPv6."}]},{"id":"x-net-happy-eyeballs","module":"networking","lesson":"networking/ipv6-essentials","title":"Why a broken IPv6 path makes a site slow","summary":"How clients choose between IPv6 and IPv4 and what a timeout costs.","actors":["Browser","DNS","IPv6 path","IPv4 path"],"steps":[{"f":0,"t":1,"l":"Look up AAAA and A","n":"The browser asks for both IPv6 and IPv4 addresses of the site."},{"f":1,"t":0,"l":"Two answers","n":"DNS returns an AAAA record and an A record, because the site was set up for both."},{"f":0,"t":2,"l":"Try IPv6 first","n":"Clients prefer IPv6, so the first connection attempt goes to the IPv6 address."},{"f":2,"t":0,"l":"No reply","n":"The firewall in front of the site allows only IPv4, so the IPv6 packets are dropped and nothing comes back."},{"f":0,"t":3,"l":"Fall back to IPv4","n":"Modern clients start an IPv4 attempt after a short delay, but older ones wait for the full timeout before they try."},{"f":3,"t":0,"l":"Connected, but late","n":"Users on IPv6-first networks see a delay of seconds or more. Testing with curl -6 finds the problem quickly."}]},{"id":"x-net-mtu-blackhole","module":"networking","lesson":"networking/latency-mtu-and-network-performance","title":"An MTU black hole in a VPN","summary":"Why small packets work and large ones hang.","actors":["Client","VPN tunnel","Router with filter","Server"],"steps":[{"f":0,"t":3,"l":"Small request","n":"A short SSH login or a health check fits into small packets, so everything seems to work."},{"f":3,"t":0,"l":"Large response","n":"The server sends full-size packets of 1500 bytes with the do-not-fragment flag set."},{"f":1,"t":1,"l":"Tunnel adds headers","n":"The VPN wraps each packet in extra headers, so the usable size drops to about 1400 bytes."},{"f":1,"t":2,"l":"Packet too big","n":"A router on the path cannot forward the packet and should send back an ICMP message asking for smaller packets."},{"f":2,"t":3,"l":"ICMP is filtered","n":"A firewall drops that ICMP message, so the server never learns that it must send smaller packets."},{"f":3,"t":0,"l":"Connection stalls","n":"The server keeps resending large packets that never arrive. Lowering the MTU or clamping the MSS fixes it."}]},{"id":"x-net-tcp-window","module":"networking","lesson":"networking/latency-mtu-and-network-performance","title":"Why a fast link can still be slow","summary":"How round trip time limits one TCP connection.","actors":["Sender","Network","Receiver","Operator"],"steps":[{"f":0,"t":1,"l":"Send a window of data","n":"TCP lets the sender have only a limited amount of unacknowledged data in flight, called the window."},{"f":1,"t":2,"l":"Travel 150 ms","n":"The data crosses an ocean and takes about 75 milliseconds one way."},{"f":2,"t":0,"l":"Acknowledgement returns","n":"The sender can only send more when acknowledgements arrive, one round trip later."},{"f":0,"t":0,"l":"Throughput is window over RTT","n":"With a 64 KB window and a 150 ms round trip the sender cannot exceed roughly 3.5 megabits per second."},{"f":3,"t":0,"l":"Measure with iperf3","n":"The operator runs a single stream and then four parallel streams to see how much the window is the limit."},{"f":3,"t":2,"l":"Choose a remedy","n":"Use larger buffers, parallel connections, a closer endpoint or a CDN, rather than buying a bigger link."}]},{"id":"x-docker-buildkit-cache","module":"docker","lesson":"docker/buildkit-caching-and-multi-arch","title":"How layer caching speeds up a build","summary":"What stays cached and what is rebuilt after a code change.","actors":["Developer","BuildKit","Layer cache","Registry"],"steps":[{"f":0,"t":1,"l":"docker build","n":"The developer changes one source file and builds the image again."},{"f":1,"t":2,"l":"FROM and WORKDIR match","n":"The first instructions are identical to the last build, so their layers come straight from the cache."},{"f":1,"t":2,"l":"COPY requirements.txt matches","n":"The dependency list did not change, so the cache is valid and the install step is skipped."},{"f":1,"t":2,"l":"COPY . . differs","n":"The changed file makes this layer different, so it and every following layer are rebuilt."},{"f":1,"t":3,"l":"Push with cache export","n":"In a pipeline the cache is exported to a registry, so a clean runner can import it and avoid starting from zero."},{"f":1,"t":0,"l":"Fast build","n":"Only the last layers were rebuilt, and the build took seconds instead of minutes."}]},{"id":"x-docker-secret-mount","module":"docker","lesson":"docker/buildkit-caching-and-multi-arch","title":"Passing a secret to a build safely","summary":"Why a secret mount leaves nothing in the image.","actors":["Developer","BuildKit","Build container","Final image"],"steps":[{"f":0,"t":1,"l":"--secret id=npmrc","n":"The developer passes the file to the build as a secret, instead of as an ARG or COPY."},{"f":1,"t":2,"l":"Mount for one RUN only","n":"BuildKit mounts the secret in memory at /root/.npmrc, only while that RUN instruction executes."},{"f":2,"t":2,"l":"npm ci uses it","n":"The package manager reads the token from the mounted file and downloads private packages."},{"f":2,"t":1,"l":"Mount disappears","n":"When the instruction ends the mount is removed, and nothing is written into the layer."},{"f":1,"t":3,"l":"Layers created","n":"The image layers contain the installed packages but not the credentials."},{"f":0,"t":3,"l":"Check history","n":"docker history on the finished image shows no token, which a security scan can verify."}]},{"id":"x-docker-oom","module":"docker","lesson":"docker/container-logging-and-resource-limits","title":"What happens when a container hits its memory limit","summary":"From growth to restart.","actors":["Application","Container cgroup","Kernel","Docker"],"steps":[{"f":0,"t":1,"l":"Memory grows","n":"A cache without a size limit holds more entries every minute."},{"f":1,"t":1,"l":"Approach 512 MB","n":"The cgroup limit is 512 MB, and the kernel starts to reclaim pages from the container, which slows it."},{"f":0,"t":1,"l":"Needs more memory","n":"The application asks for pages that the kernel cannot give without going over the limit."},{"f":2,"t":0,"l":"OOM killer","n":"The kernel kills the largest process in the container with SIGKILL. The process has no chance to log or clean up."},{"f":3,"t":3,"l":"Record exit 137","n":"Docker sees the exit, records exit code 137 and OOMKilled true in the container state."},{"f":3,"t":0,"l":"Restart policy","n":"If a policy is set, Docker restarts the container, and the cycle repeats until the cause is fixed."}]},{"id":"x-docker-multiarch","module":"docker","lesson":"docker/buildkit-caching-and-multi-arch","title":"A multi-architecture image","summary":"How one tag works on amd64 and arm64.","actors":["Developer","buildx","Registry","Docker host"],"steps":[{"f":0,"t":1,"l":"buildx --platform amd64,arm64","n":"The developer asks for two platforms in a single build."},{"f":1,"t":1,"l":"Build each platform","n":"buildx builds one image per platform, with native builders or emulation, and the Go or Node tools target the right CPU."},{"f":1,"t":2,"l":"Push images and manifest list","n":"The registry stores both images and a manifest list that maps platform to image digest."},{"f":3,"t":2,"l":"Pull the tag","n":"A host asks for shop:1.4.2 and tells the registry its CPU architecture."},{"f":2,"t":3,"l":"Send the matching image","n":"The registry returns the image that matches the host, so an arm64 laptop and an amd64 server use the same tag."},{"f":3,"t":3,"l":"Run without exec format error","n":"The binary matches the CPU, so the container starts. A single-platform image would fail with exec format error."}]},{"id":"x-cicd-feature-flag","module":"cicd","lesson":"cicd/release-management-and-feature-flags","title":"A gradual release with a feature flag","summary":"Deploy first, release later, and switch off in seconds.","actors":["Pipeline","Application","Flag service","Users"],"steps":[{"f":0,"t":1,"l":"Deploy with flag off","n":"The new code reaches production, but the flag is off, so nobody sees the new behaviour."},{"f":1,"t":2,"l":"Ask for the flag value","n":"On each request the application asks the flag service whether the feature is on for this user, with a safe default."},{"f":2,"t":1,"l":"Staff only","n":"The flag is first enabled for employees, who test the feature on the real system."},{"f":2,"t":1,"l":"One percent of users","n":"The flag is raised to one percent, chosen by a stable hash of the user id, while error rates are watched."},{"f":1,"t":3,"l":"Problem seen","n":"Error rate rises for the group with the flag on. The owner turns the flag off."},{"f":2,"t":1,"l":"Back to normal in seconds","n":"No redeploy is needed. The old behaviour returns for everyone, and the fix is released later."}]},{"id":"x-cicd-test-sharding","module":"cicd","lesson":"cicd/testing-and-quality-gates","title":"Splitting tests across parallel jobs","summary":"How a long test stage becomes short.","actors":["Pipeline","Shard 1","Shard 2","Timing data"],"steps":[{"f":0,"t":3,"l":"Read previous timings","n":"The pipeline loads the durations recorded from earlier runs to know which tests are slow."},{"f":0,"t":1,"l":"Start shard one","n":"The first job gets a share of tests with a similar total duration."},{"f":0,"t":2,"l":"Start shard two","n":"The second job runs at the same time with the rest of the tests."},{"f":1,"t":0,"l":"Report results","n":"Each shard reports its results as soon as it finishes. Failure in any shard fails the stage."},{"f":2,"t":3,"l":"Update timings","n":"Every shard writes new durations, so the next split is better balanced."},{"f":0,"t":0,"l":"Merge reports","n":"The pipeline combines the reports into one view. The stage takes the time of the slowest shard, not the sum."}]},{"id":"x-cicd-cache-key","module":"cicd","lesson":"cicd/fast-pipelines-caching-parallelism-monorepos","title":"A dependency cache keyed on the lockfile","summary":"Why the key decides if the cache is safe.","actors":["Pipeline","Lockfile","Cache store","Package registry"],"steps":[{"f":0,"t":1,"l":"Hash the lockfile","n":"The pipeline computes a hash of package-lock.json. The hash is the cache key."},{"f":0,"t":2,"l":"Look for the key","n":"The cache store is asked for an entry with that exact key."},{"f":2,"t":0,"l":"Hit: restore download cache","n":"If the dependencies did not change, the saved downloads are restored in seconds."},{"f":0,"t":3,"l":"Miss: install from registry","n":"If the lockfile changed, the key is new, so packages are downloaded and installed."},{"f":0,"t":2,"l":"Save under the new key","n":"After a successful install the download directory is stored with the new key for later runs."},{"f":0,"t":0,"l":"Never stale","n":"A branch-name key could serve old packages after a lockfile change. A lockfile hash cannot."}]},{"id":"x-cicd-argocd-sync","module":"cicd","lesson":"cicd/declarative-delivery-with-argo-cd","title":"The Argo CD sync loop","summary":"How the cluster is pulled towards the declared state.","actors":["Developer","Config repository","Argo CD","Cluster"],"steps":[{"f":0,"t":1,"l":"Merge a manifest change","n":"The developer changes the image tag in a manifest and merges it after review."},{"f":2,"t":1,"l":"Detect the new revision","n":"Argo CD polls the repository, or receives a notice, and sees a new revision of the desired state."},{"f":2,"t":3,"l":"Read live state","n":"It reads the objects that currently run in the cluster."},{"f":2,"t":2,"l":"Compute the difference","n":"Desired and live state are compared. The application is shown as OutOfSync with the exact differences."},{"f":2,"t":3,"l":"Apply the change","n":"With automated sync, Argo CD applies the new manifests, and Kubernetes rolls out the new version."},{"f":3,"t":2,"l":"Report health","n":"Argo CD watches the rollout and shows Synced and Healthy. If someone edits the cluster by hand, it shows the drift and can revert it."}]},{"id":"x-k8s-probes","module":"kubernetes","lesson":"kubernetes/probes-metrics-and-logging","title":"Startup, readiness and liveness probes","summary":"Which probe controls what.","actors":["Kubelet","Container","Service endpoints","Operator"],"steps":[{"f":0,"t":1,"l":"Startup probe","n":"While the app is starting, the kubelet runs only the startup probe. Other probes wait until it succeeds."},{"f":1,"t":0,"l":"Startup succeeds","n":"After the application is up, the startup probe passes and the other probes begin."},{"f":0,"t":1,"l":"Readiness probe","n":"The kubelet checks whether the app can serve traffic right now, for example by calling /ready."},{"f":0,"t":2,"l":"Failure removes from endpoints","n":"If readiness fails, the Pod is taken out of the Service endpoints. It is not restarted."},{"f":0,"t":1,"l":"Liveness probe","n":"A separate check detects a stuck process, for example a frozen event loop."},{"f":0,"t":1,"l":"Liveness failure restarts","n":"After several failures the kubelet restarts the container. A liveness check on the database would restart every Pod during a database fault."}]},{"id":"x-k8s-mesh-mtls","module":"kubernetes","lesson":"kubernetes/service-mesh-and-mtls","title":"A request inside a service mesh","summary":"How sidecars add identity and encryption.","actors":["Checkout app","Checkout proxy","Payments proxy","Payments app"],"steps":[{"f":0,"t":1,"l":"Plain call to payments","n":"The application calls http://payments as usual. It knows nothing about certificates."},{"f":1,"t":1,"l":"Intercept and look up","n":"The sidecar proxy catches the outgoing call and finds the destination from the mesh configuration."},{"f":1,"t":2,"l":"Mutual TLS handshake","n":"Both proxies present short-lived certificates that name their workload identities and set up an encrypted connection."},{"f":2,"t":2,"l":"Check authorization policy","n":"The receiving proxy checks that the checkout identity is allowed to call POST /charge."},{"f":2,"t":3,"l":"Forward in plain form","n":"If the policy allows it, the proxy delivers the request to the payments container on the same Pod."},{"f":3,"t":0,"l":"Reply with telemetry","n":"The reply goes back the same way, and both proxies record request counts, errors and latency for the mesh dashboards."}]},{"id":"x-k8s-rbac-check","module":"kubernetes","lesson":"kubernetes/rbac-and-security","title":"How the API server decides on a request","summary":"Authentication, authorization and admission.","actors":["kubectl","API server","RBAC","Admission"],"steps":[{"f":0,"t":1,"l":"kubectl delete pod web","n":"The request reaches the API server with a client certificate or token."},{"f":1,"t":1,"l":"Authenticate","n":"The server works out who is calling: a user, a group or a service account."},{"f":1,"t":2,"l":"Authorize","n":"RBAC looks for a role binding that grants the verb delete on pods in this namespace to the caller."},{"f":2,"t":1,"l":"Deny or allow","n":"With no matching rule the answer is Forbidden. Kubernetes is deny by default, so nothing is allowed unless a rule says so."},{"f":1,"t":3,"l":"Admission controllers","n":"Mutating and validating policies can change or reject the request, for example a rule against privileged Pods."},{"f":1,"t":0,"l":"Write to etcd and reply","n":"If every step passes, the change is stored in etcd and the caller receives the result."}]},{"id":"x-k8s-pvc-binding","module":"kubernetes","lesson":"kubernetes/storage","title":"From a claim to a mounted volume","summary":"How storage reaches a Pod.","actors":["Developer","PersistentVolumeClaim","Provisioner","Pod"],"steps":[{"f":0,"t":1,"l":"Create a claim","n":"The developer asks for 20 GB of storage with a storage class, without choosing a disk."},{"f":1,"t":2,"l":"Provisioner sees the claim","n":"The storage class names a provisioner, which notices that a new claim needs a volume."},{"f":2,"t":2,"l":"Create the disk","n":"The provisioner creates the disk in the cloud or storage system and registers a PersistentVolume for it."},{"f":1,"t":1,"l":"Bind claim and volume","n":"Kubernetes binds the claim to the new volume. The claim status changes from Pending to Bound."},{"f":3,"t":1,"l":"Pod uses the claim","n":"The Pod refers to the claim by name and the scheduler places it on a node that can reach the disk."},{"f":3,"t":3,"l":"Mount into the container","n":"The kubelet attaches and mounts the disk, and the container reads and writes data that survives restarts."}]},{"id":"x-tf-test-layers","module":"terraform","lesson":"terraform/testing-terraform","title":"Testing layers for Terraform changes","summary":"From a quick format check to a real deployment.","actors":["Developer","Pipeline","Plan policy","Test account"],"steps":[{"f":0,"t":1,"l":"Push a change","n":"The developer opens a pull request that changes a module."},{"f":1,"t":1,"l":"fmt, validate, tflint","n":"Within seconds these tools find style problems, wrong references and invalid values, without any cloud call."},{"f":1,"t":1,"l":"Security scan","n":"A scanner reads the code for public storage, open ports and missing encryption."},{"f":1,"t":2,"l":"Check the plan","n":"The plan is converted to JSON and policies reject, for example, public ingress to a database."},{"f":1,"t":3,"l":"Integration test","n":"For widely used modules, terraform test creates real resources with random names in a separate account."},{"f":3,"t":1,"l":"Destroy and report","n":"The test removes its resources, and the result is posted to the pull request before anyone reviews the change."}]},{"id":"x-tf-moved-block","module":"terraform","lesson":"terraform/import-refactor-and-moved-blocks","title":"Renaming a resource without destroying it","summary":"How a moved block keeps the object.","actors":["Developer","Terraform","State","Cloud"],"steps":[{"f":0,"t":0,"l":"Rename in code","n":"The developer changes aws_db_instance.main to aws_db_instance.database for a naming rule."},{"f":1,"t":2,"l":"Look up the new address","n":"Terraform does not find aws_db_instance.database in the state, so it sees a new resource."},{"f":1,"t":3,"l":"Plan: destroy and create","n":"The plan shows the old database destroyed and a new empty one created. This is the dangerous result."},{"f":0,"t":0,"l":"Add a moved block","n":"The developer adds a block that says from the old address to the new address."},{"f":1,"t":2,"l":"Plan again","n":"Terraform renames the entry in the state and the plan says no changes for the database."},{"f":1,"t":3,"l":"Apply changes nothing real","n":"The cloud resource stays untouched. Only the address in the state changed."}]},{"id":"x-tf-apply-saved-plan","module":"terraform","lesson":"terraform/workflows-and-drift","title":"Reviewing and applying the same plan","summary":"Why the pipeline applies the saved plan file.","actors":["Author","Pipeline","Reviewer","Cloud"],"steps":[{"f":0,"t":1,"l":"Open a pull request","n":"The author pushes the change and the pipeline starts."},{"f":1,"t":1,"l":"terraform plan -out=tfplan","n":"The plan is saved to a file and its readable form is posted as a comment."},{"f":2,"t":1,"l":"Read the plan","n":"The reviewer checks the plan for destroys, replacements and surprises, not only the code."},{"f":2,"t":1,"l":"Approve and merge","n":"After approval, the change is merged to the main branch."},{"f":1,"t":3,"l":"terraform apply tfplan","n":"The pipeline applies the saved plan, so exactly what was approved is what runs, even if the cloud changed meanwhile."},{"f":1,"t":0,"l":"Plan again to confirm","n":"A final plan should say no changes. If it does not, the author looks at drift before the next change."}]},{"id":"x-tf-state-split","module":"terraform","lesson":"terraform/environments-and-team-workflows","title":"Splitting state to shorten plans","summary":"Why separate stacks are faster and safer.","actors":["Engineer","Network stack","App stack","Data stack"],"steps":[{"f":0,"t":1,"l":"Change a security group","n":"The engineer needs an urgent change in the network."},{"f":1,"t":1,"l":"Plan reads 80 resources","n":"Only the resources of the network stack are refreshed, so the plan takes about a minute."},{"f":2,"t":2,"l":"App deploy runs at the same time","n":"Another team applies the app stack at the same time, with its own state and lock, so no one waits."},{"f":1,"t":2,"l":"Publish outputs","n":"The network stack exposes subnet ids as outputs, or they are found by tags with data sources."},{"f":2,"t":1,"l":"Read network values","n":"The app stack reads what it needs, without owning or changing those resources."},{"f":3,"t":3,"l":"Database state is separate","n":"A mistake in the app code cannot destroy the data stack, because it is a separate state with separate permissions."}]},{"id":"x-cloud-pilot-light","module":"cloud","lesson":"cloud/high-availability-and-disaster-recovery","title":"Failover with a pilot light","summary":"How a small standby grows when the main region fails.","actors":["Users","Primary region","DNS health check","Secondary region"],"steps":[{"f":0,"t":1,"l":"Normal traffic","n":"All users reach the primary region while data is replicated to the secondary region."},{"f":3,"t":3,"l":"Standby stays small","n":"The secondary holds replicated data and minimal core services, so the cost stays low."},{"f":1,"t":1,"l":"Region fails","n":"A regional outage makes the primary unreachable for users."},{"f":2,"t":2,"l":"Health check fails","n":"The DNS health check sees repeated failures and marks the primary unhealthy."},{"f":2,"t":3,"l":"Scale up the standby","n":"Automation, defined as code, builds out the application tier in the secondary region and promotes the replica database."},{"f":0,"t":3,"l":"Traffic moves","n":"DNS now answers with the secondary region, and the recovery time is the time to scale up plus DNS caching."}]},{"id":"x-cloud-landing-zone","module":"cloud","lesson":"cloud/landing-zones-and-multi-account-strategy","title":"A guardrail in a multi-account setup","summary":"Why even an administrator cannot turn off audit logs.","actors":["Team admin","Workload account","Organisation policy","Log archive account"],"steps":[{"f":0,"t":1,"l":"Try to stop audit logging","n":"An administrator in a workload account tries to disable the audit trail."},{"f":1,"t":2,"l":"Request is evaluated","n":"The request is checked against permissions in the account and against policies attached higher up in the organisation."},{"f":2,"t":1,"l":"Explicit deny","n":"A service control policy denies the stop and delete actions on audit logging for all accounts below it."},{"f":1,"t":0,"l":"Access denied","n":"The administrator receives an error, whatever permissions they hold in the account."},{"f":1,"t":3,"l":"Logs keep flowing","n":"Audit events continue to a central log archive that workload administrators cannot change."},{"f":2,"t":3,"l":"Alert on the attempt","n":"The attempt itself is recorded and a detection rule notifies the security team."}]},{"id":"x-cloud-cdn-oac","module":"cloud","lesson":"cloud/dns-and-cdn","title":"A private bucket behind a CDN","summary":"How a static site is served without making storage public.","actors":["Browser","CDN edge","Origin access control","Private bucket"],"steps":[{"f":0,"t":1,"l":"Request /index.html","n":"The browser connects to the CDN over HTTPS using the site domain and a valid certificate."},{"f":1,"t":1,"l":"Check the edge cache","n":"If the file is cached at this location, the CDN answers at once with no request to the origin."},{"f":1,"t":2,"l":"Cache miss: sign the request","n":"On a miss, the CDN signs the origin request with its own identity."},{"f":2,"t":3,"l":"Bucket accepts only the CDN","n":"The bucket policy allows reads only from this CDN distribution, and public access is blocked."},{"f":3,"t":1,"l":"Return the object","n":"The object travels back to the edge with cache headers such as max-age."},{"f":1,"t":0,"l":"Serve and cache","n":"The CDN returns the file and keeps a copy. Direct requests to the bucket address still fail."}]},{"id":"x-cloud-policy-eval","module":"cloud","lesson":"cloud/security-and-governance","title":"How the cloud decides to allow a request","summary":"Identity policy, resource policy and explicit deny.","actors":["Caller","Provider API","Policy engine","Resource"],"steps":[{"f":0,"t":1,"l":"GetObject on a bucket","n":"A role calls the storage API with temporary credentials."},{"f":1,"t":2,"l":"Gather policies","n":"The engine collects the identity policies, resource policy, permissions boundary and organisation policies."},{"f":2,"t":2,"l":"Look for an explicit deny","n":"Any matching deny ends the evaluation with a refusal, whatever allows exist."},{"f":2,"t":2,"l":"Look for an allow","n":"If there is no deny, at least one statement must allow the action on this resource for this caller."},{"f":2,"t":1,"l":"Decision","n":"No matching allow means a default deny. The result is returned to the API."},{"f":1,"t":3,"l":"Allow or AccessDenied","n":"On allow the object is read. On deny the error names the action and resource, and the audit log records the caller."}]},{"id":"x-obs-red-drilldown","module":"observability","lesson":"observability/red-use-and-golden-signals","title":"From a RED alert to a cause","summary":"Using the standard dashboard to narrow down.","actors":["On-call","Dashboard","Trace store","Log store"],"steps":[{"f":0,"t":1,"l":"Latency alert fires","n":"The p99 for checkout is above its objective, and the alert links to the service dashboard."},{"f":1,"t":0,"l":"Errors flat, duration up","n":"Rate and errors look normal, but the duration panel shows a long tail, so the problem is slowness."},{"f":0,"t":1,"l":"Split by version","n":"Filtering by version shows that only the new release is slow."},{"f":0,"t":2,"l":"Open a slow trace","n":"An example slow trace shows nine seconds waiting for a database connection."},{"f":2,"t":3,"l":"Jump to logs by trace id","n":"The trace id leads to a log line: connection pool exhausted, waiting for a free connection."},{"f":0,"t":0,"l":"Act","n":"The on-call engineer rolls back or raises the pool size, and watches the same p99 panel recover."}]},{"id":"x-obs-cardinality","module":"observability","lesson":"observability/telemetry-cost-and-cardinality","title":"How one label creates millions of series","summary":"Why request ids do not belong on metrics.","actors":["Developer","Application","Metrics server","Operator"],"steps":[{"f":0,"t":1,"l":"Add request_id label","n":"A developer adds the request id as a label on a request counter to help debugging."},{"f":1,"t":2,"l":"Each request is new","n":"Every request creates a label value never seen before, so the server must create a new time series each time."},{"f":2,"t":2,"l":"Memory grows","n":"The head block holds all active series in memory, and memory use rises with every request."},{"f":2,"t":3,"l":"Queries slow down","n":"Dashboards that touch the metric time out, and the server restarts when it runs out of memory."},{"f":3,"t":2,"l":"Find the culprit","n":"The operator lists metrics by series count and sees the counter with millions of series."},{"f":3,"t":1,"l":"Remove and move to logs","n":"The label is removed, relabel rules drop the existing series, and the request id stays in logs and traces."}]},{"id":"x-obs-tail-sampling","module":"observability","lesson":"observability/opentelemetry","title":"Tail sampling in a collector","summary":"Keeping the traces that matter.","actors":["Service A","Service B","Collector","Trace store"],"steps":[{"f":0,"t":1,"l":"Request with trace id","n":"Service A calls B and passes the trace context, so both record spans for the same trace."},{"f":0,"t":2,"l":"Spans sent to collector","n":"Both services send their spans to a collector without deciding what to keep."},{"f":1,"t":2,"l":"Late span arrives","n":"The collector holds spans in memory for a decision period, such as ten seconds, until the trace is complete."},{"f":2,"t":2,"l":"Evaluate policies","n":"If the trace has an error or took over a second, it is kept. Other traces are kept at a rate of five percent."},{"f":2,"t":3,"l":"Store kept traces","n":"Only the chosen traces are written, so storage cost drops, but every failure is still available."},{"f":2,"t":2,"l":"Drop the rest","n":"Dropped traces still count in metrics, so rates and error ratios remain correct."}]},{"id":"x-obs-otel-collector","module":"observability","lesson":"observability/opentelemetry","title":"The path of telemetry through a collector","summary":"Receive, process, export.","actors":["Application","Receiver","Processor","Backend"],"steps":[{"f":0,"t":1,"l":"Send OTLP data","n":"The application sends metrics, logs and traces with the OpenTelemetry protocol to the local collector."},{"f":1,"t":2,"l":"Hand over to processors","n":"The receiver turns the data into an internal format and passes it down the pipeline."},{"f":2,"t":2,"l":"Add and remove attributes","n":"A processor adds the environment and cluster name, and removes fields that contain personal data."},{"f":2,"t":2,"l":"Batch and limit memory","n":"Batches reduce the number of requests, and a memory limiter protects the collector under load."},{"f":2,"t":3,"l":"Export to backends","n":"Exporters send traces to the tracing system, metrics to the metrics store and logs to the log store."},{"f":3,"t":0,"l":"Change backend without code","n":"Switching vendors only changes the exporter configuration. The application code stays the same."}]},{"id":"x-sre-prr","module":"sre","lesson":"sre/production-readiness-reviews","title":"A production readiness review","summary":"How a team finds gaps before launch.","actors":["Service team","Reviewers","Checklist","Launch"],"steps":[{"f":0,"t":1,"l":"Request a review","n":"The team asks for a review six weeks before launch, while design changes are still cheap."},{"f":1,"t":2,"l":"Use the checklist as prompts","n":"Reviewers go through ownership, SLOs, alerts, capacity, rollout, recovery and security."},{"f":1,"t":0,"l":"Ask what happens when","n":"Questions are scenarios, such as what happens when the main dependency becomes slow, not yes or no checks."},{"f":0,"t":2,"l":"Record findings","n":"Each gap becomes an item with an owner and a priority: must fix, should fix or accepted risk."},{"f":0,"t":3,"l":"Fix the must-do items","n":"The team adds a rollback test, a runbook and an alert on user impact before the date."},{"f":1,"t":3,"l":"Agree to launch","n":"Reviewers confirm the launch criteria are met, and the accepted risks are written down with a name."}]},{"id":"x-sre-incident-comms","module":"sre","lesson":"sre/incident-communication-and-stakeholders","title":"Communication during an incident","summary":"Who tells whom what and when.","actors":["Commander","Responders","Comms lead","Customers and support"],"steps":[{"f":0,"t":1,"l":"Declare and assign roles","n":"The commander opens an incident channel, names the roles and sets a severity based on impact."},{"f":2,"t":3,"l":"First status update","n":"Within minutes the comms lead posts a short update: who is affected, what we are doing, when the next update comes."},{"f":1,"t":1,"l":"Investigate and mitigate","n":"Responders work in their channel, make one change at a time and announce each change."},{"f":1,"t":0,"l":"Report findings","n":"The operations lead tells the commander what was found. The commander decides about a rollback or a fail-over."},{"f":2,"t":3,"l":"Regular updates","n":"Updates follow the schedule even when there is no news, so support and customers are not left guessing."},{"f":0,"t":3,"l":"Resolve and follow up","n":"After user metrics are verified, the all-clear goes out, and a blameless review is scheduled within a few days."}]},{"id":"x-sre-load-shedding","module":"sre","lesson":"sre/reliability-patterns","title":"Load shedding under overload","summary":"Protecting the service by refusing some work.","actors":["Clients","Load balancer","Service","Dependency"],"steps":[{"f":0,"t":1,"l":"Traffic doubles","n":"A marketing email sends twice the normal traffic in a few minutes."},{"f":1,"t":2,"l":"Queues build up","n":"Requests wait for threads, latency grows, and clients retry, which adds even more load."},{"f":2,"t":2,"l":"Detect overload","n":"The service sees that its queue is longer than a limit, or that waiting time is above its target."},{"f":2,"t":0,"l":"Reject low priority work fast","n":"Optional requests get a quick 503 with a retry-after header, while checkout requests are still served."},{"f":2,"t":3,"l":"Dependency stays healthy","n":"Fewer calls reach the database, so it does not fall over and slow everything even more."},{"f":0,"t":0,"l":"Clients back off","n":"Well-behaved clients wait with exponential backoff and jitter, and the surge passes without a full outage."}]},{"id":"x-sre-toil-automation","module":"sre","lesson":"sre/postmortems-and-toil","title":"Turning toil into automation","summary":"How a repeated manual task is removed.","actors":["On-call engineer","Ticket queue","Automation","Service"],"steps":[{"f":0,"t":1,"l":"Same ticket again","n":"The engineer clears a full disk by hand for the fourth time this month, following the same five steps."},{"f":0,"t":1,"l":"Measure the toil","n":"The team records minutes per week spent on it. It is manual, repetitive and grows with the service."},{"f":0,"t":2,"l":"Write the automation","n":"A script with checks and a dry run runs the cleanup, and a review makes sure it is safe."},{"f":2,"t":3,"l":"Trigger from an alert","n":"The disk-full alert starts the automation, which frees space and records what it did."},{"f":2,"t":0,"l":"Report the action","n":"The on-call person receives a note instead of a page when the automation succeeds."},{"f":0,"t":1,"l":"Fix the cause","n":"The team removes the source of the growth, so the automation becomes a safety net and not a daily habit."}]},{"id":"x-sec-kms-envelope","module":"security","lesson":"security/encryption-and-key-management","title":"Envelope encryption with a KMS","summary":"How data is protected without exposing the master key.","actors":["Application","KMS","Data key","Storage"],"steps":[{"f":0,"t":1,"l":"Request a data key","n":"The application asks the key management service for a new data key under a named master key."},{"f":1,"t":2,"l":"Return two copies","n":"The service returns the data key in plain form and the same key encrypted under the master key."},{"f":0,"t":2,"l":"Encrypt the data","n":"The application encrypts the data locally with the plain key and then removes it from memory."},{"f":0,"t":3,"l":"Store ciphertext and wrapped key","n":"The encrypted data and the encrypted data key are stored together."},{"f":0,"t":1,"l":"Later: decrypt the data key","n":"To read the data, the application sends the wrapped key to the KMS, which checks policy and logs the call."},{"f":1,"t":0,"l":"Return the plain key","n":"Only roles allowed to use the master key can get the data key back, and the master key never leaves the service."}]},{"id":"x-sec-detection","module":"security","lesson":"security/detection-and-security-logging","title":"From a log event to a detection","summary":"How a suspicious action becomes an alert.","actors":["Cloud account","Central log store","Detection rule","Security analyst"],"steps":[{"f":0,"t":1,"l":"Audit event shipped","n":"Every control plane call is sent within minutes to a central, protected log store."},{"f":1,"t":2,"l":"Rule evaluates events","n":"A rule looks for audit logging being stopped, a new access key for a service user, or a root login."},{"f":2,"t":3,"l":"Alert with context","n":"The alert includes who, from which address, what changed and links to recent activity of that identity."},{"f":3,"t":3,"l":"Triage","n":"The analyst compares with the normal pattern and decides: true positive, false positive or unknown."},{"f":3,"t":0,"l":"Contain","n":"If it is real, the analyst disables the key or isolates the host reversibly, and keeps evidence."},{"f":3,"t":2,"l":"Tune the rule","n":"Known automation is added to an allow list and the rule precision is tracked, so alerts stay trustworthy."}]},{"id":"x-sec-secret-scan-block","module":"security","lesson":"security/secrets-management","title":"A secret scanner in the pipeline","summary":"How a leaked token is stopped before it is merged.","actors":["Developer","Pipeline","Secret scanner","Security team"],"steps":[{"f":0,"t":1,"l":"Push a change","n":"The developer accidentally includes an access key in a configuration file."},{"f":1,"t":2,"l":"Scan the diff","n":"The scanner looks for known token formats and high-entropy strings in the changed lines."},{"f":2,"t":1,"l":"Finding reported","n":"The scanner reports the file and line, and the pipeline fails before the merge."},{"f":1,"t":0,"l":"Developer sees the failure","n":"The message says what was found, and explains that the key must be treated as exposed, even if the change is never merged."},{"f":0,"t":3,"l":"Rotate the key","n":"The developer revokes the key and gets a new one from the secret manager, which is read at run time."},{"f":3,"t":1,"l":"Keep the control on","n":"The security team makes the scanner a required check and reviews how many findings occur each month."}]},{"id":"x-sec-admission-deny","module":"security","lesson":"security/kubernetes-security","title":"An admission policy rejecting a Pod","summary":"How a security rule is enforced before a workload runs.","actors":["Developer","API server","Policy engine","Cluster"],"steps":[{"f":0,"t":1,"l":"Apply a Deployment","n":"The developer applies a manifest whose container runs as root with a privileged flag."},{"f":1,"t":1,"l":"Authenticate and authorize","n":"The request passes authentication and RBAC, because the developer may create Deployments."},{"f":1,"t":2,"l":"Call the admission policy","n":"The API server sends the object to the policy engine for validation."},{"f":2,"t":2,"l":"Evaluate the rules","n":"The engine finds that the rule requires non-root and no privileged mode, and the Pod breaks both."},{"f":2,"t":0,"l":"Deny with a message","n":"The request is rejected with a clear message naming the rule and the field to change."},{"f":0,"t":3,"l":"Fix and apply again","n":"The developer sets runAsNonRoot and removes privileged. The Pod is accepted and scheduled."}]},{"id":"x-ans-run","module":"ansible","lesson":"ansible/playbooks-tasks-and-idempotence","title":"What happens when you run a playbook","summary":"From the command to a changed server, step by step.","actors":["Engineer","Control node","Managed node"],"steps":[{"f":0,"t":1,"l":"Run ansible-playbook","n":"The engineer runs the command with an inventory and a playbook file."},{"f":1,"t":1,"l":"Read inventory and playbook","n":"The control node builds the host list and the ordered list of tasks for each host."},{"f":1,"t":2,"l":"Connect over SSH","n":"Ansible opens an SSH session to each managed node using the configured user and key."},{"f":1,"t":2,"l":"Send a module","n":"For each task, a small Python module is copied to the managed node and run."},{"f":2,"t":2,"l":"Compare and change","n":"The module checks the current state and changes the system only if it differs from the request."},{"f":2,"t":1,"l":"Report the result","n":"The module returns ok, changed or failed as JSON and is removed from the node."},{"f":1,"t":0,"l":"Show the recap","n":"The engineer sees counts per host, and a second run should show changed=0."}]},{"id":"x-ans-handler","module":"ansible","lesson":"ansible/handlers-conditionals-and-loops","title":"A template change triggering a reload","summary":"How a handler runs once when configuration changes.","actors":["Playbook","Template task","Handler queue","Web server"],"steps":[{"f":0,"t":1,"l":"Run the template task","n":"The play reaches the task that renders the web server configuration."},{"f":1,"t":3,"l":"Write the file if different","n":"The rendered text is compared with the file on the server and written only if it differs."},{"f":1,"t":2,"l":"Notify the handler","n":"Because the file changed, the task queues the handler named Reload nginx."},{"f":0,"t":1,"l":"Run later tasks","n":"Other tasks run. More tasks that change things can notify the same handler."},{"f":0,"t":2,"l":"End of the play","n":"When all tasks finish for the host, the queued handlers are due."},{"f":2,"t":3,"l":"Reload once","n":"The handler reloads the web server a single time, even if several tasks notified it."}]},{"id":"x-ans-vault","module":"ansible","lesson":"ansible/vault-secrets-and-safe-practice","title":"How Vault protects a password in a run","summary":"Where the secret is encrypted and where it appears in clear text.","actors":["Repository","Engineer or pipeline","Control node","Target host"],"steps":[{"f":0,"t":0,"l":"Store the secret encrypted","n":"The password sits in the repository inside an encrypted vault file."},{"f":1,"t":2,"l":"Provide the vault password","n":"At run time the vault password is typed or fetched from a secret store, never read from the repository."},{"f":2,"t":0,"l":"Fetch the file","n":"The control node reads the encrypted file and decrypts it in memory."},{"f":2,"t":2,"l":"Render the task","n":"The task uses the value, and no_log keeps it out of console output and logs."},{"f":2,"t":3,"l":"Write the secret safely","n":"The password goes into a file on the host with strict owner and permissions."},{"f":3,"t":3,"l":"Service reads the file","n":"The application reads the password locally. No other user on the host can read it."}]},{"id":"x-ans-rolling","module":"ansible","lesson":"ansible/ansible-at-scale","title":"A rolling update with a canary","summary":"How serial batches and health checks limit damage.","actors":["Playbook","Load balancer","Canary host","Remaining hosts"],"steps":[{"f":0,"t":1,"l":"Drain the first host","n":"The play asks the load balancer to stop sending traffic to the canary host."},{"f":0,"t":2,"l":"Update the canary","n":"The new package is installed and the service restarted on that host only."},{"f":2,"t":2,"l":"Wait for health","n":"The play retries the health endpoint until it answers or the retry limit is reached."},{"f":0,"t":1,"l":"Return it to service","n":"If healthy, the canary goes back into the load balancer and receives real traffic."},{"f":0,"t":3,"l":"Continue in waves","n":"The play repeats the same steps for the next batch, then the next."},{"f":0,"t":0,"l":"Stop on failure","n":"If failures pass max_fail_percentage the play stops and the remaining hosts stay on the old version."}]},{"id":"x-ans-tf","module":"ansible","lesson":"ansible/ansible-at-scale","title":"Terraform and Ansible working together","summary":"Provisioning first, configuration second.","actors":["Terraform","Cloud","Inventory","Ansible"],"steps":[{"f":0,"t":1,"l":"Create the servers","n":"Terraform asks the cloud to create networks, instances and security rules."},{"f":1,"t":0,"l":"Return the addresses","n":"The cloud reports the new instance addresses, which Terraform records in state and outputs."},{"f":2,"t":1,"l":"Build the inventory","n":"A dynamic inventory plugin lists current instances by tag or reads the outputs."},{"f":3,"t":2,"l":"Select the hosts","n":"Ansible reads the inventory and groups the new hosts by role."},{"f":3,"t":1,"l":"Configure over SSH","n":"Ansible installs packages, writes files and starts services on each instance."},{"f":3,"t":0,"l":"Report back","n":"A clean second run shows changed=0. Later infrastructure changes go back through Terraform."}]},{"id":"x-db-query","module":"databases","lesson":"databases/indexes-and-query-plans","title":"How a query reaches the data","summary":"What the database does between your SQL and the answer.","actors":["Client","Planner","Index and table","Write-ahead log"],"steps":[{"f":0,"t":1,"l":"Send SQL","n":"The client sends a query over a connection to the database."},{"f":1,"t":1,"l":"Parse and plan","n":"The planner checks the syntax and estimates the cost of different ways to run it."},{"f":1,"t":2,"l":"Choose an index","n":"If an index fits and the query returns few rows, the plan uses it instead of scanning the table."},{"f":2,"t":2,"l":"Read the rows","n":"Needed pages come from memory if cached, or from disk if not."},{"f":2,"t":0,"l":"Return the result","n":"The matching rows travel back to the client."},{"f":0,"t":3,"l":"A write is logged first","n":"For an update the change is written to the log and flushed before the commit is acknowledged."}]},{"id":"x-db-lock","module":"databases","lesson":"databases/transactions-and-locking","title":"How a long transaction blocks a migration","summary":"One idle session can stop a busy table.","actors":["Report session","ALTER TABLE","App queries","Database"],"steps":[{"f":0,"t":3,"l":"Open a transaction","n":"A reporting session starts a transaction and reads the orders table, then stays open."},{"f":1,"t":3,"l":"Ask for a strong lock","n":"A migration runs ALTER TABLE and needs a lock that conflicts with the open transaction."},{"f":1,"t":1,"l":"Wait in the queue","n":"The ALTER cannot proceed and waits for the report to finish."},{"f":2,"t":3,"l":"New queries queue behind it","n":"Normal application queries now wait behind the queued ALTER."},{"f":3,"t":2,"l":"Connections pile up","n":"The connection pool fills with waiting statements and the application times out."},{"f":1,"t":3,"l":"Cancel the ALTER","n":"Cancelling the migration releases the queue at once. Setting lock_timeout would have done this automatically."}]},{"id":"x-db-pitr","module":"databases","lesson":"databases/backups-and-recovery","title":"Point-in-time recovery","summary":"Restoring to the minute before a mistake.","actors":["Primary","Archive","Restore host","Operator"],"steps":[{"f":0,"t":1,"l":"Archive the log continuously","n":"As changes are made, the write-ahead log segments are copied to the archive."},{"f":1,"t":1,"l":"Keep a base backup","n":"A full physical backup is taken regularly and stored with the archive."},{"f":3,"t":3,"l":"Choose the target time","n":"After a bad delete at 14:00, the operator picks 13:59 as the recovery target."},{"f":1,"t":2,"l":"Restore the base backup","n":"The restore host receives the latest base backup taken before that time."},{"f":1,"t":2,"l":"Replay the log","n":"Archived log segments are applied until the target time is reached."},{"f":2,"t":3,"l":"Verify and promote","n":"The operator checks the data, then promotes the restored server or copies back the missing rows."}]},{"id":"x-db-failover","module":"databases","lesson":"databases/replication-and-failover","title":"A safe database failover","summary":"Quorum, fencing, promotion and redirection.","actors":["Health checks","Quorum","Replica","Clients"],"steps":[{"f":0,"t":1,"l":"Primary stops answering","n":"Several health checks fail, and the group votes on whether the primary is really down."},{"f":1,"t":1,"l":"Reach agreement","n":"A majority agrees, which avoids acting on one lost network packet."},{"f":1,"t":1,"l":"Fence the old primary","n":"The old primary is cut off so it cannot accept writes if it comes back."},{"f":1,"t":2,"l":"Pick the best replica","n":"The most up-to-date replica is chosen to limit lost commits."},{"f":2,"t":2,"l":"Promote it","n":"The replica stops replaying and becomes the new primary."},{"f":2,"t":3,"l":"Redirect clients","n":"A proxy, virtual address or DNS change sends clients to the new primary, and connections reconnect."}]},{"id":"x-db-pool","module":"databases","lesson":"databases/performance-and-connection-pooling","title":"Why a connection pooler helps","summary":"Many clients sharing a few database connections.","actors":["App instances","Pooler","Database","Monitoring"],"steps":[{"f":0,"t":1,"l":"Hundreds of clients connect","n":"Each application instance opens its pool to the pooler instead of the database."},{"f":1,"t":2,"l":"Few real connections","n":"The pooler keeps a small set of server connections open to the database."},{"f":0,"t":1,"l":"A transaction starts","n":"A client sends a transaction and the pooler assigns it a free server connection."},{"f":1,"t":2,"l":"Run and release","n":"When the transaction ends, the server connection returns to the pool for another client."},{"f":2,"t":3,"l":"Stable resources","n":"The database sees a steady, small number of sessions and keeps memory for queries."},{"f":3,"t":1,"l":"Watch the queue","n":"Monitoring shows clients waiting for a connection, which tells you when to tune or scale."}]},{"id":"x-ans-inventory","module":"ansible","lesson":"ansible/ansible-basics-inventory-and-ad-hoc","title":"How Ansible finds the hosts to change","summary":"From an inventory file and a group name to a list of machines.","actors":["Engineer","Control node","Inventory","Target hosts"],"steps":[{"f":0,"t":1,"l":"Run a play against a group","n":"The engineer runs a playbook that says hosts: web. Ansible must now work out which machines belong to web."},{"f":1,"t":2,"l":"Read the inventory","n":"The control node reads the inventory file or script, where machines are listed and put into groups."},{"f":2,"t":1,"l":"Expand the group","n":"The inventory returns every host in web, including hosts that are in child groups of web."},{"f":1,"t":2,"l":"Merge variables","n":"Group variables and host variables are collected, and the more specific host value wins over the group value."},{"f":1,"t":3,"l":"Connect to each host","n":"The control node opens an SSH connection to every host in the list, a few at a time (the forks setting)."},{"f":3,"t":1,"l":"Report results","n":"Each host returns ok, changed, failed or unreachable, and the run summary counts them per host."}]},{"id":"x-ans-idempotent","module":"ansible","lesson":"ansible/playbooks-tasks-and-idempotence","title":"Why running a playbook twice is safe","summary":"A module checks the current state before it changes anything.","actors":["Playbook","Module","Target host","Run summary"],"steps":[{"f":0,"t":1,"l":"Task asks for a state","n":"The task says a package must be present or a line must exist in a file. It describes the end state, not the steps."},{"f":1,"t":2,"l":"Inspect the host","n":"The module looks at the host: is the package installed, does the line already exist?"},{"f":2,"t":1,"l":"State already matches","n":"On the second run the host already looks as requested, so there is nothing to do."},{"f":1,"t":3,"l":"Report ok","n":"The module reports ok and changes nothing, so the summary shows changed=0 for that task."},{"f":1,"t":2,"l":"State differs on a new host","n":"On a different host the package is missing, so the module installs it."},{"f":1,"t":3,"l":"Report changed","n":"That host is reported as changed. Counting changed tasks tells you whether a second run found drift."}]},{"id":"x-ans-precedence","module":"ansible","lesson":"ansible/variables-facts-and-templates","title":"Which variable value wins","summary":"Several places define the same variable, and Ansible has a fixed order.","actors":["Role defaults","Group variables","Host variables","Command line","Task using the variable"],"steps":[{"f":0,"t":4,"l":"Start with role defaults","n":"A role ships a default value, designed to be the easiest thing to override. It has very low priority."},{"f":1,"t":4,"l":"Group variables override defaults","n":"A value set for the group in the inventory replaces the role default for all hosts in that group."},{"f":2,"t":4,"l":"Host variables override groups","n":"A value set for one host is more specific, so it replaces the group value on that machine only."},{"f":3,"t":4,"l":"Extra variables win","n":"A value passed with -e on the command line beats everything else, which makes it handy and risky."},{"f":4,"t":4,"l":"Use the final value","n":"The task sees one value. When it is not the one you expected, run with -vvv or use the debug module."},{"f":4,"t":2,"l":"Keep it simple","n":"Define each variable in as few places as you can, so the answer to which value wins is obvious."}]},{"id":"x-ans-template","module":"ansible","lesson":"ansible/variables-facts-and-templates","title":"Turning a template into a config file","summary":"Facts and variables are merged into a Jinja2 template on the control node.","actors":["Template file","Variables and facts","Control node","Target host"],"steps":[{"f":2,"t":3,"l":"Gather facts","n":"The control node collects facts such as the host name, addresses and memory from the target."},{"f":2,"t":1,"l":"Combine with variables","n":"Facts are joined with inventory and role variables to build the data that the template can use."},{"f":2,"t":0,"l":"Read the template","n":"The template is a normal file with placeholders such as a listen port and a loop over backend servers."},{"f":2,"t":2,"l":"Render the text","n":"Jinja2 replaces the placeholders and runs the loops, producing the final text on the control node."},{"f":2,"t":3,"l":"Copy the result","n":"The template module compares the rendered text with the file on the host and writes it only if different."},{"f":3,"t":3,"l":"Notify a handler","n":"When the file changed, the task notifies a handler so the service reloads once at the end."}]},{"id":"x-ans-role","module":"ansible","lesson":"ansible/roles-and-collections","title":"What happens when a role is applied","summary":"A role bundles tasks, defaults, templates and handlers behind one name.","actors":["Playbook","Role","Task list","Target host"],"steps":[{"f":0,"t":1,"l":"Name the role","n":"The playbook lists roles: [nginx]. Ansible looks for the role folder in the roles path or a collection."},{"f":1,"t":1,"l":"Load defaults","n":"The role defaults load first as low priority variables, so users of the role can change them."},{"f":1,"t":2,"l":"Queue the tasks","n":"The tasks in tasks/main.yml are added to the play in order, with the role variables available."},{"f":2,"t":3,"l":"Run the tasks","n":"Each task runs on the target host. Templates and files come from the role's own folders."},{"f":2,"t":1,"l":"Collect handler notifications","n":"Tasks that changed something notify handlers. Handlers run after the tasks of the play."},{"f":1,"t":3,"l":"Restart or reload once","n":"The handler runs one time, even if five tasks notified it, and the service picks up the new config."}]},{"id":"x-ans-check-mode","module":"ansible","lesson":"ansible/testing-and-linting-ansible","title":"Previewing a change with check mode","summary":"Check mode and diff show what would change without changing it.","actors":["Engineer","Ansible","Target host","Review"],"steps":[{"f":0,"t":1,"l":"Run with --check --diff","n":"The engineer adds the two flags to the normal command. Nothing will be written to the hosts."},{"f":1,"t":2,"l":"Ask each module what it would do","n":"Modules that support check mode compare the desired state with the real state and only report."},{"f":2,"t":1,"l":"Return would-change results","n":"The host answers with changed or ok, and for files the diff of old and new content."},{"f":1,"t":0,"l":"Show the diff","n":"The engineer reads exactly which lines would be added or removed on which hosts."},{"f":0,"t":3,"l":"Review the preview","n":"A colleague checks the diff. Surprises here are cheap, because nothing has been changed yet."},{"f":0,"t":1,"l":"Run for real","n":"After approval the same command runs without --check. Tasks that cannot preview, such as shell commands, still need care."}]},{"id":"x-ans-debug","module":"ansible","lesson":"ansible/debugging-ansible-runs","title":"Debugging a failed run step by step","summary":"From a vague error to the line that explains it.","actors":["Engineer","Ansible output","Target host","Playbook"],"steps":[{"f":0,"t":1,"l":"Read the failing task","n":"The output names the task, the host and the error message. Start with the first failure, not the last."},{"f":0,"t":1,"l":"Add verbosity","n":"Running again with -vvv shows the exact arguments and the connection details used for the task."},{"f":1,"t":2,"l":"Check the connection","n":"If the host is unreachable, test SSH by hand with the same user and key to separate network from Ansible."},{"f":0,"t":3,"l":"Print the variables","n":"A debug task prints the variable the module receives, which often exposes a wrong or empty value."},{"f":0,"t":3,"l":"Narrow with limit and tags","n":"Use --limit for one host and --start-at-task to repeat only the failing part of the run."},{"f":0,"t":3,"l":"Fix and run again","n":"After the fix, run the whole play again. Because tasks are idempotent, the earlier steps report ok."}]},{"id":"x-ans-collection","module":"ansible","lesson":"ansible/roles-and-collections","title":"Installing and using a collection","summary":"How modules from a collection reach your playbook.","actors":["requirements.yml","Control node","Collection source","Playbook"],"steps":[{"f":0,"t":1,"l":"List the collections","n":"The requirements file names each collection and a version range, so every engineer gets the same set."},{"f":1,"t":2,"l":"Download","n":"ansible-galaxy collection install fetches the packages from the configured source."},{"f":2,"t":1,"l":"Store locally","n":"The collections are unpacked into a folder that Ansible searches for modules, roles and plugins."},{"f":3,"t":1,"l":"Use the full name","n":"The playbook calls a module by its full name, such as community.general.ufw, so there is no doubt where it comes from."},{"f":1,"t":3,"l":"Run the module","n":"Ansible loads the module code from the collection and runs it like any built-in module."},{"f":0,"t":0,"l":"Pin and review versions","n":"Pinning versions in the requirements file means an update is a reviewed change, not a surprise."}]},{"id":"x-db-index","module":"databases","lesson":"databases/indexes-and-query-plans","title":"How an index speeds up a query","summary":"A lookup that walks a tree instead of reading every row.","actors":["Application","Query planner","Index","Table"],"steps":[{"f":0,"t":1,"l":"Send a query","n":"The application asks for the orders of customer 42. The planner decides how to find them."},{"f":1,"t":3,"l":"Option one: scan the table","n":"Without an index the database would read every row and test each one, which is slow on a large table."},{"f":1,"t":2,"l":"Option two: use the index","n":"An index on customer_id is a sorted structure, so the planner picks it when few rows match."},{"f":2,"t":2,"l":"Walk the tree","n":"The database descends a few levels of the tree to find the entries for customer 42."},{"f":2,"t":3,"l":"Fetch the matching rows","n":"The index entries point to the rows, and only those rows are read from the table."},{"f":3,"t":0,"l":"Return the result","n":"The answer comes back in milliseconds. The cost is that every insert and update must also maintain the index."}]},{"id":"x-db-explain","module":"databases","lesson":"databases/indexes-and-query-plans","title":"Reading a query plan","summary":"What EXPLAIN tells you before you change anything.","actors":["Engineer","Database","Planner","Plan output"],"steps":[{"f":0,"t":1,"l":"Prefix the query with EXPLAIN","n":"The engineer asks the database how it would run the query, without necessarily running it."},{"f":1,"t":2,"l":"Estimate costs","n":"The planner uses table statistics to estimate rows and cost for each possible way of running the query."},{"f":2,"t":3,"l":"Choose the cheapest plan","n":"The plan lists steps such as a sequential scan, an index scan and a join method, with row estimates."},{"f":3,"t":0,"l":"Read from the inside out","n":"The most nested step runs first. Look for a scan on a big table that returns few rows."},{"f":0,"t":1,"l":"Compare estimate and reality","n":"EXPLAIN ANALYZE runs the query and shows actual rows. A big gap suggests stale statistics."},{"f":0,"t":1,"l":"Change one thing","n":"Add an index or rewrite the query, then explain again. Keep the change only if the plan really improved."}]},{"id":"x-db-mvcc","module":"databases","lesson":"databases/postgres-vacuum-bloat-and-maintenance","title":"Readers and writers without waiting","summary":"Multi-version concurrency lets a reader see a steady snapshot.","actors":["Reader","Writer","Row versions","Commit log"],"steps":[{"f":0,"t":2,"l":"Reader starts a transaction","n":"The reader gets a snapshot, which means it sees only data committed before it started."},{"f":1,"t":2,"l":"Writer updates a row","n":"The writer does not overwrite the row. It creates a new version and marks the old one as replaced."},{"f":0,"t":2,"l":"Reader still sees the old version","n":"The reader keeps reading the old version, so it is not blocked and sees consistent data."},{"f":1,"t":3,"l":"Writer commits","n":"The commit is recorded. New transactions will now see the new version of the row."},{"f":0,"t":3,"l":"Reader finishes","n":"When the reader ends, old versions that nobody needs any more can be removed."},{"f":2,"t":2,"l":"Clean up dead versions","n":"A background process (vacuum in some databases) removes them. Very long transactions delay this cleanup."}]},{"id":"x-db-deadlock","module":"databases","lesson":"databases/transactions-and-locking","title":"How a deadlock happens and resolves","summary":"Two transactions wait for each other until one is cancelled.","actors":["Transaction A","Transaction B","Row 1","Row 2","Lock manager"],"steps":[{"f":0,"t":2,"l":"A locks row 1","n":"Transaction A updates row 1 and holds a lock on it until it commits."},{"f":1,"t":3,"l":"B locks row 2","n":"Transaction B updates row 2 and holds that lock."},{"f":0,"t":3,"l":"A wants row 2","n":"A now needs row 2, which B holds, so A waits."},{"f":1,"t":2,"l":"B wants row 1","n":"B needs row 1, which A holds. Both are now waiting for each other and neither can continue."},{"f":4,"t":4,"l":"Detect the cycle","n":"The lock manager notices the circular wait after a short timeout."},{"f":4,"t":1,"l":"Cancel one transaction","n":"One transaction is rolled back with a deadlock error, and the other can finish. The application should retry the cancelled one."}]},{"id":"x-db-replica-lag","module":"databases","lesson":"databases/replication-and-failover","title":"Why a replica can show old data","summary":"Replication copies changes after the primary has committed them.","actors":["Application","Primary","Replication stream","Replica"],"steps":[{"f":0,"t":1,"l":"Write to the primary","n":"The application saves an order. The primary commits it and returns success."},{"f":1,"t":2,"l":"Send the change","n":"The change is written to a log and streamed to replicas. This takes some time."},{"f":0,"t":3,"l":"Read from the replica at once","n":"The application immediately reads the order from a replica to spread the load."},{"f":3,"t":0,"l":"Old answer","n":"The replica has not applied the change yet, so the order seems missing. This is replica lag."},{"f":2,"t":3,"l":"Replica catches up","n":"The change arrives and is applied. A moment later the same read would succeed."},{"f":0,"t":1,"l":"Read your own writes","n":"Send reads that must see a fresh write to the primary, or wait until the replica reports the matching position."}]},{"id":"x-db-expand-contract","module":"databases","lesson":"databases/safe-schema-migrations","title":"Changing a column without downtime","summary":"The expand and contract pattern in small safe releases.","actors":["Engineer","Old application","Database","New application"],"steps":[{"f":0,"t":2,"l":"Expand: add the new column","n":"The engineer adds a nullable column. The old application ignores it, so nothing breaks."},{"f":0,"t":3,"l":"Deploy code that writes both","n":"The new release writes to the old and the new column, and still reads from the old one."},{"f":0,"t":2,"l":"Backfill in batches","n":"A script copies old values into the new column in small batches, avoiding long locks."},{"f":3,"t":2,"l":"Switch reads","n":"The next release reads from the new column. If something is wrong, you can go back."},{"f":0,"t":2,"l":"Contract: stop writing the old one","n":"After a safe period the code stops writing the old column."},{"f":0,"t":2,"l":"Drop the old column","n":"Only now is the old column removed. Each step could be rolled back until this one."}]},{"id":"x-db-cache-aside","module":"databases","lesson":"databases/nosql-caches-and-choosing","title":"The cache-aside pattern","summary":"Check the cache first, fall back to the database, and fill the cache.","actors":["Application","Cache","Database","Next request"],"steps":[{"f":0,"t":1,"l":"Look in the cache","n":"The application asks the cache for the product with a key such as product:42."},{"f":1,"t":0,"l":"Miss","n":"The cache does not have it, because it expired or was never loaded."},{"f":0,"t":2,"l":"Query the database","n":"The application reads the product from the database, the source of truth."},{"f":2,"t":0,"l":"Return the row","n":"The database answers, which costs far more time than a cache read."},{"f":0,"t":1,"l":"Store with an expiry","n":"The application writes the value into the cache with a time to live, so stale data cannot stay forever."},{"f":3,"t":1,"l":"Hit next time","n":"The next request finds the value in the cache and never touches the database. After an update, delete the cache key."}]},{"id":"x-db-restore-test","module":"databases","lesson":"databases/backups-and-recovery","title":"Proving a backup can be restored","summary":"A backup is only real once a restore has worked.","actors":["Scheduler","Backup storage","Test server","Checker"],"steps":[{"f":0,"t":1,"l":"Take the backup","n":"The scheduler creates a base backup and keeps the log files, on storage separate from the database server."},{"f":0,"t":3,"l":"Record the result","n":"The job records size, duration and a checksum so that a sudden change gets noticed."},{"f":1,"t":2,"l":"Restore to a clean server","n":"On a schedule, a test server restores the latest backup and replays logs up to a chosen time."},{"f":2,"t":3,"l":"Run checks","n":"The checker counts rows in key tables, runs a few known queries and compares them with expected values."},{"f":3,"t":0,"l":"Report the outcome","n":"A failed restore raises an alert the same day, not on the day of the real disaster."},{"f":2,"t":0,"l":"Measure the time","n":"The restore time becomes a real number for your recovery objective, instead of a guess."}]},{"id":"x-linux-journal","module":"linux","lesson":"linux/logs-and-troubleshooting","title":"How a service log reaches journalctl","summary":"From a program writing a line to you reading it.","actors":["Service","systemd-journald","Disk","Engineer"],"steps":[{"f":0,"t":1,"l":"Write to standard output","n":"The service just prints a line. Under systemd, standard output and error are connected to the journal."},{"f":1,"t":1,"l":"Add metadata","n":"The journal attaches the unit name, process id, time and priority to the line."},{"f":1,"t":2,"l":"Store it","n":"Entries are stored in a binary log, in memory only or on disk depending on the configuration."},{"f":3,"t":1,"l":"Ask with journalctl -u","n":"The engineer asks for one unit. Filters such as --since and -p err narrow the answer."},{"f":1,"t":3,"l":"Return the entries","n":"Matching entries come back in time order, and -f keeps following new ones."},{"f":1,"t":2,"l":"Rotate and limit","n":"Size and age limits remove old entries, so a noisy service cannot fill the disk."}]},{"id":"x-linux-sudo","module":"linux","lesson":"linux/users-groups-permissions","title":"What happens when you run sudo","summary":"A rule lookup, a password check and a logged command.","actors":["User","sudo","Sudoers rules","Command","Auth log"],"steps":[{"f":0,"t":1,"l":"Run sudo systemctl restart nginx","n":"The user prefixes the command with sudo. The sudo program is installed with the setuid bit, so it starts as root."},{"f":1,"t":2,"l":"Look up the rules","n":"sudo reads /etc/sudoers and its include files to see whether this user may run this command as root."},{"f":2,"t":1,"l":"Allowed or denied","n":"A matching rule allows it, perhaps without a password. No rule means the attempt is refused."},{"f":1,"t":0,"l":"Ask for the user's password","n":"If a password is needed, sudo asks for the caller's own password, not the root password."},{"f":1,"t":3,"l":"Run the command as root","n":"With permission granted, sudo starts the command with root rights for that one command."},{"f":1,"t":4,"l":"Log the event","n":"Every use is written to the auth log with the user, the command and the result, which makes review possible."}]},{"id":"x-bash-redirect","module":"bash","lesson":"bash/advanced-patterns","title":"Where output goes: stdout, stderr and redirects","summary":"Two streams, and how the shell wires them to files.","actors":["Script","Standard output","Standard error","Terminal","Log file"],"steps":[{"f":0,"t":1,"l":"Normal results","n":"A command writes its results to standard output, file descriptor 1."},{"f":0,"t":2,"l":"Errors","n":"The same command writes errors to standard error, file descriptor 2, even though both usually appear on screen."},{"f":1,"t":3,"l":"No redirect","n":"By default both streams are connected to the terminal, so you see them mixed."},{"f":1,"t":4,"l":"Redirect with >","n":"Writing 'cmd > out.log' sends only standard output to the file. Errors still appear on the terminal."},{"f":2,"t":4,"l":"Join the streams","n":"Writing 'cmd > out.log 2>&1' sends errors to the same place as standard output. The order matters."},{"f":2,"t":3,"l":"Keep errors visible","n":"Sending only results to a file and keeping errors on the terminal is often the most useful setup for scripts."}]},{"id":"x-bash-loop-read","module":"bash","lesson":"bash/control-flow-and-functions","title":"Reading a file line by line","summary":"How while read processes input one record at a time.","actors":["File","Shell loop","Variables","Command in the loop"],"steps":[{"f":0,"t":1,"l":"Redirect the file into the loop","n":"'done < file' attaches the file to the loop's standard input."},{"f":1,"t":1,"l":"Read one line","n":"The read builtin takes a line from standard input and returns success while lines remain."},{"f":1,"t":2,"l":"Split into variables","n":"With IFS set, the line is split into the named variables. The last variable gets the rest of the line."},{"f":1,"t":3,"l":"Run the body","n":"The body uses the variables, for example to call a command for each user name in the file."},{"f":3,"t":1,"l":"Next iteration","n":"When the body finishes, the loop reads the next line."},{"f":1,"t":1,"l":"Stop at the end","n":"At end of file, read returns failure and the loop ends. A last line without a newline needs extra care."}]},{"id":"x-python-venv-install","module":"python","lesson":"python/basics-and-environments","title":"What pip does inside a virtual environment","summary":"Packages are installed next to the project, not into the system.","actors":["Engineer","venv","pip","Package index","Project folder"],"steps":[{"f":0,"t":1,"l":"Create the environment","n":"python3 -m venv .venv makes a private folder with its own interpreter and site-packages."},{"f":0,"t":1,"l":"Activate it","n":"Activation puts the venv bin folder first in PATH, so python and pip refer to the private copies."},{"f":0,"t":2,"l":"Install a requirement","n":"pip install -r requirements.txt reads the list of packages and versions."},{"f":2,"t":3,"l":"Resolve and download","n":"pip finds versions that satisfy all requirements and downloads wheels from the index."},{"f":2,"t":1,"l":"Install into the venv","n":"The packages go into the venv, so the system Python stays clean and other projects are unaffected."},{"f":1,"t":4,"l":"Run the project","n":"The project imports what it needs from the venv. Delete the folder and rebuild when things get confusing."}]},{"id":"x-python-exceptions","module":"python","lesson":"python/debugging-python","title":"How an exception travels up the call stack","summary":"Raise, propagate, catch and clean up.","actors":["main()","load_config()","open()","except block"],"steps":[{"f":0,"t":1,"l":"Call the function","n":"main calls load_config, which is a normal function call that adds a frame to the stack."},{"f":1,"t":2,"l":"Open the file","n":"load_config calls open on a path that does not exist."},{"f":2,"t":1,"l":"Raise FileNotFoundError","n":"The error is raised. The current function stops running at that line."},{"f":1,"t":0,"l":"Propagate upwards","n":"load_config has no handler, so the exception moves to its caller, main. Frames are removed as it goes."},{"f":0,"t":3,"l":"Catch it","n":"main has try/except FileNotFoundError and the handler runs, where it can print a clear message."},{"f":3,"t":0,"l":"Exit with a status","n":"The handler logs the cause and exits with a non-zero code. A finally block would run on every path."}]},{"id":"x-net-arp","module":"networking","lesson":"networking/dhcp-arp-and-the-local-network","title":"How a machine finds a neighbour's hardware address","summary":"ARP maps an IP address to a MAC address on the local network.","actors":["Host A","Switch","Host B","ARP cache"],"steps":[{"f":0,"t":0,"l":"Decide the next hop","n":"Host A wants to reach 10.0.0.20 on the same network, so it must send the frame straight to that machine."},{"f":0,"t":3,"l":"Look in the ARP cache","n":"A checks its cache for a recent mapping of that address. If it exists, the lookup ends here."},{"f":0,"t":1,"l":"Broadcast a request","n":"Who has 10.0.0.20? is sent to every device on the local network."},{"f":1,"t":2,"l":"Deliver to all ports","n":"The switch floods the broadcast, and every host sees it but only the owner of the address answers."},{"f":2,"t":0,"l":"Reply with the MAC","n":"Host B answers directly to A with its hardware address."},{"f":0,"t":3,"l":"Cache and send","n":"A stores the mapping for a short time and sends the data frame to B's MAC."}]},{"id":"x-net-nat","module":"networking","lesson":"networking/routing-and-nat","title":"How NAT lets a private host reach the internet","summary":"Source address rewriting and the translation table.","actors":["Private host","NAT router","Translation table","Internet server"],"steps":[{"f":0,"t":1,"l":"Send a packet out","n":"A host at 192.168.1.10 sends a packet to a public server. Its source address is private and not routable."},{"f":1,"t":2,"l":"Create a table entry","n":"The router records the private address and port against a new public port."},{"f":1,"t":3,"l":"Rewrite and forward","n":"The packet leaves with the router's public address as the source."},{"f":3,"t":1,"l":"Reply to the public address","n":"The server answers to the router's public address and the chosen port."},{"f":1,"t":2,"l":"Look up the entry","n":"The router finds which private host and port belong to that public port."},{"f":1,"t":0,"l":"Rewrite and deliver","n":"The destination is changed back and the reply reaches the host. Unrequested inbound traffic has no entry and is dropped."}]},{"id":"x-docker-layers","module":"docker","lesson":"docker/containers-and-images","title":"How image layers and the container layer work","summary":"Shared read-only layers plus one thin writable layer.","actors":["Image layers","Container","Writable layer","Another container"],"steps":[{"f":0,"t":0,"l":"Build creates layers","n":"Each instruction in the build adds a read-only layer. Unchanged layers are reused from the cache."},{"f":0,"t":1,"l":"Start a container","n":"The container uses all image layers together as one read-only filesystem."},{"f":1,"t":2,"l":"Add a writable layer","n":"A thin layer is placed on top for anything the container changes."},{"f":1,"t":2,"l":"Copy on write","n":"Changing an existing file copies it into the writable layer first. The image layer stays untouched."},{"f":0,"t":3,"l":"Share the layers","n":"A second container from the same image reuses the same layers, so it starts quickly and uses little disk."},{"f":2,"t":2,"l":"Remove the container","n":"Removing the container deletes its writable layer. Data that must stay belongs in a volume."}]},{"id":"x-docker-registry-push","module":"docker","lesson":"docker/registries-and-supply-chain","title":"Pushing an image to a registry","summary":"Tags, digests and which layers are uploaded.","actors":["Developer","Docker engine","Registry","Cluster node"],"steps":[{"f":0,"t":1,"l":"Tag the image","n":"docker tag adds a name that includes the registry address, the repository and a version tag."},{"f":0,"t":1,"l":"Run docker push","n":"The engine starts uploading the image to that address after logging in."},{"f":1,"t":2,"l":"Ask which layers exist","n":"For each layer the engine checks if the registry already has it, and skips those that do."},{"f":1,"t":2,"l":"Upload missing layers","n":"Only new layers travel over the network, which makes repeated pushes fast."},{"f":2,"t":1,"l":"Store the manifest","n":"The registry stores the manifest and returns a digest, a hash that identifies exactly this image."},{"f":3,"t":2,"l":"Pull by digest","n":"A node pulls using the digest. Tags can move, but a digest always points to the same content."}]},{"id":"x-cicd-artifact","module":"cicd","lesson":"cicd/versioning-and-artifacts","title":"Building once and promoting the same artifact","summary":"Why staging and production run the identical build.","actors":["Pipeline","Artifact store","Staging","Production"],"steps":[{"f":0,"t":0,"l":"Build one artifact","n":"The pipeline compiles the code and packages it exactly once for this commit."},{"f":0,"t":1,"l":"Store it with a version","n":"The package is saved with a version and a checksum, so it can be found and verified later."},{"f":1,"t":2,"l":"Deploy to staging","n":"Staging pulls that same artifact and runs integration tests against it."},{"f":2,"t":0,"l":"Tests pass","n":"Results are recorded against the artifact version, not against a branch that might have moved."},{"f":1,"t":3,"l":"Promote to production","n":"After approval production pulls the identical artifact. Nothing is rebuilt."},{"f":3,"t":0,"l":"Know what runs","n":"The running version maps back to one commit and one test record, which makes rollback and audit simple."}]},{"id":"x-cicd-approval","module":"cicd","lesson":"cicd/environments-promotion-and-approvals","title":"A deploy gate with approval","summary":"Automatic checks first, then a person for risky changes.","actors":["Pipeline","Policy checks","Approver","Production"],"steps":[{"f":0,"t":1,"l":"Run automatic checks","n":"Tests, security scans and policy rules run first. Failing any of them stops the pipeline."},{"f":1,"t":0,"l":"Report the result","n":"All checks are green, and the result is attached to the release."},{"f":0,"t":2,"l":"Ask for approval","n":"A production deploy waits for an approver. The request shows the change, the test results and the risk."},{"f":2,"t":0,"l":"Approve or reject","n":"The approver should be someone other than the author, who decides after reading the evidence."},{"f":0,"t":3,"l":"Deploy gradually","n":"The pipeline deploys with the rollout strategy defined for the service, such as canary then full."},{"f":3,"t":0,"l":"Verify and record","n":"Health checks decide whether the release is kept. The approval, the time and the version are stored for audit."}]},{"id":"x-k8s-ingress-tls","module":"kubernetes","lesson":"kubernetes/services-and-ingress","title":"How an ingress terminates TLS","summary":"From a browser request to a pod, with the certificate handled at the edge.","actors":["Browser","Load balancer","Ingress controller","Service","Pod"],"steps":[{"f":0,"t":1,"l":"Connect to the public address","n":"The browser opens a connection to the cloud load balancer that fronts the cluster."},{"f":1,"t":2,"l":"Pass traffic to the controller","n":"The load balancer forwards the connection to ingress controller pods inside the cluster."},{"f":2,"t":2,"l":"Present the certificate","n":"The controller picks the certificate from a secret that matches the host name and completes the TLS handshake."},{"f":2,"t":2,"l":"Match the rule","n":"It decrypts the request and checks host and path against the ingress rules."},{"f":2,"t":3,"l":"Forward to the service","n":"The request goes to the service named in the matching rule."},{"f":3,"t":4,"l":"Choose a ready pod","n":"The service sends it to one of the ready pods, which answers over plain HTTP inside the cluster."}]},{"id":"x-k8s-job","module":"kubernetes","lesson":"kubernetes/jobs-cronjobs-daemonsets","title":"How a Job and a CronJob run to completion","summary":"Unlike a Deployment, a Job is meant to finish.","actors":["CronJob","Job controller","Pod","Cluster events"],"steps":[{"f":0,"t":1,"l":"Schedule fires","n":"At the scheduled time the CronJob creates a Job object, unless the previous run is still going and the policy forbids it."},{"f":1,"t":2,"l":"Create the pod","n":"The Job controller creates a pod that runs the task once."},{"f":2,"t":2,"l":"Run to the end","n":"The container runs its command and exits with a status code."},{"f":2,"t":1,"l":"Report success or failure","n":"Exit status 0 marks the pod succeeded. Any other status marks it failed."},{"f":1,"t":2,"l":"Retry on failure","n":"On failure the controller creates a new pod, up to the backoff limit, with growing delays."},{"f":1,"t":3,"l":"Finish and clean up","n":"When the required number of pods succeed, the Job completes. Old Jobs are removed by the history limits."}]},{"id":"x-tf-count-foreach","module":"terraform","lesson":"terraform/expressions-and-dynamic-blocks","title":"Why for_each is safer than count","summary":"Removing an item from the middle of a list.","actors":["Configuration","Plan","State","Real servers"],"steps":[{"f":0,"t":2,"l":"Start with count over a list","n":"Three servers are created with count and a list of names. State addresses them as [0], [1] and [2]."},{"f":0,"t":1,"l":"Remove the middle name","n":"The list shrinks to two names, so the item that was at index 2 moves to index 1."},{"f":1,"t":2,"l":"Plan compares by position","n":"Terraform sees that [1] now has a different name and [2] is gone."},{"f":1,"t":3,"l":"Unexpected replacement","n":"It plans to change or destroy servers that nobody meant to touch, only because positions shifted."},{"f":0,"t":2,"l":"Use for_each with a set or map","n":"Each server is addressed by its key, such as web-b, so the address is stable."},{"f":1,"t":3,"l":"Only the removed one is destroyed","n":"The plan now destroys exactly the removed key and leaves the others alone."}]},{"id":"x-tf-workspace-env","module":"terraform","lesson":"terraform/environments-and-team-workflows","title":"Separate environments with separate state","summary":"Why dev and prod must not share a state file.","actors":["Engineer","Dev state","Prod state","Cloud accounts"],"steps":[{"f":0,"t":1,"l":"Plan in dev","n":"The engineer runs plan with the dev settings. It reads the dev state and the dev account only."},{"f":1,"t":3,"l":"Apply in dev","n":"Changes go to the dev account, and only the dev state is updated."},{"f":0,"t":0,"l":"Review the difference","n":"The same code runs with different variable files, so the shape matches and only the sizes differ."},{"f":0,"t":2,"l":"Plan in prod","n":"The same code is planned against the prod state and the prod account, usually by a pipeline with an approval step."},{"f":2,"t":3,"l":"Apply in prod","n":"Prod changes happen only after the change was proven in dev. A mistake in dev cannot reach the prod state."},{"f":0,"t":2,"l":"Limit access","n":"Separate credentials and state locations mean most people can change dev but not prod."}]},{"id":"x-cloud-load-balancer-health","module":"cloud","lesson":"cloud/high-availability-and-disaster-recovery","title":"How a cloud load balancer removes a broken server","summary":"Health checks and draining.","actors":["Client","Load balancer","Server A","Server B"],"steps":[{"f":1,"t":2,"l":"Probe each server","n":"The load balancer sends a health request to every target every few seconds."},{"f":1,"t":3,"l":"Probe the second server","n":"Both targets answer with success, so both receive traffic."},{"f":0,"t":1,"l":"Send user traffic","n":"Clients send requests and the balancer spreads them across healthy targets."},{"f":2,"t":2,"l":"Server A starts failing","n":"A deploy breaks the health endpoint on server A, which now returns errors."},{"f":1,"t":2,"l":"Mark unhealthy after a threshold","n":"After a few failed probes in a row the balancer stops sending new requests to A."},{"f":1,"t":3,"l":"All traffic goes to B","n":"Server B carries the load. Capacity and alerts matter here, because one server is now doing the work of two."}]},{"id":"x-cloud-secrets-manager","module":"cloud","lesson":"cloud/security-and-governance","title":"Fetching a secret at run time","summary":"The application asks for the secret with its own identity.","actors":["Application","Instance identity","Secrets service","Audit log"],"steps":[{"f":0,"t":1,"l":"Start with an attached role","n":"The workload runs with an identity assigned by the platform, so no password is stored in its image."},{"f":0,"t":2,"l":"Request the secret by name","n":"The application asks the secrets service for db/password."},{"f":2,"t":1,"l":"Check the identity","n":"The service checks that this role is allowed to read exactly this secret."},{"f":2,"t":0,"l":"Return the value","n":"The secret is returned over an encrypted connection and kept in memory."},{"f":2,"t":3,"l":"Record the access","n":"Who read which secret and when is written to the audit log."},{"f":2,"t":0,"l":"Rotate on a schedule","n":"The service creates a new value on a schedule. Applications that fetch at start-up or refresh periodically pick it up."}]},{"id":"x-obs-alert-routing","module":"observability","lesson":"observability/alerting-and-dashboards","title":"How an alert reaches the right person","summary":"Rules, grouping, routing and silence.","actors":["Metrics store","Alert rule","Alert manager","Chat channel","On-call person"],"steps":[{"f":0,"t":1,"l":"Evaluate the rule","n":"The rule runs every minute against the metrics, for example error ratio above 5 percent for 10 minutes."},{"f":1,"t":2,"l":"Fire the alert","n":"When the condition holds long enough, the alert is sent with labels such as service and severity."},{"f":2,"t":2,"l":"Group and de-duplicate","n":"Alerts with the same labels are grouped, so one outage does not create fifty messages."},{"f":2,"t":3,"l":"Route by severity","n":"Low severity goes to a channel for working hours."},{"f":2,"t":4,"l":"Page for high severity","n":"High severity pages the person on call, using the schedule, with a link to the dashboard and runbook."},{"f":2,"t":2,"l":"Resolve or silence","n":"When the condition clears a resolved message is sent. A silence mutes planned work."}]},{"id":"x-obs-slo-dashboard","module":"observability","lesson":"observability/alerting-and-dashboards","title":"From request logs to an SLO number","summary":"How raw events become one reliability figure.","actors":["Service","Metrics pipeline","SLI query","SLO report"],"steps":[{"f":0,"t":1,"l":"Emit counters","n":"Each request increments a counter labelled with its status code and route."},{"f":1,"t":2,"l":"Define the SLI","n":"The SLI is the share of good requests: non-5xx responses divided by all valid requests."},{"f":2,"t":2,"l":"Calculate over a window","n":"The query computes this ratio over 30 days and also over short windows for alerting."},{"f":2,"t":3,"l":"Compare with the target","n":"The result is compared with the SLO, for example 99.9 percent."},{"f":3,"t":3,"l":"Show the error budget","n":"The remaining budget is the allowed bad fraction minus the actual bad fraction, shown as minutes or requests."},{"f":3,"t":0,"l":"Decide what to do","n":"With budget left the team ships. With it nearly spent, the team focuses on reliability work."}]},{"id":"x-sre-blameless-review","module":"sre","lesson":"sre/postmortems-and-toil","title":"Running a blameless review","summary":"Learning from an incident without pointing fingers.","actors":["Facilitator","Responders","Timeline","Action items"],"steps":[{"f":0,"t":1,"l":"Invite everyone involved","n":"The facilitator brings in responders, owners of affected systems and anyone who made a decision."},{"f":1,"t":2,"l":"Build the timeline","n":"Using chat logs and graphs, the group writes what happened and when, with facts only."},{"f":0,"t":1,"l":"Ask how, not who","n":"Questions focus on what made the action seem reasonable at that moment and what information was missing."},{"f":1,"t":2,"l":"Find contributing factors","n":"The group lists conditions such as missing alerts, unclear runbooks or risky defaults. There is rarely one root cause."},{"f":1,"t":3,"l":"Agree on actions","n":"Each action has an owner, a date and a measurable outcome. Fewer, stronger actions beat a long list."},{"f":3,"t":0,"l":"Share and follow up","n":"The review is shared widely and the actions are tracked until done, which is how trust in the process is earned."}]},{"id":"x-sre-capacity","module":"sre","lesson":"sre/capacity-planning","title":"Planning capacity before it runs out","summary":"Forecasting from growth and headroom.","actors":["Metrics","Forecast","Capacity plan","Procurement or autoscaling"],"steps":[{"f":0,"t":1,"l":"Collect usage trends","n":"Weeks of data on traffic, CPU, memory and storage show the growth rate and the daily peaks."},{"f":1,"t":1,"l":"Project forward","n":"The forecast extends the trend, adds known events such as a launch, and shows when the limit is reached."},{"f":1,"t":2,"l":"Define headroom","n":"The plan keeps a safety margin, so the loss of a zone or a traffic spike does not cause an outage."},{"f":2,"t":3,"l":"Choose how to add capacity","n":"Autoscaling handles fast changes. Slow resources such as storage or quota increases need lead time."},{"f":3,"t":0,"l":"Verify with load tests","n":"A load test shows if the system really scales as predicted, and where the next bottleneck is."},{"f":0,"t":1,"l":"Review on a schedule","n":"Forecasts are compared with reality each quarter, and the model is corrected where it was wrong."}]},{"id":"x-sec-threat-model","module":"security","lesson":"security/security-mindset-and-threat-modeling","title":"A quick threat model session","summary":"Four questions applied to one feature.","actors":["Team","Diagram","Threat list","Backlog"],"steps":[{"f":0,"t":1,"l":"Draw the data flow","n":"The team draws users, services, data stores and the lines between them, marking trust boundaries."},{"f":0,"t":1,"l":"Ask what can go wrong","n":"For each boundary crossing the team asks how it could be spoofed, tampered with, read or overloaded."},{"f":1,"t":2,"l":"Write the threats down","n":"Each realistic threat gets a short sentence, such as a user changing an id in the URL to read another account."},{"f":2,"t":2,"l":"Rank by impact and likelihood","n":"A simple high, medium or low ranking decides what to deal with first."},{"f":2,"t":3,"l":"Choose a response for each","n":"Fix, reduce, accept or transfer. Every accepted risk has a named owner."},{"f":3,"t":0,"l":"Revisit when the design changes","n":"New features and integrations change the diagram, so the model is updated rather than filed away."}]},{"id":"x-sec-dependency-scan","module":"security","lesson":"security/securing-the-pipeline","title":"Handling a vulnerable dependency","summary":"From a scanner finding to a safe release.","actors":["Scanner","Engineer","Package registry","Pipeline"],"steps":[{"f":0,"t":1,"l":"Report a finding","n":"The scanner reports that a library version has a known vulnerability, with a severity score."},{"f":1,"t":1,"l":"Check if it matters","n":"The engineer checks if the vulnerable code is actually used and reachable. Severity alone is not the whole story."},{"f":1,"t":2,"l":"Find a fixed version","n":"The registry shows a patched version, and the release notes say if the update is compatible."},{"f":1,"t":3,"l":"Update and test","n":"The version is raised in the lock file, and the test suite runs to catch breaking changes."},{"f":3,"t":0,"l":"Scan again","n":"The pipeline repeats the scan on the new build and confirms the finding is gone."},{"f":3,"t":1,"l":"Ship within the agreed time","n":"The fix is released within the time the policy sets for that severity, and an exception is recorded if it cannot be."}]},{"id":"git-three-areas","module":"git","lesson":"git/first-repository-and-commits","title":"From edit to commit","summary":"How a change moves through the working tree, staging area and repository.","actors":["Working tree","Staging area","Repository"],"steps":[{"f":0,"t":0,"l":"Edit backup.sh","n":"You change a file in your working tree. Git notices the difference but has not saved anything yet."},{"f":0,"t":0,"l":"git status","n":"Status lists the file as modified but not staged, so it would not be part of a commit right now."},{"f":0,"t":1,"l":"git add backup.sh","n":"The change is copied into the staging area, the draft of the next commit."},{"f":0,"t":0,"l":"Edit notes.txt","n":"A second unrelated change stays in the working tree because you did not stage it."},{"f":1,"t":2,"l":"git commit -m \"Add retry\"","n":"Only the staged change becomes a permanent snapshot with a message, author and parent commit."},{"f":2,"t":2,"l":"New commit 3f9c2ab","n":"The branch pointer moves forward to the new commit, and the history grows by one step."},{"f":0,"t":0,"l":"notes.txt still modified","n":"The unstaged change is untouched, ready to become a separate commit with its own message."}]},{"id":"git-branch-ff-merge","module":"git","lesson":"git/branches-and-merging","title":"Branch and fast-forward merge","summary":"Create a branch, commit on it and merge it back when main has not moved.","actors":["Developer","main","feature/retry"],"steps":[{"f":0,"t":1,"l":"main at commit B","n":"The history is A, B and main points to B. You start from here."},{"f":0,"t":2,"l":"git switch -c feature/retry","n":"A new pointer feature/retry is created at B. No files are copied, so it is instant."},{"f":0,"t":2,"l":"Commit C","n":"You commit on the feature branch. The pointer feature/retry moves to C while main stays at B."},{"f":0,"t":2,"l":"Commit D","n":"A second commit moves feature/retry to D. The work is isolated from main."},{"f":0,"t":1,"l":"git switch main","n":"HEAD moves to main and the working files return to the state of B."},{"f":2,"t":1,"l":"git merge feature/retry","n":"Main has not moved since the branch point, so Git only moves the main pointer forward to D."},{"f":1,"t":1,"l":"Fast-forward complete","n":"History is a straight line A, B, C, D and no merge commit was created."},{"f":0,"t":2,"l":"git branch -d feature/retry","n":"The merged branch label is deleted. The commits remain because main points to them."}]},{"id":"git-merge-conflict","module":"git","lesson":"git/branches-and-merging","title":"Resolving a merge conflict","summary":"Two branches change the same line and Git asks you to decide.","actors":["Developer","Git","File"],"steps":[{"f":0,"t":1,"l":"git merge feature/retry","n":"You ask Git to merge the feature branch into main, which also changed the same file."},{"f":1,"t":2,"l":"Both sides changed line 12","n":"Git compares each branch with the common ancestor and finds two different edits to the same line."},{"f":1,"t":2,"l":"Conflict markers written","n":"The file now contains the markers with your version above the equals line and theirs below it."},{"f":1,"t":0,"l":"CONFLICT, merge stopped","n":"Git reports the file and stops. The merge is in progress and git status shows both modified."},{"f":0,"t":2,"l":"Edit to final content","n":"You decide the correct result, often a combination, and remove every marker line from the file."},{"f":0,"t":1,"l":"git add config/backup.conf","n":"Adding the file tells Git that this conflict is resolved."},{"f":0,"t":1,"l":"git commit","n":"Git creates the merge commit with two parents, finishing the merge."},{"f":0,"t":0,"l":"Run the tests","n":"A textually clean merge can still be logically wrong, so you test the combined result before pushing."}]},{"id":"git-rebase-replay","module":"git","lesson":"git/rebase-and-clean-history","title":"Rebase replays your commits","summary":"Update a feature branch on the latest main by replaying commits.","actors":["Developer","Feature branch","main"],"steps":[{"f":2,"t":2,"l":"main moved ahead","n":"While you worked, teammates merged two new commits to main, so your branch is based on old code."},{"f":0,"t":1,"l":"git rebase origin/main","n":"You ask Git to rebase. It remembers your commits, which are C and D."},{"f":1,"t":2,"l":"Move to tip of main","n":"Git sets your branch to the latest main commit, temporarily without your work."},{"f":1,"t":1,"l":"Replay C as C prime","n":"The change of C is applied on top of main, creating a new commit with a different hash."},{"f":1,"t":1,"l":"Replay D as D prime","n":"The change of D is applied next. If a conflict occurs, Git stops and asks you to resolve it."},{"f":1,"t":0,"l":"History is linear","n":"Your branch now looks as if you started from the latest main, with no merge commit."},{"f":0,"t":1,"l":"Force push with lease","n":"The rewritten branch must replace the remote copy, so you use force-with-lease on your own branch only."},{"f":0,"t":2,"l":"Rule","n":"Never rebase commits that other people have already pulled, because their copies would no longer match."}]},{"id":"git-fetch-vs-pull","module":"git","lesson":"git/remotes-fetch-pull-and-push","title":"Fetch compared with pull","summary":"What each command changes on your machine.","actors":["You","Local branch main","origin/main","Remote server"],"steps":[{"f":0,"t":3,"l":"git fetch origin","n":"You ask the server for new commits. Nothing in your working files changes."},{"f":3,"t":2,"l":"Update origin/main","n":"The remote-tracking branch moves to the latest known server commit. This pointer is read-only."},{"f":0,"t":2,"l":"git log main..origin/main","n":"You inspect what arrived before deciding how to integrate it."},{"f":0,"t":1,"l":"git merge --ff-only origin/main","n":"If your main has no extra commits it moves forward to match. Otherwise Git refuses safely."},{"f":0,"t":3,"l":"git pull","n":"Pull is fetch followed by merge or rebase in one command, so the integration is automatic."},{"f":1,"t":1,"l":"Possible merge commit","n":"If both sides had new commits, a plain pull creates a merge commit that you did not ask for."},{"f":0,"t":1,"l":"pull.ff only","n":"Setting pull.ff to only makes pull fail instead of surprising you, which pushes you to decide on purpose."}]},{"id":"git-push-rejected","module":"git","lesson":"git/remotes-fetch-pull-and-push","title":"A rejected push","summary":"Why a push fails and how to fix it without force.","actors":["You","Local branch","Remote branch"],"steps":[{"f":2,"t":2,"l":"Colleague pushes commit X","n":"While you worked, the remote branch received a new commit that you do not have."},{"f":0,"t":2,"l":"git push","n":"You try to publish your commits to the remote branch."},{"f":2,"t":0,"l":"Rejected, non-fast-forward","n":"The remote branch has history that yours does not include, so a plain push would lose commit X."},{"f":0,"t":2,"l":"git fetch","n":"You download the remote state to see exactly what is different."},{"f":0,"t":1,"l":"git rebase origin/branch","n":"You replay your commits on top of the colleague work, resolving conflicts if any."},{"f":0,"t":1,"l":"Run the tests","n":"You check that the combined code works, because both changes are now together."},{"f":1,"t":2,"l":"git push","n":"The push is now a fast-forward of the remote branch, so the server accepts it."},{"f":0,"t":2,"l":"Do not use force","n":"A forced push would have discarded commit X. Force-with-lease is only for your own rewritten branches."}]},{"id":"git-pull-request-flow","module":"git","lesson":"git/team-workflows-pull-requests-and-reviews","title":"A pull request from start to merge","summary":"The path of a change through branch, review, checks and merge.","actors":["Author","Branch","Reviewer","CI checks","main"],"steps":[{"f":0,"t":1,"l":"Create feature branch","n":"You branch from the latest main and make small commits with clear messages."},{"f":0,"t":1,"l":"Push and open a pull request","n":"The branch goes to the remote and a pull request describes what changed, why and how it was tested."},{"f":1,"t":3,"l":"Checks start","n":"The pipeline runs lint, tests and security scans on the proposed result and reports status on the pull request."},{"f":2,"t":1,"l":"Review comments","n":"The reviewer reads the change for correctness, safety and clarity and asks for changes where needed."},{"f":0,"t":1,"l":"Fix and re-request","n":"You push more commits or amend, the checks run again, and you ask for another look."},{"f":2,"t":1,"l":"Approve","n":"With checks green and the required approvals given, the merge button becomes available."},{"f":1,"t":4,"l":"Merge","n":"The platform merges by the chosen policy, squash, rebase or merge commit, into the protected main branch."},{"f":4,"t":3,"l":"Deploy pipeline","n":"The merged commit triggers the build of one artifact that moves through the environments."}]},{"id":"git-revert-shared","module":"git","lesson":"git/staging-undoing-and-stashing","title":"Reverting a shared commit","summary":"Undo a bad change on main without rewriting history.","actors":["Team","main","Revert commit","Production"],"steps":[{"f":3,"t":0,"l":"Errors increase","n":"After a deploy the error rate rises and the on-call engineer links it to the latest change."},{"f":0,"t":1,"l":"Identify the bad commit","n":"git log shows the commit 7d1e0aa merged an hour ago, and others have already pulled it."},{"f":0,"t":2,"l":"git revert 7d1e0aa","n":"Git creates a new commit that applies the opposite change. Old history stays untouched."},{"f":0,"t":2,"l":"Explain in the message","n":"The revert commit says why it exists and links the incident, so future readers understand."},{"f":2,"t":1,"l":"Merge through the normal process","n":"The revert is reviewed and checked quickly, then merged, and everyone pulls it like any other commit."},{"f":1,"t":3,"l":"Deploy the revert","n":"The pipeline builds and deploys the fixed state, and the error rate returns to normal."},{"f":0,"t":1,"l":"Fix properly later","n":"The original change is fixed on a new branch and re-applied with tests that cover the failure."}]},{"id":"git-reflog-recover","module":"git","lesson":"git/debugging-git-problems","title":"Recovering a lost commit","summary":"Use the reflog after a hard reset.","actors":["You","Branch main","Reflog","Recovery branch"],"steps":[{"f":0,"t":1,"l":"git reset --hard origin/main","n":"Your branch now points to a different commit, and the work you had committed seems to be gone."},{"f":0,"t":1,"l":"git log shows less","n":"The commit from yesterday is not listed because no branch points to it any more."},{"f":0,"t":2,"l":"git reflog","n":"The reflog lists every place HEAD pointed, including the commit from before the reset."},{"f":2,"t":0,"l":"Find 7be3f10","n":"You identify the entry that says commit: Tune ingress timeouts and copy its hash."},{"f":0,"t":3,"l":"git branch rescue 7be3f10","n":"A new branch label is created at that commit, which makes it reachable again."},{"f":3,"t":3,"l":"Commit is safe","n":"Garbage collection only removes unreachable commits, so a branch protects the work."},{"f":0,"t":1,"l":"Merge or cherry-pick","n":"You bring the rescued work back into main with a merge or cherry-pick."},{"f":0,"t":0,"l":"Limit","n":"Uncommitted edits were never saved by Git, so the reflog cannot bring them back."}]},{"id":"git-bisect","module":"git","lesson":"git/debugging-git-problems","title":"Finding the bad commit with bisect","summary":"A binary search through 200 commits.","actors":["You","Git","Test script"],"steps":[{"f":0,"t":1,"l":"git bisect start","n":"You begin a bisect session and tell Git a bad commit (current) and a good one (v1.3.0)."},{"f":1,"t":1,"l":"Checks out the middle","n":"Git picks the commit halfway between good and bad, leaving about 100 commits to examine."},{"f":0,"t":2,"l":"Run the test","n":"Your script or a manual check shows whether this commit has the bug."},{"f":0,"t":1,"l":"git bisect bad","n":"The bug is present here, so the first bad commit is in the earlier half. The range halves."},{"f":1,"t":1,"l":"Halve again","n":"Git checks out a new middle commit, and the process repeats with 50, 25, 12 commits and so on."},{"f":0,"t":1,"l":"git bisect good","n":"The test passes on this one, so the problem was introduced later. The range keeps shrinking."},{"f":1,"t":0,"l":"First bad commit found","n":"After about eight steps Git prints the commit that introduced the bug and its message."},{"f":0,"t":1,"l":"git bisect reset","n":"You return to your original branch and use the finding to write the fix and a regression test."}]},{"id":"git-secret-response","module":"git","lesson":"git/hooks-signing-and-secrets-in-history","title":"A secret was committed","summary":"The correct order of actions after a credential reaches the repository.","actors":["Scanner","Engineer","Cloud account","Repository","Team"],"steps":[{"f":0,"t":1,"l":"Alert: key in config file","n":"The scanner flags an access key in a commit. You assume it is already copied."},{"f":1,"t":2,"l":"Revoke and rotate","n":"You deactivate the key in the cloud account at once and issue a new one to the service."},{"f":1,"t":2,"l":"Review audit logs","n":"You search for activity with the old key: new users, new keys, instances, data reads."},{"f":1,"t":2,"l":"Remove persistence","n":"Anything the attacker created is deleted, and affected secrets are rotated."},{"f":1,"t":3,"l":"Rewrite history","n":"git filter-repo removes the file from all commits, and the cleaned history is force-pushed."},{"f":1,"t":4,"l":"Tell the team","n":"Everyone re-clones or resets, because old clones and forks still contain the secret."},{"f":1,"t":3,"l":"Add prevention","n":"Push protection, pipeline scanning and a secret manager are enabled so the same mistake is blocked."},{"f":1,"t":4,"l":"Write a short review","n":"The team records what happened and what changed, without blaming a person."}]},{"id":"git-stash-hotfix","module":"git","lesson":"git/staging-undoing-and-stashing","title":"Stash, hotfix and return","summary":"Pause half-done work to ship an urgent fix.","actors":["You","Stash","hotfix branch","main"],"steps":[{"f":0,"t":0,"l":"Half-done work","n":"You have uncommitted edits on a feature branch when an urgent bug report arrives."},{"f":0,"t":1,"l":"git stash push -m \"retry logic\"","n":"Your tracked changes are saved in the stash and the working tree is clean again."},{"f":0,"t":2,"l":"git switch -c hotfix/disk-alert main","n":"A new branch starts from main so the fix is isolated from your unfinished feature."},{"f":0,"t":2,"l":"Fix, test, commit","n":"You make the smallest correct change, run the tests and commit with a clear message."},{"f":2,"t":3,"l":"Merge through review","n":"The hotfix goes through a pull request and is merged to main, then deployed."},{"f":0,"t":0,"l":"git switch feature/retry","n":"You return to your feature branch, which does not yet contain the hotfix."},{"f":1,"t":0,"l":"git stash pop","n":"The saved edits come back into the working tree and the stash entry is removed."},{"f":3,"t":0,"l":"Update the feature branch","n":"You rebase or merge main so your feature also has the fix before you continue."}]},{"id":"git-release-tag-hotfix","module":"git","lesson":"git/tags-releases-and-versioning","title":"Tag a release and ship a hotfix","summary":"Annotated tags, artifacts and a fix for an older version.","actors":["Developer","main","Tag","CI","hotfix branch"],"steps":[{"f":0,"t":1,"l":"Merge release work","n":"The release changes are merged to main and the tests pass."},{"f":0,"t":2,"l":"git tag -a v1.4.0","n":"An annotated tag marks the exact release commit with a message and the tagger."},{"f":2,"t":3,"l":"Pipeline builds from the tag","n":"CI builds one artifact from the tag and stamps the version and the commit hash into it."},{"f":3,"t":3,"l":"Deploy that artifact","n":"The same artifact is promoted through the environments, so production runs exactly what was tested."},{"f":0,"t":4,"l":"Bug found in 1.4.0","n":"A defect is reported. You branch from the tag, not from main, so you fix only that version."},{"f":4,"t":2,"l":"Tag v1.4.1","n":"After the fix and tests, a new annotated tag is created. The old tag v1.4.0 is never moved."},{"f":4,"t":1,"l":"Cherry-pick to main","n":"The fix commit is copied to main, so the next release does not bring the bug back."}]},{"id":"git-shallow-sparse","module":"git","lesson":"git/large-repositories-submodules-and-worktrees","title":"Faster clones for CI","summary":"Shallow, partial and sparse clones cut the pipeline start time.","actors":["CI job","Remote repository","Local copy"],"steps":[{"f":0,"t":1,"l":"Full clone","n":"A normal clone downloads every commit and file version, which for a large repository takes minutes."},{"f":1,"t":2,"l":"7 GB received","n":"All history arrives even though the job only builds the current code of one service."},{"f":0,"t":1,"l":"Shallow clone with depth 1","n":"The job asks for only the latest commit, so far fewer objects are transferred."},{"f":0,"t":1,"l":"Partial clone with blob none","n":"File contents are downloaded only when needed, instead of every version of every file."},{"f":0,"t":2,"l":"Sparse checkout of one folder","n":"Only the service folder and shared libraries appear in the working tree."},{"f":2,"t":0,"l":"Build starts in seconds","n":"The first build step runs after a clone that takes seconds instead of minutes."},{"f":0,"t":2,"l":"Deepen only if needed","n":"If a tool needs history, such as git describe, the job fetches more commits before it runs."}]},{"id":"x-go-build-run","module":"go","lesson":"go/why-go-and-your-first-program","title":"From go build to a running program","summary":"How source files become one static binary and start running.","actors":["Developer","go command","Compiler and linker","Binary"],"steps":[{"f":0,"t":1,"l":"go build ./cmd/api","n":"The go command reads go.mod to find the module and the packages that the program imports."},{"f":1,"t":1,"l":"Resolve dependencies","n":"Dependencies come from the module cache, and go.sum checksums are verified so downloaded code matches what was recorded."},{"f":1,"t":2,"l":"Compile packages","n":"Each package is compiled once and cached, so a rebuild only recompiles what changed."},{"f":2,"t":2,"l":"Link into one executable","n":"The linker joins your code, dependencies and the Go runtime into one file with no separate runtime to install."},{"f":2,"t":3,"l":"Write the binary","n":"The result is a single file, static when CGO is disabled, which runs on a minimal container image."},{"f":0,"t":3,"l":"./api","n":"Starting the file runs the runtime first, which sets up the scheduler and memory manager, then calls main."}]},{"id":"x-go-goroutine-scheduler","module":"go","lesson":"go/goroutines-channels-and-sync","title":"How goroutines are scheduled","summary":"How many goroutines share a few operating system threads.","actors":["Your code","Go scheduler","OS thread","Run queue"],"steps":[{"f":0,"t":1,"l":"go handle(req)","n":"The go statement creates a goroutine with a small stack and hands it to the scheduler."},{"f":1,"t":3,"l":"Put it on a run queue","n":"New goroutines wait on a queue attached to a logical processor, ready to run."},{"f":1,"t":2,"l":"Assign to a thread","n":"The scheduler lets an operating system thread pick a goroutine and run it until it blocks or is preempted."},{"f":2,"t":2,"l":"Goroutine blocks on I/O","n":"When a goroutine waits for a network read, the thread does not wait with it."},{"f":1,"t":3,"l":"Park it, run another","n":"The scheduler parks the blocked goroutine and runs the next one from the queue on the same thread."},{"f":1,"t":0,"l":"Wake on ready","n":"When the network data arrives, the goroutine becomes runnable again and continues where it stopped."}]},{"id":"x-go-channel-handoff","module":"go","lesson":"go/goroutines-channels-and-sync","title":"Channels hand off values safely","summary":"How an unbuffered channel synchronises a sender and a receiver.","actors":["Producer","Channel","Consumer"],"steps":[{"f":0,"t":0,"l":"Compute a result","n":"The producer goroutine finishes some work and has a value ready."},{"f":0,"t":1,"l":"ch <- result","n":"The send blocks on an unbuffered channel until a receiver is ready, so both sides meet."},{"f":2,"t":1,"l":"result := <-ch","n":"The consumer reaches the receive and the value is handed over directly."},{"f":1,"t":2,"l":"Value delivered","n":"Both goroutines continue. The hand-off also guarantees that writes before the send are visible after the receive."},{"f":0,"t":1,"l":"close(ch)","n":"The producer closes the channel when it has nothing more to send."},{"f":2,"t":2,"l":"range ends","n":"The consumer loop over the channel finishes when it is closed and empty, so it can exit cleanly."}]},{"id":"x-go-context-cancel","module":"go","lesson":"go/context-timeouts-and-cancellation","title":"Cancelling work with context","summary":"How one cancellation stops every goroutine a request started.","actors":["Handler","Context","Worker A","Worker B"],"steps":[{"f":0,"t":1,"l":"WithTimeout(ctx, 2s)","n":"The handler derives a context with a deadline from the request context and defers cancel."},{"f":0,"t":2,"l":"Start worker A with ctx","n":"Each worker receives the context as its first parameter."},{"f":0,"t":3,"l":"Start worker B with ctx","n":"Both workers share the same cancellation signal."},{"f":1,"t":1,"l":"Deadline passes","n":"After two seconds the context closes its Done channel and records the reason."},{"f":1,"t":2,"l":"Done channel closed","n":"Worker A sees ctx.Done in its select and stops waiting on the slow call."},{"f":1,"t":3,"l":"Done channel closed","n":"Worker B stops too, so no goroutine is left running for a request that has already failed."},{"f":0,"t":0,"l":"Return error","n":"The handler returns a timeout error to the client and the resources are released."}]},{"id":"x-go-http-request","module":"go","lesson":"go/http-services-and-json","title":"A request through net/http","summary":"How a Go server routes and answers one HTTP request.","actors":["Client","Server","Mux","Handler"],"steps":[{"f":0,"t":1,"l":"GET /orders/42","n":"The client connects and sends the request. The server runs each connection in its own goroutine."},{"f":1,"t":1,"l":"Parse request","n":"net/http parses the method, path, headers and creates a request with a context."},{"f":1,"t":2,"l":"Match route","n":"The mux finds the handler registered for the method and path pattern."},{"f":2,"t":3,"l":"Call handler","n":"The handler reads the path value, checks input and calls the store with the request context."},{"f":3,"t":3,"l":"Encode JSON","n":"The handler sets the content type and writes the encoded response, handling encoding errors."},{"f":3,"t":0,"l":"200 OK + body","n":"The response goes back. If the client disconnects, the request context is cancelled."}]},{"id":"x-go-graceful-shutdown","module":"go","lesson":"go/context-timeouts-and-cancellation","title":"Graceful shutdown","summary":"How a Go service finishes in-flight requests before exiting.","actors":["Orchestrator","Service","Server","In-flight request"],"steps":[{"f":0,"t":1,"l":"SIGTERM","n":"The orchestrator asks the service to stop, usually with a grace period before killing it."},{"f":1,"t":1,"l":"Mark not ready","n":"The readiness endpoint starts failing so the load balancer stops sending new requests."},{"f":1,"t":2,"l":"Server.Shutdown(ctx)","n":"Shutdown closes listeners and waits for active requests, up to a deadline."},{"f":3,"t":2,"l":"Finish response","n":"The in-flight request completes normally and the connection closes."},{"f":1,"t":1,"l":"Cancel background work","n":"A root context is cancelled so workers flush and stop."},{"f":1,"t":0,"l":"Exit 0","n":"The process exits cleanly before the grace period ends, with no dropped requests."}]},{"id":"x-go-error-wrapping","module":"go","lesson":"go/functions-errors-and-defer","title":"Wrapping and checking errors","summary":"How context is added to an error without losing the cause.","actors":["Low-level code","Service layer","Handler","Logger"],"steps":[{"f":0,"t":0,"l":"os.Open fails","n":"The standard library returns an error that wraps the system error for a missing file."},{"f":0,"t":1,"l":"return err","n":"The service layer receives it and does not hide it."},{"f":1,"t":1,"l":"fmt.Errorf(\"load config: %w\", err)","n":"Wrapping with the %w verb adds context and keeps the original error inside."},{"f":1,"t":2,"l":"Return wrapped error","n":"The handler receives an error whose message shows the full path of the failure."},{"f":2,"t":2,"l":"errors.Is(err, fs.ErrNotExist)","n":"The handler can still test for the original cause through the wrapping."},{"f":2,"t":3,"l":"Log once with context","n":"The error is logged at the edge with request details instead of at every layer."}]},{"id":"x-go-test-table","module":"go","lesson":"go/testing-benchmarks-and-tooling","title":"A table-driven test run","summary":"How go test runs many cases of one function.","actors":["go test","Test function","Subtest","Result"],"steps":[{"f":0,"t":1,"l":"Find TestParse","n":"go test builds the package with its test files and calls each function that starts with Test."},{"f":1,"t":1,"l":"Define cases table","n":"The test holds a slice of cases with a name, input and expected output."},{"f":1,"t":2,"l":"t.Run(case.name)","n":"Each case runs as a subtest, so failures name the exact case."},{"f":2,"t":2,"l":"Compare got and want","n":"The subtest checks the result and calls t.Errorf when it differs."},{"f":2,"t":3,"l":"Pass or fail per case","n":"Results are collected per subtest and shown with -v."},{"f":0,"t":3,"l":"-race and -cover","n":"Adding flags checks data races and reports which lines the tests touched."}]},{"id":"x-go-race-condition","module":"go","lesson":"go/goroutines-channels-and-sync","title":"A data race and its fix","summary":"How two goroutines corrupt a counter and how a mutex fixes it.","actors":["Goroutine A","Counter","Goroutine B","Mutex"],"steps":[{"f":0,"t":1,"l":"Read count = 5","n":"Goroutine A reads the value before incrementing."},{"f":2,"t":1,"l":"Read count = 5","n":"Goroutine B reads the same value at the same moment."},{"f":0,"t":1,"l":"Write count = 6","n":"Goroutine A writes six back to the counter."},{"f":2,"t":1,"l":"Write count = 6","n":"B also writes six, so one increment is lost. This is a data race."},{"f":0,"t":3,"l":"Lock before change","n":"With a mutex, A takes the lock first and B has to wait."},{"f":2,"t":1,"l":"Read 6, write 7","n":"After A unlocks, B sees six and writes seven. Run go test -race to catch the unsafe version."}]},{"id":"x-go-container-build","module":"go","lesson":"go/building-containers-and-cli-tools","title":"A multi-stage Go image","summary":"How a Go program ends up in a tiny container.","actors":["Dockerfile","Build stage","Final stage","Registry"],"steps":[{"f":0,"t":1,"l":"FROM golang AS build","n":"The first stage has the full toolchain needed to compile."},{"f":1,"t":1,"l":"Copy go.mod, download modules","n":"Copying the module files first lets Docker reuse the download layer when only code changes."},{"f":1,"t":1,"l":"CGO_ENABLED=0 go build","n":"The program is compiled into a static binary with no external libraries."},{"f":1,"t":2,"l":"COPY --from=build /app","n":"Only the binary is copied into the final image."},{"f":2,"t":2,"l":"USER nonroot","n":"The final image runs as a non-root user on a minimal base such as distroless."},{"f":2,"t":3,"l":"Push image","n":"The result is tens of megabytes, which pulls and starts quickly."}]},{"id":"x-go-pprof-profile","module":"go","lesson":"go/debugging-go-programs","title":"Profiling a slow Go service","summary":"How pprof shows where CPU time goes.","actors":["Engineer","Service","pprof endpoint","Flame graph"],"steps":[{"f":0,"t":1,"l":"Notice high CPU","n":"Dashboards show the service using more CPU for the same traffic."},{"f":0,"t":2,"l":"Fetch 30 s profile","n":"The engineer requests a CPU profile from the internal debug port during load."},{"f":2,"t":2,"l":"Sample stacks","n":"The runtime samples call stacks about 100 times per second for the duration."},{"f":2,"t":3,"l":"Render flame graph","n":"Wide boxes show functions that use the most time."},{"f":0,"t":3,"l":"Find JSON encoding in a loop","n":"The widest box is repeated encoding of the same value, which can be cached."},{"f":0,"t":1,"l":"Fix and compare","n":"After the change a new profile shows the box gone and CPU use down."}]},{"id":"x-go-goroutine-leak","module":"go","lesson":"go/debugging-go-programs","title":"How a goroutine leaks","summary":"How an abandoned sender blocks forever and memory grows.","actors":["Handler","Worker goroutine","Channel","Metrics"],"steps":[{"f":0,"t":1,"l":"Start worker","n":"The handler starts a goroutine that will send its result on an unbuffered channel."},{"f":0,"t":0,"l":"Timeout, return","n":"The handler gives up after a timeout and returns an error to the client."},{"f":1,"t":1,"l":"Worker finishes later","n":"The slow call completes after the handler is gone."},{"f":1,"t":2,"l":"Send blocks","n":"The send waits for a receiver that will never come."},{"f":2,"t":3,"l":"Goroutine count rises","n":"Every timed-out request leaves one blocked goroutine, so memory grows steadily."},{"f":0,"t":1,"l":"Fix with ctx and buffer","n":"Using select on ctx.Done and a buffer of one lets the worker exit and the count stays flat."}]},{"id":"x-go-modules-checksum","module":"go","lesson":"go/interfaces-and-packages","title":"Modules and go.sum","summary":"How Go verifies dependencies.","actors":["Developer","go.mod","Module proxy","go.sum"],"steps":[{"f":0,"t":1,"l":"go get example.com/lib@v1.4.0","n":"A dependency is added with an exact version in go.mod."},{"f":1,"t":2,"l":"Download module","n":"The go command fetches the module, usually through a proxy."},{"f":2,"t":3,"l":"Record hash","n":"The content hash is written to go.sum."},{"f":0,"t":3,"l":"Commit both files","n":"Both files are committed so every machine builds the same code."},{"f":2,"t":3,"l":"Later build compares","n":"On another machine, the downloaded content must match the recorded hash."},{"f":3,"t":0,"l":"Mismatch fails the build","n":"If the content differs, the build stops, which protects against tampered or changed modules."}]},{"id":"x-helm-install-flow","module":"helm","lesson":"helm/what-helm-is-and-why-use-it","title":"What helm install does","summary":"From command to objects running in the cluster.","actors":["Engineer","Helm CLI","Kubernetes API","Release Secret"],"steps":[{"f":0,"t":1,"l":"helm install shop-web ./chart -f prod.yaml","n":"The command names the release, the chart and the values files."},{"f":1,"t":1,"l":"Merge values","n":"Chart defaults, values files and --set flags are merged in order of priority."},{"f":1,"t":1,"l":"Render templates","n":"The templates are rendered into plain Kubernetes manifests using the merged values."},{"f":1,"t":2,"l":"Send manifests","n":"Helm sends the rendered objects to the API server using your kubeconfig."},{"f":1,"t":3,"l":"Store revision 1","n":"The release record with chart, values and manifest is stored as a Secret in the namespace."},{"f":2,"t":0,"l":"Pods start","n":"The cluster creates the objects and pods start. helm status shows the release as deployed."}]},{"id":"x-helm-upgrade-atomic","module":"helm","lesson":"helm/upgrade-rollback-and-release-history","title":"An atomic upgrade that rolls back","summary":"How --atomic protects a release from a bad rollout.","actors":["Pipeline","Helm","Cluster","Release history"],"steps":[{"f":0,"t":1,"l":"helm upgrade --atomic --wait","n":"The pipeline asks for an upgrade that must become healthy before it counts as done."},{"f":1,"t":3,"l":"Create revision 5","n":"Helm records a new revision as pending-upgrade."},{"f":1,"t":2,"l":"Apply new manifests","n":"The Deployment is updated and new pods start with the new image."},{"f":2,"t":2,"l":"Readiness probe fails","n":"The new pods never become ready, because the app crashes on startup."},{"f":1,"t":2,"l":"Timeout reached, roll back","n":"After the timeout Helm re-applies the manifest of revision 4."},{"f":1,"t":0,"l":"Exit with error","n":"The pipeline fails while the site keeps serving the old version."}]},{"id":"x-helm-values-merge","module":"helm","lesson":"helm/values-per-environment-and-secrets","title":"How values are merged","summary":"Which setting wins when several sources provide the same key.","actors":["Chart values.yaml","values-prod.yaml","--set flag","Final values"],"steps":[{"f":0,"t":3,"l":"replicaCount: 2","n":"The chart supplies a default for every setting it supports."},{"f":1,"t":3,"l":"replicaCount: 4","n":"The environment file overrides the default for production."},{"f":2,"t":3,"l":"replicaCount=6","n":"A --set flag on the command line has the highest priority and wins."},{"f":0,"t":3,"l":"hosts: [a, b]","n":"The chart default list has two hosts."},{"f":1,"t":3,"l":"hosts: [c]","n":"The environment list replaces the whole default list, not just one item."},{"f":3,"t":3,"l":"helm get values -a","n":"After installing, this command shows exactly which values were used."}]},{"id":"x-helm-template-render","module":"helm","lesson":"helm/templates-and-the-go-template-language","title":"Rendering a template","summary":"How curly braces become YAML.","actors":["values.yaml","Template file","Template engine","Manifest"],"steps":[{"f":1,"t":1,"l":"replicas: {{ .Values.replicaCount }}","n":"The template contains a placeholder for the value."},{"f":0,"t":2,"l":"replicaCount: 4","n":"The engine reads the value from the merged settings."},{"f":2,"t":2,"l":"Evaluate pipes and functions","n":"Functions such as default, quote and toYaml transform values."},{"f":2,"t":2,"l":"Trim whitespace","n":"Dashes in braces remove blank lines and keep the indentation valid."},{"f":2,"t":3,"l":"replicas: 4","n":"The result is a plain Kubernetes manifest with no braces left."},{"f":3,"t":3,"l":"helm template shows it","n":"Running helm template prints the result so you can check it before applying."}]},{"id":"x-helm-rollback","module":"helm","lesson":"helm/upgrade-rollback-and-release-history","title":"Rolling back a release","summary":"How a rollback creates a new revision from an older one.","actors":["Engineer","Helm","Release history","Cluster"],"steps":[{"f":0,"t":1,"l":"helm history shop-web","n":"The engineer lists revisions and finds the last good one, revision 7."},{"f":1,"t":2,"l":"Read revision 7","n":"Helm loads the stored manifest and values of that revision."},{"f":0,"t":1,"l":"helm rollback shop-web 7 --wait","n":"The rollback command is issued and waits for readiness."},{"f":1,"t":3,"l":"Apply old manifest","n":"The objects are patched back to the state described in revision 7."},{"f":1,"t":2,"l":"Record revision 9","n":"A new revision is stored. History only grows."},{"f":3,"t":0,"l":"Pods ready","n":"The previous version serves traffic again. Data changes are not undone."}]},{"id":"x-helm-secret-leak","module":"helm","lesson":"helm/values-per-environment-and-secrets","title":"Why secrets do not belong in values","summary":"Where a password in values ends up.","actors":["Developer","Repository","Helm release","Reader"],"steps":[{"f":0,"t":1,"l":"Commit values-prod.yaml","n":"A password is committed in a values file."},{"f":1,"t":1,"l":"Stays in history","n":"Deleting the line later does not remove it from past commits and clones."},{"f":0,"t":2,"l":"helm upgrade -f values-prod.yaml","n":"The value is passed to the chart and stored in the release Secret."},{"f":3,"t":2,"l":"helm get values","n":"Anyone who can read the release Secret can print the password."},{"f":0,"t":0,"l":"Rotate the password","n":"Treat the secret as exposed and change it."},{"f":0,"t":2,"l":"Use existingSecret","n":"The chart now takes only the name of a Secret created by a secret manager."}]},{"id":"x-helm-dependency-update","module":"helm","lesson":"helm/dependencies-subcharts-and-registries","title":"Updating chart dependencies","summary":"How a subchart is pinned and fetched.","actors":["Chart.yaml","helm dependency update","Repository","Chart.lock"],"steps":[{"f":0,"t":1,"l":"dependencies: redis 19.6.2","n":"The chart lists the dependency with a version and a repository."},{"f":1,"t":2,"l":"Download the chart","n":"Helm fetches the exact version from the repository or registry."},{"f":1,"t":1,"l":"Save into charts/","n":"The package is stored in the charts folder of your chart."},{"f":1,"t":3,"l":"Write digest","n":"The lock file records the exact version and a digest."},{"f":3,"t":3,"l":"Commit Chart.lock","n":"Committing the lock keeps builds repeatable."},{"f":1,"t":3,"l":"helm dependency build","n":"CI rebuilds from the lock and does not pick up unreviewed updates."}]},{"id":"x-helm-oci-publish","module":"helm","lesson":"helm/dependencies-subcharts-and-registries","title":"Publishing a chart to an OCI registry","summary":"From chart folder to a versioned package.","actors":["Developer","Helm","Registry","Cluster"],"steps":[{"f":0,"t":1,"l":"helm package ./chart","n":"The chart is packed into a versioned .tgz file."},{"f":0,"t":1,"l":"helm registry login","n":"Helm authenticates to the registry."},{"f":1,"t":2,"l":"helm push chart.tgz oci://...","n":"The package is uploaded as an OCI artifact next to container images."},{"f":2,"t":2,"l":"Store immutable version","n":"The registry keeps the version and can sign or scan it."},{"f":3,"t":2,"l":"helm install oci://...","n":"A cluster pipeline pulls the exact version."},{"f":2,"t":3,"l":"Return the chart","n":"The pipeline now installs the same package that was reviewed."}]},{"id":"x-helm-hook-migration","module":"helm","lesson":"helm/upgrade-rollback-and-release-history","title":"A pre-upgrade migration hook","summary":"How a Job runs before the new version starts.","actors":["Helm","Hook Job","Database","Deployment"],"steps":[{"f":0,"t":0,"l":"Start upgrade","n":"Helm renders all templates, including those marked as hooks."},{"f":0,"t":1,"l":"Run pre-upgrade Job","n":"The hook Job is created before the other objects are changed."},{"f":1,"t":2,"l":"Apply schema change","n":"The Job runs the migration against the database."},{"f":1,"t":0,"l":"Job completed","n":"Helm waits for the Job and continues only if it succeeded."},{"f":0,"t":3,"l":"Update Deployment","n":"Now the new application version is rolled out."},{"f":0,"t":1,"l":"Delete policy removes Job","n":"A delete policy cleans up the finished Job. A failed hook stops the whole upgrade."}]},{"id":"x-helm-pending-upgrade","module":"helm","lesson":"helm/upgrade-rollback-and-release-history","title":"A release stuck in pending-upgrade","summary":"How an interrupted job blocks later deployments.","actors":["Pipeline","Helm","Release history","On-call engineer"],"steps":[{"f":0,"t":1,"l":"helm upgrade starts","n":"The pipeline begins an upgrade."},{"f":1,"t":2,"l":"Record pending-upgrade","n":"Helm stores the new revision in a pending state."},{"f":0,"t":0,"l":"Runner is killed","n":"The CI runner is terminated before Helm finishes."},{"f":0,"t":1,"l":"Next run","n":"A later pipeline run starts another upgrade."},{"f":1,"t":0,"l":"another operation is in progress","n":"Helm refuses because the last revision never finished."},{"f":3,"t":1,"l":"helm rollback to deployed revision","n":"The engineer rolls back to the last deployed revision, which resets the state, and the next upgrade works."}]},{"id":"x-helm-test-hook","module":"helm","lesson":"helm/debugging-helm-releases","title":"Running helm test","summary":"How a smoke test pod checks a release.","actors":["Engineer","Helm","Test pod","Application"],"steps":[{"f":0,"t":1,"l":"helm test shop-web","n":"After a deploy, the engineer or pipeline asks Helm to run the chart tests."},{"f":1,"t":2,"l":"Create test pod","n":"Helm creates the Pod marked with the test hook."},{"f":2,"t":3,"l":"curl the service","n":"The test pod calls the application the way a client would."},{"f":3,"t":2,"l":"200 OK","n":"A healthy application answers."},{"f":2,"t":1,"l":"Exit 0","n":"The pod exits successfully and Helm reports the test as passed."},{"f":1,"t":0,"l":"Pipeline continues","n":"A failed test fails the job and can trigger a rollback."}]},{"id":"x-helm-diff-drift","module":"helm","lesson":"helm/upgrade-rollback-and-release-history","title":"Detecting drift before an upgrade","summary":"How a diff shows changes made outside Helm.","actors":["Engineer","helm diff","Stored release","Live cluster"],"steps":[{"f":0,"t":1,"l":"helm diff upgrade","n":"Before applying, the engineer asks what would change."},{"f":1,"t":2,"l":"Read last manifest","n":"The plugin loads the manifest of the stored release."},{"f":1,"t":3,"l":"Read live objects","n":"It also reads the objects as they are in the cluster."},{"f":1,"t":1,"l":"Render new manifest","n":"The new chart and values are rendered."},{"f":1,"t":0,"l":"Show differences","n":"The output shows a replica count that someone edited by hand, plus the planned changes."},{"f":0,"t":0,"l":"Decide","n":"The engineer decides whether to keep or overwrite the manual change and records it in version control."}]},{"id":"x-linux-syscall","module":"linux","lesson":"linux/system-calls-strace-and-perf","title":"A system call, step by step","summary":"How a program asks the kernel to read a file.","actors":["Program","C library","Kernel","Disk"],"steps":[{"f":0,"t":1,"l":"read(fd, buf, 4096)","n":"The program calls a library function and does not touch the hardware itself."},{"f":1,"t":2,"l":"Trap into the kernel","n":"The library puts the call number in a register and executes an instruction that switches the CPU to kernel mode."},{"f":2,"t":2,"l":"Check descriptor and permissions","n":"The kernel finds the open file from the descriptor and checks that reading is allowed."},{"f":2,"t":3,"l":"Cache miss: read block","n":"If the page cache does not hold the data, the kernel asks the disk for it."},{"f":3,"t":2,"l":"Data arrives","n":"The block is placed in the page cache and the process is woken."},{"f":2,"t":0,"l":"Return bytes read","n":"The kernel copies the data to the program buffer and switches back to user mode. strace shows this exchange."}]},{"id":"x-linux-oom-kill","module":"linux","lesson":"linux/processes-memory-and-the-oom-killer","title":"How the OOM killer acts","summary":"What happens when memory runs out.","actors":["Application","Kernel allocator","Reclaim","OOM killer"],"steps":[{"f":0,"t":1,"l":"Request more memory","n":"The application touches new pages and the kernel needs physical memory for them."},{"f":1,"t":2,"l":"Free page cache, swap pages","n":"The kernel first reclaims cache and swaps out cold pages."},{"f":2,"t":1,"l":"Nothing left to reclaim","n":"If reclaim fails, allocation cannot succeed."},{"f":1,"t":3,"l":"Invoke OOM killer","n":"The kernel scores processes by memory use and their oom_score_adj."},{"f":3,"t":0,"l":"SIGKILL the victim","n":"The chosen process is killed immediately and cannot clean up."},{"f":3,"t":3,"l":"Log the decision","n":"dmesg shows the killed process, its memory use and a table of candidates."}]},{"id":"x-linux-page-cache-write","module":"linux","lesson":"linux/filesystems-page-cache-and-io","title":"A write and fsync","summary":"Why a write can return before data is on disk.","actors":["Application","Page cache","Kernel flusher","Disk"],"steps":[{"f":0,"t":1,"l":"write(fd, data)","n":"The application writes and the kernel copies the data into a page of the cache."},{"f":1,"t":0,"l":"Return immediately","n":"The call returns quickly while the page is marked dirty."},{"f":0,"t":1,"l":"fsync(fd)","n":"The application asks that its data reach stable storage."},{"f":1,"t":2,"l":"Start writeback","n":"The dirty pages are handed to the flusher."},{"f":2,"t":3,"l":"Write blocks and flush","n":"The device receives the data and flushes its own cache."},{"f":3,"t":0,"l":"fsync returns","n":"Only now is the data safe against power loss. This is why databases are limited by disk latency."}]},{"id":"x-linux-boot-kernel","module":"linux","lesson":"linux/boot-and-kernel","title":"From power on to login","summary":"The main stages of a Linux boot.","actors":["Firmware","Bootloader","Kernel","systemd"],"steps":[{"f":0,"t":0,"l":"Self-test and find boot device","n":"The firmware tests hardware and chooses a boot entry."},{"f":0,"t":1,"l":"Load the bootloader","n":"GRUB or a similar loader starts from the boot partition."},{"f":1,"t":2,"l":"Load kernel and initramfs","n":"The bootloader loads the kernel with its command line and a small temporary root filesystem."},{"f":2,"t":2,"l":"Initialise hardware, mount root","n":"The kernel loads drivers, assembles storage and mounts the real root filesystem."},{"f":2,"t":3,"l":"Start PID 1","n":"The kernel starts systemd as the first process."},{"f":3,"t":3,"l":"Reach the default target","n":"systemd starts services in dependency order until the login prompt or network services are ready."}]},{"id":"x-linux-conntrack-full","module":"linux","lesson":"linux/networking-in-the-kernel-sockets-and-conntrack","title":"A full connection tracking table","summary":"Why new connections fail while CPU is idle.","actors":["Client","NAT gateway","conntrack table","Kernel log"],"steps":[{"f":0,"t":1,"l":"New connection","n":"A client opens a connection through the gateway."},{"f":1,"t":2,"l":"Create tracking entry","n":"The kernel needs a table entry to track and translate the flow."},{"f":2,"t":2,"l":"Table at the limit","n":"The table already holds nf_conntrack_max entries."},{"f":1,"t":3,"l":"table full, dropping packet","n":"The kernel drops the packet and logs a message."},{"f":0,"t":0,"l":"Retry and time out","n":"The client sees timeouts although the application servers are idle."},{"f":1,"t":2,"l":"Raise limit, cut timeouts","n":"The operator raises the limit with memory in mind and shortens timeouts."}]},{"id":"x-linux-sysctl-persist","module":"linux","lesson":"linux/kernel-modules-sysctl-and-boot-parameters","title":"Changing a kernel setting for good","summary":"Runtime change versus persistent change.","actors":["Engineer","sysctl","Running kernel","/etc/sysctl.d"],"steps":[{"f":0,"t":1,"l":"sysctl -w net.core.somaxconn=4096","n":"The engineer changes the value on the running system."},{"f":1,"t":2,"l":"Kernel updates the value","n":"The new limit applies immediately to new listeners."},{"f":0,"t":0,"l":"Reboot later","n":"On reboot, the change is not remembered."},{"f":2,"t":2,"l":"Old default returns","n":"The kernel boots with its built-in default and the problem comes back."},{"f":0,"t":3,"l":"Write 90-net.conf","n":"The engineer saves the setting in a file under /etc/sysctl.d."},{"f":0,"t":1,"l":"sysctl --system","n":"Reloading applies it now and the file applies it at every boot."}]},{"id":"x-bash-pipeline","module":"bash","lesson":"bash/text-processing","title":"How a pipeline runs","summary":"Processes connected by pipes.","actors":["Shell","grep","sort","uniq"],"steps":[{"f":0,"t":0,"l":"Parse the line","n":"The shell splits the command line at pipe characters."},{"f":0,"t":1,"l":"Start grep","n":"The shell starts each command as a process and connects standard output to the next input."},{"f":0,"t":2,"l":"Start sort","n":"All commands run at the same time, linked by pipes."},{"f":1,"t":2,"l":"Stream matching lines","n":"Data flows from grep into sort as it is produced."},{"f":2,"t":3,"l":"Sorted lines to uniq","n":"sort needs all input before it can output, then uniq counts duplicates."},{"f":3,"t":0,"l":"Exit status","n":"The pipeline returns the status of the last command unless pipefail is set."}]},{"id":"x-python-requests-retry","module":"python","lesson":"python/http-apis-and-json","title":"A request with retry and backoff","summary":"How a script survives a flaky API.","actors":["Script","HTTP client","API","Timer"],"steps":[{"f":0,"t":1,"l":"get(url, timeout=5)","n":"The script sets a timeout so it never waits forever."},{"f":1,"t":2,"l":"Request","n":"The client sends the request over the network with the timeout set."},{"f":2,"t":1,"l":"503 Service Unavailable","n":"The API reports a temporary problem."},{"f":1,"t":3,"l":"Wait 1 s plus jitter","n":"The client waits before trying again, with random jitter."},{"f":1,"t":2,"l":"Retry","n":"The second attempt is sent after the pause to give the API time to recover."},{"f":2,"t":0,"l":"200 OK","n":"The result is returned. After a few failures the client stops and raises a clear error."}]},{"id":"x-net-http-keepalive","module":"networking","lesson":"networking/http-and-tls","title":"Keep-alive connections","summary":"Why reusing a connection saves time.","actors":["Client","Server","Handshake","Pool"],"steps":[{"f":0,"t":2,"l":"First request: TCP and TLS","n":"A new connection needs a TCP handshake and a TLS handshake before data."},{"f":0,"t":1,"l":"GET /a","n":"The first request is sent over the new connection."},{"f":1,"t":0,"l":"200 + Connection kept","n":"The server keeps the connection open."},{"f":0,"t":3,"l":"Return to pool","n":"The client keeps the connection in a pool."},{"f":0,"t":1,"l":"GET /b on same connection","n":"The next request skips the handshakes and starts at once."},{"f":1,"t":0,"l":"Idle timeout closes it","n":"Unused connections are closed by timeouts. Middleboxes may close them earlier."}]},{"id":"x-net-load-balancer-failover","module":"networking","lesson":"networking/firewalls-and-load-balancing","title":"Failing over with a health check","summary":"How a load balancer stops sending to a broken server.","actors":["Client","Load balancer","Server A","Server B"],"steps":[{"f":0,"t":1,"l":"Request","n":"A client sends a request to the load balancer address."},{"f":1,"t":2,"l":"Forward to A","n":"The balancer picks a healthy server."},{"f":1,"t":2,"l":"Health check fails","n":"Server A stops answering the check path."},{"f":1,"t":1,"l":"Mark A unhealthy","n":"After several failures the balancer removes A from rotation."},{"f":0,"t":1,"l":"Next request","n":"New requests keep arriving while server A is still broken."},{"f":1,"t":3,"l":"Forward to B","n":"Traffic goes to the remaining healthy server until A passes checks again."}]},{"id":"x-docker-container-start","module":"docker","lesson":"docker/containers-and-images","title":"What docker run does","summary":"From image to running process.","actors":["CLI","Docker daemon","Registry","Kernel"],"steps":[{"f":0,"t":1,"l":"docker run -p 8080:80 web","n":"The CLI sends the request to the daemon."},{"f":1,"t":2,"l":"Pull missing layers","n":"If the image is not local, the daemon downloads the layers."},{"f":1,"t":1,"l":"Create container filesystem","n":"Layers are stacked read-only with a writable layer on top."},{"f":1,"t":3,"l":"Set up namespaces and cgroups","n":"The kernel isolates processes, network and mounts and applies resource limits."},{"f":1,"t":3,"l":"Start the process","n":"The image command becomes process 1 in the container."},{"f":3,"t":0,"l":"Port mapped","n":"Traffic to host port 8080 reaches port 80 in the container."}]},{"id":"x-cicd-canary","module":"cicd","lesson":"cicd/deployment-strategies","title":"A canary release","summary":"Sending a small share of traffic to the new version.","actors":["Pipeline","Router","Stable version","Canary version"],"steps":[{"f":0,"t":3,"l":"Deploy canary","n":"The pipeline starts the new version beside the old one."},{"f":0,"t":1,"l":"Send 5 percent","n":"The router sends a small share of traffic to the canary."},{"f":1,"t":3,"l":"Watch errors and latency","n":"Metrics from the canary are compared with the stable version."},{"f":3,"t":0,"l":"Healthy","n":"If the canary meets the targets, the pipeline continues."},{"f":0,"t":1,"l":"Increase to 50, then 100","n":"Traffic is shifted in steps with checks between them."},{"f":0,"t":2,"l":"Roll back if worse","n":"If error rates rise, traffic returns to the stable version at once."}]},{"id":"x-k8s-rolling-update","module":"kubernetes","lesson":"kubernetes/pods-and-deployments","title":"A rolling update","summary":"How a Deployment replaces pods without downtime.","actors":["Engineer","Deployment","New pods","Old pods"],"steps":[{"f":0,"t":1,"l":"Set new image","n":"The engineer changes the image in the Deployment."},{"f":1,"t":2,"l":"Create one new pod","n":"The controller adds a pod with the new template, within maxSurge."},{"f":2,"t":2,"l":"Readiness passes","n":"The new pod receives traffic only after its readiness probe succeeds."},{"f":1,"t":3,"l":"Terminate one old pod","n":"An old pod is stopped, within maxUnavailable."},{"f":1,"t":2,"l":"Repeat","n":"The controller continues in small steps until all pods are new."},{"f":1,"t":0,"l":"Rollout complete","n":"kubectl rollout status reports success. A failing probe stops the rollout and keeps old pods."}]},{"id":"x-k8s-crashloop","module":"kubernetes","lesson":"kubernetes/debugging-kubernetes-workloads","title":"Why a pod is in CrashLoopBackOff","summary":"How restarts slow down after repeated failure.","actors":["kubelet","Container","API server","Engineer"],"steps":[{"f":0,"t":1,"l":"Start container","n":"The kubelet starts the container."},{"f":1,"t":1,"l":"Process exits with an error","n":"The application stops because of bad configuration."},{"f":0,"t":1,"l":"Restart after delay","n":"The kubelet restarts it after a short delay."},{"f":1,"t":1,"l":"Exits again","n":"The same error repeats on every start because nothing has changed."},{"f":0,"t":2,"l":"Report CrashLoopBackOff","n":"The delay grows up to five minutes and the pod status shows the back-off."},{"f":3,"t":2,"l":"kubectl logs --previous","n":"The engineer reads the last run logs and describe events to find the cause."}]},{"id":"x-tf-plan-apply","module":"terraform","lesson":"terraform/workflows-and-drift","title":"Plan and apply","summary":"How Terraform compares code, state and reality.","actors":["Engineer","Terraform","State file","Cloud API"],"steps":[{"f":0,"t":1,"l":"terraform plan","n":"The engineer asks what would change."},{"f":1,"t":2,"l":"Read state","n":"Terraform loads what it believes exists."},{"f":1,"t":3,"l":"Refresh real resources","n":"It queries the cloud for the current settings."},{"f":1,"t":0,"l":"Show the plan","n":"The plan lists additions, changes and destroys for review."},{"f":0,"t":1,"l":"terraform apply","n":"After approval, Terraform makes the calls."},{"f":1,"t":2,"l":"Update state","n":"The state is written with the new resource IDs."}]},{"id":"x-cloud-iam-assume-role","module":"cloud","lesson":"cloud/identity-and-access","title":"Assuming a role","summary":"How a service gets temporary credentials.","actors":["Service","Identity service","Role policy","Resource"],"steps":[{"f":0,"t":1,"l":"Request a role","n":"The service asks to assume a role."},{"f":1,"t":2,"l":"Check trust policy","n":"The trust policy says who may assume the role."},{"f":2,"t":1,"l":"Allowed","n":"The check passes because the caller identity is on the trust list."},{"f":1,"t":0,"l":"Temporary credentials","n":"The service receives credentials that expire soon."},{"f":0,"t":3,"l":"Call the resource","n":"The service calls the resource with them."},{"f":3,"t":0,"l":"Allowed by permissions","n":"The permission policy of the role limits what succeeds. No long-term keys are stored."}]},{"id":"x-obs-trace-request","module":"observability","lesson":"observability/logs-and-traces","title":"One request traced across services","summary":"How a trace connects spans.","actors":["User","Gateway","Orders service","Database"],"steps":[{"f":0,"t":1,"l":"Request","n":"The user request reaches the gateway, which creates a trace ID."},{"f":1,"t":2,"l":"Call with trace header","n":"The ID travels in a header to the next service."},{"f":2,"t":3,"l":"Query","n":"The orders service starts a span for its database query."},{"f":3,"t":2,"l":"Slow result","n":"The query takes 900 ms, far longer than the other steps."},{"f":2,"t":1,"l":"Response","n":"The span ends and the response returns."},{"f":1,"t":0,"l":"Trace shows the slow span","n":"In the trace view, the long database span is clearly the cause."}]},{"id":"x-sre-error-budget-spending","module":"sre","lesson":"sre/slos-and-error-budgets","title":"Spending an error budget","summary":"How an SLO guides release decisions.","actors":["Team","SLO","Error budget","Release process"],"steps":[{"f":0,"t":1,"l":"Set 99.9 percent","n":"The team agrees on a target for successful requests."},{"f":1,"t":2,"l":"Allow 0.1 percent errors","n":"The remaining allowance is the error budget for the period."},{"f":2,"t":2,"l":"Incident burns 60 percent","n":"An outage uses most of the budget."},{"f":2,"t":3,"l":"Slow down risky changes","n":"With little budget left, the team focuses on reliability work."},{"f":0,"t":3,"l":"Fix causes","n":"Work is prioritised on the causes of the outage."},{"f":2,"t":3,"l":"Budget recovers","n":"When the period resets or the budget is healthy, normal releases continue."}]},{"id":"x-sec-secret-rotation","module":"security","lesson":"security/secrets-management","title":"Rotating a leaked secret","summary":"The order of actions after a secret leaks.","actors":["Responder","Secret manager","Service","Audit log"],"steps":[{"f":0,"t":1,"l":"Revoke the old secret","n":"The first step makes the leaked value useless."},{"f":1,"t":1,"l":"Create a new secret","n":"A new value is generated in the secret manager."},{"f":1,"t":2,"l":"Service reads new value","n":"Services fetch the new secret at the next refresh or restart."},{"f":0,"t":3,"l":"Check usage logs","n":"The responder looks for use of the old secret from unknown addresses."},{"f":0,"t":2,"l":"Clean history","n":"Copies in repositories and tickets are removed."},{"f":0,"t":0,"l":"Prevent a repeat","n":"Scanning, shorter lifetimes and review of the cause close the incident."}]},{"id":"x-ansible-playbook-run","module":"ansible","lesson":"ansible/playbooks-tasks-and-idempotence","title":"A playbook run","summary":"How Ansible changes servers over SSH.","actors":["Control node","Inventory","Web server","Handler"],"steps":[{"f":0,"t":1,"l":"ansible-playbook site.yml","n":"The control node reads the playbook and selects hosts from the inventory."},{"f":1,"t":0,"l":"Hosts web1, web2","n":"The inventory returns the matching hosts and variables."},{"f":0,"t":2,"l":"Gather facts over SSH","n":"Ansible connects and collects information about each server."},{"f":0,"t":2,"l":"Run tasks","n":"Each task is a module with a desired state, run on every host."},{"f":2,"t":3,"l":"Config changed: notify","n":"A changed file notifies a handler."},{"f":3,"t":2,"l":"Restart once at end","n":"The handler restarts the service once. A second run reports no changes, which shows idempotence."}]},{"id":"x-db-replication-lag","module":"databases","lesson":"databases/replication-and-failover","title":"Replication and lag","summary":"Why a read replica may return old data.","actors":["Application","Primary","Replica","Log"],"steps":[{"f":0,"t":1,"l":"Write order","n":"The application writes to the primary."},{"f":1,"t":3,"l":"Append to log","n":"The primary records the change in its log."},{"f":3,"t":2,"l":"Ship the log","n":"The replica receives and applies the changes."},{"f":0,"t":2,"l":"Read immediately","n":"A read on the replica comes before the change is applied."},{"f":2,"t":0,"l":"Old value","n":"The application sees stale data. This delay is called replication lag."},{"f":0,"t":1,"l":"Read from primary when needed","n":"Read-your-writes cases use the primary or wait for the replica."}]},{"id":"x-git-cherry-pick","module":"git","lesson":"git/rebase-and-clean-history","title":"Cherry-pick a fix","summary":"Copying one commit to another branch.","actors":["Developer","main","release branch","Reviewer"],"steps":[{"f":0,"t":1,"l":"Fix merged on main","n":"The fix is committed and reviewed on main first."},{"f":0,"t":2,"l":"git switch release/3.2","n":"The developer switches to the release branch."},{"f":0,"t":2,"l":"git cherry-pick abc1234","n":"Git creates a new commit with the same change on top of the branch."},{"f":2,"t":2,"l":"Resolve conflicts if any","n":"If the surrounding code differs, the developer edits and continues."},{"f":2,"t":3,"l":"Open a pull request","n":"The release change is reviewed like any other."},{"f":3,"t":2,"l":"Merge and tag","n":"After checks pass, the fix is merged and a patch release is tagged."}]},{"id":"x-llm-tokenization","module":"llm","lesson":"llm/what-an-llm-is-and-how-it-predicts-tokens","title":"How text becomes tokens","summary":"What the model reads and what you are billed for.","actors":["Your app","Tokenizer","Model","Billing"],"steps":[{"f":0,"t":1,"l":"Send text","n":"Your application sends the prompt as ordinary text."},{"f":1,"t":1,"l":"Split into tokens","n":"The tokenizer cuts the text into small pieces, roughly four characters of English each."},{"f":1,"t":2,"l":"Map to numbers","n":"Each token becomes an ID number that the model can process."},{"f":2,"t":2,"l":"Process the sequence","n":"The model reads all token IDs together and builds context from them."},{"f":2,"t":3,"l":"Count usage","n":"Input and output tokens are counted for the request."},{"f":3,"t":0,"l":"Report usage","n":"The response includes token counts, which you log to track cost and limits."}]},{"id":"x-llm-next-token-loop","module":"llm","lesson":"llm/what-an-llm-is-and-how-it-predicts-tokens","title":"The next-token loop","summary":"How one answer is produced one token at a time.","actors":["Prompt","Model","Sampler","Output"],"steps":[{"f":0,"t":1,"l":"Read the prompt","n":"The model receives all prompt tokens as its starting context."},{"f":1,"t":1,"l":"Score every token","n":"It computes a probability for every possible next token."},{"f":1,"t":2,"l":"Pick one","n":"The sampler chooses a token based on the probabilities and the temperature setting."},{"f":2,"t":3,"l":"Append the token","n":"The chosen token is added to the output."},{"f":3,"t":1,"l":"Feed it back","n":"The new token becomes part of the context for the next step."},{"f":2,"t":3,"l":"Stop","n":"The loop ends at an end token or the length limit, and the stop reason is reported."}]},{"id":"x-llm-context-window","module":"llm","lesson":"llm/tokens-context-windows-and-limits","title":"Filling the context window","summary":"Why long chats and big documents run into a limit.","actors":["System prompt","Chat history","Documents","Model"],"steps":[{"f":0,"t":3,"l":"Fixed instructions","n":"The system prompt is sent first on every request and always uses space."},{"f":1,"t":3,"l":"History grows","n":"Each turn adds the question and the answer, so the history gets longer."},{"f":2,"t":3,"l":"Add documents","n":"Retrieved text or files are added and may take thousands of tokens."},{"f":3,"t":3,"l":"Reserve output space","n":"Room for the answer must remain, because input and output share the window."},{"f":3,"t":1,"l":"Limit reached","n":"If the total is too large the request fails or older parts must be removed."},{"f":1,"t":1,"l":"Trim or summarise","n":"Your application removes or summarises old turns so the important parts still fit."}]},{"id":"x-llm-temperature","module":"llm","lesson":"llm/sampling-temperature-and-determinism","title":"What temperature changes","summary":"How the same prompt can give different answers.","actors":["Model scores","Low temperature","High temperature","Your test"],"steps":[{"f":0,"t":0,"l":"Probabilities","n":"The model gives each candidate token a probability, such as 60, 25 and 15 percent."},{"f":0,"t":1,"l":"Sharpen","n":"A low temperature makes the likely token even more likely."},{"f":1,"t":3,"l":"Stable results","n":"Answers are nearly the same each run, which suits extraction and classification."},{"f":0,"t":2,"l":"Flatten","n":"A high temperature gives unlikely tokens a better chance."},{"f":2,"t":3,"l":"Varied results","n":"Answers differ between runs, which suits brainstorming but is harder to test."},{"f":3,"t":3,"l":"Test the property","n":"Even at low temperature you check required properties over several runs, not exact text."}]},{"id":"x-llm-stateless-chat","module":"llm","lesson":"llm/calling-an-llm-api","title":"Why the API forgets","summary":"How a chat works when the API is stateless.","actors":["User","Your app","Model API","Database"],"steps":[{"f":0,"t":1,"l":"Ask question one","n":"The user sends the first message."},{"f":1,"t":2,"l":"Call with message one","n":"Your application sends the system prompt and message one."},{"f":2,"t":1,"l":"Return answer one","n":"The model replies and keeps nothing about the exchange."},{"f":1,"t":3,"l":"Store the turn","n":"Your application saves both messages in its database."},{"f":0,"t":1,"l":"Ask question two","n":"The user sends a follow-up that depends on the first answer."},{"f":1,"t":2,"l":"Resend all history","n":"Your application sends the earlier messages plus the new one, which is why the model seems to remember."}]},{"id":"x-llm-streaming","module":"llm","lesson":"llm/calling-an-llm-api","title":"Streaming a response","summary":"How tokens reach the screen before the answer is finished.","actors":["Browser","Your server","Model API","Parser"],"steps":[{"f":0,"t":1,"l":"Open request","n":"The browser asks for an answer and keeps the connection open."},{"f":1,"t":2,"l":"Request a stream","n":"The server calls the API with streaming turned on."},{"f":2,"t":1,"l":"Send small events","n":"The API sends text pieces as soon as they are produced."},{"f":1,"t":0,"l":"Forward pieces","n":"The server passes each piece to the browser, which shows it at once."},{"f":2,"t":3,"l":"Final event","n":"A last event carries the stop reason and the usage counts."},{"f":3,"t":3,"l":"Parse after completion","n":"Structured data is parsed only when the full reply has arrived and the stop reason is normal."}]},{"id":"x-llm-prompt-caching","module":"llm","lesson":"llm/cost-latency-and-caching","title":"Prompt caching","summary":"How a repeated prefix becomes cheaper and faster.","actors":["Request one","Cache","Request two","Billing"],"steps":[{"f":0,"t":1,"l":"Mark a stable prefix","n":"The first request puts a long, unchanging manual at the start of the prompt."},{"f":1,"t":1,"l":"Store the prefix","n":"The provider stores the processed prefix for a short time."},{"f":0,"t":3,"l":"Pay full price once","n":"The first request is billed at the normal input rate plus a small write cost."},{"f":2,"t":1,"l":"Send the same prefix","n":"The second request begins with exactly the same text."},{"f":1,"t":2,"l":"Reuse","n":"The stored work is reused, so the answer starts sooner."},{"f":2,"t":3,"l":"Pay less","n":"The reused tokens are billed at a lower rate, and the usage report shows cache reads."}]},{"id":"x-llm-rate-limit-backoff","module":"llm","lesson":"llm/calling-an-llm-api","title":"Handling a rate limit","summary":"Why retrying at once makes things worse.","actors":["Worker","Model API","Backoff timer","Alert"],"steps":[{"f":0,"t":1,"l":"Send a burst","n":"A batch job sends many requests at once."},{"f":1,"t":0,"l":"Return 429","n":"The API answers with a rate limit error and may include a retry-after time."},{"f":0,"t":2,"l":"Wait","n":"The worker waits for the longer of the retry-after time and a growing delay."},{"f":2,"t":0,"l":"Add jitter","n":"A small random amount is added so workers do not all retry together."},{"f":0,"t":1,"l":"Retry","n":"The worker tries again with lower concurrency."},{"f":0,"t":3,"l":"Alert on persistent errors","n":"If failures continue, an alert warns the team instead of looping forever."}]},{"id":"x-llm-grounded-answer","module":"llm","lesson":"llm/training-fine-tuning-and-where-knowledge-comes-from","title":"A grounded answer with retrieval","summary":"How supplying facts reduces invented answers.","actors":["Question","Search index","Prompt builder","Model"],"steps":[{"f":0,"t":1,"l":"Question arrives","n":"A customer asks about the returns policy."},{"f":1,"t":2,"l":"Retrieve passages","n":"The index returns the few most relevant policy passages."},{"f":2,"t":3,"l":"Build the prompt","n":"The passages are placed in tags with the question and a rule to answer only from them."},{"f":3,"t":3,"l":"Answer with quotes","n":"The model answers and quotes the sentence it used."},{"f":2,"t":0,"l":"Show sources","n":"The reply links to the source passages so the customer can check."},{"f":1,"t":1,"l":"Monitor retrieval","n":"Known test questions confirm that the right passage is still found after each update."}]},{"id":"x-llm-truncated-reply","module":"llm","lesson":"llm/tokens-context-windows-and-limits","title":"A reply cut off by the limit","summary":"Why JSON sometimes fails to parse.","actors":["Request","Model","Stop reason","Parser"],"steps":[{"f":0,"t":1,"l":"Ask for a long report","n":"The request asks for a large JSON document with a small output limit."},{"f":1,"t":1,"l":"Generate tokens","n":"The model writes tokens until the limit is reached."},{"f":1,"t":2,"l":"Stop early","n":"The reply ends in the middle of a string and the stop reason says max_tokens."},{"f":2,"t":3,"l":"Skip the check","n":"A careless pipeline sends the text straight to the parser."},{"f":3,"t":3,"l":"Parse error","n":"The parser fails because the JSON is unfinished."},{"f":2,"t":0,"l":"Check first","n":"A good pipeline reads the stop reason, raises the limit or shortens the task, and tries again."}]},{"id":"x-llm-choose-technique","module":"llm","lesson":"llm/training-fine-tuning-and-where-knowledge-comes-from","title":"Prompt, retrieve or fine-tune","summary":"How to choose how to give a model what it needs.","actors":["Problem","Prompt","Retrieval","Fine-tuning"],"steps":[{"f":0,"t":1,"l":"Start with the prompt","n":"Clear instructions and examples solve many problems cheaply."},{"f":1,"t":0,"l":"Measure","n":"An evaluation set shows whether the prompt is good enough."},{"f":0,"t":2,"l":"Add retrieval for facts","n":"If the answer needs private or changing facts, retrieve them at request time."},{"f":2,"t":0,"l":"Measure again","n":"Check that answers are correct and cite the retrieved text."},{"f":0,"t":3,"l":"Fine-tune for behaviour","n":"Training helps with a stable style or format that prompting cannot achieve."},{"f":3,"t":0,"l":"Compare cost and risk","n":"Compare quality gain with data work and maintenance, and keep the evaluation as the judge."}]},{"id":"x-llm-eval-in-ci","module":"llm","lesson":"llm/choosing-and-evaluating-models","title":"Evaluation in CI","summary":"How a model or prompt change is checked before release.","actors":["Developer","CI pipeline","Evaluation set","Model API"],"steps":[{"f":0,"t":1,"l":"Open a pull request","n":"A change to a prompt or model version is proposed."},{"f":1,"t":2,"l":"Load the cases","n":"The pipeline loads saved realistic inputs with expected properties."},{"f":1,"t":3,"l":"Run each case","n":"Each case is sent to the model, several times where variation matters."},{"f":3,"t":2,"l":"Score results","n":"Checks in code score format, required facts and forbidden content."},{"f":2,"t":1,"l":"Compare to threshold","n":"The pass rate is compared with the last release and a minimum."},{"f":1,"t":0,"l":"Block or allow","n":"The pull request fails with the failing cases listed if the rate drops."}]},{"id":"x-llm-incident-trace","module":"llm","lesson":"llm/debugging-llm-applications","title":"Investigating a bad answer","summary":"How stored traces explain a wrong answer.","actors":["User report","Trace store","Engineer","Evaluation set"],"steps":[{"f":0,"t":2,"l":"Report a wrong answer","n":"A user shares the time and the question that went wrong."},{"f":2,"t":1,"l":"Find the trace","n":"The engineer finds the stored prompt, retrieved text, parameters and model version."},{"f":1,"t":2,"l":"Read what the model saw","n":"The needed fact is missing from the retrieved text."},{"f":2,"t":2,"l":"Form a hypothesis","n":"The index was not updated after the document changed."},{"f":2,"t":3,"l":"Add the case","n":"The question is added to the evaluation set with the expected fact."},{"f":2,"t":1,"l":"Fix and monitor","n":"The index job is repaired and an alert watches for stale documents."}]},{"id":"x-prompting-anatomy","module":"prompting","lesson":"prompting/anatomy-of-a-good-prompt","title":"Parts of a good prompt","summary":"What each piece of a prompt is for.","actors":["Author","Prompt","Model","Reviewer"],"steps":[{"f":0,"t":1,"l":"State the task","n":"One clear sentence says what the model must produce."},{"f":0,"t":1,"l":"Add the audience","n":"Saying who reads the result sets tone and detail."},{"f":0,"t":1,"l":"Supply the material","n":"The text to work on is wrapped in tags so it is not mixed with instructions."},{"f":0,"t":1,"l":"Set constraints","n":"Limits such as length and what to avoid are written as measurable rules."},{"f":1,"t":2,"l":"Specify the format","n":"The exact output shape is described, with an example if needed."},{"f":2,"t":3,"l":"Review on real inputs","n":"The reviewer checks answers on varied real examples, not one sample."}]},{"id":"x-prompting-few-shot","module":"prompting","lesson":"prompting/examples-and-few-shot-prompting","title":"How examples steer output","summary":"Why a few good examples beat a long description.","actors":["Author","Examples","Model","Evaluation set"],"steps":[{"f":0,"t":1,"l":"Pick varied cases","n":"Choose three to five realistic inputs that cover normal, borderline and unknown cases."},{"f":0,"t":1,"l":"Write ideal outputs","n":"Each example shows the exact output format and wording wanted."},{"f":1,"t":2,"l":"Place in the prompt","n":"The examples are added in a consistent layout before the real input."},{"f":2,"t":2,"l":"Imitate the pattern","n":"The model copies the format and the decision style from the examples."},{"f":2,"t":3,"l":"Test on unseen inputs","n":"Cases that are not in the prompt measure whether the pattern generalises."},{"f":3,"t":0,"l":"Rebalance","n":"If one label is over-predicted, examples are rebalanced and definitions added."}]},{"id":"x-prompting-reasoning","module":"prompting","lesson":"prompting/reasoning-and-step-by-step-prompts","title":"Reasoning before answering","summary":"When step-by-step thinking helps and when it costs.","actors":["Task","Direct prompt","Reasoning prompt","Evaluation set"],"steps":[{"f":0,"t":1,"l":"Try a direct answer","n":"The model answers a multi-step question in one go."},{"f":1,"t":3,"l":"Measure accuracy","n":"The evaluation set shows many mistakes on steps in the middle."},{"f":0,"t":2,"l":"Ask for steps first","n":"The prompt asks the model to work through the steps before the final answer."},{"f":2,"t":3,"l":"Measure again","n":"Accuracy rises, but tokens and delay also rise."},{"f":2,"t":2,"l":"Separate the answer","n":"The final answer is placed in its own tag so code can extract it."},{"f":3,"t":0,"l":"Choose by data","n":"Simple lookups stay direct, and hard tasks keep the reasoning step."}]},{"id":"x-prompting-system-layout","module":"prompting","lesson":"prompting/system-prompts-roles-and-context-layout","title":"Layout of a system prompt","summary":"Where rules, data and user text belong.","actors":["System message","Context block","User message","Model"],"steps":[{"f":0,"t":3,"l":"Role and rules","n":"Stable instructions about role, boundaries and style go first."},{"f":0,"t":3,"l":"Output contract","n":"The required output format and error behaviour are stated clearly."},{"f":1,"t":3,"l":"Reference data","n":"Documents are added in tags and marked as data, not instructions."},{"f":2,"t":3,"l":"User request","n":"The actual question comes last, close to where the answer begins."},{"f":3,"t":2,"l":"Answer within rules","n":"The model uses the rules, the data and the question together."},{"f":0,"t":1,"l":"No secrets","n":"Secrets and permission checks stay in code, because prompt text can often be revealed."}]},{"id":"x-prompting-structured-output","module":"prompting","lesson":"prompting/structured-output-json-and-schemas","title":"Getting reliable JSON","summary":"From schema to validated data.","actors":["Schema","Model","Validator","Your code"],"steps":[{"f":0,"t":1,"l":"Define the schema","n":"Types, required fields and allowed values are written as JSON Schema."},{"f":1,"t":1,"l":"Constrain the reply","n":"The model is asked through forced tool use or schema output to match the schema."},{"f":1,"t":2,"l":"Return JSON","n":"The reply arrives as text and the stop reason is checked."},{"f":2,"t":2,"l":"Validate","n":"A validator checks types, required fields and enum values."},{"f":2,"t":1,"l":"Retry with the error","n":"On failure, the error message is sent back once for a corrected answer."},{"f":2,"t":3,"l":"Use or review","n":"Valid data goes on, and repeated failures go to a visible review queue."}]},{"id":"x-prompting-repair-loop","module":"prompting","lesson":"prompting/validating-repairing-and-retrying-outputs","title":"The repair and retry loop","summary":"Handling output that does not validate.","actors":["Model","Parser","Retry logic","Review queue"],"steps":[{"f":0,"t":1,"l":"Reply arrives","n":"The model returns text that should be JSON."},{"f":1,"t":1,"l":"Parse fails","n":"The parser reports the exact position of the problem."},{"f":1,"t":2,"l":"Decide","n":"The logic checks the stop reason and whether retries remain."},{"f":2,"t":0,"l":"Retry with feedback","n":"The error and the original request are sent again, with a small retry limit."},{"f":0,"t":1,"l":"Second reply","n":"The next reply parses and validates."},{"f":2,"t":3,"l":"Send failures onward","n":"After the limit, the item goes to a review queue and a counter metric increases."}]},{"id":"x-prompting-version-test","module":"prompting","lesson":"prompting/prompt-versioning-and-testing","title":"Versioning and testing prompts","summary":"How a prompt change reaches production safely.","actors":["Author","Repository","CI","Production"],"steps":[{"f":0,"t":1,"l":"Edit the prompt file","n":"The prompt lives in version control with a changelog."},{"f":1,"t":2,"l":"Open a review","n":"A teammate reviews the change like any code change."},{"f":2,"t":2,"l":"Run the evaluation","n":"CI runs the saved cases and computes a pass rate."},{"f":2,"t":0,"l":"Block regressions","n":"A drop below the threshold fails the check and lists the cases."},{"f":2,"t":3,"l":"Release gradually","n":"A passing change goes to a small share of traffic first."},{"f":3,"t":1,"l":"Roll back by config","n":"A bad result is reverted by switching the version, not by editing text under pressure."}]},{"id":"x-prompting-injection","module":"prompting","lesson":"prompting/system-prompts-roles-and-context-layout","title":"Prompt injection path","summary":"How untrusted text becomes an action.","actors":["Attacker","Document","Assistant","Email tool"],"steps":[{"f":0,"t":1,"l":"Plant instructions","n":"The attacker writes instructions inside a document or ticket."},{"f":1,"t":2,"l":"Assistant reads it","n":"The assistant retrieves the document as part of normal work."},{"f":2,"t":2,"l":"Text looks like orders","n":"The model may treat the planted text as a request."},{"f":2,"t":3,"l":"Calls a tool","n":"With a powerful tool available, the assistant tries to send data out."},{"f":3,"t":0,"l":"Data leaves","n":"Without limits the data reaches the attacker."},{"f":2,"t":3,"l":"Defence in depth","n":"Least privilege, approvals and allowed recipients stop the action even if the model is fooled."}]},{"id":"x-prompting-injection-defence","module":"prompting","lesson":"prompting/system-prompts-roles-and-context-layout","title":"Layers of defence","summary":"How to limit damage from injected text.","actors":["Untrusted text","Prompt","Policy layer","Human approver"],"steps":[{"f":0,"t":1,"l":"Mark as data","n":"Untrusted content is wrapped in tags and described as data."},{"f":1,"t":2,"l":"Request an action","n":"The model asks to use a tool with specific arguments."},{"f":2,"t":2,"l":"Check the policy","n":"Code checks the tool, the arguments and the recipient against an allowed list."},{"f":2,"t":3,"l":"Ask for approval","n":"Risky actions show the exact arguments to a person."},{"f":3,"t":2,"l":"Approve or deny","n":"The decision and the exact arguments are recorded."},{"f":2,"t":0,"l":"Log everything","n":"Every request and decision is logged to review attempts later."}]},{"id":"x-prompting-regression","module":"prompting","lesson":"prompting/prompt-versioning-and-testing","title":"A silent prompt regression","summary":"How a small edit breaks a case no one tested.","actors":["Edit","Production","Users","Evaluation set"],"steps":[{"f":0,"t":1,"l":"Shorten the prompt","n":"Examples are removed to save tokens."},{"f":1,"t":2,"l":"Output changes","n":"Date handling quietly gets worse for one region format."},{"f":2,"t":1,"l":"Wrong data","n":"Invoices carry wrong due dates for two days."},{"f":2,"t":3,"l":"Complaints arrive","n":"Users report problems, but there is no baseline to compare."},{"f":3,"t":0,"l":"Build the set","n":"The failing invoices are added to an evaluation set."},{"f":3,"t":1,"l":"Prevent","n":"CI now runs the set on every prompt change and blocks drops."}]},{"id":"x-prompting-guardrail-check","module":"prompting","lesson":"prompting/validating-repairing-and-retrying-outputs","title":"Checking output in code","summary":"Why exact checks beat polite reminders.","actors":["Model","Output check","Rules","User"],"steps":[{"f":0,"t":1,"l":"Produce a reply","n":"The model writes a customer message."},{"f":1,"t":2,"l":"Load rules","n":"The checker loads rules such as no email addresses or prices."},{"f":1,"t":1,"l":"Scan","n":"Code scans the reply with patterns and arithmetic checks."},{"f":1,"t":0,"l":"Fail the reply","n":"A violating reply is blocked or regenerated with the error."},{"f":1,"t":3,"l":"Pass clean replies","n":"Only checked replies reach the user."},{"f":2,"t":2,"l":"Update rules","n":"New incidents become new checks, so the same problem cannot return silently."}]},{"id":"x-prompting-prompt-debug","module":"prompting","lesson":"prompting/debugging-bad-prompts","title":"Debugging a bad prompt","summary":"A methodical way to find which part fails.","actors":["Failing case","Minimal prompt","Change log","Evaluation set"],"steps":[{"f":0,"t":1,"l":"Collect failures","n":"Gather the real inputs where the prompt fails and find what they share."},{"f":1,"t":1,"l":"Reduce","n":"Remove parts of the prompt until the smallest version that still fails remains."},{"f":1,"t":2,"l":"Change one thing","n":"Alter one instruction or example and write down the change."},{"f":1,"t":3,"l":"Measure on the full set","n":"Run all cases several times and compare pass rates."},{"f":3,"t":2,"l":"Keep or revert","n":"Only changes that improve the whole set are kept."},{"f":2,"t":3,"l":"Add the failures","n":"The original failing inputs join the set permanently."}]},{"id":"x-skills-loading","module":"claude-skills","lesson":"claude-skills/what-a-claude-skill-is","title":"How a skill loads","summary":"Why skills cost little context until needed.","actors":["User request","Skill list","Claude","Skill folder"],"steps":[{"f":1,"t":2,"l":"Descriptions only","n":"At start Claude sees only each skill name and description."},{"f":0,"t":2,"l":"Request arrives","n":"The user asks for a task such as reviewing a contract."},{"f":2,"t":1,"l":"Match","n":"Claude compares the request with the descriptions."},{"f":2,"t":3,"l":"Load SKILL.md","n":"The matching skill body is read into context."},{"f":2,"t":3,"l":"Open linked files","n":"Reference files or scripts are opened only if the task needs them."},{"f":2,"t":0,"l":"Answer using the skill","n":"The answer follows the skill workflow and any script results."}]},{"id":"x-skills-anatomy","module":"claude-skills","lesson":"claude-skills/anatomy-of-a-skill-folder","title":"Inside a skill folder","summary":"What belongs where.","actors":["SKILL.md","references","scripts","assets"],"steps":[{"f":0,"t":0,"l":"Header","n":"The top of SKILL.md has a name and a description."},{"f":0,"t":0,"l":"Workflow","n":"The body lists the steps Claude should follow, in short sentences."},{"f":0,"t":1,"l":"Link detail","n":"Long tables and rarely needed rules live in separate reference files."},{"f":0,"t":2,"l":"Call scripts","n":"Exact work such as validation is done by a script that SKILL.md names."},{"f":0,"t":3,"l":"Templates","n":"Output templates or sample files are stored as assets."},{"f":0,"t":0,"l":"Keep it small","n":"The main file stays short so it is cheap to load and easy to review."}]},{"id":"x-skills-description-writing","module":"claude-skills","lesson":"claude-skills/writing-descriptions-that-trigger","title":"Writing a description that triggers","summary":"From vague to specific.","actors":["Draft","Trigger tests","Neighbour skills","Final"],"steps":[{"f":0,"t":0,"l":"Vague draft","n":"A description such as Helps with documents will fire rarely or everywhere."},{"f":0,"t":1,"l":"List real requests","n":"Write ten requests that should trigger and ten that should not."},{"f":0,"t":0,"l":"Use the user's words","n":"Add the nouns, verbs and file types people actually say."},{"f":0,"t":2,"l":"Exclude neighbours","n":"Say what the skill is not for, so similar skills do not collide."},{"f":1,"t":3,"l":"Re-test","n":"Run the requests again and count misses and false triggers."},{"f":3,"t":3,"l":"Save the tests","n":"The request list is stored with the skill for future edits."}]},{"id":"x-skills-progressive-disclosure","module":"claude-skills","lesson":"claude-skills/progressive-disclosure-and-structure","title":"Progressive disclosure","summary":"Three layers of information.","actors":["Metadata","Body","Linked files","Context"],"steps":[{"f":0,"t":3,"l":"Layer one","n":"The name and description are always in context and cost only a few tokens."},{"f":1,"t":3,"l":"Layer two","n":"The body is loaded when the skill triggers."},{"f":2,"t":3,"l":"Layer three","n":"Linked files are loaded only when a step needs them."},{"f":1,"t":2,"l":"Link one level","n":"Links from the body point straight to the files, not through other files."},{"f":2,"t":2,"l":"Table of contents","n":"A long file starts with a short list of its sections."},{"f":3,"t":3,"l":"Result","n":"The context stays small, so more room remains for the user's task."}]},{"id":"x-skills-script-step","module":"claude-skills","lesson":"claude-skills/scripts-and-deterministic-steps","title":"A script inside a skill","summary":"Letting code do exact work.","actors":["Claude","SKILL.md","Script","Report"],"steps":[{"f":0,"t":1,"l":"Read the workflow","n":"The skill says to run the checker on the uploaded file."},{"f":0,"t":2,"l":"Run the script","n":"Claude runs the script with the file path as an argument."},{"f":2,"t":2,"l":"Check precisely","n":"The script validates every row and counts totals exactly."},{"f":2,"t":0,"l":"Return short output","n":"It prints a few clear lines and an exit code."},{"f":0,"t":3,"l":"Use the result","n":"Claude copies the numbers from the output into the report."},{"f":3,"t":0,"l":"Explain","n":"Claude adds judgement and wording, not arithmetic."}]},{"id":"x-skills-testing-loop","module":"claude-skills","lesson":"claude-skills/testing-and-evaluating-a-skill","title":"Testing a skill","summary":"A loop that measures the real benefit.","actors":["Task set","Without skill","With skill","Scores"],"steps":[{"f":0,"t":0,"l":"Write tasks","n":"Collect 10 to 20 realistic tasks with a checklist of expected results."},{"f":0,"t":1,"l":"Run the baseline","n":"Run the tasks without the skill and record the results."},{"f":0,"t":2,"l":"Run with the skill","n":"Run the same tasks with the skill installed."},{"f":1,"t":3,"l":"Score","n":"Compare quality, tokens and time for both runs."},{"f":2,"t":3,"l":"Find failures","n":"Look at tasks where the skill did not help."},{"f":3,"t":0,"l":"Change one thing","n":"Edit one part of the skill and run the set again."}]},{"id":"x-skills-not-triggering","module":"claude-skills","lesson":"claude-skills/debugging-skills-that-do-not-trigger-or-misbehave","title":"A skill that does not trigger","summary":"Debugging in the right order.","actors":["Folder","Header","Description","Test"],"steps":[{"f":0,"t":0,"l":"Check location","n":"The folder is in a place the product reads skills from."},{"f":0,"t":1,"l":"Check the file name","n":"The file must be named SKILL.md with exact capitals."},{"f":1,"t":1,"l":"Check the header","n":"The name and description fields must be valid and not empty."},{"f":3,"t":2,"l":"Ask by name","n":"Naming the skill shows whether the body works when loaded."},{"f":2,"t":2,"l":"Improve the description","n":"Add trigger phrases and tasks in the user's words."},{"f":2,"t":3,"l":"Measure again","n":"Run should-trigger and should-not-trigger requests."}]},{"id":"x-skills-security-review","module":"claude-skills","lesson":"claude-skills/sharing-versioning-and-skill-security","title":"Reviewing an outside skill","summary":"Treat a skill like code you did not write.","actors":["Outside skill","Reviewer","Sandbox","Approved list"],"steps":[{"f":0,"t":1,"l":"Download","n":"The skill is fetched without installing it."},{"f":1,"t":1,"l":"Read every file","n":"The reviewer reads instructions and scripts, looking for network calls and downloads."},{"f":1,"t":2,"l":"Run in a sandbox","n":"The skill runs with test data and no network access."},{"f":2,"t":1,"l":"Observe","n":"Files touched and commands run are compared with what the skill claims."},{"f":1,"t":3,"l":"Pin a version","n":"A reviewed commit is added to the approved list with an owner."},{"f":3,"t":1,"l":"Re-review updates","n":"Each update is reviewed before it replaces the pinned version."}]},{"id":"x-skills-team-workflow","module":"claude-skills","lesson":"claude-skills/sharing-versioning-and-skill-security","title":"Skills as a team asset","summary":"From idea to shared, versioned skill.","actors":["Author","Repository","Reviewer","Team"],"steps":[{"f":0,"t":1,"l":"Write the skill","n":"The author drafts the skill and a set of test tasks."},{"f":1,"t":2,"l":"Pull request","n":"The reviewer checks the description, the instructions and the scripts."},{"f":2,"t":1,"l":"Merge with a version","n":"The skill gets a version number and a changelog entry."},{"f":1,"t":3,"l":"Distribute","n":"The team installs it from a known location."},{"f":3,"t":0,"l":"Feedback","n":"Users report misses with the request that failed."},{"f":0,"t":1,"l":"Improve","n":"New requests become test tasks and the next version is released."}]},{"id":"x-skills-vs-prompt-tool","module":"claude-skills","lesson":"claude-skills/what-a-claude-skill-is","title":"Skill, prompt or tool","summary":"Choosing the right building block.","actors":["Need","Prompt","Skill","Tool"],"steps":[{"f":0,"t":1,"l":"One-off request","n":"A single conversation need is solved with a prompt."},{"f":0,"t":2,"l":"Repeated know-how","n":"A workflow used again and again becomes a skill."},{"f":0,"t":3,"l":"Action or live data","n":"Reaching a system or fetching current data needs a tool."},{"f":2,"t":3,"l":"Combine","n":"A skill can explain how and when to use a tool."},{"f":2,"t":2,"l":"Bundle scripts","n":"A skill can also carry scripts for exact, repeatable steps."},{"f":0,"t":2,"l":"Review and share","n":"Skills are files, so they can be reviewed and versioned like code."}]},{"id":"x-skills-structure-split","module":"claude-skills","lesson":"claude-skills/progressive-disclosure-and-structure","title":"Splitting a long skill","summary":"From one giant file to a lean skill.","actors":["Giant file","Workflow","References","Scripts"],"steps":[{"f":0,"t":0,"l":"Spot the problem","n":"A 1,400-line SKILL.md is slow to load and hard to review."},{"f":0,"t":1,"l":"Extract the workflow","n":"The main steps move into a short body."},{"f":0,"t":2,"l":"Move reference tables","n":"Long lists and rules go to separate files with clear names."},{"f":0,"t":3,"l":"Move exact logic","n":"Calculations and validations become scripts."},{"f":1,"t":2,"l":"Link from the body","n":"Each step links to the file it needs, one level deep."},{"f":1,"t":1,"l":"Re-test","n":"The task set confirms that quality did not drop after the split."}]},{"id":"x-mcp-tool-loop","module":"mcp","lesson":"mcp/the-tool-use-loop","title":"The tool-use loop","summary":"How a model uses your code to get facts.","actors":["User","App","Model","Tool"],"steps":[{"f":0,"t":1,"l":"Ask a question","n":"The user asks for the status of ticket TCK-1042."},{"f":1,"t":2,"l":"Send tools and question","n":"The app sends the question and the tool definitions to the model."},{"f":2,"t":1,"l":"Request a tool call","n":"The model replies that it wants get_ticket with a ticket ID."},{"f":1,"t":3,"l":"Validate and run","n":"The app validates the arguments and runs the tool."},{"f":3,"t":1,"l":"Return the result","n":"The tool output is sent back as a tool result tied to the call ID."},{"f":2,"t":0,"l":"Final answer","n":"The model uses the result to answer, and the loop ends."}]},{"id":"x-mcp-schema-validation","module":"mcp","lesson":"mcp/function-calling-and-tool-schemas","title":"Validating tool arguments","summary":"Never trust arguments the model produced.","actors":["Model","Schema check","Business rules","Tool"],"steps":[{"f":0,"t":1,"l":"Propose arguments","n":"The model returns a tool name and JSON arguments."},{"f":1,"t":1,"l":"Check the schema","n":"Types, required fields and enum values are validated."},{"f":1,"t":2,"l":"Check the rules","n":"Code confirms the user may access that record."},{"f":2,"t":3,"l":"Run the tool","n":"Only valid and allowed calls are executed."},{"f":3,"t":0,"l":"Return a clear error","n":"On failure the tool result explains the problem so the model can correct it."},{"f":2,"t":2,"l":"Log the call","n":"The request ID, arguments and result are logged for later review."}]},{"id":"x-mcp-architecture","module":"mcp","lesson":"mcp/mcp-architecture-hosts-clients-servers-transports","title":"Host, client and server","summary":"Who talks to whom in MCP.","actors":["Host app","MCP client","MCP server","Backend"],"steps":[{"f":0,"t":1,"l":"Create a client","n":"The host application creates one client per connected server."},{"f":1,"t":2,"l":"Initialize","n":"The client and server exchange versions and capabilities."},{"f":1,"t":2,"l":"List tools","n":"The client asks the server which tools it offers."},{"f":0,"t":0,"l":"Give tools to the model","n":"The host passes the tool list to the model."},{"f":1,"t":2,"l":"Call a tool","n":"When the model asks, the host has its client send tools/call."},{"f":2,"t":3,"l":"Use the backend","n":"The server calls the real system and returns a result."}]},{"id":"x-mcp-stdio-transport","module":"mcp","lesson":"mcp/mcp-architecture-hosts-clients-servers-transports","title":"The stdio transport","summary":"A local server as a child process.","actors":["Host","Child process","Standard input","Standard error"],"steps":[{"f":0,"t":1,"l":"Start the process","n":"The host launches the server command from its configuration."},{"f":0,"t":2,"l":"Write requests","n":"JSON-RPC messages are written to the server's standard input."},{"f":1,"t":0,"l":"Write responses","n":"Responses are written to standard output, one message per line."},{"f":1,"t":3,"l":"Log to stderr","n":"Logs and banners must go to standard error so the stream stays clean."},{"f":1,"t":0,"l":"Banner breaks parsing","n":"A text banner on standard output corrupts the JSON stream and the host fails."},{"f":0,"t":1,"l":"Stop","n":"The host closes the pipes and ends the process."}]},{"id":"x-mcp-http-transport","module":"mcp","lesson":"mcp/mcp-architecture-hosts-clients-servers-transports","title":"A remote MCP server","summary":"Streamable HTTP with authentication.","actors":["Client","Authorization server","MCP server over HTTP","Backend API"],"steps":[{"f":0,"t":2,"l":"Request without a token","n":"The client calls the server and receives a request to authenticate."},{"f":0,"t":1,"l":"Sign in","n":"The user signs in through the authorization server and approves scopes."},{"f":1,"t":0,"l":"Receive a token","n":"The client gets a token meant for this MCP server."},{"f":0,"t":2,"l":"Call with the token","n":"Each request carries the token over TLS."},{"f":2,"t":2,"l":"Check audience and scope","n":"The server verifies that the token was issued for it and allows the action."},{"f":2,"t":3,"l":"Use separate credentials","n":"The server calls the backend with its own scoped credentials, never passing the user token on."}]},{"id":"x-mcp-primitives","module":"mcp","lesson":"mcp/resources-prompts-and-other-primitives","title":"Tools, resources and prompts","summary":"Three kinds of capability.","actors":["Model","User","Host","Server"],"steps":[{"f":3,"t":2,"l":"Expose a tool","n":"A tool is an action the model can request, such as create_ticket."},{"f":3,"t":2,"l":"Expose a resource","n":"A resource is data with a URI, such as a runbook, that the app or user attaches."},{"f":3,"t":2,"l":"Expose a prompt","n":"A prompt is a template the user picks, such as review this incident."},{"f":2,"t":0,"l":"Model calls tools","n":"Only tools are chosen by the model during its work."},{"f":2,"t":1,"l":"User picks the rest","n":"Resources and prompts are selected by the application or the person."},{"f":2,"t":2,"l":"Check support","n":"Hosts differ in what they support, so test in the host you use."}]},{"id":"x-mcp-injection-via-tool-result","module":"mcp","lesson":"mcp/permissions-auth-and-prompt-injection-defence","title":"Injection through a tool result","summary":"How a ticket can steer an agent.","actors":["Attacker","Ticket system","Agent","Email tool"],"steps":[{"f":0,"t":1,"l":"Write a ticket","n":"The attacker files a ticket containing instructions for an AI assistant."},{"f":2,"t":1,"l":"Agent reads tickets","n":"The agent fetches tickets through a read tool."},{"f":1,"t":2,"l":"Result contains orders","n":"The ticket text comes back as a tool result."},{"f":2,"t":2,"l":"Model is influenced","n":"The model may treat the text as a request from the user."},{"f":2,"t":3,"l":"Email tool is available","n":"With broad email access the agent could send data out."},{"f":3,"t":0,"l":"Allowlist stops it","n":"A recipient allowlist and an approval step block the external address."}]},{"id":"x-mcp-approval-flow","module":"mcp","lesson":"mcp/permissions-auth-and-prompt-injection-defence","title":"Human approval for risky tools","summary":"Showing the exact action before it runs.","actors":["Model","Host policy","Person","Tool"],"steps":[{"f":0,"t":1,"l":"Request delete_file","n":"The model asks to delete a file with a path argument."},{"f":1,"t":1,"l":"Classify","n":"The policy marks delete as destructive and requires approval."},{"f":1,"t":2,"l":"Show the exact path","n":"The person sees the tool name and the full arguments."},{"f":2,"t":1,"l":"Approve or deny","n":"The person decides, and the choice is recorded."},{"f":1,"t":3,"l":"Run in a safe area","n":"An approved call runs with least privilege and moves to a trash folder."},{"f":3,"t":0,"l":"Return the result","n":"The model receives either the result or the reason for denial."}]},{"id":"x-mcp-server-debugging","module":"mcp","lesson":"mcp/debugging-tool-use-and-mcp","title":"Debugging an MCP server","summary":"Working from the bottom up.","actors":["Inspector","Server","Host","Model"],"steps":[{"f":0,"t":1,"l":"Call the server directly","n":"Use an inspector to connect without the host."},{"f":0,"t":1,"l":"List tools","n":"tools/list shows exactly what the server exposes."},{"f":0,"t":1,"l":"Call a tool","n":"Run the tool with sample arguments and read the result."},{"f":2,"t":1,"l":"Check host start","n":"Confirm the host starts the same command with the right interpreter and paths."},{"f":2,"t":3,"l":"Check the tool list","n":"Confirm that the host refreshed its list and passed the tool to the model."},{"f":3,"t":2,"l":"Read traces","n":"Traces show whether the model considered and chose the tool."}]},{"id":"x-mcp-tool-description","module":"mcp","lesson":"mcp/function-calling-and-tool-schemas","title":"Why descriptions decide choices","summary":"How the model picks between tools.","actors":["Model","search_logs","get_request_trace","Result"],"steps":[{"f":0,"t":0,"l":"Read definitions","n":"The model sees only names, descriptions and schemas."},{"f":0,"t":1,"l":"Vague text","n":"A description that says Search logs does not say what is returned."},{"f":0,"t":2,"l":"Specific text","n":"One that says returns the full trace for a request ID fits an ID question."},{"f":0,"t":2,"l":"Choose","n":"The model picks the tool whose description matches the request."},{"f":2,"t":3,"l":"Get the right data","n":"The right tool returns the data needed for the answer."},{"f":0,"t":3,"l":"Test choices","n":"A conversation test confirms the right tool is chosen for typical requests."}]},{"id":"x-mcp-agent-limits","module":"mcp","lesson":"mcp/the-tool-use-loop","title":"Limits for an agent loop","summary":"Stopping runaway tool use.","actors":["Agent loop","Step counter","Budget guard","Repeat detector"],"steps":[{"f":0,"t":1,"l":"Count steps","n":"Each model call and tool call increases a counter."},{"f":1,"t":1,"l":"Stop at the cap","n":"A maximum step count ends the loop with a clear message."},{"f":0,"t":2,"l":"Track tokens and cost","n":"A running total is compared with the budget."},{"f":0,"t":3,"l":"Detect repeats","n":"The same call with the same arguments many times is a sign of a loop."},{"f":3,"t":0,"l":"Break the loop","n":"The agent is told the tool returns nothing new and must change approach or stop."},{"f":2,"t":0,"l":"Report","n":"The final answer states what was done and what is incomplete."}]},{"id":"x-mcp-confused-deputy","module":"mcp","lesson":"mcp/permissions-auth-and-prompt-injection-defence","title":"The confused deputy","summary":"Why a server must not pass tokens through.","actors":["User","MCP server","Internal service","Attacker"],"steps":[{"f":0,"t":1,"l":"Connect with a token","n":"The user connects with a broad token for several services."},{"f":1,"t":2,"l":"Forward the token","n":"A careless server passes the same token to an internal service."},{"f":3,"t":1,"l":"Craft a request","n":"An attacker tricks the assistant into asking for a harmful action."},{"f":1,"t":2,"l":"Action succeeds","n":"The internal service accepts the action because the token is valid."},{"f":1,"t":1,"l":"Validate audience","n":"A safe server accepts only tokens issued for itself."},{"f":1,"t":2,"l":"Use its own credentials","n":"It calls the internal service with a narrow credential and checks the user's rights itself."}]},{"id":"x-skills-script-safety","module":"claude-skills","lesson":"claude-skills/scripts-and-deterministic-steps","title":"A safe script in a skill","summary":"What a trustworthy bundled script looks like.","actors":["Author","Script","Sandbox","Reviewer"],"steps":[{"f":0,"t":1,"l":"Keep it read-only","n":"The script reads inputs and prints results, and writes only to a named output file."},{"f":0,"t":1,"l":"No secrets inside","n":"Credentials are never stored in the skill and are passed by the environment if needed."},{"f":0,"t":1,"l":"No hidden network","n":"The script makes no downloads or outgoing requests that the skill does not explain."},{"f":1,"t":2,"l":"Test with sample data","n":"The script runs on sample files in a restricted environment."},{"f":2,"t":3,"l":"Review the output","n":"The reviewer compares behaviour with the description and checks exit codes."},{"f":3,"t":0,"l":"Fix and re-test","n":"Findings are fixed and the script tests are run again before release."}]},{"id":"x-cloud-iam-authn-authz","module":"cloud-iam","lesson":"cloud-iam/identities-principals-and-permissions","title":"Authentication then authorization","summary":"One request, two separate checks.","actors":["User","Identity provider","Cloud API","Policy engine"],"steps":[{"f":0,"t":1,"l":"Sign in","n":"The user proves who they are, ideally with single sign-on and a second factor."},{"f":1,"t":0,"l":"Receive a token","n":"The identity provider returns a short-lived token that represents the user."},{"f":0,"t":2,"l":"Send a request","n":"The user asks the cloud API to read an object, presenting the token."},{"f":2,"t":2,"l":"Verify the token","n":"The API checks the signature, expiry and audience before trusting any claim in it."},{"f":2,"t":3,"l":"Ask for a decision","n":"The request is compared with policies for that principal, action, resource and conditions."},{"f":3,"t":2,"l":"Allow or deny","n":"With no matching allow the answer is no, and an explicit deny beats every allow."}]},{"id":"x-cloud-iam-assume-role-flow","module":"cloud-iam","lesson":"cloud-iam/aws-iam-policies-roles-and-assume-role","title":"Assuming a role","summary":"How a workload gets temporary credentials.","actors":["Application","Token service","Role","Storage"],"steps":[{"f":0,"t":1,"l":"Ask to assume","n":"The application calls the token service and names the role it needs."},{"f":1,"t":2,"l":"Check the trust policy","n":"The service reads the role's trust policy to see whether this caller is allowed to assume it."},{"f":2,"t":1,"l":"Role approved","n":"The trust policy names the caller, so the request passes this check."},{"f":1,"t":0,"l":"Return temporary keys","n":"The application receives credentials that expire in an hour or less."},{"f":0,"t":3,"l":"Call storage","n":"The request is signed with the temporary credentials and carries the session identity."},{"f":3,"t":0,"l":"Check permissions","n":"Storage allows only what the role's permission policy grants, then the session expires on its own."}]},{"id":"x-cloud-iam-policy-evaluation","module":"cloud-iam","lesson":"cloud-iam/aws-iam-policies-roles-and-assume-role","title":"How a policy decision is made","summary":"Default deny, allows and explicit denies.","actors":["Request","Organization guardrail","Identity policy","Resource policy"],"steps":[{"f":0,"t":1,"l":"Request arrives","n":"A principal asks for an action on a resource with some context such as network and MFA."},{"f":1,"t":1,"l":"Guardrails first","n":"Organisation-level policies cap what the account may do, whatever the roles inside it allow."},{"f":1,"t":2,"l":"Identity policy","n":"The identity's own policies are searched for an allow that matches action, resource and conditions."},{"f":2,"t":3,"l":"Resource policy","n":"The resource may add an allow, for example for another account, or a deny."},{"f":3,"t":0,"l":"Explicit deny wins","n":"Any matching deny ends the evaluation with a refusal."},{"f":3,"t":0,"l":"No allow means no","n":"If nothing allows the request, the default answer is deny."}]},{"id":"x-cloud-iam-least-privilege-loop","module":"cloud-iam","lesson":"cloud-iam/least-privilege-and-access-reviews","title":"Shrinking permissions with usage data","summary":"From broad to narrow without breaking things.","actors":["Owner","Access analysis","Policy","Audit log"],"steps":[{"f":0,"t":2,"l":"Start with a broad role","n":"A team holds a role with hundreds of allowed actions, granted to get going quickly."},{"f":1,"t":3,"l":"Collect usage","n":"Last-accessed data and audit logs show which actions were used in the last 90 days."},{"f":1,"t":0,"l":"Report to the owner","n":"The owner sees twelve used actions and the rest unused."},{"f":0,"t":2,"l":"Replace the policy","n":"A new policy lists only the used actions on the real resources."},{"f":2,"t":3,"l":"Watch for denials","n":"Audit logs show any denied call so a missing permission is added quickly."},{"f":0,"t":1,"l":"Schedule a review","n":"The same check is repeated every quarter and recorded."}]},{"id":"x-cloud-iam-azure-rbac","module":"cloud-iam","lesson":"cloud-iam/azure-entra-id-rbac-and-managed-identities","title":"Azure role assignment and scope","summary":"Principal, role and scope.","actors":["Principal","Role definition","Scope","Resource"],"steps":[{"f":0,"t":1,"l":"Pick a role","n":"A built-in role such as Reader lists the actions it allows."},{"f":1,"t":2,"l":"Choose a scope","n":"The assignment is created on a resource group, not the whole subscription."},{"f":0,"t":2,"l":"Create the assignment","n":"The principal, role and scope are bound together as an assignment."},{"f":2,"t":3,"l":"Inheritance","n":"Everything inside the resource group inherits the assignment."},{"f":0,"t":3,"l":"Request a resource","n":"The principal reads a resource in the group and is allowed."},{"f":0,"t":3,"l":"Outside the scope","n":"A resource in another group is refused because no assignment covers it."}]},{"id":"x-cloud-iam-managed-identity","module":"cloud-iam","lesson":"cloud-iam/azure-entra-id-rbac-and-managed-identities","title":"A managed identity gets a token","summary":"No secret stored in the application.","actors":["App service","Local token endpoint","Entra ID","Key vault"],"steps":[{"f":0,"t":0,"l":"Enable the identity","n":"The platform creates an identity for the app service and manages its credentials."},{"f":0,"t":1,"l":"Ask for a token","n":"At run time the app calls a local endpoint that only the platform exposes to it."},{"f":1,"t":2,"l":"Request from the directory","n":"The platform asks the directory for a token for this identity and the vault as audience."},{"f":2,"t":0,"l":"Receive the token","n":"The app gets a short-lived token with no secret in its configuration."},{"f":0,"t":3,"l":"Call the vault","n":"The app presents the token to read one secret."},{"f":3,"t":0,"l":"Check the role","n":"The vault allows the read only because the identity holds a narrow role on it."}]},{"id":"x-cloud-iam-secret-fetch","module":"cloud-iam","lesson":"cloud-iam/secrets-and-encryption-with-kms-and-key-vaults","title":"Fetching a secret at run time","summary":"Keep passwords out of images and code.","actors":["Service","Secrets manager","Audit log","Database"],"steps":[{"f":0,"t":1,"l":"Start up","n":"The service starts with only its identity, not a password."},{"f":0,"t":1,"l":"Request the secret","n":"It asks the secrets manager for the database password by name."},{"f":1,"t":1,"l":"Authorise","n":"The manager checks the caller's role allows this one secret."},{"f":1,"t":2,"l":"Log the read","n":"The audit log records who read which secret and when."},{"f":1,"t":0,"l":"Return the value","n":"The service keeps the value in memory and never writes it to disk or logs."},{"f":0,"t":3,"l":"Connect","n":"The service connects to the database with the fetched password."}]},{"id":"x-cloud-iam-envelope-encryption","module":"cloud-iam","lesson":"cloud-iam/secrets-and-encryption-with-kms-and-key-vaults","title":"Envelope encryption","summary":"A data key under a master key.","actors":["Application","Key service","Data key","Storage"],"steps":[{"f":0,"t":1,"l":"Ask for a data key","n":"The application requests a new key from the key management service."},{"f":1,"t":0,"l":"Receive two copies","n":"It gets the data key in plain form and the same key encrypted under the master key."},{"f":0,"t":2,"l":"Encrypt the data","n":"The application encrypts the data locally with the plain data key."},{"f":0,"t":2,"l":"Discard the plain key","n":"The plain key is erased from memory after use."},{"f":0,"t":3,"l":"Store both","n":"The ciphertext and the encrypted data key are stored together."},{"f":0,"t":1,"l":"Decrypt later","n":"To read, the encrypted data key is sent to the key service, which allows it only if policy permits."}]},{"id":"x-cloud-iam-private-endpoint","module":"cloud-iam","lesson":"cloud-iam/network-boundaries-and-private-access","title":"Reaching storage through a private endpoint","summary":"Keep traffic off the internet.","actors":["Application","Private network","Private endpoint","Storage service"],"steps":[{"f":0,"t":1,"l":"Resolve the name","n":"Private DNS resolves the storage name to a private address inside the network."},{"f":1,"t":2,"l":"Send to the private address","n":"The request travels over the private network to the endpoint, not to the internet."},{"f":2,"t":3,"l":"Forward to the service","n":"The endpoint passes the request to the storage service."},{"f":3,"t":3,"l":"Check the policy","n":"The storage policy allows requests only from this private path and denies the public one."},{"f":3,"t":0,"l":"Respond","n":"The data returns over the same private path."},{"f":0,"t":3,"l":"Public path fails","n":"A request from outside the network is refused by the policy."}]},{"id":"x-cloud-iam-audit-detection","module":"cloud-iam","lesson":"cloud-iam/logging-detection-and-audit-trails","title":"From audit log to alert","summary":"Spotting a risky action.","actors":["Principal","Control plane","Audit log","Alert"],"steps":[{"f":0,"t":1,"l":"An action happens","n":"A principal tries to stop audit logging at night."},{"f":1,"t":2,"l":"Event recorded","n":"The control plane writes the event with who, what, where and when."},{"f":2,"t":2,"l":"Copy to a protected account","n":"Logs flow to a separate account that few people can change."},{"f":2,"t":3,"l":"Rule matches","n":"A detection rule flags a change to logging as high risk."},{"f":3,"t":0,"l":"Page the responder","n":"The on-call engineer gets the alert with the principal and source address."},{"f":0,"t":2,"l":"Review and respond","n":"They restore logging, review recent actions and disable the identity if it is not legitimate."}]},{"id":"x-cloud-iam-leaked-key","module":"cloud-iam","lesson":"cloud-iam/logging-detection-and-audit-trails","title":"Responding to a leaked key","summary":"Contain, assess, remove, recover.","actors":["Scanner","Responder","Audit log","Platform"],"steps":[{"f":0,"t":1,"l":"Alert","n":"A scanner reports a live key in a public repository."},{"f":1,"t":3,"l":"Contain","n":"The responder deactivates the key without deleting it, to keep evidence."},{"f":1,"t":2,"l":"Assess","n":"The audit log shows what the key did and from which addresses."},{"f":1,"t":3,"l":"Remove","n":"Attacker-created users, keys and servers are deleted."},{"f":1,"t":3,"l":"Replace","n":"The pipeline moves to a role with short-lived credentials."},{"f":1,"t":0,"l":"Learn","n":"Secret scanning and guardrails are added so the same path cannot recur."}]},{"id":"x-cloud-iam-conditional-access","module":"cloud-iam","lesson":"cloud-iam/aws-iam-policies-roles-and-assume-role","title":"A sign-in with conditional access","summary":"Rules decide how strong the proof must be.","actors":["User","Sign-in service","Policy","Application"],"steps":[{"f":0,"t":1,"l":"Start sign-in","n":"The user opens the application and is sent to the sign-in service."},{"f":1,"t":2,"l":"Evaluate context","n":"The policy looks at the user, device, location and risk of this attempt."},{"f":2,"t":1,"l":"Require more proof","n":"An unfamiliar location triggers a second factor requirement."},{"f":0,"t":1,"l":"Complete the second factor","n":"The user approves on their device."},{"f":1,"t":0,"l":"Issue a token","n":"A short-lived token is issued with the claims the application needs."},{"f":0,"t":3,"l":"Use the application","n":"The application trusts the token and applies its own authorization."}]},{"id":"x-k8s-ops-request-flow","module":"k8s-ops","lesson":"k8s-ops/the-control-plane-in-depth","title":"A request through the API server","summary":"Authenticate, authorise, admit, store.","actors":["Client","API server","Admission","etcd"],"steps":[{"f":0,"t":1,"l":"Send a request","n":"kubectl sends a create request over TLS with a credential."},{"f":1,"t":1,"l":"Authenticate","n":"The API server identifies the caller from a certificate, token or sign-in."},{"f":1,"t":1,"l":"Authorise","n":"RBAC checks whether this subject may create this kind in this namespace."},{"f":1,"t":2,"l":"Admission","n":"Controllers may change the object or reject it, for example by policy."},{"f":1,"t":3,"l":"Persist","n":"The validated object is written to etcd, the only place state is stored."},{"f":1,"t":0,"l":"Respond","n":"The caller receives the stored object, and controllers begin to act on it."}]},{"id":"x-k8s-ops-etcd-quorum","module":"k8s-ops","lesson":"k8s-ops/etcd-backup-and-restore","title":"etcd and quorum","summary":"Why a majority of members is needed.","actors":["Leader","Follower A","Follower B","API server"],"steps":[{"f":3,"t":0,"l":"Write request","n":"The API server sends a write to the etcd leader."},{"f":0,"t":1,"l":"Replicate","n":"The leader sends the entry to the followers."},{"f":0,"t":2,"l":"Replicate","n":"The same entry goes to the other follower."},{"f":1,"t":0,"l":"Acknowledge","n":"One follower confirms, which together with the leader is a majority of three."},{"f":0,"t":3,"l":"Commit","n":"With a majority the leader commits and tells the API server the write succeeded."},{"f":2,"t":2,"l":"A member is lost","n":"The cluster keeps working with two of three, but losing a second member stops writes."}]},{"id":"x-k8s-ops-etcd-restore","module":"k8s-ops","lesson":"k8s-ops/etcd-backup-and-restore","title":"Restoring etcd from a snapshot","summary":"Bring the cluster state back.","actors":["Operator","API servers","etcd members","Snapshot file"],"steps":[{"f":0,"t":1,"l":"Stop the API servers","n":"Nothing should write while state is being replaced."},{"f":0,"t":3,"l":"Verify the snapshot","n":"The status command confirms the file is readable and shows its key count."},{"f":0,"t":2,"l":"Restore each member","n":"Every member gets a new data directory built from the same snapshot."},{"f":0,"t":2,"l":"Start the members together","n":"The members form a new cluster with the new membership settings."},{"f":0,"t":1,"l":"Start the API servers","n":"The API servers connect and serve the restored state."},{"f":0,"t":1,"l":"Reconcile","n":"Objects created after the snapshot are re-applied from the repository, and the team checks volumes separately."}]},{"id":"x-k8s-ops-upgrade-flow","module":"k8s-ops","lesson":"k8s-ops/upgrading-clusters-safely","title":"Upgrading a cluster one minor version","summary":"Order of an upgrade.","actors":["Operator","Control plane","Worker node","Workloads"],"steps":[{"f":0,"t":0,"l":"Prepare","n":"Read release notes, scan for removed APIs and take an etcd snapshot."},{"f":0,"t":1,"l":"Upgrade control plane","n":"The first control plane node is upgraded, then the others."},{"f":0,"t":2,"l":"Cordon and drain","n":"A worker node is made unschedulable and its pods are evicted."},{"f":0,"t":2,"l":"Upgrade the node","n":"The kubelet and packages are updated and restarted."},{"f":0,"t":2,"l":"Uncordon","n":"The node is schedulable again and pods return."},{"f":0,"t":3,"l":"Check workloads","n":"Smoke tests and dashboards confirm the services are healthy before the next node."}]},{"id":"x-k8s-ops-node-drain","module":"k8s-ops","lesson":"k8s-ops/nodes-draining-taints-and-capacity","title":"A node drain step by step","summary":"Respecting disruption budgets.","actors":["Operator","Node","Eviction API","Scheduler"],"steps":[{"f":0,"t":1,"l":"Cordon","n":"The node is marked unschedulable so nothing new lands on it."},{"f":0,"t":2,"l":"Start the drain","n":"The drain asks the eviction API to remove each pod."},{"f":2,"t":2,"l":"Check the budget","n":"An eviction is refused if it would break the disruption budget."},{"f":2,"t":1,"l":"Evict a pod","n":"When allowed, the pod is terminated gracefully."},{"f":1,"t":3,"l":"Recreate elsewhere","n":"The owning controller makes a new pod and the scheduler places it on another node."},{"f":0,"t":1,"l":"Maintain and uncordon","n":"After the work the node is opened for scheduling again."}]},{"id":"x-k8s-ops-rbac-decision","module":"k8s-ops","lesson":"k8s-ops/rbac-and-service-accounts","title":"An RBAC decision","summary":"Subject, verb and resource.","actors":["Subject","API server","Binding","Role"],"steps":[{"f":0,"t":1,"l":"Request","n":"A service account asks to list secrets in the shop namespace."},{"f":1,"t":2,"l":"Find bindings","n":"The API server finds role bindings that mention this subject in that namespace."},{"f":2,"t":3,"l":"Read the role","n":"The bound role lists the verbs and resources it allows."},{"f":3,"t":1,"l":"No match","n":"The role allows pods but not secrets, so nothing allows the request."},{"f":1,"t":0,"l":"Forbidden","n":"The caller receives an error naming the subject, verb and resource."},{"f":0,"t":2,"l":"Fix narrowly","n":"A new rule allows only list on secrets in that namespace."}]},{"id":"x-k8s-ops-quota-admission","module":"k8s-ops","lesson":"k8s-ops/resource-quotas-limits-and-autoscaling","title":"A quota stops a deployment","summary":"Namespace limits in action.","actors":["Team","Deployment controller","Quota check","Namespace"],"steps":[{"f":0,"t":1,"l":"Scale up","n":"The team raises replicas from 10 to 14."},{"f":1,"t":2,"l":"Create pods","n":"The controller asks the API server to create four more pods."},{"f":2,"t":3,"l":"Check the quota","n":"Admission adds the new requests to the namespace usage and compares with the hard limit."},{"f":2,"t":1,"l":"Reject","n":"The creation fails with an exceeded quota message."},{"f":1,"t":0,"l":"See the event","n":"The team reads the event on the ReplicaSet."},{"f":0,"t":3,"l":"Right-size or request more","n":"They reduce oversized requests or ask for a higher quota through review."}]},{"id":"x-k8s-ops-autoscaler-nodes","module":"k8s-ops","lesson":"k8s-ops/resource-quotas-limits-and-autoscaling","title":"Node autoscaling","summary":"Pending pods add nodes.","actors":["HPA","Scheduler","Node autoscaler","Cloud"],"steps":[{"f":0,"t":1,"l":"Add replicas","n":"Load rises and the HPA increases the replica count."},{"f":1,"t":1,"l":"Pods stay Pending","n":"No node has enough free requests for the new pods."},{"f":1,"t":2,"l":"Autoscaler notices","n":"The autoscaler sees unschedulable pods and calculates a node size that fits them."},{"f":2,"t":3,"l":"Create a node","n":"It asks the cloud to add a node to the pool."},{"f":3,"t":1,"l":"Node joins","n":"The node registers and the scheduler places the pending pods."},{"f":2,"t":3,"l":"Scale down later","n":"Under-used nodes are drained and removed when pods can move safely."}]},{"id":"x-k8s-ops-network-policy","module":"k8s-ops","lesson":"k8s-ops/network-policies-and-pod-security","title":"A network policy decision","summary":"Allow lists for pod traffic.","actors":["Web pod","Network plugin","API pod","Database pod"],"steps":[{"f":0,"t":1,"l":"Web calls API","n":"A packet leaves the web pod for the API pod."},{"f":1,"t":1,"l":"Check egress","n":"The plugin checks that egress from the web pod to the API on this port is allowed."},{"f":1,"t":2,"l":"Check ingress","n":"It checks the API pod's ingress allows traffic from web pods."},{"f":2,"t":0,"l":"Allowed","n":"Both lists allow it, so the request is delivered and answered."},{"f":0,"t":3,"l":"Web calls database","n":"A direct call from the web pod to the database is attempted."},{"f":1,"t":3,"l":"Dropped","n":"No policy allows it, so the packet is dropped and nothing reaches the database."}]},{"id":"x-k8s-ops-pod-security","module":"k8s-ops","lesson":"k8s-ops/network-policies-and-pod-security","title":"Pod security admission","summary":"A privileged pod is refused.","actors":["Developer","API server","Pod Security","Namespace"],"steps":[{"f":0,"t":1,"l":"Apply a pod","n":"A manifest asks for privileged mode and host networking."},{"f":1,"t":2,"l":"Admission check","n":"Pod Security admission reads the namespace's profile label."},{"f":2,"t":3,"l":"Compare","n":"The pod spec is checked against the baseline rules."},{"f":2,"t":1,"l":"Reject","n":"Privileged mode violates the baseline, so the request is refused with a clear message."},{"f":0,"t":0,"l":"Fix the manifest","n":"The developer removes the extra powers and sets a non-root security context."},{"f":0,"t":1,"l":"Apply again","n":"The hardened pod passes admission and starts."}]},{"id":"x-k8s-ops-node-notready","module":"k8s-ops","lesson":"k8s-ops/debugging-cluster-and-node-problems","title":"Why a node goes NotReady","summary":"From missed heartbeats to rescheduling.","actors":["Kubelet","Node controller","API server","Scheduler"],"steps":[{"f":0,"t":2,"l":"Heartbeats","n":"The kubelet sends regular heartbeats that update the node lease."},{"f":0,"t":0,"l":"Fault","n":"The disk fills and the kubelet stops reporting."},{"f":1,"t":2,"l":"Missed updates","n":"The node controller sees no update within the grace period."},{"f":1,"t":2,"l":"Mark NotReady","n":"The node condition is set and taints are added."},{"f":2,"t":3,"l":"Evict after timeout","n":"After the toleration period, pods on the node are marked for removal."},{"f":3,"t":2,"l":"Reschedule","n":"Controllers create replacements and the scheduler places them on healthy nodes."}]},{"id":"x-k8s-ops-cert-expiry","module":"k8s-ops","lesson":"k8s-ops/debugging-cluster-and-node-problems","title":"Certificate expiry in a cluster","summary":"A silent clock.","actors":["Certificates","Monitor","Operator","API server"],"steps":[{"f":0,"t":0,"l":"Issued","n":"Cluster certificates are created with a one year lifetime."},{"f":1,"t":0,"l":"Watch the date","n":"A monitor tracks the days left on each certificate."},{"f":1,"t":2,"l":"Alert early","n":"At 30 days an alert reaches the operator."},{"f":2,"t":0,"l":"Renew","n":"The operator renews the certificates with the cluster tools."},{"f":2,"t":3,"l":"Restart components","n":"The control plane components are restarted to load the new files."},{"f":0,"t":3,"l":"Without monitoring","n":"An unnoticed expiry breaks every client connection to the API server."}]},{"id":"x-argocd-push-vs-pull","module":"argocd","lesson":"argocd/pull-based-delivery-and-the-repository-as-source-of-truth","title":"Push and pull delivery","summary":"Where the credentials live.","actors":["CI","Registry","Repository","Controller"],"steps":[{"f":0,"t":1,"l":"Build and push the image","n":"CI builds the image and publishes it to the registry."},{"f":0,"t":2,"l":"Commit the new tag","n":"CI changes the image tag in the configuration repository and stops there."},{"f":3,"t":2,"l":"Watch the repository","n":"The controller in the cluster detects the new commit."},{"f":3,"t":3,"l":"Render and compare","n":"It renders the manifests and compares them with live state."},{"f":3,"t":3,"l":"Apply the change","n":"The controller applies the difference from inside the cluster."},{"f":3,"t":2,"l":"Report status","n":"The result shows as Synced and Healthy; CI never held cluster credentials."}]},{"id":"x-argocd-reconcile-loop","module":"argocd","lesson":"argocd/pull-based-delivery-and-the-repository-as-source-of-truth","title":"The reconcile loop","summary":"Desired against live state.","actors":["Repository","Repo server","Controller","Cluster"],"steps":[{"f":0,"t":1,"l":"Fetch","n":"The repo server clones the repository at the target revision."},{"f":1,"t":1,"l":"Render","n":"Helm, Kustomize or plain YAML is turned into manifests."},{"f":2,"t":3,"l":"Read live state","n":"The controller reads the matching objects from the cluster."},{"f":2,"t":2,"l":"Compare","n":"Differences between desired and live state are calculated."},{"f":2,"t":3,"l":"Sync if allowed","n":"With automation on, the controller applies the difference."},{"f":2,"t":2,"l":"Repeat","n":"The loop runs again on new commits or when live state changes."}]},{"id":"x-argocd-install-first-app","module":"argocd","lesson":"argocd/installing-argo-cd-and-the-application-resource","title":"Creating the first Application","summary":"From install to a running service.","actors":["Engineer","Argo CD","Repository","Cluster"],"steps":[{"f":0,"t":1,"l":"Install Argo CD","n":"The components start in their own namespace."},{"f":0,"t":1,"l":"Register the repository","n":"A read-only credential is added for the configuration repository."},{"f":0,"t":1,"l":"Create the Application","n":"The manifest names the source path and the destination namespace."},{"f":1,"t":2,"l":"Fetch and render","n":"Argo CD reads the folder and renders the manifests."},{"f":1,"t":1,"l":"Show OutOfSync","n":"Nothing is deployed yet, so the application is OutOfSync."},{"f":0,"t":3,"l":"Sync","n":"The engineer presses sync and the objects appear and become Healthy."}]},{"id":"x-argocd-drift-selfheal","module":"argocd","lesson":"argocd/sync-health-and-drift","title":"Drift and self-heal","summary":"A manual edit is reverted.","actors":["Engineer","Cluster","Controller","Repository"],"steps":[{"f":0,"t":1,"l":"Edit by hand","n":"An engineer changes the replica count directly in the cluster."},{"f":2,"t":1,"l":"Notice the difference","n":"The controller sees live state no longer matches the repository."},{"f":2,"t":3,"l":"Mark OutOfSync","n":"The application is shown as OutOfSync with a diff."},{"f":2,"t":1,"l":"Self-heal","n":"With self-heal on, the controller applies the repository value again."},{"f":1,"t":1,"l":"Back to desired","n":"The replica count returns to the committed number."},{"f":0,"t":3,"l":"Change by commit","n":"The engineer makes the change in the repository so it lasts."}]},{"id":"x-argocd-sync-and-health","module":"argocd","lesson":"argocd/sync-health-and-drift","title":"Sync status and health","summary":"Two different questions.","actors":["Manifests","Argo CD","Pods","Dashboard"],"steps":[{"f":0,"t":1,"l":"Apply manifests","n":"Argo CD applies the rendered manifests."},{"f":1,"t":1,"l":"Compare","n":"Live state matches desired state, so the sync status is Synced."},{"f":2,"t":2,"l":"Pods fail","n":"The image tag is wrong and pods go into CrashLoopBackOff."},{"f":1,"t":2,"l":"Assess health","n":"Argo CD evaluates the Deployment and finds it not available."},{"f":1,"t":3,"l":"Show both","n":"The dashboard shows Synced and Degraded together."},{"f":3,"t":2,"l":"Debug the workload","n":"The team looks at events and logs, not at the manifest diff."}]},{"id":"x-argocd-prune","module":"argocd","lesson":"argocd/sync-health-and-drift","title":"What prune does","summary":"Removing what left the repository.","actors":["Repository","Controller","Cluster","Protection"],"steps":[{"f":0,"t":0,"l":"Delete a file","n":"A manifest for an old service is removed from the repository."},{"f":1,"t":2,"l":"Compare","n":"The controller sees an object in the cluster that is no longer in the source."},{"f":1,"t":3,"l":"Check protection","n":"The object has no Prune=false annotation, so it may be deleted."},{"f":1,"t":2,"l":"Prune","n":"With prune on, the controller deletes the object."},{"f":0,"t":3,"l":"Mark stateful data","n":"Databases and volumes carry the annotation so they survive a mistake."},{"f":1,"t":0,"l":"Review first","n":"A render check in the pull request shows what would be removed."}]},{"id":"x-argocd-helm-values","module":"argocd","lesson":"argocd/helm-and-kustomize-with-argo-cd","title":"Helm values from the repository","summary":"Rendering without a release.","actors":["Chart","Values file","Repo server","Cluster"],"steps":[{"f":0,"t":2,"l":"Pin the chart","n":"The Application names an exact chart version."},{"f":1,"t":2,"l":"Choose the values file","n":"The environment's values file in the repository is selected."},{"f":2,"t":2,"l":"Template","n":"The repo server runs the equivalent of helm template with those values."},{"f":2,"t":3,"l":"Apply the output","n":"The rendered manifests are applied as plain objects."},{"f":2,"t":3,"l":"No release record","n":"Helm itself keeps no release, because Argo CD tracks the resources."},{"f":1,"t":0,"l":"Review the diff","n":"A change to a value shows up as a reviewed difference."}]},{"id":"x-argocd-app-of-apps","module":"argocd","lesson":"argocd/environments-app-of-apps-and-applicationsets","title":"App-of-apps bootstrap","summary":"One parent creates many applications.","actors":["Engineer","Parent app","Child apps","Cluster"],"steps":[{"f":0,"t":1,"l":"Create the parent","n":"One Application points at a folder of Application manifests."},{"f":1,"t":2,"l":"Sync the parent","n":"Syncing creates each child Application."},{"f":2,"t":3,"l":"Children sync","n":"Each child delivers its own service to the cluster."},{"f":0,"t":1,"l":"Add a file","n":"A new Application manifest is committed to the folder."},{"f":1,"t":2,"l":"Detect the new child","n":"The parent creates the new Application automatically."},{"f":2,"t":3,"l":"New service appears","n":"The new service is delivered with no extra clicks."}]},{"id":"x-argocd-applicationset","module":"argocd","lesson":"argocd/environments-app-of-apps-and-applicationsets","title":"An ApplicationSet generating applications","summary":"One template, many targets.","actors":["Generator","ApplicationSet","Applications","Clusters"],"steps":[{"f":0,"t":1,"l":"List the targets","n":"A generator lists staging and production, or every registered cluster."},{"f":1,"t":1,"l":"Fill the template","n":"The template inserts each target's name and path."},{"f":1,"t":2,"l":"Create applications","n":"One Application is created per target."},{"f":2,"t":3,"l":"Deliver","n":"Each application syncs to its own cluster and namespace."},{"f":0,"t":1,"l":"A target is added","n":"A new cluster is registered and the generator sees it."},{"f":1,"t":2,"l":"New application appears","n":"A new Application is created and delivers the same service."}]},{"id":"x-argocd-promotion","module":"argocd","lesson":"argocd/environments-app-of-apps-and-applicationsets","title":"Promoting a version","summary":"Staging first, then production.","actors":["Developer","Staging overlay","Production overlay","Reviewer"],"steps":[{"f":0,"t":1,"l":"Commit the new tag","n":"The new image tag is committed to the staging overlay."},{"f":1,"t":1,"l":"Sync and test","n":"Staging delivers the version and tests run."},{"f":0,"t":2,"l":"Open a promotion request","n":"The same tag is proposed for the production overlay in a pull request."},{"f":3,"t":2,"l":"Review","n":"A reviewer checks the diff, test results and timing."},{"f":3,"t":2,"l":"Merge","n":"The merge is the approval and leaves an audit record."},{"f":2,"t":2,"l":"Production syncs","n":"Production delivers the same version that was tested in staging."}]},{"id":"x-argocd-hooks-waves","module":"argocd","lesson":"argocd/hooks-sync-waves-and-progressive-delivery","title":"Waves and hooks in a sync","summary":"Running things in order.","actors":["Controller","Wave minus one","Hooks","Wave zero"],"steps":[{"f":0,"t":1,"l":"Start the sync","n":"The controller sorts resources by sync wave."},{"f":1,"t":1,"l":"Wave minus one","n":"Namespaces and CRDs are applied first and must become healthy."},{"f":0,"t":2,"l":"PreSync hook","n":"A migration Job runs before the application changes."},{"f":2,"t":0,"l":"Job completes","n":"The controller waits for the Job to finish successfully."},{"f":0,"t":3,"l":"Wave zero","n":"The Deployment and Service are applied."},{"f":0,"t":2,"l":"PostSync hook","n":"A smoke test runs and the hook is cleaned up when it succeeds."}]},{"id":"x-argocd-rollout-canary","module":"argocd","lesson":"argocd/hooks-sync-waves-and-progressive-delivery","title":"A canary rollout with analysis","summary":"Gradual traffic with a safety net.","actors":["Rollout","Canary pods","Metrics","Stable pods"],"steps":[{"f":0,"t":1,"l":"Start the canary","n":"A small number of pods run the new version."},{"f":0,"t":1,"l":"Send five percent","n":"A traffic rule sends five percent of requests to the canary."},{"f":2,"t":2,"l":"Analyse","n":"Analysis queries the error rate for the canary."},{"f":2,"t":0,"l":"Pass","n":"The error rate is under the threshold, so the rollout advances to 25 percent."},{"f":0,"t":3,"l":"Fail","n":"If the threshold is crossed, traffic returns to the stable pods automatically."},{"f":0,"t":1,"l":"Finish","n":"After the last step the canary becomes the stable version."}]},{"id":"x-argocd-project-boundary","module":"argocd","lesson":"argocd/access-projects-secrets-and-multi-cluster","title":"A project blocks a deployment","summary":"Teams stay inside their boundary.","actors":["Team A application","AppProject","Argo CD","Team B namespace"],"steps":[{"f":0,"t":1,"l":"Application created","n":"Team A defines an application that targets team B's namespace."},{"f":1,"t":2,"l":"Check the project","n":"The project's allowed destinations list only team A namespaces."},{"f":2,"t":0,"l":"Reject","n":"Sync is refused with a message that the destination is not permitted."},{"f":0,"t":3,"l":"Change to its own namespace","n":"Team A points the application at its own namespace."},{"f":1,"t":2,"l":"Pass","n":"The destination is allowed, so the sync proceeds."},{"f":2,"t":3,"l":"Resources limited","n":"The project also blocks cluster-level kinds that the team has no need for."}]},{"id":"x-argocd-secrets-external","module":"argocd","lesson":"argocd/access-projects-secrets-and-multi-cluster","title":"Secrets without storing them in the repository","summary":"A reference instead of a value.","actors":["Repository","Argo CD","External Secrets Operator","Secrets manager"],"steps":[{"f":0,"t":1,"l":"Commit a reference","n":"The repository holds a resource that names a secret, not its value."},{"f":1,"t":2,"l":"Sync the reference","n":"Argo CD applies the reference object to the cluster."},{"f":2,"t":3,"l":"Fetch the value","n":"The operator reads the real value from the cloud secrets manager with its own identity."},{"f":2,"t":1,"l":"Create the Kubernetes Secret","n":"A Secret is created in the namespace for the pods to use."},{"f":1,"t":1,"l":"Hide the value","n":"Argo CD ignores the generated Secret contents so they never appear in diffs."},{"f":3,"t":2,"l":"Rotate","n":"A new value in the manager is picked up automatically on the next refresh."}]},{"id":"x-argocd-multi-cluster","module":"argocd","lesson":"argocd/access-projects-secrets-and-multi-cluster","title":"Delivering to a second cluster","summary":"A hub and its targets.","actors":["Hub Argo CD","Cluster credential","Target cluster","Application"],"steps":[{"f":0,"t":2,"l":"Register the target","n":"A command adds the remote cluster and creates a service account there."},{"f":0,"t":1,"l":"Store the credential","n":"The token is saved in the hub as a secret, so the hub namespace must be protected."},{"f":3,"t":0,"l":"Point an application at it","n":"The application's destination uses the remote cluster's address."},{"f":0,"t":2,"l":"Sync","n":"The hub applies the rendered manifests to the remote cluster."},{"f":2,"t":0,"l":"Report health","n":"The remote resources' health is reported back to the hub."},{"f":0,"t":2,"l":"Limit the role","n":"The service account in the target has only the rights the applications need."}]},{"id":"x-argocd-debug-stages","module":"argocd","lesson":"argocd/debugging-argo-cd","title":"Debugging by stage","summary":"Fetch, render, apply, health.","actors":["Engineer","Repo server","API server","Workload"],"steps":[{"f":0,"t":1,"l":"Read the condition","n":"argocd app get shows which stage failed first."},{"f":1,"t":1,"l":"Fetch","n":"A bad credential or path fails here with a clear message."},{"f":1,"t":1,"l":"Render","n":"The same helm template or kustomize build is run locally to reproduce errors."},{"f":1,"t":2,"l":"Apply","n":"A forbidden or not permitted message points to RBAC or project rules."},{"f":2,"t":3,"l":"Health","n":"If everything applied, the pods are debugged with events and logs."},{"f":0,"t":0,"l":"Record the cause","n":"The fix and a prevention are written down."}]},{"id":"x-linux-signal-delivery","module":"linux","lesson":"linux/processes-and-services","title":"How a signal reaches a process","summary":"From kill to exit.","actors":["Shell","Kernel","Process","Handler"],"steps":[{"f":0,"t":1,"l":"Send SIGTERM","n":"The kill command asks the kernel to deliver SIGTERM to the process ID."},{"f":1,"t":2,"l":"Mark the signal pending","n":"The kernel records the signal for the target process."},{"f":2,"t":3,"l":"Run the handler","n":"If the program installed a handler, it runs and begins an orderly shutdown."},{"f":3,"t":2,"l":"Close connections","n":"The handler finishes requests, flushes buffers and releases locks."},{"f":0,"t":1,"l":"Escalate if stuck","n":"If the process ignores SIGTERM, a later SIGKILL is sent."},{"f":1,"t":2,"l":"Kill without a handler","n":"SIGKILL cannot be caught, so the kernel removes the process at once."}]},{"id":"x-linux-file-write-path","module":"linux","lesson":"linux/filesystems-page-cache-and-io","title":"How a file write reaches the disk","summary":"Page cache and fsync.","actors":["Program","Page cache","Filesystem","Disk"],"steps":[{"f":0,"t":1,"l":"write() call","n":"The program writes bytes, which go to memory in the page cache."},{"f":1,"t":0,"l":"Return quickly","n":"The call returns before the data is on disk."},{"f":1,"t":2,"l":"Dirty pages","n":"The cache marks pages dirty and the kernel flushes them in the background."},{"f":0,"t":1,"l":"fsync() call","n":"A program that needs durability asks for the data to be flushed."},{"f":2,"t":3,"l":"Write blocks","n":"The filesystem writes data and its journal to the disk."},{"f":3,"t":0,"l":"Confirm","n":"Only after the disk reports completion does fsync return, so a crash no longer loses the data."}]},{"id":"x-git-squash-merge","module":"git","lesson":"git/rebase-and-clean-history","title":"A squash merge","summary":"Many commits become one.","actors":["Feature branch","Pull request","main","History"],"steps":[{"f":0,"t":1,"l":"Open the pull request","n":"The feature branch has twelve small commits, including fixes."},{"f":1,"t":1,"l":"Review and approve","n":"Reviewers approve the combined change."},{"f":1,"t":2,"l":"Squash and merge","n":"Git combines the twelve commits into one new commit on main."},{"f":2,"t":3,"l":"Clean history","n":"The history shows one commit with a clear message and a link to the review."},{"f":0,"t":0,"l":"Branch left behind","n":"The old branch still has the twelve commits and is deleted."},{"f":2,"t":3,"l":"Revert is easy","n":"If it causes trouble, one revert undoes the whole feature."}]},{"id":"x-git-reflog-rescue","module":"git","lesson":"git/debugging-git-problems","title":"Rescuing work with the reflog","summary":"Undoing a bad reset.","actors":["Developer","Branch","Reflog","Recovered branch"],"steps":[{"f":0,"t":1,"l":"Reset by mistake","n":"A hard reset moves the branch back and the last three commits vanish from view."},{"f":1,"t":2,"l":"Reflog keeps moves","n":"Git recorded every previous position of the branch tip."},{"f":0,"t":2,"l":"Read the reflog","n":"The developer runs git reflog and finds the commit before the reset."},{"f":0,"t":3,"l":"Create a branch","n":"A new branch is created at that commit."},{"f":3,"t":1,"l":"Commits return","n":"All three commits are reachable again."},{"f":0,"t":1,"l":"Move on","n":"The developer merges or cherry-picks the work back where it belongs."}]},{"id":"x-bash-read-lines","module":"bash","lesson":"bash/text-processing","title":"Reading a file line by line safely","summary":"Why while read needs care.","actors":["Script","File","Loop","Command"],"steps":[{"f":0,"t":1,"l":"Open the file","n":"The script redirects the file into a while loop."},{"f":1,"t":2,"l":"Read one line","n":"The read command takes a line, with IFS= and -r so spaces and backslashes survive."},{"f":2,"t":3,"l":"Run a command","n":"The loop passes the line to a command inside quotes."},{"f":3,"t":2,"l":"Do not consume input","n":"A command that reads standard input would swallow the rest of the file."},{"f":2,"t":1,"l":"Repeat","n":"The loop continues until read returns end of file."},{"f":0,"t":3,"l":"Check the exit code","n":"The script checks the status and stops on failure."}]},{"id":"x-bash-lock-file","module":"bash","lesson":"bash/safe-automation","title":"A script that refuses to run twice","summary":"Locking with flock.","actors":["Cron","Script","Lock file","Second run"],"steps":[{"f":0,"t":1,"l":"Start the job","n":"Cron starts the script on schedule."},{"f":1,"t":2,"l":"Take the lock","n":"The script uses flock to take an exclusive lock on a lock file."},{"f":1,"t":1,"l":"Do the work","n":"The long task runs while holding the lock."},{"f":0,"t":3,"l":"A second run starts","n":"A late job starts while the first is still running."},{"f":3,"t":2,"l":"Lock is busy","n":"The second run cannot get the lock and exits quietly."},{"f":1,"t":2,"l":"Release","n":"When the first run ends, the lock is released automatically."}]},{"id":"x-python-package-publish","module":"python","lesson":"python/testing-and-packaging","title":"Publishing a Python package","summary":"From source to installable.","actors":["Developer","Build tool","Index","User"],"steps":[{"f":0,"t":1,"l":"Set the version","n":"The developer updates the version in the project metadata."},{"f":1,"t":1,"l":"Build","n":"The build tool creates a source archive and a wheel."},{"f":0,"t":2,"l":"Upload","n":"The files are uploaded to a package index with a scoped token."},{"f":2,"t":3,"l":"Index serves","n":"The index stores the files and lists the new version."},{"f":3,"t":2,"l":"Install","n":"A user installs the package, preferably with a pinned version."},{"f":3,"t":0,"l":"Verify","n":"Hashes and a lock file ensure the same files are used each time."}]},{"id":"x-python-exit-codes","module":"python","lesson":"python/writing-command-line-tools","title":"A Python tool exits with the right code","summary":"So automation can react.","actors":["Script","Exception handler","Shell","Pipeline"],"steps":[{"f":0,"t":1,"l":"Run the work","n":"The script calls an API and the call fails."},{"f":1,"t":1,"l":"Catch the error","n":"The handler catches the specific exception and logs a clear message."},{"f":1,"t":0,"l":"Choose the code","n":"It exits with a non-zero code instead of returning normally."},{"f":0,"t":2,"l":"Shell sees failure","n":"The shell stores the exit status for the caller."},{"f":2,"t":3,"l":"Pipeline stops","n":"The pipeline step fails and the team is notified."},{"f":0,"t":3,"l":"Success path","n":"On success the script exits with zero and later steps continue."}]},{"id":"x-go-interface-satisfaction","module":"go","lesson":"go/interfaces-and-packages","title":"How a Go type satisfies an interface","summary":"No implements keyword.","actors":["Interface","Type","Compiler","Caller"],"steps":[{"f":0,"t":2,"l":"Define the interface","n":"The interface lists the methods a caller needs."},{"f":1,"t":1,"l":"Write the type","n":"A type defines methods with matching names and signatures."},{"f":2,"t":1,"l":"Check at compile time","n":"The compiler checks the type has every method, with no declaration needed."},{"f":3,"t":0,"l":"Accept the interface","n":"The caller's function takes the interface, so it accepts any matching type."},{"f":3,"t":1,"l":"Swap in a fake","n":"A test passes a small fake type that has the same methods."},{"f":2,"t":3,"l":"Mismatch fails early","n":"A missing method is reported as a compile error."}]},{"id":"x-go-cli-exit","module":"go","lesson":"go/building-containers-and-cli-tools","title":"A Go command-line tool","summary":"Flags, work and exit codes.","actors":["User","flag package","main","os.Exit"],"steps":[{"f":0,"t":1,"l":"Pass flags","n":"The user runs the tool with flags such as a timeout and a path."},{"f":1,"t":2,"l":"Parse","n":"The flag package parses values and prints usage for mistakes."},{"f":2,"t":2,"l":"Run the work","n":"main calls a function that returns an error instead of exiting inside it."},{"f":2,"t":3,"l":"Choose an exit code","n":"main maps errors to exit codes in one place."},{"f":3,"t":0,"l":"Exit","n":"The process ends with a status that scripts can test."},{"f":2,"t":0,"l":"Print errors to stderr","n":"Messages go to standard error so output stays clean."}]},{"id":"x-net-arp-lookup","module":"networking","lesson":"networking/dhcp-arp-and-the-local-network","title":"How ARP finds a MAC address","summary":"Local delivery on a subnet.","actors":["Host A","Switch","Host B","ARP cache"],"steps":[{"f":0,"t":3,"l":"Check the cache","n":"Host A looks for host B's MAC address in its ARP cache."},{"f":0,"t":1,"l":"Broadcast a question","n":"Nothing is cached, so A broadcasts who has this IP address."},{"f":1,"t":2,"l":"Switch floods","n":"The switch sends the broadcast to every port in the subnet."},{"f":2,"t":0,"l":"Host B replies","n":"Host B answers directly with its MAC address."},{"f":0,"t":3,"l":"Cache the answer","n":"Host A stores the mapping for a short time."},{"f":0,"t":2,"l":"Send the frame","n":"The frame goes to host B's MAC address through the switch."}]},{"id":"x-net-nat-translation","module":"networking","lesson":"networking/routing-and-nat","title":"How NAT rewrites a connection","summary":"Private addresses reaching the internet.","actors":["Private host","NAT gateway","Translation table","Server"],"steps":[{"f":0,"t":1,"l":"Send a packet","n":"A private host sends a packet to a public server."},{"f":1,"t":2,"l":"Create a mapping","n":"The gateway records the private address and port against a public port."},{"f":1,"t":3,"l":"Rewrite and forward","n":"The source address is changed to the gateway's public address."},{"f":3,"t":1,"l":"Reply returns","n":"The server answers to the gateway's public address and port."},{"f":1,"t":2,"l":"Look up the mapping","n":"The gateway finds which private host owns that port."},{"f":1,"t":0,"l":"Rewrite back","n":"The destination is changed to the private host and the packet is delivered."}]},{"id":"x-docker-bind-vs-volume","module":"docker","lesson":"docker/volumes-and-networking","title":"Bind mount and volume","summary":"Where container data lives.","actors":["Container","Bind mount","Volume","Host"],"steps":[{"f":0,"t":1,"l":"Mount a host folder","n":"A bind mount maps an existing host path into the container."},{"f":1,"t":3,"l":"Edits are shared","n":"Changes inside and outside the container appear in both places."},{"f":0,"t":2,"l":"Mount a volume","n":"A named volume is managed by Docker and mounted at a path."},{"f":2,"t":3,"l":"Stored by Docker","n":"Data lives in Docker's own area, independent of the container."},{"f":0,"t":2,"l":"Remove the container","n":"The volume remains with its data until it is removed explicitly."},{"f":1,"t":3,"l":"Beware permissions","n":"Host paths bring host ownership and permissions into the container."}]},{"id":"x-docker-image-scan","module":"docker","lesson":"docker/registries-and-supply-chain","title":"Scanning an image before it ships","summary":"Catch known flaws early.","actors":["Build","Scanner","Registry","Policy"],"steps":[{"f":0,"t":1,"l":"Build the image","n":"The pipeline builds the image from the Dockerfile."},{"f":1,"t":1,"l":"Scan","n":"The scanner compares installed packages with a database of known vulnerabilities."},{"f":1,"t":3,"l":"Apply a policy","n":"The policy fails the build for critical flaws with an available fix."},{"f":3,"t":0,"l":"Fix","n":"The team updates the base image or package and rebuilds."},{"f":0,"t":2,"l":"Push","n":"The clean image is pushed to the registry."},{"f":2,"t":3,"l":"Rescan regularly","n":"New flaws are published daily, so stored images are scanned again."}]},{"id":"x-cicd-manual-approval","module":"cicd","lesson":"cicd/environments-promotion-and-approvals","title":"A pipeline with approval","summary":"A gate before production.","actors":["Pipeline","Staging","Approver","Production"],"steps":[{"f":0,"t":1,"l":"Deploy to staging","n":"The pipeline deploys the build and runs tests automatically."},{"f":1,"t":0,"l":"Tests pass","n":"Results are attached to the run."},{"f":0,"t":2,"l":"Request approval","n":"The pipeline pauses and notifies the approver with the change and test results."},{"f":2,"t":0,"l":"Approve","n":"The approver reviews and approves, and the decision is recorded."},{"f":0,"t":3,"l":"Deploy to production","n":"The same artifact that was tested is deployed."},{"f":3,"t":0,"l":"Verify","n":"A health check confirms the release, and the pipeline reports success."}]},{"id":"x-cicd-rollback-artifact","module":"cicd","lesson":"cicd/versioning-and-artifacts","title":"Rolling back by redeploying an artifact","summary":"Previous version, same process.","actors":["Pipeline","Artifact store","Production","Monitor"],"steps":[{"f":0,"t":2,"l":"Release v42","n":"The pipeline deploys build 42 to production."},{"f":3,"t":2,"l":"Spot errors","n":"The monitor shows error rates rising after the release."},{"f":3,"t":0,"l":"Trigger rollback","n":"The on-call engineer starts the rollback job with the previous version number."},{"f":0,"t":1,"l":"Fetch v41","n":"The pipeline retrieves the stored v41 artifact, not a rebuild."},{"f":0,"t":2,"l":"Redeploy","n":"v41 is deployed with the same process as any release."},{"f":3,"t":0,"l":"Recover","n":"Error rates return to normal and the team investigates v42 calmly."}]},{"id":"x-k8s-statefulset-order","module":"kubernetes","lesson":"kubernetes/statefulsets-and-running-databases","title":"How a StatefulSet starts pods","summary":"Stable names and order.","actors":["StatefulSet controller","Pod 0","Pod 1","Volume"],"steps":[{"f":0,"t":1,"l":"Create pod 0","n":"The controller creates pod 0 first with a stable name."},{"f":1,"t":3,"l":"Attach storage","n":"Pod 0 gets its own volume claim that persists."},{"f":1,"t":0,"l":"Wait until ready","n":"The controller waits for pod 0 to be Running and Ready."},{"f":0,"t":2,"l":"Create pod 1","n":"Only after pod 0 is ready is pod 1 created."},{"f":2,"t":3,"l":"Own volume","n":"Pod 1 receives a separate volume claim."},{"f":0,"t":3,"l":"Replace in place","n":"A failed pod returns with the same name and the same volume."}]},{"id":"x-k8s-node-failure","module":"kubernetes","lesson":"kubernetes/scheduling-and-troubleshooting","title":"A node fails","summary":"Rescheduling workloads.","actors":["Node","Node controller","Deployment controller","Scheduler"],"steps":[{"f":0,"t":0,"l":"Node stops responding","n":"Power loss stops the kubelet heartbeats."},{"f":1,"t":1,"l":"Mark unreachable","n":"After the grace period the node is marked NotReady and tainted."},{"f":1,"t":2,"l":"Evict after the timeout","n":"Pods on the node are removed from the API after their toleration expires."},{"f":2,"t":2,"l":"Create replacements","n":"The Deployment's ReplicaSet creates new pods to restore the count."},{"f":2,"t":3,"l":"Place them","n":"The scheduler assigns the new pods to healthy nodes."},{"f":3,"t":0,"l":"Service recovers","n":"Traffic goes to the new pods once they are ready."}]},{"id":"x-helm-diff-before-upgrade","module":"helm","lesson":"helm/upgrade-rollback-and-release-history","title":"Checking a change with helm diff","summary":"See before you apply.","actors":["Engineer","helm diff","Cluster","Release"],"steps":[{"f":0,"t":1,"l":"Prepare the change","n":"The engineer updates values or the chart version."},{"f":1,"t":2,"l":"Read the live release","n":"The diff plugin reads the manifest of the current release."},{"f":1,"t":1,"l":"Render the new manifest","n":"The new chart and values are rendered locally."},{"f":1,"t":0,"l":"Show the differences","n":"Lines are shown for each changed object."},{"f":0,"t":0,"l":"Review","n":"The engineer checks image tags, replicas and resources."},{"f":0,"t":3,"l":"Upgrade","n":"Only then does helm upgrade run, with the diff attached to the review."}]},{"id":"x-helm-repo-version","module":"helm","lesson":"helm/dependencies-subcharts-and-registries","title":"Choosing a chart version","summary":"From repository index to release.","actors":["Engineer","Repository index","Chart","Cluster"],"steps":[{"f":0,"t":1,"l":"Update the index","n":"helm repo update downloads the list of available chart versions."},{"f":0,"t":1,"l":"Search versions","n":"helm search shows several versions of the chart."},{"f":0,"t":2,"l":"Pin one","n":"The engineer chooses an exact version, not the latest."},{"f":2,"t":0,"l":"Pull and inspect","n":"The chart is pulled and its values and templates reviewed."},{"f":0,"t":3,"l":"Install","n":"The release is installed with the pinned version and recorded."},{"f":0,"t":1,"l":"Upgrade deliberately","n":"New versions are adopted by a reviewed change."}]},{"id":"x-terraform-workspaces","module":"terraform","lesson":"terraform/environments-and-team-workflows","title":"Workspaces and separate state","summary":"Two ways to separate environments.","actors":["Engineer","Workspace","State file","Environment"],"steps":[{"f":0,"t":1,"l":"Select a workspace","n":"The engineer chooses a workspace named staging."},{"f":1,"t":2,"l":"Use its state","n":"Each workspace has its own state in the same backend."},{"f":0,"t":3,"l":"Apply","n":"Resources for staging are created from the same code."},{"f":0,"t":1,"l":"Switch to production","n":"A second workspace uses another state, easy to confuse with the first."},{"f":0,"t":2,"l":"Prefer separate directories","n":"Many teams use separate configurations and backends for clearer boundaries and permissions."},{"f":0,"t":3,"l":"Check before apply","n":"The plan header shows which environment is targeted."}]},{"id":"x-terraform-failed-apply","module":"terraform","lesson":"terraform/workflows-and-drift","title":"Recovering from a failed apply","summary":"Half-created infrastructure.","actors":["Terraform","Cloud API","State","Engineer"],"steps":[{"f":0,"t":1,"l":"Apply","n":"Terraform creates resources one by one."},{"f":1,"t":0,"l":"One call fails","n":"The cloud rejects a request, for example due to a quota."},{"f":0,"t":2,"l":"Save progress","n":"The state records the resources created before the error."},{"f":0,"t":3,"l":"Read the error","n":"The engineer reads the message and fixes the cause, such as raising the quota."},{"f":3,"t":0,"l":"Run apply again","n":"The next apply continues from the saved state."},{"f":0,"t":2,"l":"Check the plan","n":"The plan shows only the remaining work and no duplicates."}]},{"id":"x-ansible-handlers","module":"ansible","lesson":"ansible/handlers-conditionals-and-loops","title":"Handlers and notifications","summary":"Restart only when something changed.","actors":["Playbook","Task","Handler","Service"],"steps":[{"f":0,"t":1,"l":"Run the task","n":"A task updates the configuration file."},{"f":1,"t":1,"l":"Detect a change","n":"The file differs, so the task reports changed."},{"f":1,"t":2,"l":"Notify","n":"The task notifies the restart handler."},{"f":0,"t":2,"l":"Run other tasks","n":"The play continues with later tasks."},{"f":2,"t":3,"l":"Run handlers at the end","n":"The restart runs once, after the tasks that needed it."},{"f":0,"t":3,"l":"No change, no restart","n":"On a second run nothing changes and the service is not touched."}]},{"id":"x-ansible-dynamic-inventory","module":"ansible","lesson":"ansible/dynamic-inventory-for-cloud","title":"Dynamic inventory from the cloud","summary":"Hosts found at run time.","actors":["Playbook","Inventory plugin","Cloud API","Hosts"],"steps":[{"f":0,"t":1,"l":"Ask for inventory","n":"The playbook run starts with an inventory plugin."},{"f":1,"t":2,"l":"Query the cloud","n":"The plugin lists servers with their tags."},{"f":2,"t":1,"l":"Return the list","n":"The cloud returns servers and metadata."},{"f":1,"t":0,"l":"Build groups","n":"Hosts are grouped by tag such as web or db."},{"f":0,"t":3,"l":"Run on the group","n":"The play targets the web group and connects to those hosts."},{"f":0,"t":3,"l":"Always current","n":"New servers are included next run and deleted servers disappear."}]},{"id":"x-cloud-health-check","module":"cloud","lesson":"cloud/high-availability-and-disaster-recovery","title":"A load balancer health check","summary":"Only healthy targets get traffic.","actors":["Load balancer","Target A","Target B","Users"],"steps":[{"f":0,"t":1,"l":"Probe","n":"The load balancer requests the health path from each target."},{"f":1,"t":0,"l":"Healthy","n":"Target A returns 200 and stays in rotation."},{"f":0,"t":2,"l":"Probe B","n":"Target B is probed in the same way on the same path."},{"f":2,"t":0,"l":"Unhealthy","n":"Target B returns errors repeatedly."},{"f":0,"t":2,"l":"Remove","n":"After the threshold, target B receives no new traffic."},{"f":3,"t":0,"l":"Users unaffected","n":"Requests go to target A while B is repaired and re-added."}]},{"id":"x-cloud-budget-alert","module":"cloud","lesson":"cloud/managed-services-and-cost","title":"A cost budget alert","summary":"Catch a bill spike early.","actors":["Billing data","Budget","Alert","Team"],"steps":[{"f":0,"t":1,"l":"Collect costs","n":"Usage and cost data is collected daily by tag."},{"f":1,"t":1,"l":"Compare with budget","n":"The service compares spend with the monthly budget."},{"f":1,"t":2,"l":"Cross a threshold","n":"Forecast spend passes 80 percent of the budget."},{"f":2,"t":3,"l":"Notify","n":"The team receives an alert naming the service and the tag."},{"f":3,"t":0,"l":"Investigate","n":"They find idle large servers left running."},{"f":3,"t":1,"l":"Fix and prevent","n":"They remove the servers and add scheduled shutdown for test environments."}]},{"id":"x-obs-slo-dashboard-reading","module":"observability","lesson":"observability/alerting-and-dashboards","title":"How an SLO is computed","summary":"From events to a budget.","actors":["Requests","Metrics","Query","Dashboard"],"steps":[{"f":0,"t":1,"l":"Count requests","n":"Every request increments total and error counters."},{"f":1,"t":2,"l":"Query a window","n":"A query computes the good request ratio over 30 days."},{"f":2,"t":3,"l":"Compare with the target","n":"The ratio is compared with the 99.9 percent objective."},{"f":3,"t":3,"l":"Show the budget","n":"The dashboard displays the error budget remaining."},{"f":3,"t":0,"l":"Show the burn rate","n":"A second panel shows how fast the budget is being used."},{"f":3,"t":0,"l":"Decide","n":"The team slows releases if the budget is nearly spent."}]},{"id":"x-obs-trace-id-logs","module":"observability","lesson":"observability/logs-and-traces","title":"Linking logs and traces","summary":"One ID across tools.","actors":["Gateway","Service","Log search","Trace view"],"steps":[{"f":0,"t":1,"l":"Create a trace ID","n":"The gateway creates an ID and passes it in a header."},{"f":1,"t":1,"l":"Log with the ID","n":"The service writes the ID in every log line."},{"f":1,"t":3,"l":"Send spans","n":"The service also sends spans with the same ID to the tracing backend."},{"f":2,"t":2,"l":"Search logs","n":"An engineer searches logs for the ID."},{"f":3,"t":2,"l":"Open the trace","n":"The trace view shows the same request and where it was slow."},{"f":2,"t":3,"l":"Fix with evidence","n":"Logs show the error and the trace shows the slow call that caused it."}]},{"id":"x-sre-capacity-planning","module":"sre","lesson":"sre/capacity-planning","title":"Capacity planning from a trend","summary":"Plan before you run out.","actors":["Metrics","Forecast","Plan","Review"],"steps":[{"f":0,"t":1,"l":"Collect usage","n":"Weekly peaks for CPU, memory and storage are collected."},{"f":1,"t":1,"l":"Fit a trend","n":"A forecast projects when usage will reach 80 percent."},{"f":1,"t":2,"l":"Add headroom","n":"The plan adds a margin for failures and launches."},{"f":2,"t":2,"l":"Schedule the work","n":"The purchase or scale-up is scheduled before the date, with lead time."},{"f":3,"t":0,"l":"Review monthly","n":"The forecast is compared with actual growth."},{"f":3,"t":2,"l":"Adjust","n":"Differences change the plan, not only the numbers."}]},{"id":"x-sre-oncall-handoff","module":"sre","lesson":"sre/on-call","title":"An on-call handoff","summary":"Passing context safely.","actors":["Outgoing engineer","Notes","Incoming engineer","Alerts"],"steps":[{"f":0,"t":1,"l":"Write the notes","n":"The outgoing engineer lists open issues, recent changes and risky tasks."},{"f":1,"t":2,"l":"Share","n":"The notes are shared in the handoff meeting or channel."},{"f":2,"t":1,"l":"Ask questions","n":"The incoming engineer asks about anything unclear."},{"f":3,"t":2,"l":"Review alerts","n":"Together they check open alerts and silences."},{"f":2,"t":3,"l":"Confirm","n":"The incoming engineer confirms ownership and the pager is switched."},{"f":0,"t":2,"l":"Stay reachable","n":"The outgoing engineer remains available for a short overlap."}]},{"id":"x-security-dependency-scan","module":"security","lesson":"security/securing-the-pipeline","title":"Scanning dependencies","summary":"Known flaws in libraries.","actors":["Developer","Pipeline","Scanner","Advisory data"],"steps":[{"f":0,"t":1,"l":"Open a pull request","n":"The change updates dependencies."},{"f":1,"t":2,"l":"Run the scanner","n":"The pipeline lists direct and indirect dependencies."},{"f":2,"t":3,"l":"Compare","n":"Versions are matched against known vulnerability data."},{"f":2,"t":1,"l":"Report findings","n":"A critical flaw with a fixed version is found."},{"f":0,"t":0,"l":"Update","n":"The developer upgrades to the fixed version."},{"f":1,"t":1,"l":"Pass","n":"The scan is clean and the pull request can merge."}]},{"id":"x-security-rotate-credential","module":"security","lesson":"security/secrets-management","title":"Rotating a credential","summary":"Replace without an outage.","actors":["Secret store","Service A","Database","Operator"],"steps":[{"f":0,"t":0,"l":"Create the new secret","n":"The operator creates version 2 while version 1 remains valid."},{"f":0,"t":3,"l":"Add the new password","n":"The database accepts both passwords for now."},{"f":1,"t":0,"l":"Read the new version","n":"Service A reloads the secret and starts using version 2."},{"f":0,"t":1,"l":"Verify","n":"Logs show all instances connected with the new password."},{"f":0,"t":3,"l":"Retire the old","n":"Version 1 is removed from the database."},{"f":0,"t":0,"l":"Record","n":"The date and owner are recorded for the next rotation."}]},{"id":"x-db-write-ahead-log","module":"databases","lesson":"databases/backups-and-recovery","title":"Write-ahead logging","summary":"Durability before the data file.","actors":["Client","Database","Log","Data files"],"steps":[{"f":0,"t":1,"l":"Commit","n":"The client commits a transaction."},{"f":1,"t":2,"l":"Write the log","n":"The change is appended to the write-ahead log and flushed."},{"f":1,"t":0,"l":"Acknowledge","n":"Only after the log is safe is the commit confirmed."},{"f":1,"t":3,"l":"Update data later","n":"The data files are updated in the background."},{"f":1,"t":1,"l":"Crash","n":"The server loses power before data files are written."},{"f":2,"t":3,"l":"Replay","n":"On restart the log is replayed so committed changes are restored."}]},{"id":"x-db-connection-exhaustion","module":"databases","lesson":"databases/performance-and-connection-pooling","title":"Running out of connections","summary":"Why a pool and a limit matter.","actors":["Application","Pool","Database","Alert"],"steps":[{"f":0,"t":1,"l":"Traffic grows","n":"More application instances start, each opening its own connections."},{"f":1,"t":2,"l":"Reach the limit","n":"The database hits its maximum number of connections."},{"f":2,"t":0,"l":"Refuse new connections","n":"New requests fail with too many connections."},{"f":3,"t":0,"l":"Alert","n":"An alert fires on connection use above 80 percent."},{"f":1,"t":2,"l":"Add a pooler","n":"A pooler shares a small number of server connections among many clients."},{"f":0,"t":1,"l":"Set pool sizes","n":"Each application gets a limit so the total stays under the cap."}]},{"id":"x-llm-cheaper-model","module":"llm","lesson":"llm/choosing-and-evaluating-models","title":"Choosing a cheaper model for simple steps","summary":"Match model to task.","actors":["Router","Small model","Large model","Evaluation"],"steps":[{"f":0,"t":3,"l":"Collect examples","n":"Real requests are labelled by difficulty."},{"f":0,"t":1,"l":"Try the small model","n":"Simple classification is run on the cheaper model."},{"f":3,"t":1,"l":"Measure","n":"The evaluation set shows the pass rate matches the larger model on this step."},{"f":0,"t":2,"l":"Keep the large model","n":"Hard reasoning steps stay on the more capable model."},{"f":0,"t":0,"l":"Route","n":"The router sends each step to the cheapest model that passes."},{"f":3,"t":0,"l":"Recheck","n":"The evaluation runs again on every model or prompt change."}]},{"id":"x-llm-batch-processing","module":"llm","lesson":"llm/cost-latency-and-caching","title":"Batch processing","summary":"Non-urgent work at lower cost.","actors":["Job","Batch API","Model","Results"],"steps":[{"f":0,"t":1,"l":"Collect requests","n":"A nightly job gathers ten thousand summaries to produce."},{"f":1,"t":1,"l":"Submit as a batch","n":"The requests are sent as one batch with IDs."},{"f":1,"t":2,"l":"Process later","n":"The provider processes them within a time window at a lower price."},{"f":1,"t":0,"l":"Poll for status","n":"The job checks the batch status periodically."},{"f":2,"t":3,"l":"Download results","n":"Results are returned with the same IDs."},{"f":3,"t":0,"l":"Match and validate","n":"Each result is matched to its request and validated, and failures are retried."}]},{"id":"x-prompting-tags-data","module":"prompting","lesson":"prompting/system-prompts-roles-and-context-layout","title":"Separating data from instructions","summary":"Tags keep roles clear.","actors":["Instructions","Document","Prompt","Model"],"steps":[{"f":0,"t":2,"l":"Write the task","n":"The instructions say what to do with the document."},{"f":1,"t":2,"l":"Wrap the data","n":"The document is placed inside tags marked as data."},{"f":2,"t":3,"l":"Send","n":"The prompt contains instructions first, then the tagged document."},{"f":3,"t":3,"l":"Treat tags as data","n":"The model summarises the content and does not follow orders written inside it."},{"f":2,"t":3,"l":"Not a guarantee","n":"Tags help but do not replace limiting what the system can do."},{"f":3,"t":0,"l":"Validate","n":"The output is validated in code before anything uses it."}]},{"id":"x-prompting-ab-compare","module":"prompting","lesson":"prompting/prompt-versioning-and-testing","title":"Comparing two prompt versions","summary":"Decide with data.","actors":["Version A","Version B","Evaluation set","Decision"],"steps":[{"f":0,"t":2,"l":"Run version A","n":"The saved cases are run through version A several times."},{"f":1,"t":2,"l":"Run version B","n":"The same cases are run through version B."},{"f":2,"t":3,"l":"Score","n":"Checks in code score format, facts and forbidden content."},{"f":3,"t":3,"l":"Compare","n":"Pass rates, cost and latency are compared per case type."},{"f":3,"t":0,"l":"Choose","n":"The better version is released gradually."},{"f":3,"t":2,"l":"Keep the cases","n":"Failures become new cases for the future."}]},{"id":"x-skills-reference-on-demand","module":"claude-skills","lesson":"claude-skills/progressive-disclosure-and-structure","title":"Loading a reference file on demand","summary":"Only when a step needs it.","actors":["Request","SKILL.md","Reference file","Claude"],"steps":[{"f":0,"t":3,"l":"Skill triggers","n":"The request matches the skill and the body loads."},{"f":1,"t":3,"l":"Follow the workflow","n":"The steps run; most requests never need the long reference."},{"f":1,"t":2,"l":"A step needs detail","n":"A step says to read the rules file for invoices over a limit."},{"f":3,"t":2,"l":"Open the file","n":"Claude reads the single file named by the step."},{"f":2,"t":3,"l":"Use the detail","n":"The rules are applied to the task."},{"f":3,"t":0,"l":"Stay lean","n":"Other requests never pay for the reference in context."}]},{"id":"x-skills-version-update","module":"claude-skills","lesson":"claude-skills/sharing-versioning-and-skill-security","title":"Updating a skill","summary":"Change with tests.","actors":["Author","Test tasks","Repository","Team"],"steps":[{"f":0,"t":1,"l":"Edit the skill","n":"The author improves a description or step."},{"f":1,"t":1,"l":"Run the tasks","n":"The saved tasks are run before and after."},{"f":1,"t":0,"l":"Compare","n":"Results show better quality and no new false triggers."},{"f":0,"t":2,"l":"Bump the version","n":"The change is merged with a changelog entry and a new version."},{"f":2,"t":3,"l":"Roll out","n":"The team installs the new version from the repository."},{"f":3,"t":0,"l":"Report problems","n":"A missed request is added to the test tasks for next time."}]},{"id":"x-mcp-resource-template","module":"mcp","lesson":"mcp/resources-prompts-and-other-primitives","title":"Reading a resource by URI","summary":"Data the application attaches.","actors":["User","Host","MCP server","Backend"],"steps":[{"f":0,"t":1,"l":"Pick a document","n":"The user selects a runbook in the host's attachment menu."},{"f":1,"t":2,"l":"Read the resource","n":"The host asks the server to read the resource by its URI."},{"f":2,"t":3,"l":"Fetch","n":"The server loads the runbook from the backend."},{"f":3,"t":2,"l":"Return content","n":"The text is returned as the resource contents."},{"f":2,"t":1,"l":"Attach","n":"The host adds it to the model's context for the conversation."},{"f":1,"t":0,"l":"Respect size","n":"Large documents are summarised or limited to save context."}]},{"id":"x-mcp-tracing-calls","module":"mcp","lesson":"mcp/debugging-tool-use-and-mcp","title":"Tracing tool calls","summary":"Make agent runs debuggable.","actors":["Agent","Tool","Trace store","Engineer"],"steps":[{"f":0,"t":1,"l":"Create a run ID","n":"Each conversation gets a run ID and each call a step number."},{"f":0,"t":1,"l":"Call a tool","n":"The agent calls a tool with arguments."},{"f":1,"t":2,"l":"Log the step","n":"The call, duration, result size and errors are stored with the run ID."},{"f":0,"t":1,"l":"Repeat","n":"Later steps are logged in order."},{"f":3,"t":2,"l":"Investigate","n":"An engineer opens the trace for a wrong answer."},{"f":3,"t":2,"l":"Find the cause","n":"They see the tool returned an empty result and the agent gave up."}]},{"id":"f-linux-disk-full","module":"linux","kind":"failure","lesson":"linux/disks-and-filesystems","title":"Failure and recovery: a full disk stops a service","summary":"Logs fill /var, writes fail, and the fix has two parts.","actors":["Service","Filesystem","Operator","Logrotate"],"steps":[{"f":0,"t":1,"l":"Normal writes","n":"The service writes a little log data each second and the filesystem has plenty of free space."},{"f":0,"t":1,"l":"Logs grow","n":"A debug flag left on triples the log volume and nobody notices for days."},{"f":1,"t":0,"l":"Disk fills","n":"The filesystem reaches one hundred percent and the next write returns no space left on device."},{"f":0,"t":2,"l":"Symptom","n":"Requests start failing and the service logs an error about being unable to write its own state."},{"f":2,"t":1,"l":"Check usage","n":"The operator runs df -h to find the full filesystem and du -xh to find the biggest directories."},{"f":2,"t":1,"l":"Find held files","n":"lsof shows a deleted log file still held open, so deleting it freed no space until the process restarts."},{"f":2,"t":0,"l":"Fix","n":"Truncate the log, restart the service to release the file, and turn the debug flag off."},{"f":3,"t":1,"l":"Prevent","n":"Logrotate with size limits and a disk usage alert at eighty percent keeps it from recurring."}]},{"id":"f-linux-oom-kill","module":"linux","kind":"failure","lesson":"linux/processes-memory-and-the-oom-killer","title":"Failure and recovery: the OOM killer ends the wrong process","summary":"Memory runs out and the kernel picks a victim.","actors":["Application","Kernel","Operator","Monitoring"],"steps":[{"f":0,"t":1,"l":"Allocate memory","n":"The application keeps asking for more memory as a cache grows without a size limit."},{"f":1,"t":1,"l":"Memory pressure","n":"Free memory and page cache are used up and swap, if any, fills."},{"f":1,"t":0,"l":"OOM kill","n":"The kernel scores processes and ends the one with the highest score, which is the large database process."},{"f":3,"t":2,"l":"Alert fires","n":"A process-restart alert fires and the operator sees the database vanished at the same moment."},{"f":2,"t":1,"l":"Read the log","n":"dmesg or journalctl -k shows Out of memory: Killed process with the process name and its memory use."},{"f":2,"t":0,"l":"Find the cause","n":"The real culprit is the cache with no limit, not the database that was killed."},{"f":2,"t":0,"l":"Fix","n":"Cap the cache size, set a memory limit with systemd, and protect the database with a lower oom score."},{"f":3,"t":2,"l":"Verify","n":"Memory graphs stay flat, no new kill messages appear, and the database stays up for a full day."}]},{"id":"f-git-force-push","module":"git","kind":"failure","lesson":"git/branches-and-merging","title":"Failure and recovery: a force push overwrites a teammate's work","summary":"Lost commits are usually still recoverable.","actors":["Developer","Remote","Teammate","Reflog"],"steps":[{"f":0,"t":1,"l":"Shared branch","n":"Two people work on the same branch and the remote has three commits from the teammate."},{"f":0,"t":1,"l":"Rewrite history","n":"The developer rebases locally and runs a plain force push because the normal push was rejected."},{"f":1,"t":1,"l":"Remote moves","n":"The remote branch now points at the developer's history and the teammate's commits are no longer on it."},{"f":2,"t":1,"l":"Symptom","n":"The teammate's next pull reports a diverged history and the commits seem to be gone."},{"f":2,"t":3,"l":"Look locally","n":"The teammate's own clone still has the commits and git reflog lists them by position."},{"f":2,"t":1,"l":"Restore","n":"Create a branch at the lost commit with git branch rescue and push it so the work is safe."},{"f":0,"t":1,"l":"Merge it back","n":"The developer rebases onto the rescue branch and pushes again, without losing either set of changes."},{"f":1,"t":0,"l":"Prevent","n":"Protect shared branches and use force-with-lease instead of a plain force push."}]},{"id":"f-git-secret-committed","module":"git","kind":"failure","lesson":"git/hooks-signing-and-secrets-in-history","title":"Failure and recovery: a secret reaches the repository","summary":"Rotating the secret matters more than rewriting history.","actors":["Developer","Repository","Scanner","Security"],"steps":[{"f":0,"t":1,"l":"Commit a config","n":"A developer commits a file that contains a real access key and pushes it to the shared repository."},{"f":1,"t":2,"l":"Scan finds it","n":"A scheduled scanner finds a string that matches the key pattern in the latest commit."},{"f":2,"t":3,"l":"Alert","n":"The scanner opens a finding and the security team is told which key and which commit."},{"f":3,"t":0,"l":"Revoke first","n":"The key is revoked and a new one issued before anything else, because anyone who cloned has the old one."},{"f":3,"t":1,"l":"Rewrite history","n":"The file is removed from all commits with a history rewrite tool and the repository is force pushed."},{"f":1,"t":0,"l":"Clean clones","n":"Everyone re-clones or resets, since old clones and forks still hold the secret."},{"f":0,"t":1,"l":"Move the secret","n":"The new key is read from a secret manager at runtime and the file now holds only a placeholder."},{"f":2,"t":1,"l":"Prevent","n":"A pre-commit hook and a push check block the pattern before it reaches the remote."}]},{"id":"f-bash-unset-variable","module":"bash","kind":"failure","lesson":"bash/safe-automation","title":"Failure and recovery: an unset variable deletes the wrong path","summary":"A tiny script bug becomes a large deletion.","actors":["Script","Shell","Filesystem","Reviewer"],"steps":[{"f":0,"t":1,"l":"The script","n":"A cleanup script runs rm -rf with a variable named BUILD_DIR followed by a slash."},{"f":0,"t":1,"l":"Variable empty","n":"A typo means BUILD_DIR was never set, so the shell expands it to an empty string."},{"f":1,"t":2,"l":"Dangerous path","n":"The command becomes rm -rf slash, and only the protection of the system saves the whole machine."},{"f":2,"t":0,"l":"Damage","n":"Files under directories the user owns are deleted before the command is stopped."},{"f":3,"t":0,"l":"Review","n":"A reviewer asks why the script did not stop when the variable was empty."},{"f":0,"t":1,"l":"Fix the script","n":"Add set -u so unset variables are an error, and use the expansion that fails when the value is empty."},{"f":0,"t":2,"l":"Guard","n":"Check that the path starts with the expected directory and exists before any delete."},{"f":2,"t":0,"l":"Recover","n":"Restore from backup and add a dry run option that only prints what would be removed."}]},{"id":"f-bash-partial-write","module":"bash","kind":"failure","lesson":"bash/temporary-files-and-atomic-writes","title":"Failure and recovery: a half-written file is read by another job","summary":"Atomic writes prevent torn reads.","actors":["Writer","Temp file","Reader","Filesystem"],"steps":[{"f":0,"t":1,"l":"Write directly","n":"A job writes its report straight to the final file name over a few seconds."},{"f":2,"t":3,"l":"Read too early","n":"A second job reads the same file in the middle of the write."},{"f":3,"t":2,"l":"Truncated data","n":"The reader gets half the lines and builds a wrong summary without any error."},{"f":2,"t":0,"l":"Spot it","n":"Numbers in the summary do not match, and the file modified time is within the reader's run."},{"f":0,"t":1,"l":"Fix: temp file","n":"The writer creates a temporary file in the same directory and writes everything there."},{"f":1,"t":3,"l":"Fix: rename","n":"A rename onto the final name is atomic, so the reader sees either the old file or the complete new one."},{"f":0,"t":1,"l":"Clean up","n":"A trap removes the temp file if the script fails, so no stale partial files remain."},{"f":2,"t":0,"l":"Verify","n":"Re-running both jobs together always gives a complete report."}]},{"id":"f-python-unhandled-timeout","module":"python","kind":"failure","lesson":"python/http-apis-and-json","title":"Failure and recovery: a request with no timeout hangs a script","summary":"One slow API stalls a whole job.","actors":["Script","HTTP client","API","Scheduler"],"steps":[{"f":0,"t":1,"l":"Normal call","n":"A nightly script calls an API with the requests library and finishes in seconds."},{"f":1,"t":2,"l":"API slows","n":"The API stops answering and keeps the connection open without sending data."},{"f":1,"t":1,"l":"Wait forever","n":"The call has no timeout, so it waits and the script never reaches its next line."},{"f":3,"t":0,"l":"Symptom","n":"The scheduler reports the job still running hours later and the next run is skipped or overlaps."},{"f":3,"t":0,"l":"Diagnose","n":"Stack dump or py-spy shows the thread blocked in a socket read inside the client."},{"f":0,"t":1,"l":"Fix","n":"Set a connect and read timeout on every call and catch the timeout error."},{"f":0,"t":1,"l":"Retry safely","n":"Retry with a small backoff and a limit, then fail clearly with a message and a non-zero exit code."},{"f":3,"t":0,"l":"Verify","n":"The scheduler shows the job ending within its time limit even when the API is down."}]},{"id":"f-python-wrong-environment","module":"python","kind":"failure","lesson":"python/basics-and-environments","title":"Failure and recovery: the wrong Python environment breaks a deploy","summary":"Works on my machine, fails on the server.","actors":["Developer","Server","Package index","Virtualenv"],"steps":[{"f":0,"t":1,"l":"Works locally","n":"The script runs fine on a laptop where the packages were installed globally over time."},{"f":0,"t":1,"l":"Deploy","n":"The script is copied to a server without a lock file or a recorded list of packages."},{"f":1,"t":1,"l":"Import error","n":"The server reports a missing module, and after installing it, a newer version behaves differently."},{"f":1,"t":0,"l":"Symptom","n":"The job fails with ModuleNotFoundError, then with a changed function signature."},{"f":0,"t":3,"l":"Investigate","n":"pip freeze on both machines shows different versions and which python is used is not the same."},{"f":0,"t":3,"l":"Fix","n":"Create a virtualenv, pin versions in a requirements file with hashes, and install from it."},{"f":0,"t":1,"l":"Automate","n":"The deploy step creates the environment from the lock file, so every machine is the same."},{"f":1,"t":0,"l":"Verify","n":"A fresh server runs the script with the same versions and the same results."}]},{"id":"f-net-dns-stale","module":"networking","kind":"failure","lesson":"networking/dns","title":"Failure and recovery: a stale DNS answer sends traffic to the old server","summary":"Cached records outlive a cutover.","actors":["Client","Resolver","Authoritative DNS","Old server"],"steps":[{"f":0,"t":1,"l":"Normal lookup","n":"A client asks a resolver for the service name and receives an address with a long time to live."},{"f":1,"t":2,"l":"Cutover","n":"The team moves the service to a new address and updates the record at the authoritative server."},{"f":1,"t":0,"l":"Cache holds","n":"The resolver keeps serving the old answer until the cached time to live runs out."},{"f":0,"t":3,"l":"Symptom","n":"Some users reach the old server, which is draining, and see errors while others work fine."},{"f":0,"t":1,"l":"Diagnose","n":"dig shows different answers from different resolvers and the remaining time to live in each."},{"f":2,"t":1,"l":"Fix","n":"Wait for the time to live, or flush the caches you control, and keep the old server serving until then."},{"f":2,"t":1,"l":"Next time","n":"Lower the time to live a day before a planned cutover and raise it again afterwards."},{"f":0,"t":3,"l":"Verify","n":"dig from several resolvers returns the new address and the old server sees no more traffic."}]},{"id":"f-net-mtu-blackhole","module":"networking","kind":"failure","lesson":"networking/latency-mtu-and-network-performance","title":"Failure and recovery: a smaller path MTU drops large packets","summary":"Small requests work, large ones hang.","actors":["Client","Router","Tunnel","Server"],"steps":[{"f":0,"t":1,"l":"Normal path","n":"Packets of 1500 bytes travel from client to server over ordinary links."},{"f":1,"t":2,"l":"Tunnel added","n":"A VPN tunnel is added on the path and its overhead lowers the usable packet size to about 1400 bytes."},{"f":1,"t":0,"l":"Drop","n":"A large packet with the do not fragment bit cannot fit and the router drops it, but the message back is blocked."},{"f":0,"t":3,"l":"Symptom","n":"Pings and small requests work, but a large download or a TLS handshake stalls and times out."},{"f":0,"t":1,"l":"Diagnose","n":"ping with a set size and the do not fragment flag finds the largest size that passes."},{"f":0,"t":2,"l":"Fix","n":"Lower the MTU on the tunnel interface or clamp the segment size so packets fit."},{"f":1,"t":0,"l":"Allow messages","n":"Permit the needed ICMP messages so path discovery can work for other traffic."},{"f":0,"t":3,"l":"Verify","n":"Large transfers complete at normal speed and the handshake no longer hangs."}]},{"id":"f-docker-restart-loop","module":"docker","kind":"failure","lesson":"docker/debugging-containers","title":"Failure and recovery: a container restarts in a loop","summary":"The exit code points at the cause.","actors":["Orchestrator","Container","Image","Operator"],"steps":[{"f":0,"t":1,"l":"Start","n":"The orchestrator starts a new container from the latest image tag."},{"f":1,"t":1,"l":"Crash","n":"The main process exits right after start with a non-zero exit code."},{"f":0,"t":1,"l":"Restart","n":"The restart policy starts it again and again, with a growing delay between attempts."},{"f":3,"t":0,"l":"Symptom","n":"The status shows restarting or crash loop and the service is never ready."},{"f":3,"t":1,"l":"Read logs","n":"docker logs shows a missing environment variable that the new image now requires."},{"f":3,"t":1,"l":"Check exit code","n":"Code 1 points at the application and 137 would point at memory limits being hit."},{"f":3,"t":2,"l":"Fix","n":"Provide the variable or roll back to the previous image tag that worked."},{"f":0,"t":1,"l":"Verify","n":"The container stays running, passes its health check, and the restart count stops increasing."}]},{"id":"f-docker-rate-limit","module":"docker","kind":"failure","lesson":"docker/registries-and-supply-chain","title":"Failure and recovery: an image pull hits the registry rate limit","summary":"Builds stall on a public registry.","actors":["CI runner","Registry","Mirror","Team"],"steps":[{"f":0,"t":1,"l":"Normal pulls","n":"The pipeline pulls base images from a public registry without logging in."},{"f":0,"t":1,"l":"Many builds","n":"A busy day produces many builds from the same shared address."},{"f":1,"t":0,"l":"Limit reached","n":"The registry returns too many requests and refuses further pulls for a few hours."},{"f":3,"t":0,"l":"Symptom","n":"Builds fail at the pull step with a rate limit message, even though the code did not change."},{"f":3,"t":1,"l":"Confirm","n":"The response headers show the remaining pulls and the time when the limit resets."},{"f":3,"t":2,"l":"Fix now","n":"Log in with a registry account to raise the limit, or retry after the reset."},{"f":3,"t":2,"l":"Fix for good","n":"Mirror the needed base images into a private registry or pull through a cache."},{"f":0,"t":2,"l":"Verify","n":"Builds pull from the private registry and no longer depend on the public limit."}]},{"id":"f-cicd-bad-deploy","module":"cicd","kind":"failure","lesson":"cicd/deployment-strategies","title":"Failure and recovery: a bad release is caught by a canary","summary":"Small blast radius, fast rollback.","actors":["Pipeline","Canary","Monitoring","Operator"],"steps":[{"f":0,"t":1,"l":"Build and test","n":"The pipeline builds the release and all tests pass, so it is approved for production."},{"f":0,"t":1,"l":"Canary start","n":"Only five percent of traffic is routed to the new version while ninety five stays on the old one."},{"f":1,"t":2,"l":"Metrics flow","n":"The canary reports errors and latency, and monitoring compares them with the old version."},{"f":2,"t":0,"l":"Threshold breach","n":"The canary error rate is ten times higher than the baseline for three minutes in a row."},{"f":0,"t":1,"l":"Automatic abort","n":"The pipeline stops the rollout and sends all traffic back to the old version without waiting for a person."},{"f":3,"t":2,"l":"Investigate","n":"The operator reads the canary logs and finds a missing database column the new code expects."},{"f":3,"t":0,"l":"Fix forward","n":"A migration is added and tested, and a new release is built."},{"f":0,"t":1,"l":"Verify","n":"The next canary stays within thresholds, so the rollout moves from five percent to fifty and then to everyone."}]},{"id":"f-cicd-flaky-pipeline","module":"cicd","kind":"failure","lesson":"cicd/testing-and-quality-gates","title":"Failure and recovery: a flaky test erodes trust in the pipeline","summary":"Retries hide the problem, quarantine fixes it.","actors":["Developer","Pipeline","Test","Tracker"],"steps":[{"f":0,"t":1,"l":"Green most days","n":"The pipeline passes on most runs and developers merge without thinking about it."},{"f":1,"t":2,"l":"Random failure","n":"One test fails about one run in ten with a timing error that has nothing to do with the change."},{"f":0,"t":1,"l":"Rerun habit","n":"Developers press the rerun button until it passes and stop reading the failures."},{"f":1,"t":0,"l":"Cost","n":"Each rerun adds ten minutes, and a real failure is dismissed as just the flaky one."},{"f":3,"t":1,"l":"Measure","n":"A report of pass and fail by test over the last fifty runs shows which test is flaky."},{"f":3,"t":2,"l":"Quarantine","n":"The flaky test is moved to a separate non-blocking job with an owner and a due date."},{"f":3,"t":2,"l":"Fix","n":"The test waits for a condition instead of a fixed sleep, and its shared state is isolated."},{"f":1,"t":0,"l":"Restore","n":"The test returns to the blocking set and the failure rate is tracked to stay at zero."}]},{"id":"f-k8s-crashloop","module":"kubernetes","kind":"failure","lesson":"kubernetes/debugging-kubernetes-workloads","title":"Failure and recovery: a pod stuck in CrashLoopBackOff","summary":"Read the events and the previous logs.","actors":["Kubelet","Pod","API server","Operator"],"steps":[{"f":0,"t":1,"l":"Create","n":"A deployment rollout creates new pods with a changed config map reference."},{"f":1,"t":1,"l":"Start fails","n":"The container starts, the application exits with an error, and the kubelet records the exit code."},{"f":0,"t":1,"l":"Back off","n":"The kubelet restarts the container with growing delays, and the status becomes CrashLoopBackOff."},{"f":3,"t":2,"l":"Symptom","n":"kubectl get pods shows a growing restart count and the pod never becomes ready."},{"f":3,"t":2,"l":"Describe","n":"kubectl describe pod shows the last state, the exit code and events about back-off restarting."},{"f":3,"t":1,"l":"Previous logs","n":"kubectl logs with the previous flag shows the application complaining about a missing config key."},{"f":3,"t":2,"l":"Fix","n":"Correct the config map key, apply it, and roll the deployment so the pods pick it up."},{"f":2,"t":3,"l":"Verify","n":"Pods become ready, the restart count stays at zero, and the rollout reports successfully rolled out."}]},{"id":"f-k8s-service-no-endpoints","module":"kubernetes","kind":"failure","lesson":"kubernetes/services-and-ingress","title":"Failure and recovery: a Service has no endpoints","summary":"Selectors and labels must match.","actors":["Client","Service","Pods","Operator"],"steps":[{"f":0,"t":1,"l":"Working service","n":"A Service selects pods by the label app equals web and traffic reaches them."},{"f":3,"t":2,"l":"Relabel","n":"A change renames the pod label to app equals website but leaves the Service selector unchanged."},{"f":1,"t":2,"l":"Mismatch","n":"The Service now matches zero pods, so its list of endpoints becomes empty."},{"f":0,"t":1,"l":"Symptom","n":"Clients get connection refused or timeouts even though every pod is running and ready."},{"f":3,"t":1,"l":"Check endpoints","n":"kubectl get endpoints shows none for the Service, which points at the selector."},{"f":3,"t":1,"l":"Compare labels","n":"kubectl get pods with show-labels and the Service selector show different values."},{"f":3,"t":1,"l":"Fix","n":"Make the selector and pod labels match, and prefer one shared label set in a single template."},{"f":0,"t":1,"l":"Verify","n":"Endpoints list the pod addresses and requests reach the pods again."}]},{"id":"f-k8sops-etcd-quorum","module":"k8s-ops","kind":"failure","lesson":"k8s-ops/etcd-backup-and-restore","title":"Failure and recovery: etcd loses quorum","summary":"Restore from a snapshot, then bring members back.","actors":["Control plane","etcd","Backup","Operator"],"steps":[{"f":0,"t":1,"l":"Healthy cluster","n":"Three etcd members agree on every write and the API server answers quickly."},{"f":1,"t":1,"l":"Members fail","n":"Two of three members are lost together when a rack fails, and quorum needs two."},{"f":0,"t":1,"l":"Writes stop","n":"The API server cannot write, so kubectl commands time out and no new pods can be scheduled."},{"f":3,"t":0,"l":"Symptom","n":"Existing pods keep running, but nothing changes, and the API server logs say etcd is unavailable."},{"f":3,"t":2,"l":"Locate backup","n":"The operator finds the latest snapshot and checks its date and size."},{"f":3,"t":1,"l":"Restore","n":"A snapshot is restored into a new data directory and a fresh cluster of members is started from it."},{"f":3,"t":0,"l":"Rejoin","n":"The API servers point at the restored members and nodes reconnect."},{"f":3,"t":0,"l":"Verify","n":"kubectl shows the expected objects, the member list is healthy, and a new snapshot is taken."}]},{"id":"f-k8sops-upgrade-skew","module":"k8s-ops","kind":"failure","lesson":"k8s-ops/upgrading-clusters-safely","title":"Failure and recovery: an upgrade breaks workloads","summary":"Remove deprecated APIs before upgrading.","actors":["Operator","Control plane","Nodes","Workloads"],"steps":[{"f":0,"t":1,"l":"Plan","n":"The operator reads the release notes and plans a minor version upgrade, one version at a time."},{"f":0,"t":1,"l":"Upgrade control plane","n":"The control plane is upgraded first and starts serving the newer API version."},{"f":1,"t":3,"l":"Removed API","n":"A manifest uses an API version that was removed, so applying it now returns an error."},{"f":3,"t":0,"l":"Symptom","n":"A deployment pipeline fails to apply, and a controller using the old API stops reconciling."},{"f":0,"t":1,"l":"Find usages","n":"A scan of the manifests and the API server metrics lists clients still calling deprecated APIs."},{"f":0,"t":3,"l":"Fix","n":"Update the manifests to the supported API version and redeploy the affected workloads."},{"f":0,"t":2,"l":"Continue","n":"Nodes are drained and upgraded one at a time, with the drain respecting disruption budgets."},{"f":1,"t":3,"l":"Verify","n":"All nodes report the new version and every workload is ready."}]},{"id":"f-tf-state-lock","module":"terraform","kind":"failure","lesson":"terraform/state","title":"Failure and recovery: a stuck state lock blocks every plan","summary":"Unlock safely, only when no run is active.","actors":["Engineer","Terraform","State backend","Pipeline"],"steps":[{"f":0,"t":1,"l":"Normal run","n":"Terraform locks the remote state, plans, applies, and releases the lock."},{"f":1,"t":2,"l":"Crash","n":"The apply is interrupted when the runner is killed, so the lock is never released."},{"f":0,"t":1,"l":"Next plan","n":"An engineer runs plan and sees an error that the state is locked by another operation."},{"f":0,"t":3,"l":"Check","n":"The lock info shows a run id and a time, and the pipeline shows no active run."},{"f":0,"t":1,"l":"Confirm","n":"The engineer checks that no apply is really running before touching the lock."},{"f":0,"t":1,"l":"Unlock","n":"terraform force-unlock with the lock id releases it, and the person records why it was done."},{"f":0,"t":1,"l":"Plan again","n":"A new plan shows whether the interrupted apply left a partial change to review."},{"f":1,"t":2,"l":"Prevent","n":"Add a timeout and retries to the runner and keep applies in one serialised pipeline job."}]},{"id":"f-tf-drift","module":"terraform","kind":"failure","lesson":"terraform/workflows-and-drift","title":"Failure and recovery: a manual change causes drift","summary":"Plan finds it and code decides what is right.","actors":["Engineer","Console","Terraform","State"],"steps":[{"f":0,"t":1,"l":"In sync","n":"The code, the state and the real resources all agree and the plan shows no changes."},{"f":0,"t":1,"l":"Manual edit","n":"During an incident someone widens a security group rule in the console."},{"f":2,"t":3,"l":"Drift exists","n":"The real resource now differs from the state and from the code."},{"f":0,"t":2,"l":"Scheduled plan","n":"A nightly plan reports one change that would remove the new rule."},{"f":0,"t":1,"l":"Decide","n":"The team asks whether the manual change should stay or be removed."},{"f":0,"t":1,"l":"Keep","n":"If it should stay, update the code so it matches and run the plan to confirm no changes."},{"f":0,"t":1,"l":"Revert","n":"If not, apply to restore the declared value, and note it in the incident record."},{"f":0,"t":3,"l":"Prevent","n":"Restrict console edits and run the drift plan on a schedule with alerts."}]},{"id":"f-cloud-region-outage","module":"cloud","kind":"failure","lesson":"cloud/high-availability-and-disaster-recovery","title":"Failure and recovery: a region outage and a failover","summary":"Rehearsed failover turns a disaster into a drill.","actors":["User","DNS","Primary region","Standby region"],"steps":[{"f":0,"t":1,"l":"Normal","n":"Traffic goes through DNS to the primary region and the standby receives replicated data."},{"f":2,"t":2,"l":"Region fails","n":"A power and network failure makes the primary region unavailable to users."},{"f":3,"t":2,"l":"Health check","n":"Health checks from outside the region fail three times in a row."},{"f":1,"t":3,"l":"Failover","n":"DNS answers change to the standby region, or a traffic manager moves users, within the record's time to live."},{"f":3,"t":3,"l":"Promote data","n":"The standby database is promoted and the application config points at it."},{"f":0,"t":3,"l":"Users recover","n":"New requests succeed in the standby region after a short interruption."},{"f":3,"t":2,"l":"Failback","n":"When the primary is healthy again, data is synced back before traffic is moved in a quiet window."},{"f":3,"t":1,"l":"Review","n":"The measured recovery time is compared with the target and the runbook is updated."}]},{"id":"f-cloud-cost-spike","module":"cloud","kind":"failure","lesson":"cloud/managed-services-and-cost","title":"Failure and recovery: an unexpected cloud bill","summary":"Budgets and tags find the owner fast.","actors":["Budget alert","Cost report","Owner","Resource"],"steps":[{"f":0,"t":1,"l":"Normal spend","n":"Daily spend follows the usual pattern and stays below the monthly budget line."},{"f":3,"t":3,"l":"Runaway resource","n":"A test job leaves a large cluster running and a log bucket with no lifecycle rule grows daily."},{"f":0,"t":1,"l":"Alert","n":"A budget alert fires at eighty percent of the month on day twelve."},{"f":1,"t":2,"l":"Break down","n":"The cost report grouped by tag and service shows one project accounting for most of the rise."},{"f":2,"t":3,"l":"Owner confirms","n":"The tag points at the owner who confirms the cluster is not needed."},{"f":2,"t":3,"l":"Stop the cost","n":"The cluster is deleted and the bucket gets an expiry rule for old data."},{"f":1,"t":2,"l":"Prevent","n":"Tags become mandatory, budgets get alerts per team, and idle resources are reported weekly."},{"f":0,"t":1,"l":"Verify","n":"Daily spend returns to the normal line the next day."}]},{"id":"f-iam-access-denied","module":"cloud-iam","kind":"failure","lesson":"cloud-iam/debugging-access-denied-and-cloud-security-incidents","title":"Failure and recovery: debugging an AccessDenied error","summary":"Work out which layer said no.","actors":["Engineer","Identity","Policy engine","Resource"],"steps":[{"f":0,"t":3,"l":"Request","n":"A deployment role calls an action on a storage bucket and the call returns AccessDenied."},{"f":2,"t":3,"l":"Identity policy","n":"The engineer checks that the role's own policy allows the action on that exact resource."},{"f":2,"t":3,"l":"Resource policy","n":"The bucket policy has an explicit deny for requests that do not come through the private endpoint."},{"f":2,"t":3,"l":"Boundaries","n":"A permissions boundary or an organisation policy can also remove permissions, so they are checked too."},{"f":1,"t":2,"l":"Find the layer","n":"The decision log shows an explicit deny in the bucket policy, and an explicit deny always wins."},{"f":0,"t":2,"l":"Fix","n":"Route the call through the private endpoint, or update the policy condition for this role."},{"f":0,"t":3,"l":"Retry","n":"The same call now succeeds, and the change is made in code, not in the console."},{"f":1,"t":2,"l":"Keep least privilege","n":"The fix adds one condition and no wildcard, and the access review notes it."}]},{"id":"f-iam-leaked-key","module":"cloud-iam","kind":"failure","lesson":"cloud-iam/logging-detection-and-audit-trails","title":"Failure and recovery: a leaked access key","summary":"Revoke first, investigate second.","actors":["Attacker","Key","Audit log","Security team"],"steps":[{"f":0,"t":1,"l":"Key leaks","n":"A long-lived access key is pushed into a public repository by mistake."},{"f":0,"t":1,"l":"Abuse","n":"Within minutes, a bot uses the key to start large instances in many regions."},{"f":2,"t":3,"l":"Detection","n":"A usage anomaly alert and the audit log show unusual calls from an unknown address."},{"f":3,"t":1,"l":"Revoke","n":"The security team deactivates the key at once, before anything else is done."},{"f":3,"t":2,"l":"Investigate","n":"The audit log lists every call made with that key and the resources created."},{"f":3,"t":3,"l":"Clean up","n":"Unwanted resources are deleted, and any new credentials created by the attacker are removed."},{"f":3,"t":1,"l":"Replace","n":"The workload moves to short-lived role credentials so there is no long-lived key to leak."},{"f":3,"t":2,"l":"Prevent","n":"Secret scanning, least-privilege roles and cost alerts shorten the time to notice next time."}]},{"id":"f-obs-alert-storm","module":"observability","kind":"failure","lesson":"observability/alerting-and-dashboards","title":"Failure and recovery: an alert storm buries the real problem","summary":"Group and route so one cause is one page.","actors":["Service","Alertmanager","On-call","Dashboard"],"steps":[{"f":0,"t":1,"l":"One root cause","n":"A database slows down and fifty services that depend on it start timing out."},{"f":1,"t":2,"l":"Fifty alerts","n":"Each service fires its own alert and the on-call phone receives fifty pages in two minutes."},{"f":2,"t":2,"l":"Overwhelm","n":"The responder cannot tell which alert is the cause and which are the effects."},{"f":2,"t":3,"l":"Group","n":"Alerts are grouped by cluster and dependency so a single message shows the common cause."},{"f":2,"t":3,"l":"Inhibit","n":"A rule suppresses the downstream alerts while the database alert is firing."},{"f":2,"t":3,"l":"Find cause","n":"The dashboard for the database shows slow queries and connection saturation."},{"f":2,"t":1,"l":"Fix","n":"Raise the pool and kill the long query, and services recover without any change to the services."},{"f":1,"t":2,"l":"Verify","n":"Alerts resolve in order, the page count is one, and the rules are kept for the next time."}]},{"id":"f-obs-high-cardinality","module":"observability","kind":"failure","lesson":"observability/telemetry-cost-and-cardinality","title":"Failure and recovery: high cardinality crashes the metrics server","summary":"One label can create millions of series.","actors":["Application","Prometheus","Dashboard","Engineer"],"steps":[{"f":0,"t":1,"l":"Normal metrics","n":"A request counter carries labels for method and status code, giving a few dozen series."},{"f":0,"t":1,"l":"New label","n":"A change adds the user id as a label so that debugging a single user is easier."},{"f":1,"t":1,"l":"Series explode","n":"Every user becomes a new series, and memory use climbs with each scrape."},{"f":2,"t":3,"l":"Symptom","n":"Dashboards slow down, queries time out, and the server is killed for running out of memory."},{"f":3,"t":1,"l":"Find it","n":"A query for the series count by metric name shows one metric with millions of series."},{"f":3,"t":0,"l":"Remove","n":"The label is dropped in code and relabelling drops it at scrape time right away."},{"f":3,"t":1,"l":"Keep detail","n":"Per-user data goes to logs or traces, which are built for high cardinality."},{"f":1,"t":2,"l":"Prevent","n":"A limit on series per target and a review check on new labels stop it next time."}]},{"id":"f-sre-error-budget","module":"sre","kind":"failure","lesson":"sre/slos-and-error-budgets","title":"Failure and recovery: the error budget runs out","summary":"Reliability work takes priority.","actors":["Service","SLO tracker","Product team","SRE"],"steps":[{"f":0,"t":1,"l":"Budget set","n":"A ninety nine point nine percent target gives the service forty three minutes of errors per month."},{"f":0,"t":1,"l":"Bad release","n":"A release causes errors for thirty minutes and a second incident adds fifteen more."},{"f":1,"t":1,"l":"Budget gone","n":"The tracker shows the monthly budget fully used on day nineteen, with eleven days still to go."},{"f":1,"t":2,"l":"Policy","n":"The agreed policy says feature releases pause and reliability work comes first until the budget recovers."},{"f":3,"t":2,"l":"Review","n":"The SRE and product team list the causes and choose the fixes that remove the most risk."},{"f":2,"t":0,"l":"Fix","n":"Add a canary step, a rollback test, and a timeout fix for the slow dependency."},{"f":2,"t":3,"l":"Resume","n":"Releases restart when the rolling window shows budget back, with the new checks in place."},{"f":1,"t":2,"l":"Verify","n":"The next month ends with budget left and fewer pages."}]},{"id":"f-sre-bad-change","module":"sre","kind":"failure","lesson":"sre/incident-response","title":"Failure and recovery: a bad change during an incident","summary":"Recent changes are the first suspect.","actors":["Responder","Change log","Service","Incident lead"],"steps":[{"f":0,"t":1,"l":"Alert","n":"Error rates rise at 10:02 and the responder starts an incident."},{"f":3,"t":0,"l":"Roles","n":"The incident lead assigns a responder, a communicator and a note taker."},{"f":0,"t":1,"l":"Ask what changed","n":"The change log shows a config rollout at 10:00 to the same service."},{"f":0,"t":2,"l":"Hypothesis","n":"The rollout is the leading suspect because the timing and the affected service match."},{"f":0,"t":2,"l":"Mitigate","n":"Roll back the config first, since a rollback is quicker and safer than diagnosing under pressure."},{"f":2,"t":0,"l":"Recovery","n":"Error rates fall within three minutes, which confirms the hypothesis."},{"f":3,"t":0,"l":"Follow up","n":"The team writes down the timeline, and the cause is found later in calm conditions."},{"f":3,"t":1,"l":"Improve","n":"Staged rollouts and an automatic rollback on error spikes become action items."}]},{"id":"f-sec-ransomware","module":"security","kind":"failure","lesson":"security/ransomware-resilience-and-recovery","title":"Failure and recovery: ransomware and a clean restore","summary":"Immutable backups decide the outcome.","actors":["Attacker","Servers","Backups","Response team"],"steps":[{"f":0,"t":1,"l":"Foothold","n":"A stolen password for a remote access account gives the attacker a way into the network."},{"f":0,"t":1,"l":"Spread","n":"The attacker moves between servers and gains an administrator account."},{"f":0,"t":2,"l":"Backups targeted","n":"The attacker tries to delete backups, but the immutable copies cannot be changed before their retention date."},{"f":0,"t":1,"l":"Encrypt","n":"Files are encrypted and a ransom note appears on the servers."},{"f":3,"t":1,"l":"Contain","n":"The response team isolates affected network segments and disables the stolen accounts."},{"f":3,"t":2,"l":"Restore","n":"Clean systems are rebuilt from known good images and data is restored from the immutable backup."},{"f":3,"t":1,"l":"Harden","n":"Multi-factor authentication, network segmentation and tested restore times are put in place."},{"f":3,"t":2,"l":"Review","n":"The timeline and gaps become action items, and the restore time is compared with the target."}]},{"id":"f-sec-vuln-patch","module":"security","kind":"failure","lesson":"security/vulnerability-management-and-security-incidents","title":"Failure and recovery: a critical vulnerability is announced","summary":"Know where it runs, then patch by priority.","actors":["Advisory","Inventory","Team","Pipeline"],"steps":[{"f":0,"t":1,"l":"Advisory","n":"A critical flaw is announced in a widely used library, with a fix released the same day."},{"f":1,"t":2,"l":"Find usage","n":"The software inventory lists every service and image that includes the vulnerable version."},{"f":2,"t":2,"l":"Prioritise","n":"Internet-facing services go first, then internal ones, and unused images are removed."},{"f":2,"t":3,"l":"Patch","n":"The dependency is updated and the pipeline rebuilds and tests each affected service."},{"f":3,"t":1,"l":"Deploy","n":"Fixed versions are rolled out in stages, with the same checks as any release."},{"f":1,"t":2,"l":"Verify","n":"A rescan shows no remaining vulnerable versions in running workloads."},{"f":2,"t":0,"l":"Communicate","n":"The team records what was affected, when it was fixed and what monitoring watched meanwhile."},{"f":1,"t":2,"l":"Improve","n":"An automatic dependency update and a scan on every build cut the time next time."}]},{"id":"f-ans-partial-failure","module":"ansible","kind":"failure","lesson":"ansible/playbooks-tasks-and-idempotence","title":"Failure and recovery: a playbook fails halfway across a fleet","summary":"Idempotent tasks make re-running safe.","actors":["Operator","Ansible","Hosts","Load balancer"],"steps":[{"f":0,"t":1,"l":"Run","n":"The operator runs a playbook that updates the configuration on twenty web servers."},{"f":1,"t":2,"l":"Rolling batch","n":"Without a batch limit, all hosts restart their service at nearly the same moment."},{"f":2,"t":2,"l":"Error","n":"A template contains a typo, and the service fails to start on every host that applied it."},{"f":2,"t":3,"l":"Outage","n":"The load balancer sees every back end as unhealthy and the site is down."},{"f":0,"t":1,"l":"Stop","n":"The operator stops the play and uses the previous config from version control to restore service."},{"f":0,"t":1,"l":"Fix","n":"Correct the template, run a syntax check, and use check mode with diff before applying."},{"f":0,"t":1,"l":"Re-run","n":"Idempotent tasks skip hosts that are already correct and only change what is still wrong."},{"f":1,"t":3,"l":"Prevent","n":"Use serial batches and a failure threshold so one bad host stops the run early."}]},{"id":"f-ans-vault-password","module":"ansible","kind":"failure","lesson":"ansible/vault-secrets-and-safe-practice","title":"Failure and recovery: a lost Vault password","summary":"Plan secret recovery before you need it.","actors":["Operator","Vault file","Secret store","Playbook"],"steps":[{"f":0,"t":1,"l":"Encrypted vars","n":"Secrets for the playbooks are stored in an encrypted vault file."},{"f":0,"t":1,"l":"Password gone","n":"The one engineer who knew the vault password leaves and the password was only on their laptop."},{"f":3,"t":1,"l":"Failure","n":"The playbook cannot decrypt the file and every deploy fails with a decryption error."},{"f":0,"t":2,"l":"Look for copies","n":"The team checks the secret store and the pipeline for a stored copy of the password."},{"f":0,"t":2,"l":"Recover","n":"If a copy exists, it is used to re-key the vault with a new password stored in the secret store."},{"f":0,"t":1,"l":"Last resort","n":"If none exists, every secret in the file must be rotated at its source and the file recreated."},{"f":0,"t":1,"l":"Prevent","n":"The password is held in the shared secret manager with two named owners and an access log."},{"f":3,"t":0,"l":"Verify","n":"A fresh clone of the repository decrypts and runs in the pipeline using the stored password."}]},{"id":"f-db-replica-lag","module":"databases","kind":"failure","lesson":"databases/replication-and-failover","title":"Failure and recovery: replica lag serves stale data","summary":"Reads from a replica can be behind.","actors":["Application","Primary","Replica","Operator"],"steps":[{"f":0,"t":1,"l":"Normal","n":"The application writes to the primary and reads from a replica a few milliseconds behind."},{"f":0,"t":1,"l":"Heavy write","n":"A bulk update runs on the primary and produces a large amount of change data quickly."},{"f":1,"t":2,"l":"Lag grows","n":"The replica applies changes more slowly and falls minutes behind."},{"f":0,"t":2,"l":"Symptom","n":"Users save a change and then see the old value, and support calls say it did not save."},{"f":3,"t":2,"l":"Measure","n":"The replica lag metric and replication status show the delay and the slow apply thread."},{"f":3,"t":1,"l":"Mitigate","n":"Send reads that must see the latest write to the primary and pause the bulk job."},{"f":3,"t":1,"l":"Fix","n":"Break the job into small batches and give the replica more resources for applying changes."},{"f":0,"t":2,"l":"Verify","n":"Lag stays under a second during the next bulk job and read-your-write cases work."}]},{"id":"f-db-long-transaction","module":"databases","kind":"failure","lesson":"databases/transactions-and-locking","title":"Failure and recovery: a long transaction blocks the table","summary":"One idle transaction can stall writers.","actors":["Session A","Session B","Lock manager","DBA"],"steps":[{"f":0,"t":1,"l":"Open transaction","n":"A tool opens a transaction, updates a row and then sits idle without committing."},{"f":0,"t":2,"l":"Lock held","n":"The row lock stays held for as long as the transaction is open."},{"f":1,"t":2,"l":"Others wait","n":"Another session tries to update the same row and waits in the lock queue."},{"f":1,"t":3,"l":"Pile up","n":"More sessions queue behind it and the connection pool fills with waiting requests."},{"f":3,"t":2,"l":"Find blocker","n":"The DBA queries the lock views and finds the idle transaction at the head of the chain."},{"f":3,"t":0,"l":"Resolve","n":"The blocking session is ended, which rolls it back and releases the lock."},{"f":3,"t":1,"l":"Fix the cause","n":"Set an idle in transaction timeout and make the tool commit or roll back promptly."},{"f":3,"t":2,"l":"Verify","n":"The queue clears, requests complete, and the lock wait graph is empty."}]},{"id":"f-go-goroutine-leak","module":"go","kind":"failure","lesson":"go/context-timeouts-and-cancellation","title":"Failure and recovery: a goroutine leak grows memory","summary":"Every goroutine needs a way to stop.","actors":["Handler","Goroutine","Channel","Profiler"],"steps":[{"f":0,"t":1,"l":"Request","n":"Each request starts a goroutine that sends its result on an unbuffered channel."},{"f":0,"t":1,"l":"Early return","n":"The handler times out and returns before it reads from the channel."},{"f":1,"t":2,"l":"Blocked forever","n":"The goroutine waits to send and nothing will ever receive, so it never exits."},{"f":3,"t":1,"l":"Growth","n":"Memory and the goroutine count climb with every timed-out request until the pod is killed."},{"f":3,"t":0,"l":"Diagnose","n":"A goroutine profile shows thousands stuck at the same channel send line."},{"f":0,"t":1,"l":"Fix","n":"Pass a context, use a buffered channel or select on the context so the goroutine can stop."},{"f":0,"t":1,"l":"Test","n":"A test checks that the goroutine count returns to its starting value after a timeout."},{"f":3,"t":0,"l":"Verify","n":"The goroutine count stays flat under load and the pod no longer restarts."}]},{"id":"f-go-nil-map","module":"go","kind":"failure","lesson":"go/functions-errors-and-defer","title":"Failure and recovery: a nil map write panics a service","summary":"A panic should not take down everything.","actors":["Request","Handler","Recover","Logs"],"steps":[{"f":0,"t":1,"l":"Request","n":"A handler builds a response using a map declared with var and never created."},{"f":1,"t":1,"l":"Write","n":"The handler writes a key to the nil map, and Go raises a panic."},{"f":1,"t":0,"l":"Crash","n":"With no recovery, the panic ends the whole process and every in-flight request fails."},{"f":3,"t":0,"l":"Symptom","n":"The service restarts, and the logs show a stack trace pointing at the map assignment."},{"f":3,"t":1,"l":"Find it","n":"The stack trace names the file and line, and the map was never initialised with make."},{"f":1,"t":1,"l":"Fix","n":"Create the map with make before writing to it, or return an error when input is missing."},{"f":1,"t":2,"l":"Contain","n":"A recover in middleware turns an unexpected panic into a 500 response and a logged stack."},{"f":3,"t":0,"l":"Verify","n":"A test with empty input passes, and the service stays up under the same request."}]},{"id":"f-helm-failed-upgrade","module":"helm","kind":"failure","lesson":"helm/upgrade-rollback-and-release-history","title":"Failure and recovery: a failed Helm upgrade and rollback","summary":"The release history is your safety net.","actors":["Operator","Helm","Cluster","Release history"],"steps":[{"f":0,"t":1,"l":"Upgrade","n":"The operator runs helm upgrade with a new image tag and a changed values file."},{"f":1,"t":2,"l":"Apply","n":"Helm renders the templates and applies the changes, and the new pods fail their readiness probe."},{"f":1,"t":3,"l":"Failed status","n":"The release is marked failed and the old pods are still serving because of the rolling update."},{"f":0,"t":1,"l":"Look","n":"helm status and helm history show the failed revision and the last good revision."},{"f":0,"t":2,"l":"Find cause","n":"kubectl describe on the pods shows the readiness probe path changed in the new chart version."},{"f":0,"t":1,"l":"Roll back","n":"helm rollback to the last good revision restores the previous manifests as a new revision."},{"f":0,"t":1,"l":"Fix the chart","n":"Correct the probe path, test with helm template and a dry run, then upgrade again."},{"f":1,"t":2,"l":"Prevent","n":"Use atomic with a timeout so a failed upgrade rolls back automatically."}]},{"id":"f-helm-values-typo","module":"helm","kind":"failure","lesson":"helm/values-per-environment-and-secrets","title":"Failure and recovery: a values typo is silently ignored","summary":"Schema validation catches mistakes early.","actors":["Engineer","Values file","Chart","Cluster"],"steps":[{"f":0,"t":1,"l":"Set a value","n":"The engineer sets replicaCont instead of replicaCount in the production values file."},{"f":1,"t":2,"l":"Render","n":"The chart does not know that key, so it ignores it and uses the default of one replica."},{"f":2,"t":3,"l":"Deploy","n":"The release succeeds, so there is no error message to warn anyone."},{"f":3,"t":0,"l":"Symptom","n":"Under load the service has one pod and falls over, while the values file looks right."},{"f":0,"t":2,"l":"Compare","n":"helm get values and helm template show the rendered replica count is one."},{"f":0,"t":1,"l":"Fix","n":"Correct the key, and add a values schema file so unknown keys fail at install time."},{"f":0,"t":2,"l":"Review","n":"A diff check between rendered environments is added to the pipeline."},{"f":3,"t":2,"l":"Verify","n":"The release shows the expected replicas and a bad key now fails with a clear message."}]},{"id":"f-argo-outofsync-loop","module":"argocd","kind":"failure","lesson":"argocd/sync-health-and-drift","title":"Failure and recovery: Argo CD syncs and then flips back","summary":"Two controllers fight over one field.","actors":["Repository","Argo CD","Cluster","Autoscaler"],"steps":[{"f":0,"t":1,"l":"Desired state","n":"The repository says replicas is two and Argo CD syncs it to the cluster."},{"f":3,"t":2,"l":"Autoscaler acts","n":"The horizontal autoscaler changes replicas to five because of load."},{"f":1,"t":2,"l":"Drift seen","n":"Argo CD compares and marks the application OutOfSync because replicas differs."},{"f":1,"t":2,"l":"Self-heal","n":"With self-heal on, Argo CD sets replicas back to two and the autoscaler sets it to five again."},{"f":1,"t":0,"l":"Loop","n":"The application flips between the two states and the history fills with syncs."},{"f":0,"t":1,"l":"Diagnose","n":"The diff shows only the replicas field, which points at two owners for one field."},{"f":0,"t":1,"l":"Fix","n":"Remove replicas from the manifest, or tell Argo CD to ignore that field in the application."},{"f":1,"t":2,"l":"Verify","n":"The application stays Synced and Healthy while the autoscaler changes the count."}]},{"id":"f-argo-bad-sync-rollback","module":"argocd","kind":"failure","lesson":"argocd/debugging-argo-cd","title":"Failure and recovery: a bad commit reaches the cluster","summary":"Revert in the repository, not in the cluster.","actors":["Developer","Repository","Argo CD","Cluster"],"steps":[{"f":0,"t":1,"l":"Merge","n":"A change with a wrong image tag is merged to the main branch of the config repository."},{"f":1,"t":2,"l":"Auto sync","n":"Argo CD sees the new commit and applies it to the cluster within minutes."},{"f":2,"t":3,"l":"Degraded","n":"The pods cannot pull the image and the application becomes Degraded."},{"f":2,"t":0,"l":"Alert","n":"An alert shows the health status and the sync revision that caused it."},{"f":0,"t":1,"l":"Revert","n":"The developer reverts the commit in the repository, which keeps the history honest."},{"f":1,"t":2,"l":"Resync","n":"Argo CD syncs the reverted state and the old pods become the desired state again."},{"f":2,"t":3,"l":"Healthy","n":"Pods run, the application shows Synced and Healthy, and traffic is normal."},{"f":0,"t":1,"l":"Prevent","n":"A required review and a preview environment catch a bad tag before it is merged."}]},{"id":"f-llm-context-overflow","module":"llm","kind":"failure","lesson":"llm/tokens-context-windows-and-limits","title":"Failure and recovery: the prompt overflows the context window","summary":"Long input is cut or rejected.","actors":["User","Application","Model","Logs"],"steps":[{"f":0,"t":1,"l":"Short chats","n":"Early conversations fit easily in the model context window and answers are accurate."},{"f":0,"t":1,"l":"Long chat","n":"A long conversation with pasted documents grows past the window limit."},{"f":1,"t":2,"l":"Truncation","n":"The application silently drops the oldest messages to make the request fit."},{"f":2,"t":0,"l":"Symptom","n":"The model forgets earlier instructions and answers as if they were never given."},{"f":3,"t":1,"l":"Diagnose","n":"Logs of token counts show the request was trimmed and the system instructions were among the dropped parts."},{"f":1,"t":1,"l":"Fix","n":"Keep instructions pinned, summarise older turns, and retrieve only the relevant document parts."},{"f":1,"t":2,"l":"Guard","n":"Count tokens before sending and warn or compact when the request nears the limit."},{"f":0,"t":1,"l":"Verify","n":"A long conversation test keeps following the original instructions to the end."}]},{"id":"f-llm-hallucinated-answer","module":"llm","kind":"failure","lesson":"llm/debugging-llm-applications","title":"Failure and recovery: a confident wrong answer","summary":"Ground answers in sources and check them.","actors":["User","Application","Model","Knowledge base"],"steps":[{"f":0,"t":1,"l":"Question","n":"A user asks about an internal policy that the model was never trained on."},{"f":1,"t":2,"l":"No context","n":"The application sends the question without any policy text."},{"f":2,"t":1,"l":"Guess","n":"The model produces a fluent, specific answer that is not true."},{"f":1,"t":0,"l":"Impact","n":"The user follows the wrong guidance, and the error is only noticed later."},{"f":3,"t":1,"l":"Diagnose","n":"Reviewing the prompt shows there was no source text, so the answer could not have been grounded."},{"f":1,"t":3,"l":"Fix","n":"Retrieve the relevant policy passages and instruct the model to answer only from them and to say when unsure."},{"f":1,"t":0,"l":"Show sources","n":"The answer cites the passages so a user can check them."},{"f":3,"t":1,"l":"Evaluate","n":"A test set of questions with known answers measures how often the system now cites correctly."}]},{"id":"f-prompt-format-drift","module":"prompting","kind":"failure","lesson":"prompting/validating-repairing-and-retrying-outputs","title":"Failure and recovery: the model stops returning valid JSON","summary":"Validate, repair, and retry.","actors":["Application","Model","Validator","Logs"],"steps":[{"f":0,"t":1,"l":"Works","n":"A prompt asks for JSON and the model has returned valid JSON in every test."},{"f":1,"t":2,"l":"Slight change","n":"The model adds a short sentence before the JSON on some responses."},{"f":2,"t":0,"l":"Parse error","n":"The application's JSON parser fails and the request returns a server error."},{"f":3,"t":0,"l":"Symptom","n":"An error rate of a few percent appears with no code change on the application side."},{"f":3,"t":2,"l":"Diagnose","n":"Logged raw outputs show the extra text and a trailing comma in a few cases."},{"f":0,"t":2,"l":"Repair","n":"Use structured output with a schema, validate every response, and retry once with the error message."},{"f":2,"t":3,"l":"Fallback","n":"If it still fails, return a clear error or a safe default and log the sample."},{"f":3,"t":0,"l":"Verify","n":"The error rate returns to near zero, and failures are visible in a dashboard."}]},{"id":"f-prompt-regression","module":"prompting","kind":"failure","lesson":"prompting/prompt-versioning-and-testing","title":"Failure and recovery: a prompt edit breaks a working case","summary":"Test prompts like code.","actors":["Author","Prompt","Test set","Reviewer"],"steps":[{"f":0,"t":1,"l":"Improve","n":"An author rewrites a prompt to fix one complaint and sees that example improve."},{"f":1,"t":2,"l":"No tests","n":"There is no test set, so no one checks the other twenty common cases."},{"f":1,"t":0,"l":"Release","n":"The new prompt goes live and handles the complaint well."},{"f":3,"t":0,"l":"Symptom","n":"A week later, support finds that refund requests are now answered in the wrong format."},{"f":3,"t":1,"l":"Find the change","n":"Prompt version history shows the edit and the date that matches the first bad answer."},{"f":0,"t":2,"l":"Fix","n":"Revert to the previous version and build a test set from real cases that includes the complaint."},{"f":2,"t":3,"l":"Gate","n":"Every prompt change runs the test set and the reviewer sees what got better and what got worse."},{"f":0,"t":1,"l":"Verify","n":"The next edit passes all cases, with the previous failure now a permanent test."}]},{"id":"f-skill-never-triggers","module":"claude-skills","kind":"failure","lesson":"claude-skills/writing-descriptions-that-trigger","title":"Failure and recovery: a skill never triggers","summary":"The description decides when it loads.","actors":["User","Claude","Skill","Author"],"steps":[{"f":0,"t":1,"l":"Request","n":"A user asks for a task that the skill was written to handle."},{"f":1,"t":2,"l":"Match","n":"Claude reads the skill descriptions and the description is vague, so it does not match the request."},{"f":1,"t":0,"l":"Skipped","n":"Claude answers without the skill and the output ignores the team conventions."},{"f":3,"t":0,"l":"Symptom","n":"The author expects the skill to run, yet the transcript shows it was never loaded."},{"f":3,"t":2,"l":"Diagnose","n":"Comparing the description with real requests shows missing words that users actually use."},{"f":3,"t":2,"l":"Fix","n":"Rewrite the description to say what it does and when to use it, with the trigger phrases."},{"f":3,"t":1,"l":"Test","n":"Try ten phrasings, including ones that should not trigger, and record which load the skill."},{"f":0,"t":1,"l":"Verify","n":"The skill loads on the right requests and stays quiet on the others."}]},{"id":"f-skill-overbroad","module":"claude-skills","kind":"failure","lesson":"claude-skills/debugging-skills-that-do-not-trigger-or-misbehave","title":"Failure and recovery: an overbroad skill triggers on everything","summary":"Narrow scope and add a boundary.","actors":["User","Claude","Skill","Author"],"steps":[{"f":0,"t":1,"l":"Install","n":"A skill for writing release notes is installed with a short generic description."},{"f":0,"t":1,"l":"Unrelated ask","n":"A user asks for a meeting summary and the skill loads anyway."},{"f":1,"t":2,"l":"Wrong format","n":"The skill's template makes the summary read like release notes."},{"f":2,"t":0,"l":"Symptom","n":"Users complain that unrelated answers now follow a strange structure."},{"f":3,"t":1,"l":"Diagnose","n":"The description says documents and writing, which matches almost any request."},{"f":3,"t":2,"l":"Fix","n":"Narrow the description to release notes for software changes and add when not to use it."},{"f":3,"t":1,"l":"Test","n":"Run requests that should and should not trigger and check each outcome."},{"f":0,"t":1,"l":"Verify","n":"Meeting summaries are normal again and release notes use the template."}]},{"id":"f-mcp-tool-timeout","module":"mcp","kind":"failure","lesson":"mcp/debugging-tool-use-and-mcp","title":"Failure and recovery: a tool call times out","summary":"Bound the wait and report clearly.","actors":["Agent","Host","MCP server","Backend"],"steps":[{"f":0,"t":1,"l":"Call","n":"The agent asks the host to call a search tool provided by an MCP server."},{"f":1,"t":2,"l":"Forward","n":"The host forwards the request to the server, which queries a slow backend."},{"f":2,"t":3,"l":"Backend hangs","n":"The backend takes much longer than expected and the server keeps waiting."},{"f":1,"t":0,"l":"Timeout","n":"The host reaches its time limit and returns an error to the agent."},{"f":0,"t":1,"l":"Agent reacts","n":"A good agent reports the failure and tries a smaller query, while a bad one repeats the call forever."},{"f":3,"t":2,"l":"Diagnose","n":"Server logs with a request id show the backend latency and where time was spent."},{"f":2,"t":3,"l":"Fix","n":"Add a timeout and a limit on results in the server, and a clear error message the model can use."},{"f":0,"t":1,"l":"Verify","n":"The agent recovers within its retry limit and gives the user an honest answer."}]},{"id":"f-mcp-prompt-injection","module":"mcp","kind":"failure","lesson":"mcp/permissions-auth-and-prompt-injection-defence","title":"Failure and recovery: a tool result tries to give orders","summary":"Treat tool output as data, not instructions.","actors":["User","Agent","Tool","Policy"],"steps":[{"f":0,"t":1,"l":"Task","n":"A user asks the agent to summarise a web page using a fetch tool."},{"f":1,"t":2,"l":"Fetch","n":"The tool returns the page text, and it contains hidden text telling the assistant to send private data away."},{"f":2,"t":1,"l":"Injection","n":"The text looks like an instruction and the model may follow it as if the user had written it."},{"f":3,"t":1,"l":"Block","n":"A policy layer denies any call to a send tool that the user did not request."},{"f":1,"t":0,"l":"Ask","n":"The agent shows the user what the page asked for and asks whether to proceed."},{"f":3,"t":1,"l":"Contain","n":"Tool output is marked as untrusted content, and tools run with the minimum permissions."},{"f":3,"t":2,"l":"Log","n":"The attempt is logged with the source address so the page can be reported."},{"f":0,"t":1,"l":"Verify","n":"A test page with hidden commands is now ignored and the summary stays accurate."}]},{"id":"sd-design-method","module":"system-design","lesson":"system-design/the-design-method-and-estimation","title":"The design method in order","summary":"Clarify, estimate, sketch, deep-dive, break it, state the trade-offs.","actors":["Designer","Requirements","Numbers","Design"],"steps":[{"f":0,"t":1,"l":"Clarify","n":"Ask who uses the system, what must never be wrong, and what the availability target is, before drawing anything."},{"f":1,"t":0,"l":"SLO and constraints","n":"The answer might be 99.99 percent with no duplicate payments and reads that may be five seconds stale."},{"f":0,"t":2,"l":"Estimate","n":"Convert users and behaviour into requests per second, storage and bandwidth using round numbers and a 3x peak factor."},{"f":2,"t":0,"l":"Which number crosses a limit?","n":"Find the figure that passes a threshold, such as one node capacity, because that is where the design must change."},{"f":0,"t":3,"l":"Sketch","n":"Draw the smallest design that meets the numbers: entry point, services, data store, queue where needed."},{"f":0,"t":3,"l":"Deep-dive the risk","n":"Design the data store, the rollout and the failover path properly, since that is where the risk sits."},{"f":0,"t":3,"l":"Walk the failure modes","n":"For each box ask what happens when it is slow, down, wrong or overloaded, and record the answer."},{"f":0,"t":1,"l":"State the trade-offs","n":"Say what the design gives up, such as cost or latency, so reviewers can challenge the choice."}]},{"id":"sd-cache-stampede","module":"system-design","lesson":"system-design/caching-without-stampedes","title":"A cache stampede and its defence","summary":"Many misses on one key, and how coalescing stops them.","actors":["Clients","Cache","Coalescer","Database"],"steps":[{"f":0,"t":1,"l":"GET popular-key","n":"Thousands of requests read a hot key from the cache and get fast answers."},{"f":1,"t":1,"l":"TTL expires","n":"The key reaches its expiry time and is removed from the cache."},{"f":0,"t":1,"l":"Burst of misses","n":"Many requests arrive at the same moment and all find nothing in the cache."},{"f":1,"t":2,"l":"Ask to refill","n":"Without coalescing every request would go to the database; with it they are handed to one refill."},{"f":2,"t":3,"l":"One query","n":"Only the first request queries the database for the row while the others wait for its result."},{"f":3,"t":2,"l":"Row returned","n":"The database answers once, so its load stays flat instead of spiking."},{"f":2,"t":1,"l":"Fill cache with jittered TTL","n":"The value is stored with a randomised TTL so related keys do not all expire together next time."},{"f":1,"t":0,"l":"Everyone gets the value","n":"Waiting requests are answered from the freshly filled cache."}]},{"id":"sd-retry-idempotency","module":"system-design","lesson":"system-design/queues-retries-and-idempotency","title":"A retry that does not charge twice","summary":"Timeout, backoff with jitter and an idempotency key.","actors":["Client","API","Payment store"],"steps":[{"f":0,"t":1,"l":"POST /charge with key K1","n":"The client sends the request with a unique idempotency key generated for this operation."},{"f":1,"t":2,"l":"Charge and store K1","n":"The server applies the charge and records key K1 with the result in the same transaction."},{"f":1,"t":0,"l":"Response lost","n":"The response is lost on the network, so the client sees a timeout and does not know if it worked."},{"f":0,"t":0,"l":"Wait with backoff and jitter","n":"The client waits a randomised, growing delay so many clients do not retry at the same moment."},{"f":0,"t":1,"l":"Retry with key K1","n":"The client repeats the same request with the same key."},{"f":1,"t":2,"l":"Look up K1","n":"The server finds the key already recorded and does not charge again."},{"f":1,"t":0,"l":"Return stored result","n":"The client receives the original result, and the customer is charged exactly once."}]},{"id":"sd-replication-lag","module":"system-design","lesson":"system-design/consistency-and-availability-in-practice","title":"A stale read after a write","summary":"Replication lag and read-your-writes.","actors":["User","App","Primary","Replica"],"steps":[{"f":0,"t":1,"l":"Save profile","n":"The user changes their email address and submits the form."},{"f":1,"t":2,"l":"Write to primary","n":"The application writes the change to the primary database, which confirms it."},{"f":2,"t":3,"l":"Replicate (async)","n":"The primary sends the change to the replica, which takes a little time to apply it."},{"f":0,"t":1,"l":"Reload page","n":"The user reloads the page a moment later and the application chooses a replica for the read."},{"f":1,"t":3,"l":"Read from replica","n":"The replica has not yet applied the change, so it returns the old email address."},{"f":1,"t":2,"l":"Fix: read primary after write","n":"For a short window after a write the application reads from the primary, or waits for a version token."},{"f":2,"t":0,"l":"Fresh data shown","n":"The user sees their own change, which is the read-your-writes guarantee."}]},{"id":"sd-leader-election","module":"system-design","lesson":"system-design/quorum-leaders-and-split-brain","title":"Leader election with a quorum","summary":"How followers elect a new leader after the old one stops.","actors":["Leader","Follower A","Follower B"],"steps":[{"f":0,"t":1,"l":"Heartbeat","n":"The leader sends regular heartbeats to its followers to show it is alive."},{"f":0,"t":0,"l":"Leader stops","n":"The leader crashes or is cut off, and heartbeats stop arriving."},{"f":1,"t":1,"l":"Timeout fires first","n":"Follower A has a randomised election timeout and is the first to notice the silence."},{"f":1,"t":2,"l":"Request vote, term 2","n":"Follower A becomes a candidate for a new term and asks the others for votes."},{"f":2,"t":1,"l":"Vote granted","n":"Follower B has not voted in this term and grants its vote."},{"f":1,"t":1,"l":"Majority reached","n":"Two of three is a majority, so Follower A becomes leader without needing the old leader."},{"f":1,"t":2,"l":"Heartbeat, term 2","n":"The new leader announces itself; any message from the old term will now be rejected."}]},{"id":"sd-fencing","module":"system-design","lesson":"system-design/quorum-leaders-and-split-brain","title":"Fencing stops a stale leader","summary":"A paused leader wakes up and is rejected by the resource.","actors":["Old leader","Lock service","New leader","Storage"],"steps":[{"f":0,"t":1,"l":"Acquire lock, token 33","n":"The first leader gets the lock and a fencing token of 33."},{"f":0,"t":0,"l":"Long pause","n":"The process freezes in a garbage collection or a VM pause and cannot renew its lease."},{"f":1,"t":2,"l":"Lease expires, token 34","n":"The lock service gives the lock to a new leader with the higher token 34."},{"f":2,"t":3,"l":"Write with token 34","n":"The new leader writes to storage, which records that it has seen token 34."},{"f":0,"t":0,"l":"Wakes up","n":"The old leader resumes and still believes that it holds the lock."},{"f":0,"t":3,"l":"Write with token 33","n":"The old leader attempts to write using its stale token."},{"f":3,"t":0,"l":"Rejected: 33 is lower than 34","n":"Storage refuses the write, so the stale leader cannot corrupt data."}]},{"id":"sd-circuit-breaker","module":"system-design","lesson":"system-design/graceful-degradation-and-circuit-breakers","title":"A circuit breaker opening and closing","summary":"Closed, open and half-open states protecting a caller.","actors":["Caller","Breaker","Dependency"],"steps":[{"f":0,"t":1,"l":"Call","n":"The caller sends a request through the breaker, which starts closed and lets it pass."},{"f":1,"t":2,"l":"Forward","n":"The dependency is slow and the call times out; the breaker counts a failure."},{"f":1,"t":1,"l":"Failure rate over threshold","n":"When more than half of recent calls fail or are slow, the breaker opens."},{"f":0,"t":1,"l":"Call while open","n":"New calls fail immediately without waiting for a timeout, and the caller uses its fallback."},{"f":1,"t":0,"l":"Fallback result","n":"The caller shows a default or cached result and keeps its threads free."},{"f":1,"t":1,"l":"Cool-down ends: half-open","n":"After the cool-down the breaker allows a few trial calls through."},{"f":1,"t":2,"l":"Trial call succeeds","n":"The dependency answers quickly, so the breaker closes and traffic ramps back."}]},{"id":"sd-token-bucket","module":"system-design","lesson":"system-design/rate-limiting-and-load-shedding","title":"Token bucket and shedding","summary":"How a limiter allows bursts and sheds the excess.","actors":["Client","Gateway","Bucket","Service"],"steps":[{"f":0,"t":1,"l":"Request","n":"A client sends a request to the gateway."},{"f":1,"t":2,"l":"Take a token","n":"The gateway asks the bucket for a token; the bucket refills at a steady rate up to a maximum."},{"f":2,"t":1,"l":"Token granted","n":"A token is available, so the request is allowed, including short bursts up to the bucket size."},{"f":1,"t":3,"l":"Forward to service","n":"The service handles the request within its concurrency limit."},{"f":0,"t":1,"l":"Burst of requests","n":"The client sends far more than its rate and the bucket runs empty."},{"f":1,"t":0,"l":"429 with Retry-After","n":"The gateway rejects cheaply and tells the client when to try again, before any expensive work."},{"f":0,"t":0,"l":"Back off with jitter","n":"The client waits a randomised delay, so retries do not arrive together."}]},{"id":"sd-cell-routing","module":"system-design","lesson":"system-design/failure-domains-cells-and-bulkheads","title":"Routing a customer to a cell","summary":"One thin router, many independent cells.","actors":["Customer","Router","Cell 3","Cell 7"],"steps":[{"f":0,"t":1,"l":"Request for customer 4812","n":"The request arrives at the thin router with the customer identifier."},{"f":1,"t":1,"l":"Look up home cell","n":"The router maps the customer to cell 3 using a small, replicated table."},{"f":1,"t":2,"l":"Forward to cell 3","n":"Everything for this customer runs inside cell 3: services, queue and data."},{"f":2,"t":0,"l":"Response","n":"Cell 3 answers without calling any other cell."},{"f":3,"t":3,"l":"Cell 7 fails","n":"A bad host pool takes cell 7 down; it serves about a tenth of customers."},{"f":1,"t":2,"l":"Customer 4812 unaffected","n":"Requests for customers in other cells continue normally, so the blast radius is bounded."}]},{"id":"sd-shuffle-shard","module":"system-design","lesson":"system-design/blast-radius-and-shuffle-sharding","title":"Shuffle sharding in action","summary":"Each customer gets a small random set of workers.","actors":["Bad customer","Router","Workers","Other customer"],"steps":[{"f":1,"t":1,"l":"Assign subsets","n":"The router gives each customer a random subset of workers, for example two out of eight."},{"f":0,"t":1,"l":"Sends poison request","n":"The bad customer sends a request that crashes whichever worker handles it."},{"f":1,"t":2,"l":"Hits workers 2 and 5","n":"Only the two workers in this customer subset can ever receive its requests."},{"f":2,"t":2,"l":"Workers 2 and 5 crash","n":"The damage is contained to two workers, however often the request is retried."},{"f":3,"t":1,"l":"Other customer request","n":"Another customer has workers 1 and 5, so only one of its workers is affected."},{"f":1,"t":2,"l":"Retry on worker 1","n":"The router retries on the surviving worker in the subset and the customer still gets service."}]},{"id":"f-sd-doubled-file","module":"system-design","kind":"failure","lesson":"system-design/config-and-control-plane-change-safety","title":"Failure and recovery: a doubled file crashes every proxy","summary":"A generated file passes a size limit and is pushed everywhere.","actors":["Generator","Control plane","Proxies","Operators"],"steps":[{"f":0,"t":0,"l":"Query changes behaviour","n":"A database permissions change makes the query return duplicate rows, so the generated file doubles in size."},{"f":0,"t":1,"l":"Publish with no size check","n":"The file is published without any bound or shape check against what the proxy can accept."},{"f":1,"t":2,"l":"Push to every proxy","n":"The control plane replicates the file to the whole fleet within minutes, with no staging."},{"f":2,"t":2,"l":"Limit exceeded, crash","n":"Each proxy loads the file, finds more features than its fixed limit and aborts instead of keeping the old file."},{"f":2,"t":3,"l":"Errors everywhere","n":"Traffic fails across the fleet and the symptoms look like an attack, which slows diagnosis."},{"f":3,"t":1,"l":"Stop the push, restore last good","n":"Operators halt generation and distribute a known good file, then restart the proxies."},{"f":3,"t":0,"l":"Add guards","n":"Add a size and shape check before publish, staged rollout with a bake time, a loader that keeps the last good file and a global kill switch."}]},{"id":"f-sd-survivor-overload","module":"system-design","kind":"failure","lesson":"system-design/multi-region-and-global-traffic","title":"Failure and recovery: the surviving region overloads","summary":"Two regions at 60 percent each, and one fails.","actors":["Users","Traffic steering","Region A","Region B"],"steps":[{"f":2,"t":2,"l":"Region A fails","n":"A database and network fault takes the whole region out of service."},{"f":1,"t":1,"l":"Health checks fail","n":"The steering layer marks region A unhealthy and moves its share of traffic."},{"f":1,"t":3,"l":"All traffic to region B","n":"Region B was at 60 percent and now receives its own load plus region A load."},{"f":3,"t":3,"l":"Demand at 120 percent","n":"Capacity is exceeded, queues grow and latency passes client timeouts."},{"f":0,"t":3,"l":"Retries add load","n":"Clients retry the failures, so the survivor is busier and almost no useful work completes."},{"f":3,"t":0,"l":"Shed by priority","n":"Region B rejects low priority work with 429 and Retry-After, keeping login and payments fast."},{"f":3,"t":3,"l":"Scale out and recover","n":"Capacity is added in region B while limits hold, and error rates fall back toward normal."},{"f":1,"t":2,"l":"Fix the design","n":"Plan headroom for the lost share, drill the failover, and ramp traffic back into region A in steps."}]},{"id":"sd-consistent-hashing","module":"system-design","lesson":"system-design/partitioning-sharding-and-consistent-hashing","title":"Consistent hashing adds a node","summary":"Only a slice of keys moves when a node joins.","actors":["Client","Ring","Node A","Node B","New node"],"steps":[{"f":0,"t":1,"l":"Lookup key K","n":"The client hashes the key to a point on the ring."},{"f":1,"t":2,"l":"Next node clockwise","n":"The key belongs to the first node found clockwise, here node A."},{"f":1,"t":3,"l":"Another key goes to B","n":"Other keys land on other nodes, so each node holds a slice of the ring."},{"f":4,"t":1,"l":"New node joins","n":"A new node takes positions on the ring, using several virtual nodes for even load."},{"f":2,"t":4,"l":"Move a slice","n":"Only keys between the new node and its predecessor move, about one Nth of the data."},{"f":0,"t":1,"l":"Same lookup again","n":"Most keys are still on the same nodes, so caches stay warm and there is no storm."}]},{"id":"sd-backup-restore","module":"system-design","lesson":"system-design/backup-restore-and-object-storage-design","title":"Backup, point-in-time restore and timing","summary":"From a base copy and a log to a verified restore.","actors":["Database","Backup store","Operator","Clean environment"],"steps":[{"f":0,"t":1,"l":"Base copy and log shipping","n":"A periodic base copy is stored with a continuous log of changes in an independent account."},{"f":2,"t":0,"l":"Mistake at 14:00","n":"A table is dropped by mistake; replicas copy the drop within seconds."},{"f":2,"t":1,"l":"Choose a restore time","n":"The operator picks 13:59 as the restore point using the change log."},{"f":1,"t":3,"l":"Restore base copy","n":"The base copy is restored into a clean environment, which takes the longest part of the time."},{"f":1,"t":3,"l":"Replay log to 13:59","n":"Changes are replayed up to just before the mistake."},{"f":3,"t":3,"l":"Verify","n":"Row counts, checksums and an application smoke test confirm the data is right."},{"f":2,"t":2,"l":"Record the time","n":"The real elapsed time is compared with the RTO and the gap is filed as work."}]},{"id":"sd-shared-secret-scope","module":"system-design","lesson":"system-design/security-and-identity-by-design","title":"Short-lived workload credentials","summary":"A workload gets scoped, expiring access.","actors":["Workload","Identity provider","Secret manager","Storage"],"steps":[{"f":0,"t":1,"l":"Prove identity","n":"The workload presents its platform identity, not a copied key."},{"f":1,"t":0,"l":"Short-lived token","n":"The provider issues a token that expires in minutes and is scoped to this workload."},{"f":0,"t":2,"l":"Request secret","n":"The workload asks the secret manager for only the secret it needs."},{"f":2,"t":0,"l":"Secret returned and logged","n":"The manager returns the secret and records who accessed it and when."},{"f":0,"t":3,"l":"Read one bucket","n":"The token allows reading only the one bucket and prefix it needs."},{"f":3,"t":0,"l":"Other bucket denied","n":"A request for a different bucket is refused, so a compromise reaches little."}]},{"id":"f-sd-restore-too-slow","module":"system-design","kind":"failure","lesson":"system-design/backup-restore-and-object-storage-design","title":"Failure and recovery: the backup that could not meet the RTO","summary":"A destructive change meets a restore nobody had timed.","actors":["Operator","Primary database","Backup store","Business"],"steps":[{"f":0,"t":1,"l":"Destructive change","n":"A script deletes data in the primary and replicas copy the deletion."},{"f":0,"t":2,"l":"Start the restore","n":"The team restores last night full backup and expects it to be quick."},{"f":2,"t":1,"l":"Hours of copying","n":"Moving the data takes 2 hours 41 minutes against a 60 minute target."},{"f":3,"t":0,"l":"Pressure rises","n":"The business cannot work and asks for an estimate that nobody can give with confidence."},{"f":0,"t":1,"l":"Replay the log","n":"After the base restore, the log is replayed to just before the mistake, losing nothing."},{"f":0,"t":1,"l":"Verify and reopen","n":"Checks pass and the service reopens, hours later than the target."},{"f":0,"t":3,"l":"Fix the design","n":"Add snapshots or a warm standby, keep point-in-time recovery, and time a restore every month."}]},{"id":"x-mlops-parts","module":"mlops","lesson":"mlops/what-mlops-is-and-how-ml-systems-fail","title":"The parts around the model","summary":"Where a production ML system really lives.","actors":["Data source","Pipeline","Model","Service"],"steps":[{"f":0,"t":1,"l":"Collect data","n":"Raw events and records are collected from products and other systems."},{"f":1,"t":1,"l":"Check and clean","n":"The pipeline validates the data and removes records that break the rules."},{"f":1,"t":2,"l":"Train a model","n":"The cleaned data is turned into features and used to train and evaluate a model."},{"f":2,"t":3,"l":"Package and serve","n":"The approved model is packaged and served as an API or a batch job."},{"f":3,"t":0,"l":"Feed back outcomes","n":"Real outcomes flow back as new data, so the system can learn again."},{"f":3,"t":3,"l":"Monitor everything","n":"Inputs, predictions and quality are watched, not only speed and errors."}]},{"id":"x-mlops-skew","module":"mlops","lesson":"mlops/what-mlops-is-and-how-ml-systems-fail","title":"Training-serving skew","summary":"Same name, different calculation.","actors":["Notebook","Training job","Serving code","Model"],"steps":[{"f":0,"t":1,"l":"Compute a feature","n":"A data scientist computes days since login with one library in a notebook."},{"f":1,"t":3,"l":"Train on it","n":"The model learns with that exact calculation."},{"f":2,"t":2,"l":"Reimplement it","n":"An engineer rewrites the feature in the service using hours instead of days."},{"f":2,"t":3,"l":"Send different values","n":"The service sends values that look nothing like the training data."},{"f":3,"t":2,"l":"Return poor answers","n":"The model answers confidently but wrongly, and no error is raised."},{"f":2,"t":0,"l":"Share one definition","n":"The fix is one feature definition used by both training and serving."}]},{"id":"x-mlops-validate","module":"mlops","lesson":"mlops/data-and-feature-pipelines-for-ml","title":"Validating a batch before training","summary":"A bad batch should stop the pipeline.","actors":["Source","Validator","Pipeline","Owner"],"steps":[{"f":0,"t":1,"l":"Deliver a batch","n":"A new daily table arrives for training."},{"f":1,"t":1,"l":"Run the checks","n":"Row counts, freshness, nulls, ranges and allowed values are tested."},{"f":1,"t":3,"l":"Raise an alert","n":"A check fails because one column is mostly null, and the owner is alerted."},{"f":1,"t":2,"l":"Stop the pipeline","n":"The pipeline does not train on the bad batch."},{"f":3,"t":0,"l":"Fix upstream","n":"The owner finds the upstream change and corrects it."},{"f":0,"t":2,"l":"Resume with good data","n":"A corrected batch passes and the pipeline continues."}]},{"id":"x-mlops-pit","module":"mlops","lesson":"mlops/data-and-feature-pipelines-for-ml","title":"Point-in-time feature join","summary":"Use only what was known at the time.","actors":["Events","Feature table","Join","Training set"],"steps":[{"f":0,"t":2,"l":"Pick an event","n":"An event with a label and a timestamp is taken as a training row."},{"f":1,"t":2,"l":"Offer feature values","n":"The feature table holds many values for each customer over time."},{"f":2,"t":2,"l":"Find the right time","n":"The join picks the latest value at or before the event time."},{"f":2,"t":3,"l":"Write the row","n":"The row contains only information that existed at the moment of the prediction."},{"f":3,"t":3,"l":"Avoid leakage","n":"Future information never enters, so test scores match production."},{"f":3,"t":0,"l":"Repeat for every event","n":"The same rule applies to every row, so the whole set is leak-free."}]},{"id":"x-mlops-tracking","module":"mlops","lesson":"mlops/experiment-tracking-and-reproducibility","title":"A tracked training run","summary":"Every run leaves a full record.","actors":["Engineer","Training job","Tracker","Registry"],"steps":[{"f":0,"t":1,"l":"Start a run","n":"The engineer starts training from a code commit and a data version."},{"f":1,"t":2,"l":"Log parameters","n":"The job records parameters, seed and environment to the tracker."},{"f":1,"t":1,"l":"Train and evaluate","n":"The model trains and is scored on a fixed evaluation set."},{"f":1,"t":2,"l":"Log metrics and files","n":"Metrics, per-group results and the model file are stored with the run."},{"f":0,"t":2,"l":"Compare runs","n":"The engineer compares runs in a table on the same data and metric."},{"f":2,"t":3,"l":"Promote the best","n":"The chosen run is registered, with a link back to its full record."}]},{"id":"x-mlops-gate","module":"mlops","lesson":"mlops/training-pipelines-and-testing-models-in-ci","title":"An evaluation gate","summary":"Compare with production before release.","actors":["Pipeline","Candidate","Gate","Registry"],"steps":[{"f":0,"t":1,"l":"Train a candidate","n":"The scheduled pipeline trains a new candidate model."},{"f":1,"t":2,"l":"Send it to the gate","n":"The candidate is scored on a fixed evaluation set."},{"f":2,"t":2,"l":"Compare with production","n":"The gate compares the candidate with the live model, overall and by group."},{"f":2,"t":0,"l":"Report the result","n":"The gate reports pass or fail with the numbers behind it."},{"f":0,"t":3,"l":"Register on pass","n":"Only a passing candidate is registered for staging."},{"f":2,"t":2,"l":"Block on a regression","n":"A drop for any named group fails the gate and stops the release."}]},{"id":"x-mlops-ci","module":"mlops","lesson":"mlops/training-pipelines-and-testing-models-in-ci","title":"Tests for code, data and model","summary":"Three layers of checks.","actors":["Developer","CI","Data check","Model test"],"steps":[{"f":0,"t":1,"l":"Push a change","n":"A developer changes feature code and pushes it."},{"f":1,"t":1,"l":"Run unit tests","n":"Small tests check that feature functions return expected values."},{"f":1,"t":2,"l":"Run data checks","n":"A sample of data is validated against the schema and expectations."},{"f":1,"t":3,"l":"Run model tests","n":"The model must load, accept its input shape and meet a minimum quality bar."},{"f":3,"t":1,"l":"Run behaviour tests","n":"Small input changes should not flip answers and hard cases should still work."},{"f":1,"t":0,"l":"Report to the developer","n":"The change merges only if every layer passes."}]},{"id":"x-mlops-canary","module":"mlops","lesson":"mlops/model-registry-packaging-and-safe-releases","title":"Shadow, then canary","summary":"Release in small, watched steps.","actors":["Registry","New model","Traffic router","Monitor"],"steps":[{"f":0,"t":1,"l":"Promote to staging","n":"The new version is promoted with its image digest and lineage."},{"f":2,"t":1,"l":"Shadow traffic","n":"A copy of real requests goes to the new model, and its answers are only logged."},{"f":3,"t":3,"l":"Compare answers","n":"The monitor compares its answers and latency with the live model."},{"f":2,"t":1,"l":"Start a small canary","n":"A small share of real traffic is served by the new model."},{"f":3,"t":2,"l":"Watch quality","n":"Errors, latency and a quality proxy are checked before widening."},{"f":0,"t":1,"l":"Promote in steps","n":"Traffic is raised in steps while the previous version stays ready."}]},{"id":"x-mlops-serving","module":"mlops","lesson":"mlops/serving-models-batch-online-and-streaming","title":"Dynamic batching","summary":"A short wait raises throughput.","actors":["Clients","Batcher","Model","Autoscaler"],"steps":[{"f":0,"t":1,"l":"Requests arrive","n":"Several requests arrive within a few milliseconds."},{"f":1,"t":1,"l":"Wait briefly","n":"The batcher waits up to its limit to collect more requests."},{"f":1,"t":2,"l":"Run one batch","n":"The model processes the group in one pass, which is cheaper per item."},{"f":2,"t":0,"l":"Return results","n":"Each client receives its own answer."},{"f":3,"t":1,"l":"Watch queue and latency","n":"The autoscaler watches concurrent requests and latency, not only CPU."},{"f":3,"t":2,"l":"Add replicas","n":"More replicas are added early, keeping a warm minimum because models load slowly."}]},{"id":"x-mlops-drift","module":"mlops","lesson":"mlops/monitoring-drift-and-retraining","title":"From drift signal to retrain","summary":"Detect, decide and retrain safely.","actors":["Monitor","On-call","Pipeline","Registry"],"steps":[{"f":0,"t":0,"l":"Compare with training","n":"The monitor compares live features and predictions with a training reference."},{"f":0,"t":1,"l":"Open a ticket","n":"A sustained shift over several hours opens a ticket, not a page."},{"f":1,"t":0,"l":"Investigate","n":"The engineer checks upstream changes and quality on important groups."},{"f":1,"t":2,"l":"Trigger a retrain","n":"If the shift is real, a retrain starts with fresh, validated data."},{"f":2,"t":3,"l":"Pass the gate","n":"The new model passes the same gate and staged release as any other."},{"f":3,"t":0,"l":"Reset the reference","n":"The new training data becomes the reference for future drift checks."}]},{"id":"f-mlops-silent","module":"mlops","kind":"failure","lesson":"mlops/what-mlops-is-and-how-ml-systems-fail","title":"Failure and recovery: a model that decayed unseen","summary":"Quiet decay found by the business.","actors":["Model","Monitoring","Business","Team"],"steps":[{"f":0,"t":0,"l":"Serve normally","n":"The model answers fast with no errors for months."},{"f":0,"t":0,"l":"Behaviour changes","n":"Customer behaviour drifts and the predictions slowly get worse."},{"f":1,"t":1,"l":"Nothing fires","n":"Latency and error dashboards stay green, so no alert is raised."},{"f":2,"t":3,"l":"Business notices","n":"Conversions fall and the business team reports it six weeks later."},{"f":3,"t":1,"l":"Find the cause","n":"The team finds that no input or quality checks exist."},{"f":3,"t":0,"l":"Roll back and retrain","n":"The last good model is restored and a fresh one is trained and tested."},{"f":3,"t":1,"l":"Add monitoring","n":"Input checks, prediction drift and a monthly quality report against a baseline are added."}]},{"id":"f-mlops-badretrain","module":"mlops","kind":"failure","lesson":"mlops/training-pipelines-and-testing-models-in-ci","title":"Failure and recovery: a retrain that shipped a regression","summary":"An automatic release with no group gate.","actors":["Pipeline","Registry","Support","Team"],"steps":[{"f":0,"t":1,"l":"Retrain on schedule","n":"The weekly job trains and promotes its result automatically."},{"f":1,"t":2,"l":"Users are affected","n":"New customers get poor results, while the overall metric barely moves."},{"f":2,"t":3,"l":"Tickets arrive","n":"Support reports the problem and the team starts investigating."},{"f":3,"t":1,"l":"Roll back","n":"The registry stage is moved back to the previous version in one step."},{"f":3,"t":0,"l":"Find the cause","n":"A data fault lowered quality for one group, and the gate only checked the average."},{"f":3,"t":0,"l":"Add a group gate","n":"The gate now compares named groups and blocks any candidate that is worse."},{"f":0,"t":1,"l":"Release in stages","n":"Future retrains go through shadow and canary stages before full release."}]},{"id":"x-aiops-baseline","module":"aiops","lesson":"aiops/what-aiops-is-and-is-not","title":"Measure before you buy","summary":"A baseline decides whether a tool helped.","actors":["Team","Data","Tool trial","Review"],"steps":[{"f":0,"t":1,"l":"Collect the baseline","n":"The team measures alerts per incident, time to acknowledge and false pages."},{"f":0,"t":1,"l":"Fix telemetry first","n":"Labels, service names and change records are cleaned up."},{"f":0,"t":2,"l":"Trial beside current practice","n":"The tool runs for a few weeks alongside the current process."},{"f":2,"t":3,"l":"Compare numbers","n":"Results are compared with the baseline, not with opinion."},{"f":3,"t":0,"l":"Decide","n":"The tool stays if noise and time to cause improve."},{"f":3,"t":0,"l":"Review again","n":"The numbers are reviewed every quarter, so decay is noticed."}]},{"id":"x-aiops-seasonal","module":"aiops","lesson":"aiops/anomaly-detection-on-metrics","title":"A seasonal baseline","summary":"Compare with the same time last week.","actors":["Metric","Baseline","Detector","On-call"],"steps":[{"f":0,"t":1,"l":"Collect history","n":"The metric is stored for several weeks."},{"f":1,"t":1,"l":"Build the pattern","n":"The baseline learns the shape of each hour and day of the week."},{"f":0,"t":2,"l":"Receive a new value","n":"A new Monday 9am value arrives."},{"f":2,"t":1,"l":"Compare like with like","n":"The detector compares it with earlier Monday 9am values, not the previous hour."},{"f":2,"t":2,"l":"Require duration","n":"The deviation must last several minutes before it counts."},{"f":2,"t":3,"l":"Alert if real","n":"Only a sustained, large deviation reaches the on-call engineer."}]},{"id":"x-aiops-correlate","module":"aiops","lesson":"aiops/alert-correlation-and-noise-reduction","title":"Correlating a storm","summary":"Many alerts, one incident.","actors":["Alerts","Correlator","Dependency map","On-call"],"steps":[{"f":0,"t":1,"l":"Alerts pour in","n":"Two hundred alerts arrive from thirty services within minutes."},{"f":1,"t":1,"l":"Deduplicate","n":"Identical alerts collapse into one with a count."},{"f":1,"t":2,"l":"Look up dependencies","n":"The correlator checks which services share a failing dependency."},{"f":2,"t":1,"l":"Find the common source","n":"Twenty-nine services depend on one storage volume that is also unhealthy."},{"f":1,"t":3,"l":"Open one incident","n":"One incident is raised with the volume on top and dependants folded below."},{"f":3,"t":3,"l":"Fix the source","n":"The engineer frees space, and the dependent alerts clear by themselves."}]},{"id":"x-aiops-inhibit","module":"aiops","lesson":"aiops/alert-correlation-and-noise-reduction","title":"Inhibition rules","summary":"A bigger alert mutes smaller ones.","actors":["Source alert","Alert manager","Warnings","On-call"],"steps":[{"f":0,"t":1,"l":"Node down fires","n":"A critical alert says a node is down."},{"f":2,"t":1,"l":"Pod warnings fire","n":"Many warning alerts fire for pods on that node."},{"f":1,"t":1,"l":"Match the labels","n":"The rule matches alerts on the same cluster and node."},{"f":1,"t":2,"l":"Mute the warnings","n":"The warnings are inhibited while the node alert is active."},{"f":1,"t":3,"l":"Page once","n":"The engineer gets one page about the real fault."},{"f":0,"t":1,"l":"Resume on recovery","n":"When the node returns, inhibition ends and warnings flow normally again."}]},{"id":"x-aiops-templates","module":"aiops","lesson":"aiops/logs-and-traces-finding-patterns-with-ml","title":"Log templates","summary":"Millions of lines become a short list.","actors":["Log lines","Template builder","Report","Engineer"],"steps":[{"f":0,"t":1,"l":"Stream of lines","n":"Millions of lines arrive with different values inside similar messages."},{"f":1,"t":1,"l":"Replace variable parts","n":"Numbers, ids and names are replaced by placeholders."},{"f":1,"t":2,"l":"Count templates","n":"Each template is counted per minute, per version and per host."},{"f":2,"t":3,"l":"Show new templates","n":"The report lists templates that did not exist before the release."},{"f":3,"t":2,"l":"Check growth","n":"The engineer looks at templates whose rate is rising fast."},{"f":3,"t":0,"l":"Read examples","n":"A few real lines are read to confirm what the template means."}]},{"id":"x-aiops-trace","module":"aiops","lesson":"aiops/logs-and-traces-finding-patterns-with-ml","title":"Comparing slow traces","summary":"Find the step that grew.","actors":["Request","Trace store","Compare tool","Engineer"],"steps":[{"f":0,"t":1,"l":"Requests are traced","n":"Each request is recorded with timed steps called spans."},{"f":3,"t":2,"l":"Pick slow and typical","n":"The engineer selects the slowest requests and a typical sample."},{"f":2,"t":1,"l":"Compare span durations","n":"The tool compares the time spent in each service and call."},{"f":2,"t":3,"l":"Highlight the difference","n":"One database call is much longer in the slow requests."},{"f":3,"t":1,"l":"Check the path","n":"A retry that did not exist before appears in the slow traces."},{"f":3,"t":3,"l":"Link to a change","n":"The retry started right after a configuration push."}]},{"id":"x-aiops-hints","module":"aiops","lesson":"aiops/root-cause-hints-and-incident-assistants","title":"Ranking change hints","summary":"Evidence beside every suggestion.","actors":["Change log","Dependency map","Ranker","On-call"],"steps":[{"f":0,"t":2,"l":"List recent changes","n":"Deployments, flags and config pushes before the first symptom are collected."},{"f":1,"t":2,"l":"Add dependency health","n":"The ranker checks which dependencies started failing first."},{"f":2,"t":2,"l":"Score each candidate","n":"Each change is scored by time gap, graph distance and size of anomaly."},{"f":2,"t":3,"l":"Show hints with reasons","n":"The engineer sees ranked hints with the evidence for each."},{"f":3,"t":0,"l":"Confirm","n":"The engineer checks the timeline and confirms or rejects the top hint."},{"f":3,"t":2,"l":"Record the outcome","n":"The real cause is recorded, so hint accuracy can be measured."}]},{"id":"x-aiops-assistant","module":"aiops","lesson":"aiops/root-cause-hints-and-incident-assistants","title":"Assistant with guardrails","summary":"Summaries, not decisions.","actors":["Responder","Assistant","Incident data","Production"],"steps":[{"f":0,"t":1,"l":"Ask for a summary","n":"The responder asks for a status update and the likely runbook."},{"f":1,"t":2,"l":"Read allowed data","n":"The assistant sees only data the policy allows."},{"f":1,"t":0,"l":"Answer with sources","n":"It writes a summary and quotes the lines it relied on."},{"f":0,"t":0,"l":"Check the quotes","n":"The responder checks the sources before trusting the summary."},{"f":0,"t":3,"l":"Make the change","n":"Only the responder approves and runs any change to production."},{"f":1,"t":2,"l":"Log the exchange","n":"Every question and answer is logged for later review."}]},{"id":"x-aiops-remediate","module":"aiops","lesson":"aiops/safe-automation-and-auto-remediation","title":"A guarded auto-fix","summary":"Check, act, verify, escalate.","actors":["Alert","Automation","Service","On-call"],"steps":[{"f":0,"t":1,"l":"Alert fires","n":"A worker queue has stalled for ten minutes."},{"f":1,"t":1,"l":"Check preconditions","n":"The rule confirms the alert is active and no deployment is running."},{"f":1,"t":1,"l":"Check the limits","n":"It checks the action budget, the cooldown and the number of targets."},{"f":1,"t":2,"l":"Restart the worker","n":"The rule restarts one deployment and writes an audit entry."},{"f":1,"t":2,"l":"Verify","n":"After five minutes it checks that the queue depth has dropped."},{"f":1,"t":3,"l":"Escalate if not fixed","n":"If verification fails, the automation stops and pages a person."}]},{"id":"x-aiops-levels","module":"aiops","lesson":"aiops/safe-automation-and-auto-remediation","title":"From suggestion to unattended","summary":"Earn trust in stages.","actors":["Rule","Engineer","Audit log","Kill switch"],"steps":[{"f":0,"t":1,"l":"Suggest only","n":"The rule posts the action it would take and waits."},{"f":1,"t":0,"l":"Approve with one click","n":"The engineer approves, and the rule runs the action."},{"f":0,"t":2,"l":"Log every action","n":"Each action is recorded with the reason and how to undo it."},{"f":1,"t":2,"l":"Review the record","n":"After many correct decisions, the team reviews the audit log."},{"f":1,"t":0,"l":"Allow unattended runs","n":"The safest cases are allowed to run without approval."},{"f":1,"t":3,"l":"Keep the kill switch","n":"One control can still stop all automation at any time."}]},{"id":"f-aiops-storm","module":"aiops","kind":"failure","lesson":"aiops/alert-correlation-and-noise-reduction","title":"Failure and recovery: an alert storm with no grouping","summary":"Wall of alerts, slow cause.","actors":["Storage","Services","Pager","Engineer"],"steps":[{"f":0,"t":0,"l":"Disk fills up","n":"A shared storage volume reaches 100 percent."},{"f":1,"t":1,"l":"Services fail","n":"Twenty-nine services that use the volume begin to fail."},{"f":1,"t":2,"l":"Alerts flood in","n":"Two hundred alerts reach the pager in ten minutes."},{"f":2,"t":3,"l":"Engineer reads them","n":"The engineer spends the early minutes reading alerts one by one."},{"f":3,"t":0,"l":"Find the disk","n":"The common dependency is finally spotted and space is freed."},{"f":0,"t":1,"l":"Services recover","n":"The failing services recover and the dependent alerts clear."},{"f":3,"t":2,"l":"Add grouping","n":"Stable labels, grouping by dependency and inhibition rules are added for next time."}]},{"id":"f-aiops-cleanup","module":"aiops","kind":"failure","lesson":"aiops/safe-automation-and-auto-remediation","title":"Failure and recovery: a cleanup that deleted too much","summary":"Automation without guardrails.","actors":["Rule","Disk","Services","Team"],"steps":[{"f":0,"t":1,"l":"Triggered by a disk alert","n":"A cleanup rule runs when the disk is nearly full."},{"f":0,"t":1,"l":"Empty variable","n":"A path variable is empty, so the delete scope is far wider than intended."},{"f":1,"t":2,"l":"Data disappears","n":"Files other services need are deleted and errors begin."},{"f":3,"t":0,"l":"Use the kill switch","n":"The team stops all automation with one control."},{"f":3,"t":1,"l":"Restore from backup","n":"The latest snapshot is mounted and files are restored and verified."},{"f":3,"t":0,"l":"Add preconditions","n":"The rule now aborts on an empty target and deletes only inside a named directory."},{"f":3,"t":0,"l":"Add limits and a dry run","n":"Action limits, a dry run, verification and an audit log are added to every rule."}]},{"id":"x-virt-boot","module":"virtualization","lesson":"virtualization/what-virtualization-is-and-hypervisor-types","title":"How a guest starts on KVM","summary":"From virsh start to a running guest.","actors":["Admin","libvirt","QEMU","KVM in the kernel","Guest OS"],"steps":[{"f":0,"t":1,"l":"virsh start web-1","n":"The admin asks libvirt to start the guest defined in its XML file, which lists CPUs, memory, disks and network interfaces."},{"f":1,"t":1,"l":"Check resources","n":"libvirt checks that the disks exist, the network is defined and the host has memory to give the guest."},{"f":1,"t":2,"l":"Launch QEMU","n":"libvirt starts a QEMU process with the devices from the definition. QEMU provides the virtual hardware."},{"f":2,"t":3,"l":"Create the virtual CPUs","n":"QEMU asks the kernel KVM module for a virtual machine and virtual CPUs, which run guest code directly on the real CPU."},{"f":2,"t":2,"l":"Attach disks and network","n":"QEMU opens the disk image and connects the virtual network card to the bridge on the host."},{"f":3,"t":4,"l":"Run the firmware and boot","n":"The virtual CPUs begin executing firmware, which loads the guest kernel from the virtual disk."},{"f":4,"t":0,"l":"Guest is up","n":"The guest gets an address and answers on the network. From the host it is one QEMU process with its own memory."}]},{"id":"x-virt-migrate","module":"virtualization","lesson":"virtualization/live-migration-ha-and-troubleshooting","title":"A live migration","summary":"Copy memory while the guest keeps running.","actors":["Admin","Source host","Destination host","Guest"],"steps":[{"f":0,"t":1,"l":"Start migration","n":"The admin asks the source host to migrate the guest to the destination, over shared storage or with disk copy."},{"f":1,"t":2,"l":"Prepare destination","n":"The destination starts an empty guest of the same shape and waits for memory pages to arrive."},{"f":1,"t":2,"l":"Copy all memory","n":"The source copies every memory page to the destination while the guest keeps running."},{"f":3,"t":3,"l":"Guest dirties pages","n":"The running guest changes some pages, so they must be copied again in later rounds."},{"f":1,"t":2,"l":"Copy dirty pages","n":"Each round copies fewer pages if the network is faster than the guest writes. The rounds stop when the rest is small."},{"f":1,"t":2,"l":"Pause and finish","n":"The source pauses the guest for a moment, sends the last pages and CPU state, and the destination resumes it."},{"f":2,"t":0,"l":"Guest runs on the destination","n":"The guest continues with its address and sessions. The source releases its memory."}]},{"id":"f-virt-pool","module":"virtualization","kind":"failure","lesson":"virtualization/virtual-disks-snapshots-and-templates","title":"Failure and recovery: a pool full of snapshots","summary":"Overlays grow until the pool fills and guests pause.","actors":["Guest","Storage pool","Monitoring","On-call engineer","Hypervisor"],"steps":[{"f":0,"t":1,"l":"Guests write data","n":"Each guest with snapshots writes changes into an overlay file, which grows with every write."},{"f":1,"t":1,"l":"Pool fills quietly","n":"Twelve snapshot chains grow for a week and the pool passes 90 percent with no alert."},{"f":1,"t":4,"l":"A write fails","n":"A guest write cannot allocate a block, so the hypervisor gets an error from the pool."},{"f":4,"t":0,"l":"Guests pause","n":"To protect data the hypervisor pauses affected guests with an I/O error. Users see hung services."},{"f":2,"t":3,"l":"Alert arrives","n":"Application monitoring reports failures. The on-call engineer sees paused guests, not the cause."},{"f":3,"t":1,"l":"Find the cause","n":"virsh pool-info shows no space left and virsh snapshot-list shows old snapshots on every guest."},{"f":3,"t":1,"l":"Free space safely","n":"After confirming backups, the engineer deletes the oldest snapshots one guest at a time and watches the pool."},{"f":3,"t":0,"l":"Resume guests","n":"With free space, the guests resume. Later the team adds snapshot expiry and an alert at 80 percent."}]},{"id":"x-sto-write","module":"storage","lesson":"storage/filesystems-ext4-xfs-and-mounts","title":"A write from program to disk","summary":"Cache, journal and device.","actors":["Program","Page cache","Filesystem","Block layer","Disk"],"steps":[{"f":0,"t":1,"l":"write() call","n":"The program writes bytes. The kernel copies them into the page cache and the call returns quickly."},{"f":1,"t":1,"l":"Mark pages dirty","n":"The pages are dirty: newer in memory than on disk. They will be written later in the background."},{"f":0,"t":2,"l":"fsync() call","n":"A database calls fsync to demand that the data is safe on disk before it carries on."},{"f":2,"t":2,"l":"Write the journal","n":"The filesystem first records the intended change in its journal so a crash can be repaired."},{"f":2,"t":3,"l":"Send blocks","n":"The filesystem hands the data blocks to the block layer, which queues and merges requests."},{"f":3,"t":4,"l":"Device writes","n":"The disk stores the blocks, and a flush makes sure its own cache is on stable media."},{"f":4,"t":0,"l":"fsync returns","n":"Only now does the call return. A crash after this point cannot lose the data."}]},{"id":"x-sto-lvm","module":"storage","lesson":"storage/lvm-and-raid","title":"Growing a volume online","summary":"Add space without unmounting.","actors":["Admin","Volume group","Logical volume","Filesystem"],"steps":[{"f":0,"t":1,"l":"Check free extents","n":"The admin runs vgs to see whether the volume group has free space, and adds a new disk with vgextend if not."},{"f":0,"t":2,"l":"lvextend -r","n":"The command enlarges the logical volume by taking free extents from the group."},{"f":2,"t":3,"l":"Tell the filesystem","n":"With the resize option the tool runs the filesystem growth for you after the volume has grown."},{"f":3,"t":3,"l":"Grow online","n":"ext4 or XFS adds the new space to its structures while it stays mounted and in use."},{"f":3,"t":0,"l":"More space shows","n":"df now shows the larger size, and applications carry on without restarting."},{"f":0,"t":3,"l":"Confirm","n":"The admin checks lsblk, df and the application logs, and records the change."}]},{"id":"f-sto-fstab","module":"storage","kind":"failure","lesson":"storage/filesystems-ext4-xfs-and-mounts","title":"Failure and recovery: a bad fstab line stops boot","summary":"One wrong UUID sends the server to emergency mode.","actors":["Admin","fstab","systemd","Console"],"steps":[{"f":0,"t":1,"l":"Add a mount line","n":"The admin adds a data disk to fstab, copying the UUID by hand and making one character wrong."},{"f":0,"t":2,"l":"Reboot","n":"The server is restarted without testing the file with mount -a."},{"f":2,"t":1,"l":"Read fstab","n":"During boot systemd turns every line into a mount unit, including the new one."},{"f":2,"t":2,"l":"Device not found","n":"The UUID matches no device, so the mount unit waits and then fails."},{"f":2,"t":3,"l":"Emergency mode","n":"Because the mount is required, boot stops and the console shows an emergency prompt."},{"f":0,"t":3,"l":"Read the log","n":"The admin reads journalctl -xb and sees the failed dependency for the data mount."},{"f":0,"t":1,"l":"Fix the entry","n":"Root is remounted read-write and the UUID is corrected from blkid, then mount -a runs without errors."},{"f":0,"t":2,"l":"Reboot and harden","n":"The server boots normally. The team adds nofail to optional mounts and tests fstab before reboots."}]},{"id":"x-sql-plan","module":"sql-ops","lesson":"sql-ops/reading-explain-and-finding-slow-queries","title":"How a query is planned and run","summary":"Parse, plan, execute.","actors":["Client","Parser","Planner","Executor","Storage"],"steps":[{"f":0,"t":1,"l":"Send SQL","n":"The client sends the statement text to the server."},{"f":1,"t":1,"l":"Parse and check","n":"The parser checks syntax and that the tables and columns exist."},{"f":1,"t":2,"l":"Plan","n":"The planner uses table statistics to estimate rows and cost for several plans."},{"f":2,"t":2,"l":"Choose the cheapest","n":"It picks an index scan or a sequential scan, and a join order, based on the estimates."},{"f":2,"t":3,"l":"Run the plan","n":"The executor runs the chosen steps, asking storage for rows."},{"f":3,"t":4,"l":"Read data","n":"Storage returns pages from memory or disk, and rows are filtered and joined."},{"f":3,"t":0,"l":"Return rows","n":"Results go back to the client. EXPLAIN ANALYZE shows estimated against actual rows for each step."}]},{"id":"x-sql-pool","module":"sql-ops","lesson":"sql-ops/connections-pooling-and-capacity","title":"A pooler shares connections","summary":"Many clients, few connections.","actors":["Clients","Pooler","Database"],"steps":[{"f":0,"t":1,"l":"Many clients connect","n":"Hundreds of application connections arrive at the pooler, most of them idle at any moment."},{"f":1,"t":1,"l":"Wait for a turn","n":"The pooler keeps a small set of server connections and queues requests when all are busy."},{"f":1,"t":2,"l":"Lend a connection","n":"In transaction mode it lends a server connection only for one transaction."},{"f":2,"t":1,"l":"Run and return","n":"The database runs the transaction and the connection goes back to the pool at commit."},{"f":1,"t":0,"l":"Reply to the client","n":"The client sees its answer and its next transaction may use a different server connection."},{"f":1,"t":1,"l":"Wait time is the signal","n":"If wait time for a free connection grows, demand is above capacity and you need to act."}]},{"id":"f-sql-conn","module":"sql-ops","kind":"failure","lesson":"sql-ops/locks-deadlocks-and-long-transactions","title":"Failure and recovery: idle transactions fill the connection limit","summary":"Stuck sessions block new requests at peak.","actors":["API","Database","Monitoring","On-call engineer"],"steps":[{"f":0,"t":1,"l":"Begin a transaction","n":"A handler starts a transaction and then calls a slow external service before it commits."},{"f":1,"t":1,"l":"Slot stays held","n":"The session sits idle in transaction and keeps its connection slot and sometimes locks."},{"f":0,"t":1,"l":"Traffic grows","n":"At peak more handlers do the same until nearly all slots are used by idle sessions."},{"f":1,"t":0,"l":"New requests fail","n":"The database refuses new connections with too many connections and users see errors."},{"f":2,"t":3,"l":"Alert fires","n":"Error rate alerts page the on-call engineer who sees connection errors."},{"f":3,"t":1,"l":"Group by state","n":"pg_stat_activity grouped by state shows most sessions are idle in transaction from one service."},{"f":3,"t":1,"l":"End stuck sessions","n":"The engineer terminates the oldest idle sessions to restore service and notes the owner."},{"f":3,"t":0,"l":"Fix the code","n":"The team moves the external call out of the transaction, adds a timeout and a pooler, and alerts on pool wait."}]},{"id":"x-gpu-req","module":"gpu-serving","lesson":"gpu-serving/serving-stacks-vllm-tgi-triton","title":"One request through an LLM server","summary":"From prompt to streamed tokens.","actors":["Client","Server","Scheduler","GPU"],"steps":[{"f":0,"t":1,"l":"Send a prompt","n":"The client calls the API with a prompt and settings such as the maximum tokens."},{"f":1,"t":1,"l":"Tokenise","n":"The server turns text into tokens. This runs on the CPU and can limit speed if it is slow."},{"f":1,"t":2,"l":"Queue the request","n":"The scheduler places the request in the waiting queue until there is room in the KV cache."},{"f":2,"t":3,"l":"Prefill","n":"The GPU processes the whole prompt in parallel and fills the KV cache. This sets the time to first token."},{"f":3,"t":3,"l":"Decode token by token","n":"Each step produces one token for every request in the batch, reading the weights and the cache."},{"f":3,"t":0,"l":"Stream tokens","n":"Tokens are sent back as they are produced, and the request leaves the batch when it finishes."}]},{"id":"x-gpu-k8s","module":"gpu-serving","lesson":"gpu-serving/gpus-on-kubernetes","title":"How a pod gets a GPU","summary":"From resource request to device.","actors":["Pod spec","Scheduler","Node","Device plugin","Container"],"steps":[{"f":0,"t":1,"l":"Request nvidia.com/gpu","n":"The pod asks for one GPU as a resource limit."},{"f":1,"t":1,"l":"Filter nodes","n":"The scheduler keeps only nodes that advertise a free GPU and whose taints the pod tolerates."},{"f":1,"t":2,"l":"Bind the pod","n":"The pod is assigned to a node and the kubelet takes over."},{"f":2,"t":3,"l":"Allocate a device","n":"The kubelet asks the device plugin for a GPU and receives its device paths and settings."},{"f":3,"t":4,"l":"Expose the GPU","n":"The container runtime mounts the GPU device files and driver libraries into the container."},{"f":4,"t":4,"l":"Run nvidia-smi","n":"Inside the container nvidia-smi lists the GPU and the model server can use it."}]},{"id":"f-gpu-oom","module":"gpu-serving","kind":"failure","lesson":"gpu-serving/monitoring-and-debugging-gpu-workloads","title":"Failure and recovery: the model server crashes under load","summary":"Cache runs out and a long request breaks it.","actors":["User","Server","GPU","Monitoring","Engineer"],"steps":[{"f":0,"t":1,"l":"Heavy traffic arrives","n":"Several users send long prompts at once after a product launch."},{"f":1,"t":2,"l":"Cache fills","n":"Each request needs KV cache, and the cache usage rises towards 100 percent."},{"f":1,"t":2,"l":"Allocation fails","n":"A new request needs a block that is not free and the GPU raises an out of memory error."},{"f":1,"t":0,"l":"Requests fail","n":"The server returns errors or restarts, and users see timeouts."},{"f":3,"t":4,"l":"Alert pages the engineer","n":"Alerts for restarts and error rate fire. Time to first token had been climbing for an hour."},{"f":4,"t":3,"l":"Read the metrics","n":"The engineer sees cache usage near 100 percent and a long waiting queue before the crash."},{"f":4,"t":1,"l":"Limit and scale","n":"The engineer lowers the maximum context length and concurrency and adds a replica."},{"f":4,"t":3,"l":"Add an early alert","n":"The team alerts on cache usage above 85 percent and on queue time so it can scale before a crash."}]},{"id":"x-os-boot","module":"openstack","lesson":"openstack/compute-flavors-images-and-scheduling","title":"Booting a server in OpenStack","summary":"From API call to ACTIVE.","actors":["User","Nova API","Scheduler","Compute node","Neutron and Glance"],"steps":[{"f":0,"t":1,"l":"openstack server create","n":"The user sends a token with the request. Nova checks it, checks quota and records the server in the database."},{"f":1,"t":2,"l":"Ask the scheduler","n":"A message on the queue asks the scheduler to choose a host."},{"f":2,"t":2,"l":"Filter and weigh","n":"Placement shows hosts with room, filters remove unsuitable ones, and the best is chosen."},{"f":2,"t":3,"l":"Send to the node","n":"The chosen compute node receives the build request through the message queue."},{"f":3,"t":4,"l":"Get image and network","n":"The node downloads the image from Glance and asks Neutron for a port with an address."},{"f":3,"t":3,"l":"Start the guest","n":"The node starts the guest through libvirt and the state moves from BUILD to ACTIVE."}]},{"id":"x-os-packet","module":"openstack","lesson":"openstack/neutron-networking-security-groups-and-floating-ips","title":"A packet from the internet to a server","summary":"Floating IP, router and security group.","actors":["Client","Router","Security group","Server"],"steps":[{"f":0,"t":1,"l":"Connect to the floating IP","n":"The client sends traffic to the public address of the floating IP."},{"f":1,"t":1,"l":"Translate the address","n":"The router maps the floating IP to the private address of the server using NAT."},{"f":1,"t":2,"l":"Check the rules","n":"The port security group is checked for an ingress rule matching protocol, port and source."},{"f":2,"t":3,"l":"Allow or drop","n":"If a rule allows it, the packet reaches the server. Otherwise it is dropped without a reply."},{"f":3,"t":3,"l":"Server firewall","n":"The operating system firewall inside the server also has to allow the connection."},{"f":3,"t":0,"l":"Reply goes back","n":"The reply is translated back to the floating IP and returned to the client."}]},{"id":"f-os-rabbit","module":"openstack","kind":"failure","lesson":"openstack/what-openstack-is-and-core-services","title":"Failure and recovery: the message queue stops","summary":"Every service reports errors at once.","actors":["Users","Nova and Neutron","RabbitMQ","Monitoring","Operator"],"steps":[{"f":2,"t":2,"l":"Disk fills on the controller","n":"Logs fill the disk where RabbitMQ stores its data, and the broker stops accepting messages."},{"f":1,"t":2,"l":"Services cannot send messages","n":"Nova, Neutron and Cinder cannot talk to each other through the queue."},{"f":1,"t":0,"l":"Requests fail","n":"New servers, ports and volumes fail or hang, and users see many different errors."},{"f":3,"t":4,"l":"Many alerts fire together","n":"Monitoring shows errors in every service at the same time, a sign of a shared dependency."},{"f":4,"t":2,"l":"Check the queue","n":"rabbitmqctl cluster_status fails and the disk on the controller is full."},{"f":4,"t":2,"l":"Free space and restart","n":"The operator removes old logs, restarts RabbitMQ and checks that the cluster is healthy."},{"f":4,"t":1,"l":"Verify services","n":"compute service list and network agent list show every service up again."},{"f":4,"t":3,"l":"Prevent a repeat","n":"The team adds disk alerts and queue depth monitoring and moves logs off the controller disk."}]},{"id":"x-bm-feeds","module":"baremetal","lesson":"baremetal/servers-racks-and-remote-management","title":"Two power feeds, one server","summary":"How redundant power keeps a server up when a feed fails.","actors":["Feed A","Feed B","Power supply 1","Power supply 2","Server"],"steps":[{"f":0,"t":2,"l":"Feed A powers PSU 1","n":"Power supply 1 takes mains power from feed A and shares the load with the second supply."},{"f":1,"t":3,"l":"Feed B powers PSU 2","n":"Power supply 2 takes power from feed B, a separate line from a separate breaker."},{"f":2,"t":4,"l":"Load is shared","n":"The server draws current from both supplies, each carrying about half of the load."},{"f":0,"t":0,"l":"Feed A fails","n":"A breaker trips or maintenance cuts feed A, so power supply 1 loses its input."},{"f":3,"t":4,"l":"PSU 2 takes over","n":"Power supply 2 now carries the whole load alone and the server keeps running."},{"f":4,"t":4,"l":"BMC logs redundancy lost","n":"The management controller writes a redundancy lost event so operators know one feed is gone."}]},{"id":"x-bm-bmc-cycle","module":"baremetal","lesson":"baremetal/servers-racks-and-remote-management","title":"Power cycling a hung server with the BMC","summary":"From a dead SSH session to a running server without leaving your desk.","actors":["Operator","BMC","Host OS","Hardware"],"steps":[{"f":0,"t":2,"l":"SSH times out","n":"The operator tries to log in. The host operating system has hung, so nothing answers."},{"f":0,"t":1,"l":"Ask the BMC for status","n":"ipmitool chassis power status goes to the BMC on its own network port, which still works."},{"f":1,"t":0,"l":"Power is on","n":"The BMC reports that power is on, so the hardware is up but the operating system is stuck."},{"f":0,"t":1,"l":"Read the event log","n":"ipmitool sel list shows recent hardware events, such as memory or temperature alarms."},{"f":0,"t":1,"l":"Power cycle","n":"ipmitool chassis power cycle asks the BMC to cut and restore power to the server."},{"f":1,"t":3,"l":"Hardware restarts","n":"The BMC switches power off and on and the server boots from its disk again."},{"f":2,"t":0,"l":"Host answers again","n":"SSH works once the operating system is back, and the operator records the cause from the event log."}]},{"id":"x-bm-pxe","module":"baremetal","lesson":"baremetal/provisioning-pxe-dhcp-and-images","title":"A PXE boot step by step","summary":"How a blank server finds and loads its installer from the network.","actors":["Server NIC","DHCP server","TFTP server","Installer"],"steps":[{"f":0,"t":1,"l":"DHCP discover","n":"The server has no disk to boot from, so its network card broadcasts a request for an address."},{"f":1,"t":0,"l":"Offer with next-server","n":"The DHCP server answers with an address, the next-server and the name of the boot file."},{"f":0,"t":2,"l":"Fetch the boot loader","n":"The firmware downloads the boot loader, such as grubx64.efi, from the TFTP server."},{"f":2,"t":0,"l":"Send loader and config","n":"TFTP sends the loader, which then asks for its configuration file and the kernel."},{"f":0,"t":3,"l":"Start the installer","n":"The loader starts the kernel and ramdisk, which run the installer with an answer file."},{"f":3,"t":3,"l":"Install unattended","n":"The installer partitions the disks, installs packages and reboots into the new system."}]},{"id":"x-bm-kickstart","module":"baremetal","lesson":"baremetal/provisioning-pxe-dhcp-and-images","title":"An unattended install with an answer file","summary":"What the installer reads so that nobody has to answer questions.","actors":["Installer","Answer file server","Disks","Config management"],"steps":[{"f":0,"t":1,"l":"Fetch the answer file","n":"The installer downloads a kickstart or autoinstall file from a web server named on the kernel line."},{"f":1,"t":0,"l":"Settings arrive","n":"The file describes the disk layout, packages, users and network settings for this class of server."},{"f":0,"t":2,"l":"Partition and format","n":"The installer creates the partitions, filesystems and RAID arrays that the file asks for."},{"f":0,"t":2,"l":"Install packages","n":"A minimal set of packages is written to disk, and the boot loader is installed."},{"f":0,"t":3,"l":"Register for configuration","n":"A first-boot step contacts the configuration tool so the machine gets its specific settings."},{"f":3,"t":3,"l":"Machine becomes specific","n":"Ansible or Puppet applies roles, so the generic install turns into a database or web server."}]},{"id":"x-bm-image","module":"baremetal","lesson":"baremetal/provisioning-pxe-dhcp-and-images","title":"Deploying an image with Ironic","summary":"Writing a prepared disk image to a bare metal node.","actors":["Operator","Ironic","BMC","Node","Image store"],"steps":[{"f":0,"t":1,"l":"Request a deploy","n":"The operator asks for a node with an image and a configuration drive, as if creating a cloud server."},{"f":1,"t":2,"l":"Power on through the BMC","n":"Ironic uses the node BMC to set network boot and power the machine on."},{"f":2,"t":3,"l":"Node boots an agent","n":"The node boots a small agent image from the network that waits for instructions."},{"f":3,"t":4,"l":"Agent downloads the image","n":"The agent pulls the requested disk image from the image store and writes it to the disk."},{"f":1,"t":2,"l":"Switch to disk boot","n":"Ironic changes the boot device to disk and reboots the node."},{"f":3,"t":0,"l":"Node is active","n":"cloud-init applies the keys and hostname, and the operator logs in to a running server."}]},{"id":"x-bm-rebuild","module":"baremetal","lesson":"baremetal/disks-raid-firmware-and-burn-in","title":"A RAID 1 rebuild","summary":"From a failed disk to a healthy mirror.","actors":["Monitoring","Operator","mdadm","Old disk","New disk"],"steps":[{"f":2,"t":0,"l":"Disk marked faulty","n":"mdadm drops the failing disk from the array, which becomes degraded but keeps serving data."},{"f":0,"t":1,"l":"Alert fires","n":"Monitoring alerts on a degraded array so someone acts before a second disk fails."},{"f":1,"t":3,"l":"Confirm with SMART","n":"The operator checks the disk with smartctl and sees failed health and reallocated sectors."},{"f":1,"t":2,"l":"Remove the faulty disk","n":"mdadm removes the failed device from the array, and the disk is pulled from the bay."},{"f":1,"t":4,"l":"Add the new disk","n":"The replacement is inserted and added to the array with mdadm --add."},{"f":2,"t":4,"l":"Copy the mirror","n":"mdadm copies every block from the surviving disk to the new one while the array stays online."},{"f":2,"t":1,"l":"Array is clean","n":"The state returns to clean and the operator closes the alert with a note in the inventory."}]},{"id":"x-bm-smart","module":"baremetal","lesson":"baremetal/disks-raid-firmware-and-burn-in","title":"Reading a SMART warning","summary":"How a disk reports its own decline before it fails.","actors":["Disk","smartd","Monitoring","Operator"],"steps":[{"f":0,"t":0,"l":"Sectors go bad","n":"The disk finds sectors it cannot read and remaps some to its spare area."},{"f":0,"t":1,"l":"smartd polls attributes","n":"The smartd service reads the SMART attributes every half hour and compares them with thresholds."},{"f":1,"t":2,"l":"Reallocated count rises","n":"The count of reallocated sectors rises across several polls, so smartd sends a warning."},{"f":2,"t":3,"l":"Ticket is raised","n":"Monitoring turns the warning into a ticket for the datacentre team with the serial number."},{"f":3,"t":0,"l":"Check the details","n":"The operator runs smartctl -a and sees pending sectors as well, a sign of a dying disk."},{"f":3,"t":3,"l":"Replace before failure","n":"The disk is replaced in a planned window, long before it takes the array down."}]},{"id":"x-bm-lacp","module":"baremetal","lesson":"baremetal/datacenter-networking-leaf-spine-and-bonding","title":"How an LACP bond forms","summary":"Two cables become one logical link.","actors":["Server eno1","Server eno2","Switch port 1","Switch port 2"],"steps":[{"f":0,"t":2,"l":"LACP packets leave","n":"The server sends LACP messages on each link saying that it wants to form an aggregate."},{"f":1,"t":3,"l":"Second link too","n":"The second interface does the same toward its own switch port."},{"f":2,"t":0,"l":"Switch answers","n":"Both switch ports are in one port channel and reply with matching keys."},{"f":3,"t":1,"l":"Keys match","n":"The server sees the same partner key on both links and groups them into one bond."},{"f":0,"t":2,"l":"Traffic is hashed","n":"Each flow is assigned to one link by a hash of addresses and ports, which keeps packets in order."},{"f":1,"t":3,"l":"Many flows use both","n":"With many connections, the load spreads across both links."}]},{"id":"x-bm-leafspine","module":"baremetal","lesson":"baremetal/datacenter-networking-leaf-spine-and-bonding","title":"A packet across a leaf-spine fabric","summary":"Three hops between racks.","actors":["Server A","Leaf 1","Spine","Leaf 2","Server B"],"steps":[{"f":0,"t":1,"l":"Frame to the top-of-rack","n":"Server A sends its packet to the leaf switch at the top of its rack."},{"f":1,"t":2,"l":"Choose a spine","n":"The leaf has equal-cost routes to every spine and picks one by hashing the flow."},{"f":2,"t":3,"l":"Spine forwards","n":"The spine knows which leaf holds the destination subnet and sends the packet there."},{"f":3,"t":4,"l":"Leaf delivers","n":"Leaf 2 delivers the packet to server B in its rack."},{"f":4,"t":0,"l":"Reply may use another spine","n":"The return path can take a different spine, which spreads load evenly."},{"f":2,"t":2,"l":"Add capacity","n":"Adding a spine adds a new path for every flow without changing any server."}]},{"id":"x-bm-dimm","module":"baremetal","lesson":"baremetal/operating-a-fleet-failures-lifecycle-and-capacity","title":"Replacing a failing DIMM","summary":"The routine for one sick server.","actors":["Monitoring","Operator","Scheduler","Server","Vendor"],"steps":[{"f":0,"t":1,"l":"ECC alert","n":"Monitoring shows repeated correctable ECC errors from one memory slot."},{"f":1,"t":2,"l":"Drain the host","n":"The operator cordons the server so workloads move to other machines first."},{"f":1,"t":3,"l":"Read the event log","n":"ipmitool sel elist confirms the same DIMM slot in every event and the operator notes it."},{"f":1,"t":4,"l":"Order the part","n":"The vendor ships a replacement under warranty, or a spare is taken from on-site stock."},{"f":1,"t":3,"l":"Swap and test","n":"The DIMM is replaced and a memory test runs for a short period to prove the fix."},{"f":1,"t":2,"l":"Return to service","n":"The host is uncordoned and the repair is recorded against its asset tag."}]},{"id":"x-bm-fail-feed","module":"baremetal","kind":"failure","lesson":"baremetal/servers-racks-and-remote-management","title":"Failure and recovery: a rack loses both feeds","summary":"Why redundancy failed and how it was restored.","actors":["Feed A","Feed B","Rack servers","On-call","Facilities"],"steps":[{"f":0,"t":0,"l":"Feed A fails","n":"A breaker trips on feed A, as the design allows for."},{"f":1,"t":2,"l":"Feed B takes the rack","n":"Feed B alone now carries every server, but the load is above its rated capacity."},{"f":1,"t":1,"l":"Feed B trips","n":"The breaker on feed B opens because the rack draws more than one feed can supply."},{"f":2,"t":3,"l":"Four servers go dark","n":"Monitoring shows servers lost at the same moment, with BMC events for lost power."},{"f":3,"t":4,"l":"Call facilities","n":"On-call confirms that both feeds are down and asks facilities to reset the breakers."},{"f":4,"t":2,"l":"Power restored","n":"Facilities reset the breakers and the servers boot, but the rack is still overloaded."},{"f":3,"t":3,"l":"Fix the cause","n":"The team moves servers out of the rack until one feed can carry the whole load, and adds a power budget to the capacity plan."}]},{"id":"x-bm-fail-reinstall","module":"baremetal","kind":"failure","lesson":"baremetal/provisioning-pxe-dhcp-and-images","title":"Failure and recovery: nodes in service reinstall themselves","summary":"Why a reboot wiped running servers.","actors":["Node","PXE server","Operator","Monitoring","Inventory"],"steps":[{"f":2,"t":1,"l":"Upgrade the PXE server","n":"The operator updates the provisioning stack and its DHCP configuration changes."},{"f":1,"t":1,"l":"It answers everyone","n":"The new configuration offers a boot file to every machine, not only machines marked for build."},{"f":0,"t":1,"l":"A node reboots","n":"A routine kernel update reboots a running node, which has network boot first in its boot order."},{"f":1,"t":0,"l":"Installer is offered","n":"The PXE server sends the installer, which repartitions and wipes the disks."},{"f":3,"t":2,"l":"Alerts fire","n":"Monitoring shows nodes disappearing and returning as empty machines."},{"f":2,"t":1,"l":"Stop the damage","n":"The operator stops the DHCP service and sets the boot order to disk first through the BMC."},{"f":2,"t":4,"l":"Rebuild and prevent","n":"Affected nodes are rebuilt from images, and the PXE server now answers only nodes marked as build in inventory."}]},{"id":"x-sm-pod2pod","module":"service-mesh","lesson":"service-mesh/kubernetes-networking-under-the-hood","title":"A packet from one pod to another","summary":"The path on a Kubernetes cluster with a CNI.","actors":["Pod A","Node 1","Network","Node 2","Pod B"],"steps":[{"f":0,"t":1,"l":"Leaves through its veth","n":"Pod A sends the packet out of its virtual ethernet pair into the network namespace of node 1."},{"f":1,"t":1,"l":"Route lookup","n":"Node 1 looks up the destination pod address and finds that it belongs to a pod range on node 2."},{"f":1,"t":2,"l":"Send over the network","n":"The CNI forwards the packet to node 2, either routed directly or wrapped in a VXLAN tunnel."},{"f":2,"t":3,"l":"Arrive at node 2","n":"Node 2 receives the packet, unwraps it if needed and finds the local route to pod B."},{"f":3,"t":4,"l":"Deliver to Pod B","n":"The packet enters pod B through its veth pair with the original source address intact."},{"f":4,"t":0,"l":"Reply returns","n":"Pod B answers and the same steps run in reverse, with no NAT in between."}]},{"id":"x-sm-service","module":"service-mesh","lesson":"service-mesh/kubernetes-networking-under-the-hood","title":"From a Service name to a pod","summary":"DNS, ClusterIP and kube-proxy working together.","actors":["Client pod","CoreDNS","kube-proxy rules","Pod 1","Pod 2"],"steps":[{"f":0,"t":1,"l":"Resolve web.shop","n":"The client asks CoreDNS for web.shop.svc.cluster.local."},{"f":1,"t":0,"l":"ClusterIP returned","n":"CoreDNS answers with the Service ClusterIP, a virtual address that no machine owns."},{"f":0,"t":2,"l":"Connect to the ClusterIP","n":"The client opens a connection and the node rules match the destination address."},{"f":2,"t":2,"l":"Pick an endpoint","n":"The rules choose one ready endpoint at random and rewrite the destination to the pod address."},{"f":2,"t":3,"l":"Reach the pod","n":"The connection goes to pod 1. Later connections may go to pod 2."},{"f":3,"t":0,"l":"Response returns","n":"The reply is rewritten back so the client believes it talked to the ClusterIP."}]},{"id":"x-sm-ingress","module":"service-mesh","lesson":"service-mesh/kubernetes-networking-under-the-hood","title":"A request through an Ingress","summary":"Traffic from the internet to a pod.","actors":["Browser","Load balancer","Ingress controller","Service","Pod"],"steps":[{"f":0,"t":1,"l":"Request arrives","n":"The browser sends an HTTPS request to the public address of the load balancer."},{"f":1,"t":2,"l":"Forward to the controller","n":"The load balancer passes the connection to one ingress controller pod running on a node."},{"f":2,"t":2,"l":"Match host and path","n":"The controller finishes TLS and matches the host and path against the Ingress rules."},{"f":2,"t":3,"l":"Route to the Service","n":"It sends the request to the Service named in the rule, using its endpoints directly."},{"f":3,"t":4,"l":"Reach a ready pod","n":"One ready pod receives the request and builds the response."},{"f":4,"t":0,"l":"Response returns","n":"The answer goes back along the same path to the browser."}]},{"id":"x-sm-netpol","module":"service-mesh","lesson":"service-mesh/cni-network-policy-and-ebpf","title":"How a network policy decides","summary":"What the CNI checks for each new connection.","actors":["Client pod","CNI datapath","Policy rules","Server pod"],"steps":[{"f":0,"t":1,"l":"Open a connection","n":"The client pod sends a SYN packet toward the server pod."},{"f":1,"t":2,"l":"Look up the identity","n":"The datapath finds the labels of the source pod and the destination pod."},{"f":2,"t":1,"l":"Evaluate rules","n":"The policy engine checks whether any rule allows this source, port and protocol."},{"f":1,"t":3,"l":"Allowed: forward","n":"If a rule matches, the packet is delivered and the connection is tracked."},{"f":1,"t":0,"l":"Denied: drop","n":"If no rule matches and the destination has a default deny, the packet is silently dropped."},{"f":0,"t":0,"l":"Client times out","n":"Because the packet is dropped, the client sees a timeout and not a refusal."}]},{"id":"x-sm-inject","module":"service-mesh","lesson":"service-mesh/what-a-service-mesh-is-and-how-it-works","title":"How a sidecar gets injected","summary":"Labelling a namespace and creating a pod.","actors":["Operator","API server","Injector webhook","Pod"],"steps":[{"f":0,"t":1,"l":"Label the namespace","n":"The operator sets istio-injection=enabled on the namespace."},{"f":0,"t":1,"l":"Create or restart a pod","n":"A deployment creates a new pod, because existing pods are never changed."},{"f":1,"t":2,"l":"Call the webhook","n":"The API server sends the pod definition to the mutating admission webhook of the mesh."},{"f":2,"t":1,"l":"Add the proxy","n":"The webhook adds an init container to redirect traffic and the istio-proxy sidecar container."},{"f":1,"t":3,"l":"Pod starts with two containers","n":"The pod starts with the app and the proxy, and shows 2/2 ready."},{"f":3,"t":3,"l":"Proxy receives config","n":"The proxy connects to the control plane and gets its listeners, routes and certificates."}]},{"id":"x-sm-mtls","module":"service-mesh","lesson":"service-mesh/mtls-and-traffic-management","title":"A mutual TLS handshake between sidecars","summary":"Identity on both sides of one call.","actors":["App A","Proxy A","Proxy B","App B","istiod"],"steps":[{"f":4,"t":1,"l":"Certificates issued","n":"istiod gave each proxy a short-lived certificate tied to its service account."},{"f":0,"t":1,"l":"Plain call to localhost","n":"App A sends an ordinary HTTP request. The traffic is redirected to its own proxy."},{"f":1,"t":2,"l":"Start TLS","n":"Proxy A opens a TLS connection to proxy B and presents its certificate."},{"f":2,"t":1,"l":"Present and verify","n":"Proxy B presents its certificate, and both sides check the other against the mesh root."},{"f":2,"t":3,"l":"Decrypt and deliver","n":"Proxy B decrypts the request and passes it to app B on localhost, with the caller identity attached."},{"f":3,"t":0,"l":"Response returns encrypted","n":"The reply travels back through both proxies and is encrypted on the wire."}]},{"id":"x-sm-canary","module":"service-mesh","lesson":"service-mesh/mtls-and-traffic-management","title":"A canary release with weights","summary":"Sending ten percent of traffic to version 2.","actors":["Client","Proxy","VirtualService","Reviews v1","Reviews v2"],"steps":[{"f":0,"t":1,"l":"Request leaves the client","n":"The client calls the reviews service. Its proxy intercepts the request."},{"f":1,"t":2,"l":"Look up the route","n":"The proxy consults the route rules it received for the host reviews."},{"f":2,"t":1,"l":"90 and 10","n":"The rule says ninety percent to subset v1 and ten percent to subset v2."},{"f":1,"t":3,"l":"Most go to v1","n":"Nine out of ten requests are sent to pods labelled version v1."},{"f":1,"t":4,"l":"Some go to v2","n":"One in ten requests reaches version 2, where errors and latency are watched."},{"f":2,"t":2,"l":"Raise the weight","n":"If metrics stay healthy, the operator edits the weights step by step until v2 takes all traffic."}]},{"id":"x-sm-retry","module":"service-mesh","lesson":"service-mesh/mtls-and-traffic-management","title":"Timeouts and retries on one call","summary":"What the proxy does when a backend is slow.","actors":["Client","Proxy","Backend 1","Backend 2"],"steps":[{"f":0,"t":1,"l":"Request starts a timer","n":"The proxy sets an overall timeout of two seconds for the request."},{"f":1,"t":2,"l":"First attempt","n":"The first try goes to backend 1 with a per-try timeout of 500 milliseconds."},{"f":2,"t":1,"l":"No answer in time","n":"The per-try timeout passes without a reply, so the proxy gives up on this attempt."},{"f":1,"t":3,"l":"Retry elsewhere","n":"A retry is sent to backend 2, a different endpoint, with a short random delay."},{"f":3,"t":1,"l":"Answer arrives","n":"Backend 2 replies in time and the proxy returns the response."},{"f":1,"t":0,"l":"Client sees success","n":"The client only sees a slightly slower success and never knew of the failed attempt."}]},{"id":"x-sm-outlier","module":"service-mesh","lesson":"service-mesh/mtls-and-traffic-management","title":"Outlier detection ejects a bad pod","summary":"Circuit breaking at the endpoint level.","actors":["Proxy","Pod 1","Pod 2","Pod 3"],"steps":[{"f":0,"t":1,"l":"Traffic spreads","n":"The proxy sends requests round-robin to three healthy pods."},{"f":1,"t":0,"l":"Pod 1 starts failing","n":"Pod 1 returns server errors on several consecutive requests."},{"f":0,"t":0,"l":"Threshold reached","n":"After five consecutive 5xx errors the proxy marks pod 1 as an outlier."},{"f":0,"t":1,"l":"Eject for a while","n":"Pod 1 is removed from the pool for thirty seconds, and no new requests are sent to it."},{"f":0,"t":2,"l":"Others take the load","n":"Pods 2 and 3 handle all traffic, so users no longer see the errors."},{"f":0,"t":1,"l":"Try again later","n":"After the ejection time the pod is tried again. If it fails it is ejected for longer."}]},{"id":"x-sm-push","module":"service-mesh","lesson":"service-mesh/observing-and-troubleshooting-the-mesh","title":"How configuration reaches the proxies","summary":"From kubectl apply to an updated route.","actors":["Operator","API server","istiod","Proxy"],"steps":[{"f":0,"t":1,"l":"Apply a VirtualService","n":"The operator applies a routing rule, and the API server stores it."},{"f":2,"t":1,"l":"istiod watches","n":"The control plane notices the change through its watch on the API server."},{"f":2,"t":2,"l":"Compute proxy config","n":"istiod translates the rule into Envoy listeners, routes, clusters and endpoints."},{"f":2,"t":3,"l":"Push over xDS","n":"It sends the new configuration to every affected proxy over a long-lived gRPC stream."},{"f":3,"t":2,"l":"Proxy acknowledges","n":"The proxy accepts or rejects the update and tells istiod."},{"f":0,"t":2,"l":"Check sync","n":"istioctl proxy-status shows SYNCED when the proxy has acknowledged the latest version."}]},{"id":"x-sm-fail-strict","module":"service-mesh","kind":"failure","lesson":"service-mesh/observing-and-troubleshooting-the-mesh","title":"Failure and recovery: STRICT mTLS breaks a caller","summary":"A plain text client meets a strict destination.","actors":["Platform team","Reviews proxy","Web (no sidecar)","Monitoring","On-call"],"steps":[{"f":0,"t":1,"l":"Set mode STRICT","n":"The platform team applies a PeerAuthentication in strict mode for the shop namespace."},{"f":2,"t":1,"l":"Plain text call","n":"The web pod has no sidecar, because it started before injection was enabled, so it calls in plain text."},{"f":1,"t":2,"l":"Connection reset","n":"The reviews proxy requires mTLS and resets the connection before any request is read."},{"f":3,"t":4,"l":"503 alerts fire","n":"Monitoring shows a spike in 503 errors on the storefront with response flag UF."},{"f":4,"t":1,"l":"Check the flag and policy","n":"On-call reads the proxy log, sees UF, and finds the recent PeerAuthentication change."},{"f":4,"t":0,"l":"Roll back to PERMISSIVE","n":"The mode is set back to permissive, which accepts both kinds of traffic, and errors stop."},{"f":4,"t":2,"l":"Fix the cause","n":"The web deployment is restarted so it gets a sidecar, then the mode is set to strict again safely."}]},{"id":"x-sm-fail-retry","module":"service-mesh","kind":"failure","lesson":"service-mesh/mtls-and-traffic-management","title":"Failure and recovery: a retry storm","summary":"How retries turned a slowdown into an outage.","actors":["Storefront","Orders","Inventory","Database","On-call"],"steps":[{"f":3,"t":3,"l":"Database slows","n":"A heavy report makes the database answer in seconds instead of milliseconds."},{"f":2,"t":3,"l":"Inventory times out and retries","n":"Inventory times out and retries its query three times for each request."},{"f":1,"t":2,"l":"Orders retries too","n":"Orders times out on inventory and retries three times, so each request becomes nine queries."},{"f":0,"t":1,"l":"Storefront retries again","n":"The storefront repeats the pattern and the database sees twenty-seven queries per user request."},{"f":3,"t":3,"l":"Database overloaded","n":"The database falls over under the multiplied load, and every service fails."},{"f":4,"t":0,"l":"Cut retries and shed load","n":"On-call removes inner retries, sets per-try timeouts and a retry budget, and enables outlier detection."},{"f":4,"t":3,"l":"Recovery","n":"Once the load drops back to normal, the database recovers and the services return."}]},{"id":"x-virt-kvm-trap","module":"virtualization","lesson":"virtualization/what-virtualization-is-and-hypervisor-types","title":"How a guest instruction runs on KVM","summary":"Most instructions run directly on the CPU; a few leave the guest.","actors":["Guest code","CPU","KVM module","QEMU"],"steps":[{"f":0,"t":1,"l":"Run directly","n":"Ordinary instructions in the guest, such as arithmetic, run on the real CPU at full speed."},{"f":0,"t":1,"l":"Privileged instruction","n":"The guest tries something only a kernel may do, such as touching a hardware register."},{"f":1,"t":2,"l":"Hardware exit","n":"The CPU stops the guest and hands control to the KVM module in the host kernel (a VM exit)."},{"f":2,"t":2,"l":"Handle simple cases","n":"KVM deals with simple causes itself, such as a timer or a page fault, and resumes the guest."},{"f":2,"t":3,"l":"Device access goes to QEMU","n":"If the guest touched a virtual device such as a disk controller, KVM passes the request to QEMU."},{"f":3,"t":0,"l":"Resume the guest","n":"QEMU emulates the device, KVM re-enters the guest and it continues as if real hardware answered."}]},{"id":"x-virt-vcpu","module":"virtualization","lesson":"virtualization/cpu-memory-and-overcommit","title":"Steal time on an oversubscribed host","summary":"Why a guest feels slow although its own load is low.","actors":["Guest vCPU","Host scheduler","Other guests","Monitoring"],"steps":[{"f":0,"t":1,"l":"Guest has work","n":"The guest wants to run a thread and its virtual CPU becomes ready."},{"f":2,"t":1,"l":"Other guests also ready","n":"Many other guests on the same cores are also busy, so more vCPUs want time than there are cores."},{"f":1,"t":2,"l":"Another vCPU runs","n":"The host scheduler runs a different guest vCPU first, and the first one waits in the queue."},{"f":1,"t":0,"l":"Guest finally runs","n":"After a delay the guest vCPU gets a core. The guest sees time pass without its code running."},{"f":0,"t":3,"l":"Steal time is reported","n":"The guest kernel counts the wait as steal time, shown as st in top and vmstat."},{"f":3,"t":1,"l":"Rebalance guests","n":"The operator moves a guest to another host or lowers the vCPU to core ratio, and steal time falls."}]},{"id":"x-virt-snapshot","module":"virtualization","lesson":"virtualization/virtual-disks-snapshots-and-templates","title":"A qcow2 snapshot chain","summary":"How writes after a snapshot go to a new layer.","actors":["Guest","Base image","Overlay","Admin"],"steps":[{"f":3,"t":1,"l":"Take a snapshot","n":"The admin takes a snapshot. The current disk image becomes read-only."},{"f":1,"t":2,"l":"Create an overlay","n":"A new overlay file is created that records only the blocks that change from now on."},{"f":0,"t":2,"l":"Guest writes","n":"All new writes from the guest go to the overlay, so the base image stays untouched."},{"f":0,"t":2,"l":"Reads check the overlay first","n":"A read looks in the overlay and falls back to the base image for blocks never changed."},{"f":2,"t":2,"l":"Overlay grows","n":"The longer the guest runs, the more blocks the overlay holds, and a chain of overlays slows reads."},{"f":3,"t":2,"l":"Commit or delete","n":"The admin merges the overlay back with a block commit or deletes the snapshot, which frees the space."}]},{"id":"x-virt-bridge","module":"virtualization","lesson":"virtualization/virtual-networking-bridges-and-vlans","title":"Traffic through a Linux bridge","summary":"From guest to physical network.","actors":["Guest NIC","tap device","Bridge br0","Physical NIC","Switch"],"steps":[{"f":0,"t":1,"l":"Guest sends a frame","n":"The guest virtual NIC writes a frame that appears on a tap device on the host."},{"f":1,"t":2,"l":"Bridge learns the source","n":"The bridge records that the guest MAC address lives behind this tap port."},{"f":2,"t":2,"l":"Look up the destination","n":"The bridge checks its table. Unknown or outside addresses go out of the uplink."},{"f":2,"t":3,"l":"Forward to the uplink","n":"The frame is sent to the physical NIC that is attached to the bridge."},{"f":3,"t":4,"l":"Leaves the host","n":"The frame reaches the physical switch, which forwards it on its VLAN."},{"f":4,"t":0,"l":"Reply returns","n":"The reply comes back through the same ports and the bridge delivers it to the right tap."}]},{"id":"x-virt-vlan","module":"virtualization","lesson":"virtualization/virtual-networking-bridges-and-vlans","title":"A VLAN tag on a trunk","summary":"Two networks over one cable.","actors":["Guest A (VLAN 10)","Guest B (VLAN 20)","Host bridge","Trunk port","Switch"],"steps":[{"f":0,"t":2,"l":"Guest A sends untagged","n":"Guest A sends a normal frame. It does not know about VLANs."},{"f":2,"t":2,"l":"Bridge adds tag 10","n":"The host bridge port for guest A is assigned VLAN 10, so the frame is tagged 10 on the way out."},{"f":1,"t":2,"l":"Guest B is tagged 20","n":"The same happens for guest B with VLAN 20, over the same uplink."},{"f":2,"t":3,"l":"One cable, two networks","n":"Both tagged frames leave through the trunk port that carries VLANs 10 and 20."},{"f":3,"t":4,"l":"Switch separates traffic","n":"The switch keeps VLAN 10 and VLAN 20 apart, so A and B cannot reach each other without a router."},{"f":4,"t":2,"l":"Return traffic is untagged","n":"On the way back the host removes the tag and delivers the frame to the correct guest."}]},{"id":"x-virt-precopy","module":"virtualization","lesson":"virtualization/live-migration-ha-and-troubleshooting","title":"Why a migration does not converge","summary":"A busy guest dirties memory faster than the network copies it.","actors":["Source host","Guest","Network","Destination host"],"steps":[{"f":0,"t":3,"l":"Copy round one","n":"The source starts copying every memory page of the guest to the destination."},{"f":1,"t":1,"l":"Guest keeps writing","n":"A busy database writes to memory the whole time, so pages already copied become stale again."},{"f":0,"t":3,"l":"Copy dirty pages","n":"Round two copies only the pages changed in round one, over the same network link."},{"f":2,"t":2,"l":"Link is the limit","n":"If the guest dirties pages faster than the link can carry them, each round is as large as the last."},{"f":0,"t":0,"l":"Migration stalls","n":"The migration never reaches the small final step, and the operator sees it still running after minutes."},{"f":0,"t":1,"l":"Throttle or compress","n":"The admin enables auto-converge to slow the guest or compression, and the final switch can finish."}]},{"id":"x-virt-ha","module":"virtualization","lesson":"virtualization/live-migration-ha-and-troubleshooting","title":"HA restarts guests after a host dies","summary":"What a cluster does when a host fails.","actors":["Failed host","Cluster manager","Fencing device","Surviving host","Guest"],"steps":[{"f":0,"t":1,"l":"Heartbeats stop","n":"The cluster manager stops receiving heartbeats from the host."},{"f":1,"t":1,"l":"Wait, then suspect","n":"After a timeout it marks the host as suspect, since a network cut would look the same."},{"f":1,"t":2,"l":"Fence the host","n":"It cuts power to the host through a fencing device, so the old guests cannot still be writing to the disks."},{"f":2,"t":1,"l":"Fencing confirmed","n":"The fencing device reports success, which is the only safe signal that the guests are really stopped."},{"f":1,"t":3,"l":"Restart guests elsewhere","n":"The manager restarts the guests on surviving hosts using the shared storage."},{"f":3,"t":4,"l":"Guests are back","n":"Each guest boots again, with a short outage, and the operator investigates the dead host."}]},{"id":"x-virt-template","module":"virtualization","lesson":"virtualization/virtual-disks-snapshots-and-templates","title":"Cloning from a template","summary":"How a new guest starts from a golden image.","actors":["Admin","Template image","Clone overlay","New guest"],"steps":[{"f":0,"t":1,"l":"Prepare a template","n":"The admin builds a clean guest, removes machine-specific data and keeps it as a read-only template."},{"f":0,"t":2,"l":"Create a linked clone","n":"A new overlay is created that uses the template as its backing file, which takes seconds."},{"f":2,"t":3,"l":"Boot the new guest","n":"The new guest boots from the overlay and reads unchanged blocks from the template."},{"f":3,"t":3,"l":"First boot setup","n":"cloud-init sets the hostname, keys and network, so the clone becomes a distinct machine."},{"f":3,"t":2,"l":"Writes stay local","n":"All changes go to the clone overlay, so the template is never modified by guests."},{"f":0,"t":1,"l":"Update the template","n":"A patched template is built later and new clones use it, while old ones keep their old base."}]},{"id":"x-virt-fail-pool","module":"virtualization","kind":"failure","lesson":"virtualization/virtual-disks-snapshots-and-templates","title":"Failure and recovery: the pool fills and guests pause","summary":"Old snapshots consume the storage pool.","actors":["Guests","Storage pool","Monitoring","Operator","Snapshots"],"steps":[{"f":4,"t":1,"l":"Snapshots grow","n":"Snapshots taken weeks ago keep growing as guests write, and nobody reviews them."},{"f":1,"t":1,"l":"Pool reaches 98 percent","n":"Free space shrinks until the pool has almost nothing left for new writes."},{"f":0,"t":1,"l":"Writes fail","n":"A guest tries to write a new block, the host cannot allocate space, and the guest is paused with an I/O error."},{"f":2,"t":3,"l":"Alert fires too late","n":"Monitoring alerts only on the guest pause, because pool usage had no threshold alert."},{"f":3,"t":4,"l":"Find the biggest snapshots","n":"The operator lists snapshots per guest with the hypervisor tools and finds two old ones."},{"f":3,"t":4,"l":"Delete the stale ones","n":"Using the proper command merges or drops the chain safely, and the pool gains free space."},{"f":3,"t":0,"l":"Resume and prevent","n":"Guests are resumed, and the team adds pool usage alerts and a snapshot expiry policy."}]},{"id":"x-st-write","module":"storage","lesson":"storage/filesystems-ext4-xfs-and-mounts","title":"A write through the page cache","summary":"Why data is not on disk when write returns.","actors":["Application","Page cache","Filesystem journal","Disk"],"steps":[{"f":0,"t":1,"l":"write() returns fast","n":"The application writes data and the kernel stores it in the page cache in memory, then returns."},{"f":1,"t":1,"l":"Data marked dirty","n":"The pages are marked dirty and wait for a later flush, so a power cut now would lose them."},{"f":0,"t":1,"l":"fsync is requested","n":"A careful program calls fsync to demand that the data and metadata reach stable storage."},{"f":1,"t":2,"l":"Journal first","n":"The filesystem writes the intent to its journal so a crash can be recovered consistently."},{"f":2,"t":3,"l":"Flush to disk","n":"The journal and data blocks are written to the device, which may have its own cache."},{"f":3,"t":0,"l":"fsync returns","n":"Only now does the call return, so the application knows the data should survive a power loss."}]},{"id":"x-st-mount","module":"storage","lesson":"storage/filesystems-ext4-xfs-and-mounts","title":"What happens at boot when fstab is wrong","summary":"A bad line in /etc/fstab and a stuck boot.","actors":["systemd","fstab","Missing disk","Operator"],"steps":[{"f":0,"t":1,"l":"Read fstab","n":"At boot systemd reads /etc/fstab and creates a mount unit for each line."},{"f":0,"t":2,"l":"Look for the device","n":"One line names a device by /dev/sdb1, but after a hardware change the name has moved."},{"f":2,"t":0,"l":"Device not found","n":"systemd waits for the device until a timeout of about ninety seconds and then marks the mount failed."},{"f":0,"t":0,"l":"Dependent services fail","n":"Services that need that mount are skipped and the system drops into emergency mode."},{"f":3,"t":1,"l":"Fix with a UUID","n":"The operator edits the line to use UUID=... from blkid, and adds nofail for non-critical mounts."},{"f":3,"t":0,"l":"Boot continues","n":"mount -a succeeds without errors, and the machine starts normally after a reboot."}]},{"id":"x-st-lvm-extend","module":"storage","lesson":"storage/lvm-and-raid","title":"Growing a logical volume online","summary":"Add space to a mounted filesystem without downtime.","actors":["Admin","Volume group","Logical volume","Filesystem"],"steps":[{"f":0,"t":1,"l":"Check free extents","n":"vgs shows free space in the volume group. If none, a new disk must be added to the group first."},{"f":0,"t":2,"l":"Extend the volume","n":"lvextend -L +20G adds twenty gigabytes of extents to the logical volume."},{"f":2,"t":2,"l":"Device is larger","n":"The block device is bigger now, but the filesystem on it still thinks it has the old size."},{"f":0,"t":3,"l":"Grow the filesystem","n":"resize2fs for ext4 or xfs_growfs for XFS expands the filesystem while it stays mounted."},{"f":3,"t":0,"l":"Space appears","n":"df -h now shows the extra capacity and applications keep running throughout."},{"f":0,"t":1,"l":"Record the change","n":"The admin notes the new size and checks that the volume group still has headroom."}]},{"id":"x-st-raid5","module":"storage","lesson":"storage/lvm-and-raid","title":"Writing to RAID 5 and the write penalty","summary":"Why small writes cost four I/Os.","actors":["Application","RAID controller","Data disk","Parity disk"],"steps":[{"f":0,"t":1,"l":"Small write arrives","n":"The application changes one block in the array."},{"f":1,"t":2,"l":"Read old data","n":"The controller must first read the old data block from its disk."},{"f":1,"t":3,"l":"Read old parity","n":"It also reads the old parity block for that stripe."},{"f":1,"t":1,"l":"Compute new parity","n":"New parity is old parity XOR old data XOR new data, calculated in memory."},{"f":1,"t":2,"l":"Write data","n":"The new data block is written to the data disk."},{"f":1,"t":3,"l":"Write parity","n":"The new parity block is written, giving four I/Os for one logical write, which is the write penalty."}]},{"id":"x-st-nfs","module":"storage","lesson":"storage/network-storage-nfs-iscsi-and-ceph","title":"An NFS mount and a read","summary":"From open to bytes.","actors":["Client app","NFS client","Network","NFS server","Export"],"steps":[{"f":0,"t":1,"l":"open() on a mounted path","n":"The application opens a file under /mnt/shared as if it were local."},{"f":1,"t":3,"l":"LOOKUP request","n":"The NFS client sends a request to the server asking for the file handle of that name."},{"f":3,"t":4,"l":"Check export and permissions","n":"The server checks the export rules and the file permissions for the caller."},{"f":3,"t":1,"l":"Handle returned","n":"The server replies with a file handle that identifies the file on the server."},{"f":1,"t":3,"l":"READ request","n":"A read of a range of bytes goes to the server, over TCP, and may be cached on the client."},{"f":3,"t":0,"l":"Data returned","n":"The bytes arrive and the application sees them. A slow network shows up as slow reads."}]},{"id":"x-st-ceph","module":"storage","lesson":"storage/network-storage-nfs-iscsi-and-ceph","title":"Ceph places an object","summary":"No central lookup table.","actors":["Client","CRUSH map","Primary OSD","Replica OSDs"],"steps":[{"f":0,"t":1,"l":"Compute placement","n":"The client hashes the object name to a placement group and uses CRUSH to find which OSDs hold it."},{"f":0,"t":2,"l":"Write to the primary","n":"No central server is asked. The client talks directly to the primary OSD for that group."},{"f":2,"t":3,"l":"Replicate","n":"The primary sends the write to the replica OSDs on other hosts, as the failure domain rules require."},{"f":3,"t":2,"l":"Replicas acknowledge","n":"Each replica confirms that the data is safely stored."},{"f":2,"t":0,"l":"Acknowledge the client","n":"Only after all replicas respond does the primary tell the client the write is complete."},{"f":1,"t":1,"l":"OSD fails later","n":"If an OSD dies, CRUSH recomputes placement and the cluster copies data to restore the replica count."}]},{"id":"x-st-df-du","module":"storage","lesson":"storage/performance-backups-and-troubleshooting","title":"df says full but du disagrees","summary":"A deleted file that is still open.","actors":["Operator","df","du","Process","Filesystem"],"steps":[{"f":0,"t":1,"l":"Check free space","n":"df -h shows the volume at 100 percent used."},{"f":0,"t":2,"l":"Look for big files","n":"du -sh finds only a fraction of that space in visible files."},{"f":0,"t":0,"l":"Numbers disagree","n":"The gap means space is held by something that is not in any directory."},{"f":0,"t":3,"l":"List deleted open files","n":"lsof +L1 shows a log file that was deleted while a process still has it open."},{"f":3,"t":4,"l":"Space is held","n":"The kernel cannot free the blocks until the last process closes the file descriptor."},{"f":0,"t":3,"l":"Restart or truncate","n":"Restarting the process, or truncating through /proc, releases the space and df drops."}]},{"id":"x-st-backup","module":"storage","lesson":"storage/performance-backups-and-troubleshooting","title":"A backup you can restore","summary":"The restore test is part of the backup.","actors":["Scheduler","Backup job","Backup store","Restore test","Operator"],"steps":[{"f":0,"t":1,"l":"Run nightly","n":"The scheduler starts the backup job at night when load is low."},{"f":1,"t":2,"l":"Copy and verify","n":"The job copies data to the backup store and checks the size and checksums."},{"f":1,"t":4,"l":"Report status","n":"The job sends a result with size and duration, and an alert fires if it is missing."},{"f":0,"t":3,"l":"Weekly restore test","n":"Once a week another job restores a sample into a scratch system."},{"f":3,"t":3,"l":"Check the content","n":"The test opens the restored database or files and compares counts with the source."},{"f":3,"t":4,"l":"Report the result","n":"A failed restore raises an alert, so a backup that cannot be restored is found early."}]},{"id":"x-st-fail-inodes","module":"storage","kind":"failure","lesson":"storage/filesystems-ext4-xfs-and-mounts","title":"Failure and recovery: out of inodes","summary":"Creating files fails although space is free.","actors":["Application","Filesystem","Operator","Cleanup job","Monitoring"],"steps":[{"f":0,"t":1,"l":"Millions of small files","n":"A service writes one tiny file per request into a single directory."},{"f":1,"t":1,"l":"Inodes run out","n":"The filesystem has free blocks but every inode is used, so it cannot describe a new file."},{"f":0,"t":1,"l":"Writes fail","n":"The application sees no space left on device errors while df -h shows 40 percent free."},{"f":4,"t":2,"l":"Alert fires","n":"Errors reach monitoring, but disk usage looks fine, which confuses the first responder."},{"f":2,"t":1,"l":"Check inodes","n":"df -i shows 100 percent of inodes used, which explains the failure."},{"f":2,"t":3,"l":"Clean up old files","n":"The operator removes expired files in batches and finds the directory that holds millions of them."},{"f":2,"t":1,"l":"Prevent a repeat","n":"The team adds inode alerts, changes the app to a directory tree or object storage, and sizes inodes at mkfs."}]},{"id":"x-sq-plan","module":"sql-ops","lesson":"sql-ops/reading-explain-and-finding-slow-queries","title":"How the planner picks a plan","summary":"From SQL text to a chosen strategy.","actors":["Client","Parser","Planner","Statistics","Executor"],"steps":[{"f":0,"t":1,"l":"Send the query","n":"The client sends SQL. The parser checks the syntax and builds a tree of the request."},{"f":1,"t":2,"l":"Hand over the tree","n":"The planner receives the tree and lists possible ways to run it, such as index scan or full scan."},{"f":2,"t":3,"l":"Ask for statistics","n":"It reads table statistics for row counts and value distributions to estimate the cost of each way."},{"f":2,"t":2,"l":"Pick the cheapest","n":"The plan with the lowest estimated cost wins, even if the estimate is wrong."},{"f":2,"t":4,"l":"Run the plan","n":"The executor runs it step by step and returns rows to the client."},{"f":4,"t":0,"l":"Compare estimate and actual","n":"EXPLAIN ANALYZE shows both. A big gap points to stale statistics."}]},{"id":"x-sq-index","module":"sql-ops","lesson":"sql-ops/indexes-that-help-and-indexes-that-hurt","title":"An index lookup versus a scan","summary":"Why the same query takes 4 ms or 4 seconds.","actors":["Query","Planner","Index","Table"],"steps":[{"f":0,"t":1,"l":"Filter by customer_id","n":"The query asks for the orders of one customer from a table of fifty million rows."},{"f":1,"t":3,"l":"No index: scan","n":"Without an index the planner must read every row of the table and test each one."},{"f":1,"t":2,"l":"With an index: search","n":"With an index on customer_id the planner descends a small tree to the matching entries."},{"f":2,"t":3,"l":"Fetch matching rows","n":"Only the few rows found are fetched from the table."},{"f":3,"t":0,"l":"Fast answer","n":"A handful of reads returns in milliseconds, instead of reading the whole table."},{"f":2,"t":2,"l":"Cost on writes","n":"Every insert and update must also update the index, which is why unneeded indexes hurt."}]},{"id":"x-sq-deadlock","module":"sql-ops","lesson":"sql-ops/locks-deadlocks-and-long-transactions","title":"A deadlock between two transactions","summary":"Each waits for a lock held by the other.","actors":["Transaction A","Transaction B","Row 1","Row 2","Database"],"steps":[{"f":0,"t":2,"l":"A locks row 1","n":"Transaction A updates row 1 and holds a lock on it."},{"f":1,"t":3,"l":"B locks row 2","n":"Transaction B updates row 2 and holds a lock on it."},{"f":0,"t":3,"l":"A wants row 2","n":"Transaction A now tries to update row 2 and waits for B."},{"f":1,"t":2,"l":"B wants row 1","n":"Transaction B tries to update row 1 and waits for A, so neither can continue."},{"f":4,"t":4,"l":"Detect the cycle","n":"After a short timeout the database finds the cycle of waits."},{"f":4,"t":1,"l":"Abort one","n":"It aborts one transaction with a deadlock error, the other proceeds, and the application retries the failed one."}]},{"id":"x-sq-pool","module":"sql-ops","lesson":"sql-ops/connections-pooling-and-capacity","title":"A pooler in front of the database","summary":"Many clients, few server connections.","actors":["App instances","PgBouncer","Database","Monitoring"],"steps":[{"f":0,"t":1,"l":"Hundreds of clients connect","n":"Each app instance opens many connections, far more than the database should hold."},{"f":1,"t":1,"l":"Pool shares connections","n":"The pooler keeps a small number of server connections and hands them out per transaction."},{"f":1,"t":2,"l":"Few connections reach the database","n":"The database sees twenty active connections instead of five hundred."},{"f":2,"t":1,"l":"Queries return","n":"Results flow back through the pooler to the right client."},{"f":1,"t":0,"l":"Waiting clients queue","n":"When all server connections are busy, new requests wait briefly rather than overloading the database."},{"f":3,"t":1,"l":"Watch the queue","n":"Monitoring tracks waiting clients and pool usage, a sign of capacity limits."}]},{"id":"x-sq-repl","module":"sql-ops","lesson":"sql-ops/replication-lag-vacuum-and-day-two-operations","title":"Replication lag builds up","summary":"A replica falls behind the primary.","actors":["Primary","WAL stream","Replica","Reader app"],"steps":[{"f":0,"t":1,"l":"Primary writes WAL","n":"Every change is written to the write-ahead log and streamed to the replica."},{"f":1,"t":2,"l":"Replica replays","n":"The replica applies the log records in order to stay current."},{"f":2,"t":2,"l":"A long query blocks replay","n":"A long reporting query on the replica holds old row versions that replay must wait for."},{"f":1,"t":2,"l":"WAL piles up","n":"New log records arrive faster than they are applied, and lag grows to minutes."},{"f":3,"t":2,"l":"Readers see old data","n":"The application reads stale values from the replica and users report missing changes."},{"f":2,"t":2,"l":"Fix the cause","n":"Moving heavy reports elsewhere or tuning conflict settings lets replay catch up and lag fall."}]},{"id":"x-sq-vacuum","module":"sql-ops","lesson":"sql-ops/replication-lag-vacuum-and-day-two-operations","title":"Vacuum reclaims dead rows","summary":"Updates leave old versions behind.","actors":["Application","Table","Autovacuum","Planner"],"steps":[{"f":0,"t":1,"l":"UPDATE creates a new row version","n":"PostgreSQL writes a new version and keeps the old one for transactions that may still need it."},{"f":1,"t":1,"l":"Dead rows pile up","n":"Once no transaction needs the old versions they are dead but still take space."},{"f":2,"t":1,"l":"Autovacuum wakes up","n":"When dead rows pass a threshold, autovacuum scans the table and marks that space reusable."},{"f":2,"t":3,"l":"Update statistics","n":"It also refreshes statistics so the planner makes good choices."},{"f":1,"t":1,"l":"Space is reused","n":"New rows fit into the freed space and the table stops growing."},{"f":0,"t":1,"l":"Long transactions block it","n":"An old open transaction prevents cleanup, so bloat grows even when vacuum runs."}]},{"id":"x-sq-migrate","module":"sql-ops","lesson":"sql-ops/indexes-that-help-and-indexes-that-hurt","title":"Adding an index without blocking writes","summary":"CREATE INDEX CONCURRENTLY step by step.","actors":["Operator","Database","Table","Writers"],"steps":[{"f":0,"t":1,"l":"Start a concurrent build","n":"The operator runs CREATE INDEX CONCURRENTLY, which does not take a lock that blocks writes."},{"f":1,"t":2,"l":"First scan","n":"The database scans the table once and builds the index while writers continue."},{"f":3,"t":2,"l":"Writers keep going","n":"Inserts and updates run normally, and their changes are recorded for the next pass."},{"f":1,"t":2,"l":"Second scan","n":"A second pass adds the changes made during the first scan."},{"f":1,"t":1,"l":"Wait for old transactions","n":"The build waits for transactions that started before it, then marks the index valid."},{"f":0,"t":1,"l":"Verify and use","n":"The operator checks the index is valid and confirms the plan now uses it."}]},{"id":"x-sq-fail-conn","module":"sql-ops","kind":"failure","lesson":"sql-ops/connections-pooling-and-capacity","title":"Failure and recovery: connections exhausted","summary":"Every afternoon the API starts failing.","actors":["API pods","Database","Monitoring","Operator","Pooler"],"steps":[{"f":0,"t":1,"l":"Traffic peak opens connections","n":"At 15:00 traffic rises and each pod opens more connections to handle it."},{"f":1,"t":1,"l":"Slots run out","n":"The database reaches max_connections and refuses new ones with a reserved-slots error."},{"f":0,"t":0,"l":"Requests fail","n":"The API returns errors, and retries open even more connections, making it worse."},{"f":2,"t":3,"l":"Alerts fire","n":"Monitoring shows errors and a database connection count at its limit."},{"f":3,"t":1,"l":"Find who holds them","n":"pg_stat_activity shows most connections idle in transaction from one service."},{"f":3,"t":4,"l":"Add a pooler and fix the leak","n":"A pooler caps server connections and the service is fixed to close transactions promptly."},{"f":3,"t":2,"l":"Alert on usage","n":"The team alerts on connection usage at 80 percent so the next rise is seen before errors."}]},{"id":"x-gp-request","module":"gpu-serving","lesson":"gpu-serving/serving-stacks-vllm-tgi-triton","title":"One LLM request through a serving stack","summary":"From prompt to streamed tokens.","actors":["Client","Server","Scheduler","GPU","KV cache"],"steps":[{"f":0,"t":1,"l":"Send a prompt","n":"The client sends a prompt and starts waiting for a streaming response."},{"f":1,"t":2,"l":"Queue the request","n":"The server tokenises the prompt and adds it to the scheduler queue."},{"f":2,"t":3,"l":"Prefill","n":"The GPU processes all prompt tokens in parallel and builds the key and value tensors."},{"f":3,"t":4,"l":"Store the KV cache","n":"Those tensors are kept in GPU memory so later tokens need not recompute them."},{"f":3,"t":0,"l":"Decode token by token","n":"Each step generates one token using the cache and streams it to the client."},{"f":2,"t":4,"l":"Free the cache at the end","n":"When the answer finishes, the cache memory is released for other requests."}]},{"id":"x-gp-batching","module":"gpu-serving","lesson":"gpu-serving/serving-stacks-vllm-tgi-triton","title":"Continuous batching","summary":"New requests join a running batch.","actors":["Request A","Request B","Scheduler","GPU"],"steps":[{"f":0,"t":2,"l":"A is running","n":"Request A is generating tokens as part of the current batch."},{"f":1,"t":2,"l":"B arrives","n":"Request B arrives while A is still running."},{"f":2,"t":2,"l":"Static batching would wait","n":"A static batcher would make B wait until the whole batch finished, wasting time."},{"f":2,"t":3,"l":"Add B at the next step","n":"Continuous batching adds B to the batch at the very next decode step."},{"f":3,"t":0,"l":"A finishes early","n":"When A finishes, its slot is freed at once and a waiting request can use it."},{"f":3,"t":1,"l":"GPU stays busy","n":"The GPU always has a full batch, so throughput is much higher at similar latency."}]},{"id":"x-gp-sched","module":"gpu-serving","lesson":"gpu-serving/gpus-on-kubernetes","title":"Scheduling a pod onto a GPU","summary":"From a resource request to a running container.","actors":["Pod spec","Scheduler","Device plugin","Node","Container"],"steps":[{"f":0,"t":1,"l":"Request nvidia.com/gpu: 1","n":"The pod asks for one GPU in its resource limits."},{"f":2,"t":3,"l":"Plugin advertises GPUs","n":"The device plugin on each GPU node reports how many GPUs it has to the kubelet."},{"f":1,"t":3,"l":"Find a node with capacity","n":"The scheduler picks a node with a free GPU and all other requirements met."},{"f":3,"t":2,"l":"Allocate a device","n":"The kubelet asks the device plugin to allocate a specific GPU for the pod."},{"f":3,"t":4,"l":"Mount device and libraries","n":"The container runtime exposes the GPU device and driver libraries inside the container."},{"f":4,"t":4,"l":"Workload sees the GPU","n":"nvidia-smi inside the container lists the GPU, and the model can load."}]},{"id":"x-gp-tp","module":"gpu-serving","lesson":"gpu-serving/gpu-basics-memory-and-what-limits-inference","title":"Tensor parallelism across GPUs","summary":"One model split over two cards.","actors":["Request","GPU 0","GPU 1","Interconnect"],"steps":[{"f":0,"t":1,"l":"Model too big for one card","n":"The weights do not fit in the memory of a single GPU."},{"f":1,"t":2,"l":"Split each layer","n":"Every layer is divided, so GPU 0 and GPU 1 each hold half of its weights."},{"f":1,"t":1,"l":"Compute a half","n":"Both GPUs compute their half of the layer at the same time on the same input."},{"f":1,"t":3,"l":"Exchange partial results","n":"They combine the halves with an all-reduce over the interconnect after each layer."},{"f":3,"t":2,"l":"Link speed matters","n":"On a slow link the exchange dominates, which is why NVLink is preferred inside one node."},{"f":2,"t":0,"l":"Output token","n":"After the last layer a token is produced, with some cost in communication for the benefit of fitting the model."}]},{"id":"x-gp-autoscale","module":"gpu-serving","lesson":"gpu-serving/scaling-latency-and-cost","title":"Scaling on queue depth","summary":"Why CPU is the wrong signal for a GPU service.","actors":["Requests","Metrics","Autoscaler","Replicas"],"steps":[{"f":0,"t":3,"l":"Load rises","n":"More requests arrive and replicas start to queue them."},{"f":3,"t":1,"l":"GPU utilisation is already high","n":"The GPU shows high use even at modest load, so it tells little about spare capacity."},{"f":3,"t":1,"l":"Queue length rises","n":"The number of waiting requests and the time to first token increase."},{"f":1,"t":2,"l":"Autoscaler reads the queue","n":"The autoscaler uses queue depth or latency as its scaling signal."},{"f":2,"t":3,"l":"Add a replica","n":"A new replica is scheduled, but loading a model can take minutes."},{"f":3,"t":0,"l":"Latency recovers","n":"Once the new replica is ready the queue drains, and warm spare capacity avoids the delay next time."}]},{"id":"x-gp-quant","module":"gpu-serving","lesson":"gpu-serving/gpu-basics-memory-and-what-limits-inference","title":"Quantisation to fit a model","summary":"Trading precision for memory.","actors":["Model weights","Quantiser","GPU memory","Evaluation"],"steps":[{"f":0,"t":2,"l":"16-bit weights do not fit","n":"A 70-billion parameter model needs about 140 GB at 16 bits, more than one card holds."},{"f":0,"t":1,"l":"Reduce the precision","n":"The quantiser stores weights in 8 or 4 bits, shrinking the memory by two to four times."},{"f":1,"t":2,"l":"Fits with room for the cache","n":"The smaller weights leave GPU memory for the KV cache and more concurrent requests."},{"f":2,"t":3,"l":"Measure the quality","n":"The team runs evaluation prompts and compares answers with the full-precision model."},{"f":3,"t":1,"l":"Pick the lowest safe precision","n":"If quality loss is acceptable, the quantised model is used, otherwise a milder format is chosen."},{"f":1,"t":2,"l":"Throughput improves","n":"Smaller weights also mean less memory traffic, so tokens per second often rise."}]},{"id":"x-gp-cold","module":"gpu-serving","lesson":"gpu-serving/scaling-latency-and-cost","title":"A cold start of a model replica","summary":"Why a new pod takes minutes to serve.","actors":["Scheduler","Node","Pod","Model store","GPU"],"steps":[{"f":0,"t":1,"l":"Pod is scheduled","n":"The scheduler places the pod on a node with a free GPU."},{"f":1,"t":2,"l":"Pull the image","n":"The node pulls a container image of several gigabytes, which is slow the first time."},{"f":2,"t":3,"l":"Download the weights","n":"The server downloads tens of gigabytes of model weights from storage."},{"f":2,"t":4,"l":"Load into GPU memory","n":"The weights are copied into GPU memory and the server compiles its kernels."},{"f":2,"t":2,"l":"Readiness probe passes","n":"Only now does the pod report ready and receive traffic."},{"f":1,"t":1,"l":"Speed it up","n":"Baking weights into a cache volume or a node-local disk shortens the next start."}]},{"id":"x-gp-monitor","module":"gpu-serving","lesson":"gpu-serving/monitoring-and-debugging-gpu-workloads","title":"Reading GPU health signals","summary":"What the metrics say about a slow service.","actors":["Operator","DCGM metrics","GPU","Serving logs"],"steps":[{"f":0,"t":1,"l":"Open the GPU dashboard","n":"The operator looks at utilisation, memory use, temperature and clocks."},{"f":1,"t":2,"l":"Memory near the limit","n":"Memory use sits at 98 percent, so the KV cache has no room for more requests."},{"f":1,"t":2,"l":"Clocks are throttled","n":"The clock speed has dropped because of temperature, which lowers throughput."},{"f":0,"t":3,"l":"Check serving logs","n":"The logs show requests waiting in the queue and some preempted for lack of cache space."},{"f":0,"t":2,"l":"Decide the fix","n":"Lower the maximum context length, add a replica or cool the node, depending on the signal."},{"f":0,"t":1,"l":"Confirm after the change","n":"Latency and queue length drop, and the memory graph leaves a safe margin."}]},{"id":"x-gp-fail-oom","module":"gpu-serving","kind":"failure","lesson":"gpu-serving/gpu-basics-memory-and-what-limits-inference","title":"Failure and recovery: CUDA out of memory","summary":"A model server crashes on a long prompt.","actors":["Client","Server","GPU","Monitoring","Operator"],"steps":[{"f":0,"t":1,"l":"Long prompt arrives","n":"A user sends a prompt with a very long context."},{"f":1,"t":2,"l":"KV cache grows","n":"The cache for that request grows with the context and competes with other requests for memory."},{"f":2,"t":2,"l":"Memory runs out","n":"The GPU raises a CUDA out of memory error and the process dies."},{"f":3,"t":4,"l":"Restart loop alert","n":"Monitoring shows the pod restarting and requests failing with 503."},{"f":4,"t":2,"l":"Compare model and limits","n":"The operator compares the weights, cache size and max context against the card memory."},{"f":4,"t":1,"l":"Lower limits","n":"The server is configured with a smaller max context and a GPU memory utilisation cap below 100 percent."},{"f":4,"t":3,"l":"Alert on memory","n":"The team adds memory headroom alerts and a request limit, so one long prompt cannot take the service down."}]},{"id":"x-os-boot2","module":"openstack","lesson":"openstack/compute-flavors-images-and-scheduling","title":"Booting a server in OpenStack","summary":"From API call to ACTIVE.","actors":["User","Nova API","Scheduler","Compute node","Neutron and Cinder"],"steps":[{"f":0,"t":1,"l":"openstack server create","n":"The user asks for a server with an image, a flavor and a network. The token is checked first."},{"f":1,"t":2,"l":"Scheduler picks a host","n":"The scheduler asks Placement which hosts have enough CPU, memory and disk and picks one."},{"f":2,"t":3,"l":"Message to the compute node","n":"A message over the queue tells the chosen node to build the instance."},{"f":3,"t":4,"l":"Network and volume","n":"The node asks Neutron for a port and Cinder for any volume, then downloads the image."},{"f":3,"t":3,"l":"Libvirt starts the guest","n":"Nova calls libvirt, which starts the virtual machine with the requested resources."},{"f":3,"t":0,"l":"Status ACTIVE","n":"The server reports ACTIVE. If any step fails, it shows ERROR with a fault message."}]},{"id":"x-os-token","module":"openstack","lesson":"openstack/identity-projects-quotas-and-keystone","title":"Authenticating with Keystone","summary":"Getting and using a token.","actors":["Client","Keystone","Nova","Policy"],"steps":[{"f":0,"t":1,"l":"Send credentials","n":"The client sends user, password, domain and project to Keystone."},{"f":1,"t":1,"l":"Check them","n":"Keystone validates the credentials and the role assignment on the project."},{"f":1,"t":0,"l":"Return a token and catalog","n":"A scoped token and the service catalog with endpoint addresses come back."},{"f":0,"t":2,"l":"Call Nova with the token","n":"The client calls the Nova endpoint and presents the token in a header."},{"f":2,"t":1,"l":"Validate the token","n":"Nova (through middleware) asks Keystone whether the token is valid and for which project and roles."},{"f":2,"t":3,"l":"Check policy","n":"The policy decides whether those roles may perform the action, then Nova carries it out."}]},{"id":"x-os-secgroup","module":"openstack","lesson":"openstack/neutron-networking-security-groups-and-floating-ips","title":"Traffic to a floating IP","summary":"Following an SSH connection.","actors":["Client","Router NAT","Security group","Server"],"steps":[{"f":0,"t":1,"l":"Connect to the floating IP","n":"The client opens an SSH connection to the public floating IP address."},{"f":1,"t":1,"l":"Translate the address","n":"The Neutron router maps the floating IP to the private address of the server."},{"f":1,"t":2,"l":"Check ingress rules","n":"The packet is checked against the security group rules attached to the port."},{"f":2,"t":2,"l":"Rule allows or drops","n":"If no rule allows port 22 from the client, the packet is silently dropped and SSH times out."},{"f":2,"t":3,"l":"Allowed: deliver","n":"With a matching rule the packet reaches the server and sshd answers."},{"f":3,"t":0,"l":"Reply returns","n":"Stateful tracking lets the reply go back through the router with the floating IP as its source."}]},{"id":"x-os-quota","module":"openstack","lesson":"openstack/identity-projects-quotas-and-keystone","title":"A quota stops a request","summary":"The request is refused before any host is chosen.","actors":["User","Nova API","Quota check","Admin"],"steps":[{"f":0,"t":1,"l":"Request 8 cores","n":"The user creates a server needing 8 cores."},{"f":1,"t":2,"l":"Check usage against limits","n":"Nova counts the project usage, 16 of 20 cores, and adds the new request."},{"f":2,"t":1,"l":"Limit exceeded","n":"The total of 24 is above 20, so the check fails."},{"f":1,"t":0,"l":"403 Quota exceeded","n":"The user gets a quota exceeded error that is a rule, not a fault."},{"f":0,"t":3,"l":"Ask or clean up","n":"The user either deletes unused servers or asks an admin for a higher limit."},{"f":3,"t":2,"l":"Raise the quota","n":"The admin raises the cores limit for the project and the request can succeed."}]},{"id":"x-os-upgrade","module":"openstack","lesson":"openstack/operating-openstack-logs-upgrades-and-troubleshooting","title":"A rolling upgrade","summary":"Controller by controller.","actors":["Operator","Controller 1","Controller 2","Compute nodes","Database"],"steps":[{"f":0,"t":0,"l":"Read release notes","n":"The operator reads the notes for the upgrade path and database migrations."},{"f":0,"t":4,"l":"Back up the database","n":"A full backup is taken and tested, because migrations cannot always be reversed."},{"f":0,"t":1,"l":"Upgrade the first controller","n":"The services on controller 1 are upgraded and the database schema is migrated."},{"f":1,"t":2,"l":"Second controller still serves","n":"Controller 2 keeps serving API calls with the older code during the change."},{"f":0,"t":3,"l":"Upgrade compute nodes in waves","n":"Compute agents are upgraded a few at a time, with checks that guests keep running."},{"f":0,"t":1,"l":"Verify services","n":"Service lists, test servers and logs confirm that every component runs the new version."}]},{"id":"x-os-volume","module":"openstack","lesson":"openstack/compute-flavors-images-and-scheduling","title":"Attaching a Cinder volume","summary":"Block storage to a running server.","actors":["User","Cinder","Nova","Compute node","Server"],"steps":[{"f":0,"t":1,"l":"Create a volume","n":"The user asks Cinder for a 100 GB volume, and the backend (such as Ceph) allocates it."},{"f":0,"t":2,"l":"Attach to the server","n":"The user asks Nova to attach the volume to a running server."},{"f":2,"t":1,"l":"Get connection info","n":"Nova asks Cinder how to reach the volume, for example the Ceph pool and image."},{"f":2,"t":3,"l":"Compute node connects","n":"The node connects to the backend and presents the volume to libvirt."},{"f":3,"t":4,"l":"Guest sees a new disk","n":"A block device such as /dev/vdb appears inside the server."},{"f":4,"t":4,"l":"Format and mount","n":"The user creates a filesystem and mounts it, and the data now lives on the volume, not the server disk."}]},{"id":"x-os-migrate","module":"openstack","lesson":"openstack/operating-openstack-logs-upgrades-and-troubleshooting","title":"Evacuating a failed compute node","summary":"Moving servers off a dead host.","actors":["Monitoring","Operator","Nova","Dead node","Healthy node"],"steps":[{"f":0,"t":1,"l":"Node reported down","n":"Monitoring shows nova-compute down on one node and its servers unreachable."},{"f":1,"t":2,"l":"Confirm it is really down","n":"The operator checks the service list and the BMC, and powers the node off to avoid two copies running."},{"f":1,"t":2,"l":"Evacuate","n":"nova evacuate rebuilds each server on another host using shared storage or the same image."},{"f":2,"t":4,"l":"Servers rebuilt","n":"Healthy nodes start the servers, which keep their addresses and volumes."},{"f":1,"t":3,"l":"Repair the node","n":"The failed node is repaired or replaced before returning to service."},{"f":1,"t":2,"l":"Enable it again","n":"nova-compute is enabled on the repaired node and scheduling resumes."}]},{"id":"x-os-image","module":"openstack","lesson":"openstack/compute-flavors-images-and-scheduling","title":"Image caching on compute nodes","summary":"Why the second boot is faster.","actors":["Glance","Compute node","Cache","Server"],"steps":[{"f":1,"t":0,"l":"First boot needs the image","n":"The node asks Glance for the image because it has no local copy."},{"f":0,"t":1,"l":"Download","n":"Glance streams the image over the network, which takes time for a large image."},{"f":1,"t":2,"l":"Store in the cache","n":"Nova keeps the base image in a local cache directory on the node."},{"f":1,"t":3,"l":"Create the instance disk","n":"The instance disk is a copy or an overlay on top of the cached base image."},{"f":1,"t":2,"l":"Second boot uses the cache","n":"A later boot of the same image finds it in the cache and starts much faster."},{"f":1,"t":2,"l":"Old images are cleaned","n":"Unused cached images are removed after a period, so disk space is reclaimed."}]},{"id":"x-os-fail-nohost","module":"openstack","kind":"failure","lesson":"openstack/compute-flavors-images-and-scheduling","title":"Failure and recovery: No valid host was found","summary":"A server goes to ERROR at scheduling time.","actors":["User","Nova","Scheduler","Placement","Admin"],"steps":[{"f":0,"t":1,"l":"Create a large server","n":"The user requests a flavor with 64 GB of memory."},{"f":1,"t":2,"l":"Scheduler asks Placement","n":"The scheduler asks for hosts that can fit the request."},{"f":2,"t":3,"l":"No host fits","n":"Placement returns no candidates, because no node has enough free memory in one piece."},{"f":2,"t":1,"l":"Fail the request","n":"The scheduler gives up and the server goes to ERROR with No valid host was found."},{"f":0,"t":4,"l":"Report the error","n":"The user reports the failure and the admin reads the fault in server show."},{"f":4,"t":3,"l":"Check capacity","n":"The admin compares free memory per hypervisor and finds the largest block is 48 GB."},{"f":4,"t":0,"l":"Fix and retry","n":"The admin adds a node or the user picks a smaller flavor, and the retry succeeds."}]},{"id":"x-sq-explain-analyze","module":"sql-ops","lesson":"sql-ops/reading-explain-and-finding-slow-queries","title":"Finding the slow step in a plan","summary":"Reading EXPLAIN ANALYZE from the inside out.","actors":["Operator","EXPLAIN ANALYZE","Plan node","Fix"],"steps":[{"f":0,"t":1,"l":"Run with ANALYZE","n":"The operator runs EXPLAIN (ANALYZE, BUFFERS) so the query really executes and timings are real."},{"f":1,"t":2,"l":"Read the innermost nodes first","n":"Each node shows actual time and rows; the deepest nodes feed the ones above."},{"f":2,"t":2,"l":"Compare estimate and actual rows","n":"A node that expected 10 rows but returned 2 million shows bad statistics."},{"f":2,"t":2,"l":"Spot the expensive node","n":"A sequential scan on a large table with a filter that removes most rows takes most of the time."},{"f":0,"t":3,"l":"Choose a fix","n":"Add an index, rewrite the filter, or run ANALYZE so the planner sees real distributions."},{"f":0,"t":1,"l":"Run it again","n":"The new plan shows an index scan and a fall in time, which confirms the fix."}]},{"id":"x-cf-native","module":"cfn-bicep","lesson":"cfn-bicep/native-iac-cloudformation-bicep-or-terraform","title":"Where state lives in each tool","summary":"The cloud keeps state for native tools, while you keep it for Terraform.","actors":["Engineer","CloudFormation","Terraform","Cloud"],"steps":[{"f":0,"t":1,"l":"Submit a template","n":"The engineer sends a template and CloudFormation records it as a stack."},{"f":1,"t":3,"l":"Create resources","n":"The service creates the resources and tracks them itself, so no state file is needed."},{"f":0,"t":2,"l":"Run terraform apply","n":"With Terraform the engineer plans and applies from their own machine or pipeline."},{"f":2,"t":2,"l":"Write state","n":"Terraform writes what it created to a state file in a backend that the team must protect."},{"f":2,"t":3,"l":"Create resources","n":"Terraform calls the same cloud APIs to build the resources."},{"f":0,"t":2,"l":"State is lost","n":"If the state file is corrupted, Terraform no longer knows what it owns until it is repaired."}]},{"id":"x-cf-template","module":"cfn-bicep","lesson":"cfn-bicep/cloudformation-templates-parameters-and-resources","title":"Deploying a CloudFormation stack","summary":"Validation, deploy and events show the path from file to resources.","actors":["Engineer","CLI","CloudFormation","Resources"],"steps":[{"f":0,"t":1,"l":"Validate","n":"The engineer runs validate-template to catch syntax errors early."},{"f":0,"t":1,"l":"Deploy","n":"The deploy command uploads the template with parameter values."},{"f":1,"t":2,"l":"Create the stack","n":"CloudFormation reads the template and builds a plan of resources and dependencies."},{"f":2,"t":3,"l":"Create in order","n":"It creates resources in dependency order, such as the role before the function."},{"f":2,"t":1,"l":"Stream events","n":"Each resource status is reported as an event the CLI prints."},{"f":2,"t":0,"l":"Stack complete","n":"The stack reaches CREATE_COMPLETE and outputs become available."}]},{"id":"x-cf-func","module":"cfn-bicep","lesson":"cfn-bicep/intrinsic-functions-conditions-and-mappings","title":"Resolving a template at deploy time","summary":"Parameters, mappings and conditions turn one template into an environment.","actors":["Parameters","Mappings","Conditions","Resources"],"steps":[{"f":0,"t":1,"l":"Env is prod","n":"The deployer passes Env=prod as a parameter."},{"f":0,"t":1,"l":"Lookup size","n":"FindInMap uses Env to read the instance type m5.large from the mapping."},{"f":0,"t":2,"l":"Evaluate IsProd","n":"The condition IsProd becomes true because Env equals prod."},{"f":2,"t":3,"l":"Create the alarm","n":"The alarm resource guarded by IsProd is created."},{"f":1,"t":3,"l":"Apply the size","n":"The server resource receives the looked-up instance type."},{"f":3,"t":3,"l":"Dev differs","n":"With Env=dev the alarm is skipped and a smaller instance is used from the same file."}]},{"id":"x-cf-change","module":"cfn-bicep","lesson":"cfn-bicep/stacks-change-sets-and-safe-updates","title":"Reading a change set before updating","summary":"The preview shows replacement before data is lost.","actors":["Engineer","Change set","Reviewer","Stack"],"steps":[{"f":0,"t":1,"l":"Create change set","n":"The engineer proposes the new template without applying it."},{"f":1,"t":1,"l":"Compute the diff","n":"CloudFormation compares the new template to the running stack."},{"f":1,"t":2,"l":"Show the changes","n":"The change set lists Modify Database with Replacement True."},{"f":2,"t":2,"l":"Stop and think","n":"The reviewer sees that replacement would delete the database and asks for a snapshot policy."},{"f":0,"t":1,"l":"Adjust and recreate","n":"The engineer adds UpdateReplacePolicy Snapshot and creates a new change set."},{"f":2,"t":3,"l":"Approve","n":"The reviewer approves, the change set is executed and the stack updates safely."}]},{"id":"x-cf-nested","module":"cfn-bicep","lesson":"cfn-bicep/nested-stacks-stacksets-and-reusable-modules","title":"A StackSet rollout","summary":"One template reaches many accounts with a stop on failure.","actors":["Admin","StackSet","Account A","Account B"],"steps":[{"f":0,"t":1,"l":"Create the StackSet","n":"The admin defines a baseline role template and the target accounts."},{"f":1,"t":2,"l":"Deploy to account A","n":"The first batch deploys the stack to account A."},{"f":1,"t":3,"l":"Deploy to account B","n":"Account B receives the stack in the same batch within the concurrency limit."},{"f":3,"t":1,"l":"One failure","n":"Account B reports a failure because a role name already exists."},{"f":1,"t":1,"l":"Failure tolerance","n":"The tolerance of one failure is reached, so the rollout stops before reaching more accounts."},{"f":0,"t":1,"l":"Fix and resume","n":"The admin fixes the conflict and resumes the operation."}]},{"id":"x-cf-drift","module":"cfn-bicep","lesson":"cfn-bicep/drift-rollbacks-and-resource-protection","title":"Drift detection finds a manual change","summary":"A console edit is found and reconciled through code.","actors":["Engineer","Cloud console","CloudFormation","Resource"],"steps":[{"f":0,"t":1,"l":"Quick fix by hand","n":"An engineer opens a security group port in the console during an incident."},{"f":1,"t":3,"l":"Resource changes","n":"The real security group now differs from the template."},{"f":2,"t":3,"l":"Detect drift","n":"A scheduled drift detection compares actual properties with the template."},{"f":2,"t":0,"l":"Report MODIFIED","n":"The report shows the expected and actual values for the changed rule."},{"f":0,"t":2,"l":"Decide","n":"The team decides the rule is not needed and re-applies the stack."},{"f":2,"t":3,"l":"Back in sync","n":"The resource matches the template again and the manual change is gone."}]},{"id":"x-cf-bicep","module":"cfn-bicep","lesson":"cfn-bicep/bicep-syntax-resources-and-parameters","title":"From Bicep file to Azure resources","summary":"The compiler checks the file and Resource Manager creates resources.","actors":["Engineer","Bicep compiler","Resource Manager","Resource group"],"steps":[{"f":0,"t":1,"l":"Write main.bicep","n":"The engineer writes parameters, a storage account resource and an output."},{"f":1,"t":1,"l":"Compile","n":"The Bicep compiler checks types and produces an ARM template."},{"f":1,"t":2,"l":"Submit deployment","n":"The ARM template and parameters are sent to Azure Resource Manager."},{"f":2,"t":2,"l":"Order the work","n":"Resource Manager reads references and decides which resources come first."},{"f":2,"t":3,"l":"Create resources","n":"The storage account is created inside the resource group."},{"f":2,"t":0,"l":"Return outputs","n":"The blob endpoint is returned as a deployment output."}]},{"id":"x-cf-module","module":"cfn-bicep","lesson":"cfn-bicep/bicep-modules-loops-and-conditions","title":"A module with a loop","summary":"One module creates a subnet for each name in a list.","actors":["Main file","Module","Loop","vnet"],"steps":[{"f":0,"t":1,"l":"Call the module","n":"main.bicep passes the vnet name and a list of subnet names."},{"f":1,"t":3,"l":"Create the vnet","n":"The module declares the virtual network first."},{"f":1,"t":2,"l":"Loop over names","n":"A for expression creates one subnet resource for each name."},{"f":2,"t":3,"l":"Subnets attach","n":"Each subnet is created as a child of the vnet with its own address range."},{"f":1,"t":0,"l":"Return outputs","n":"The module returns the vnet id for other modules to use."},{"f":0,"t":1,"l":"Add a name later","n":"Adding one more name to the list creates one more subnet and leaves the others untouched."}]},{"id":"x-cf-whatif","module":"cfn-bicep","lesson":"cfn-bicep/bicep-deployments-what-if-and-scopes","title":"What-if prevents a surprise delete","summary":"The preview exposes a delete that complete mode would perform.","actors":["Pipeline","What-if","Reviewer","Azure"],"steps":[{"f":0,"t":1,"l":"Run what-if","n":"The pipeline runs what-if for the pull request before any deployment."},{"f":1,"t":3,"l":"Compare with Azure","n":"The preview compares the template with the current resource group contents."},{"f":1,"t":2,"l":"Show results","n":"It lists a Create, a Modify and a Delete for a virtual machine."},{"f":2,"t":2,"l":"Spot the delete","n":"The reviewer notices the template was run in complete mode with a partial file."},{"f":2,"t":0,"l":"Change the mode","n":"The pipeline is switched to incremental mode and the template is completed."},{"f":0,"t":3,"l":"Deploy safely","n":"The deployment now adds and updates resources without deleting the VM."}]},{"id":"x-cf-oidc","module":"cfn-bicep","lesson":"cfn-bicep/deployment-stacks-and-delivery-pipelines","title":"A pipeline using a federated identity","summary":"No secret is stored because a short-lived token is exchanged.","actors":["Pipeline","CI provider","Cloud identity","Cloud"],"steps":[{"f":0,"t":1,"l":"Job starts","n":"The pipeline job starts and requests an OIDC token from the CI provider."},{"f":1,"t":0,"l":"Token issued","n":"The token states the repository, branch and environment of the job."},{"f":0,"t":2,"l":"Present the token","n":"The pipeline presents it to the cloud identity service."},{"f":2,"t":2,"l":"Check the trust rule","n":"The cloud checks that the token matches the rule allowing only the main branch to deploy."},{"f":2,"t":0,"l":"Short-lived credentials","n":"The cloud returns credentials that expire in about an hour."},{"f":0,"t":3,"l":"Deploy","n":"The pipeline deploys with these credentials, and nothing secret was ever stored."}]},{"id":"x-cf-lint","module":"cfn-bicep","lesson":"cfn-bicep/testing-linting-and-policy-checks-for-templates","title":"Checks before a template merges","summary":"Lint, policy and preview run in a fixed order.","actors":["Developer","Linter","Policy engine","CI"],"steps":[{"f":0,"t":3,"l":"Open a pull request","n":"The developer pushes a template change and CI starts."},{"f":3,"t":1,"l":"Lint","n":"cfn-lint checks the syntax and property names and reports no errors."},{"f":3,"t":2,"l":"Policy check","n":"cfn-guard evaluates the rule that security groups must not allow SSH from anywhere."},{"f":2,"t":3,"l":"Rule fails","n":"The check reports the offending rule and its location."},{"f":3,"t":0,"l":"Merge blocked","n":"The pull request cannot merge until the source range is narrowed."},{"f":0,"t":3,"l":"Fix and push","n":"The developer fixes the rule, all checks pass and the preview is attached for review."}]},{"id":"x-cf-failevents","module":"cfn-bicep","lesson":"cfn-bicep/debugging-failed-deployments-and-moving-to-terraform","title":"Failure and recovery: a stack create fails","summary":"The first failed event holds the real reason.","actors":["Engineer","CloudFormation","Resource","CloudTrail"],"steps":[{"f":0,"t":1,"l":"Deploy","n":"The engineer deploys a stack and sees a vague message that creation failed."},{"f":1,"t":2,"l":"Resource creation fails","n":"One bucket is rejected because its name is already used in another account."},{"f":1,"t":1,"l":"Rollback starts","n":"CloudFormation cancels the remaining resources and begins to roll back."},{"f":0,"t":1,"l":"Read the events","n":"The engineer lists stack events and looks at the earliest failure, not the last."},{"f":1,"t":0,"l":"Find the reason","n":"The event says the bucket name already exists, which explains all the later cancellations."},{"f":0,"t":1,"l":"Delete the failed stack","n":"A stack stuck in ROLLBACK_COMPLETE cannot be updated, so it is deleted."},{"f":0,"t":1,"l":"Redeploy","n":"The template now lets CloudFormation generate the name and the deploy is repeated."},{"f":1,"t":3,"l":"Check who changed what","n":"CloudTrail confirms the pipeline role made the calls, with no permission problems."}],"kind":"failure"},{"id":"x-cf-faildrift","module":"cfn-bicep","lesson":"cfn-bicep/drift-rollbacks-and-resource-protection","title":"Failure and recovery: replacement deletes a database","summary":"A small change replaced a database and the team recovers from a snapshot.","actors":["Engineer","Stack","Database","Backup"],"steps":[{"f":0,"t":1,"l":"Update the stack","n":"The engineer changes a database property and runs the update directly."},{"f":1,"t":2,"l":"Replacement","n":"The property requires replacement, so a new empty database is created."},{"f":1,"t":2,"l":"Old one deleted","n":"The old database is deleted when the update completes."},{"f":0,"t":2,"l":"Orders missing","n":"The application starts and reports that all tables are empty."},{"f":0,"t":3,"l":"Find the backup","n":"The engineer finds the last automated snapshot from earlier that day."},{"f":3,"t":2,"l":"Restore","n":"A new database is restored from the snapshot and the application is pointed at it."},{"f":0,"t":1,"l":"Add protection","n":"UpdateReplacePolicy Snapshot, DeletionPolicy and a change set review step are added."},{"f":1,"t":2,"l":"Safe next time","n":"Future replacements keep a snapshot and are reviewed before they run."}],"kind":"failure"},{"id":"x-gc-hier","module":"gcp","lesson":"gcp/google-cloud-organization-projects-and-billing","title":"A policy flowing down the hierarchy","summary":"A rule set at the top applies to every project below.","actors":["Admin","Organization","Folder","Project"],"steps":[{"f":0,"t":1,"l":"Set a policy","n":"The admin sets an organization policy that blocks service account key creation."},{"f":1,"t":2,"l":"Inherited by folders","n":"Every folder under the organization receives the constraint automatically."},{"f":2,"t":3,"l":"Inherited by projects","n":"The production project inherits it, so nobody there can create keys."},{"f":3,"t":3,"l":"A user tries","n":"A developer runs the create key command in the project."},{"f":3,"t":0,"l":"Request denied","n":"The call fails with an organization policy error that names the constraint."},{"f":0,"t":2,"l":"Exception at folder level","n":"The admin may allow an exception for one sandbox folder only, and it is recorded."}]},{"id":"x-gc-cli","module":"gcp","lesson":"gcp/gcloud-cli-configurations-and-automation","title":"Choosing the right project for a command","summary":"A named configuration decides which project receives the command.","actors":["Engineer","gcloud","Configuration","API"],"steps":[{"f":0,"t":1,"l":"Run a command","n":"The engineer types gcloud compute instances list."},{"f":1,"t":2,"l":"Read the configuration","n":"gcloud reads the active configuration for the account, project and region."},{"f":2,"t":1,"l":"Project returned","n":"The configuration says acme-pay-dev, so the command targets dev."},{"f":1,"t":3,"l":"Call the API","n":"gcloud sends the request using the engineer's credentials."},{"f":3,"t":1,"l":"Check IAM","n":"The API verifies the engineer has permission in that project and returns the list."},{"f":0,"t":2,"l":"Switch explicitly","n":"For production the engineer passes --project so the target is stated in the command."}]},{"id":"x-gc-vpc","module":"gcp","lesson":"gcp/vpc-networks-subnets-and-firewall-rules","title":"A packet through firewall rules","summary":"Implied deny and priority decide whether traffic is allowed.","actors":["Client","Load balancer","Firewall","VM"],"steps":[{"f":0,"t":1,"l":"Request arrives","n":"A client sends HTTPS to the load balancer's public address."},{"f":1,"t":2,"l":"Forward to the backend","n":"The load balancer sends the request to a VM on port 8080 from a Google range."},{"f":2,"t":2,"l":"Evaluate rules","n":"Rules are checked by priority and the lowest number that matches decides."},{"f":2,"t":3,"l":"Allow rule matches","n":"A rule allows tcp:8080 from the load balancer ranges to the web service account."},{"f":3,"t":1,"l":"VM answers","n":"The VM sends its response back through the same path."},{"f":2,"t":2,"l":"Other traffic denied","n":"A direct connection from the internet to port 22 matches no allow rule and is dropped."}]},{"id":"x-gc-mig","module":"gcp","lesson":"gcp/compute-engine-images-and-managed-instance-groups","title":"Autoscaling and autohealing in a MIG","summary":"The group adds capacity under load and replaces a failing VM.","actors":["Load","Autoscaler","Instance group","Health check"],"steps":[{"f":0,"t":1,"l":"Load rises","n":"CPU across the group climbs above the 60 percent target."},{"f":1,"t":2,"l":"Scale out","n":"The autoscaler asks the group to add instances up to the maximum."},{"f":2,"t":2,"l":"New VMs start","n":"The group creates VMs from the template in several zones."},{"f":3,"t":2,"l":"Instance fails","n":"The health check marks one VM unhealthy after repeated failures."},{"f":2,"t":2,"l":"Recreate","n":"The group deletes that VM and creates a fresh one from the template."},{"f":1,"t":2,"l":"Scale in later","n":"When load falls the autoscaler removes extra instances after a cooldown."}]},{"id":"x-gc-storage","module":"gcp","lesson":"gcp/cloud-storage-and-persistent-disks","title":"An object through its lifecycle","summary":"Lifecycle rules move data to colder classes and then delete it.","actors":["Application","Bucket","Lifecycle","Archive class"],"steps":[{"f":0,"t":1,"l":"Upload","n":"The application writes an export file to a Standard class bucket."},{"f":1,"t":1,"l":"Read often at first","n":"For the first weeks the file is read daily at Standard prices."},{"f":2,"t":1,"l":"After 30 days","n":"A lifecycle rule changes the storage class to Nearline."},{"f":2,"t":3,"l":"After 90 days","n":"Another rule moves the file to Archive for the cheapest keeping cost."},{"f":2,"t":1,"l":"After one year","n":"A final rule deletes the object, as required by the retention policy."},{"f":0,"t":1,"l":"Overwrite","n":"If someone overwrites the file, versioning keeps the previous version until it expires."}]},{"id":"x-gc-gke","module":"gcp","lesson":"gcp/gke-autopilot-and-standard-clusters","title":"A pod using Workload Identity","summary":"The pod gets short-lived Google credentials without any key file.","actors":["Pod","Kubernetes API","Metadata server","Google API"],"steps":[{"f":0,"t":1,"l":"Pod starts","n":"The pod runs with a Kubernetes service account that is annotated with a Google service account."},{"f":0,"t":2,"l":"Ask for a token","n":"The client library calls the GKE metadata server for credentials."},{"f":2,"t":1,"l":"Verify the mapping","n":"The metadata server checks the Kubernetes service account and its binding."},{"f":2,"t":0,"l":"Short-lived token","n":"A token for the Google service account is returned and expires within the hour."},{"f":0,"t":3,"l":"Call the API","n":"The pod calls Cloud Storage with the token."},{"f":3,"t":0,"l":"Allowed by IAM","n":"IAM sees the Google service account has the bucket role and returns the data."}]},{"id":"x-gc-run","module":"gcp","lesson":"gcp/cloud-run-and-cloud-functions","title":"A request scaling Cloud Run","summary":"Instances start on demand and stop when there is no traffic.","actors":["Client","Cloud Run","Revision","Database"],"steps":[{"f":0,"t":1,"l":"First request after idle","n":"No instance is running, so the platform starts one from the container image."},{"f":1,"t":2,"l":"Cold start","n":"The container starts and listens on the port, which adds a short delay."},{"f":2,"t":3,"l":"Query database","n":"The instance handles the request and reads from the database."},{"f":2,"t":0,"l":"Response","n":"The reply goes back to the client."},{"f":0,"t":1,"l":"Traffic grows","n":"Concurrency fills, so more instances are added up to the maximum."},{"f":1,"t":2,"l":"Scale to zero","n":"After the idle period the extra instances are removed and cost stops."}]},{"id":"x-gc-db","module":"gcp","lesson":"gcp/cloud-sql-spanner-bigquery-and-firestore","title":"Cloud SQL failover","summary":"The standby takes over when the primary zone fails.","actors":["Application","Primary","Standby","Backup"],"steps":[{"f":0,"t":1,"l":"Normal writes","n":"The application writes to the primary instance in zone A."},{"f":1,"t":2,"l":"Replicate","n":"Every committed change is copied to the standby in zone B."},{"f":1,"t":1,"l":"Zone fails","n":"Zone A becomes unavailable and the primary stops answering."},{"f":2,"t":2,"l":"Promote","n":"The standby is promoted to primary, usually in about a minute."},{"f":0,"t":2,"l":"Reconnect","n":"The application reconnects to the same address and resumes writing."},{"f":2,"t":3,"l":"Backups continue","n":"Automated backups and point-in-time logs keep running for recovery."}]},{"id":"x-gc-pubsub","module":"gcp","lesson":"gcp/pub-sub-eventarc-and-cloud-tasks","title":"Ack deadline and redelivery","summary":"A message handled too slowly is delivered again.","actors":["Publisher","Topic","Subscriber","Dead-letter topic"],"steps":[{"f":0,"t":1,"l":"Publish","n":"The publisher sends a message to the topic."},{"f":1,"t":2,"l":"Deliver","n":"The subscription pushes it to the subscriber with a 10 second ack deadline."},{"f":2,"t":2,"l":"Handler is slow","n":"The handler needs 45 seconds because it calls a slow service."},{"f":1,"t":2,"l":"Redeliver","n":"The deadline passes with no ack, so Pub/Sub delivers the message again."},{"f":2,"t":2,"l":"Idempotent check","n":"The handler detects the id was already processed and skips the effect."},{"f":1,"t":3,"l":"After 5 attempts","n":"If the message still fails it goes to the dead-letter topic for review."}]},{"id":"x-gc-ops","module":"gcp","lesson":"gcp/observability-with-cloud-logging-monitoring-and-slos","title":"A burn rate alert","summary":"The alert fires when the error budget is used too quickly.","actors":["Service","Monitoring","SLO","On-call"],"steps":[{"f":0,"t":1,"l":"Emit metrics","n":"The service reports request counts and latencies to Cloud Monitoring."},{"f":1,"t":2,"l":"Compute the SLI","n":"Monitoring divides good requests by all requests over a window."},{"f":2,"t":2,"l":"Compare with objective","n":"The objective is 99.9 percent, and the current error rate is far above the allowed 0.1 percent."},{"f":2,"t":3,"l":"Fast burn alert","n":"The budget would be gone in a few hours, so the on-call engineer is paged."},{"f":3,"t":0,"l":"Investigate","n":"The engineer follows traces and logs to the failing release."},{"f":3,"t":0,"l":"Roll back","n":"The release is reverted and the burn rate falls back to normal."}]},{"id":"x-gc-tf","module":"gcp","lesson":"gcp/terraform-on-google-cloud","title":"Terraform in CI with federation","summary":"A pipeline plans and applies using a short-lived service account.","actors":["Pipeline","Federation","Service account","State bucket"],"steps":[{"f":0,"t":1,"l":"Job gets a token","n":"The CI job exchanges its OIDC token with workload identity federation."},{"f":1,"t":2,"l":"Impersonate","n":"The federation grants permission to impersonate the Terraform service account."},{"f":2,"t":3,"l":"Lock the state","n":"Terraform locks the state object in the Cloud Storage bucket."},{"f":0,"t":3,"l":"Read and plan","n":"The plan compares the state with the real resources and shows changes."},{"f":0,"t":2,"l":"Apply after approval","n":"After a reviewer approves, the apply runs with the same short-lived identity."},{"f":3,"t":3,"l":"Write and unlock","n":"The new state is written, the old version is kept by versioning and the lock is released."}]},{"id":"x-gc-failperm","module":"gcp","lesson":"gcp/security-cost-and-debugging-on-google-cloud","title":"Failure and recovery: permission denied","summary":"The exact missing permission is found instead of granting Owner.","actors":["Developer","API","Troubleshooter","Admin"],"steps":[{"f":0,"t":1,"l":"Call fails","n":"The developer reads an object and receives PERMISSION_DENIED for storage.objects.get."},{"f":0,"t":3,"l":"Ask for access","n":"The developer asks the admin to fix it, and the quick answer is to grant Owner."},{"f":3,"t":2,"l":"Run the troubleshooter","n":"The admin checks the principal, resource and permission in Policy Troubleshooter."},{"f":2,"t":3,"l":"Missing role found","n":"It shows that no binding on the bucket includes the needed permission."},{"f":3,"t":1,"l":"Grant narrowly","n":"The admin grants the object viewer role on that single bucket only."},{"f":0,"t":1,"l":"Retry","n":"The developer repeats the call and it succeeds."},{"f":3,"t":3,"l":"Record and review","n":"The change is recorded, and IAM Recommender later removes any unused extras."},{"f":1,"t":0,"l":"No Owner needed","n":"The project stays free of broad roles and the audit log shows a clean reason for the grant."}],"kind":"failure"},{"id":"x-gc-failquota","module":"gcp","lesson":"gcp/gke-autopilot-and-standard-clusters","title":"Failure and recovery: pods stuck pending","summary":"A pool limit blocks scheduling until capacity is raised.","actors":["Deployer","Scheduler","Autoscaler","Operator"],"steps":[{"f":0,"t":1,"l":"Deploy more replicas","n":"The deployer scales a service from 3 to 20 pods."},{"f":1,"t":1,"l":"Not enough room","n":"The scheduler cannot place the pods and marks them Pending with Insufficient cpu."},{"f":1,"t":2,"l":"Ask for nodes","n":"The cluster autoscaler is asked to add nodes to the pool."},{"f":2,"t":2,"l":"Maximum reached","n":"The node pool is already at its maximum of 3 nodes, so it cannot add more."},{"f":3,"t":1,"l":"Read the events","n":"The operator describes a pod and reads the scheduling event and the autoscaler message."},{"f":3,"t":2,"l":"Raise the limit","n":"The operator raises the node pool maximum and checks the project quota."},{"f":2,"t":1,"l":"Nodes added","n":"New nodes join and the scheduler places the waiting pods."},{"f":3,"t":0,"l":"Right-size requests","n":"The team also lowers oversized requests so pods use capacity more efficiently."}],"kind":"failure"},{"id":"x-msg-models","module":"messaging","lesson":"messaging/queues-logs-and-pub-sub-choosing-a-model","title":"One event, three messaging models","summary":"A queue, a topic and a log treat the same message differently.","actors":["Producer","Queue","Topic","Log"],"steps":[{"f":0,"t":1,"l":"Send to a queue","n":"The producer sends a job to the queue and one worker will take it."},{"f":1,"t":1,"l":"Message removed","n":"Once the worker acknowledges, the queue deletes the message for good."},{"f":0,"t":2,"l":"Publish to a topic","n":"The same producer publishes an event and every subscriber receives its own copy."},{"f":0,"t":3,"l":"Append to a log","n":"The event is appended to the log with an offset and stays for the retention period."},{"f":3,"t":3,"l":"Late reader replays","n":"A new consumer starts at an older offset and reads history that the queue no longer holds."},{"f":0,"t":3,"l":"Same event, many readers","n":"Billing and search each keep their own offset in the log and read at their own speed."}]},{"id":"x-msg-delivery","module":"messaging","lesson":"messaging/delivery-guarantees-ordering-and-idempotency","title":"A duplicate delivery made harmless","summary":"The consumer checks a message id before applying the effect.","actors":["Broker","Consumer","Database","Producer"],"steps":[{"f":0,"t":1,"l":"Deliver message 7f3a","n":"The broker delivers a message with a stable id to the consumer."},{"f":1,"t":2,"l":"Record id and apply","n":"In one transaction the consumer inserts the id and updates the data."},{"f":1,"t":0,"l":"Acknowledge lost","n":"The acknowledgement is lost on the network, so the broker thinks the work failed."},{"f":0,"t":1,"l":"Redeliver 7f3a","n":"The broker delivers the same message again after the timeout."},{"f":1,"t":2,"l":"Id already present","n":"The insert finds the id already recorded, so no row is inserted."},{"f":1,"t":0,"l":"Skip and acknowledge","n":"The consumer skips the effect, acknowledges, and the customer is charged only once."}]},{"id":"x-msg-rabbit","module":"messaging","lesson":"messaging/rabbitmq-exchanges-queues-and-routing","title":"A message routed by a topic exchange","summary":"The exchange copies the message into every queue whose binding matches.","actors":["Producer","Exchange","Billing queue","Search queue"],"steps":[{"f":0,"t":1,"l":"Publish with a key","n":"The producer publishes to the events exchange with routing key order.paid.eu."},{"f":1,"t":1,"l":"Match bindings","n":"The topic exchange compares the key with each binding pattern."},{"f":1,"t":2,"l":"Copy to billing","n":"The billing binding order.paid.# matches, so a copy enters the billing queue."},{"f":1,"t":3,"l":"Copy to search","n":"The search binding order.# also matches, so it receives a copy too."},{"f":1,"t":1,"l":"No match elsewhere","n":"A queue bound to refund.# does not match and gets nothing."},{"f":2,"t":2,"l":"Consumer reads","n":"The billing consumer takes the message and acknowledges it when done."}]},{"id":"x-msg-rabbitdlx","module":"messaging","lesson":"messaging/rabbitmq-acknowledgements-prefetch-and-dead-letters","title":"Retry then park a failing message","summary":"A delayed retry queue limits attempts and a parked queue holds the rest.","actors":["Main queue","Consumer","Retry queue","Parked queue"],"steps":[{"f":0,"t":1,"l":"Deliver with prefetch","n":"The queue hands the consumer up to its prefetch limit of messages."},{"f":1,"t":1,"l":"Processing fails","n":"The consumer cannot process one message because the payload is malformed."},{"f":1,"t":2,"l":"Reject without requeue","n":"The consumer rejects it and the broker dead-letters it into the retry queue."},{"f":2,"t":2,"l":"Wait for TTL","n":"The retry queue holds it for 30 seconds before it expires."},{"f":2,"t":0,"l":"Return to main","n":"On expiry the message is dead-lettered back to the main queue for another attempt."},{"f":1,"t":3,"l":"After N attempts","n":"Once the attempt header reaches the limit the message goes to the parked queue for a human."}]},{"id":"x-msg-kpart","module":"messaging","lesson":"messaging/kafka-topics-partitions-and-brokers","title":"A keyed record reaches its partition","summary":"The same key always lands in the same partition so order is kept.","actors":["Producer","Partitioner","Broker 1","Broker 2"],"steps":[{"f":0,"t":1,"l":"Send record with key","n":"The producer sends an order event with the key order-4411."},{"f":1,"t":1,"l":"Hash the key","n":"The partitioner hashes the key and takes it modulo the partition count."},{"f":1,"t":2,"l":"Leader for partition 2","n":"Partition 2 is led by broker 1, so the record is sent there."},{"f":2,"t":3,"l":"Replicate","n":"The followers on broker 2 fetch the record and copy it to their logs."},{"f":2,"t":0,"l":"Acknowledge","n":"With acks=all the leader answers after enough replicas have the record."},{"f":0,"t":1,"l":"Later record, same key","n":"The next event for order-4411 hashes to the same partition and keeps its order."}]},{"id":"x-msg-group","module":"messaging","lesson":"messaging/kafka-producers-consumers-and-consumer-groups","title":"A consumer group rebalance","summary":"Partitions move when a member joins, and consumption pauses briefly.","actors":["Consumer 1","Coordinator","Consumer 2","Topic"],"steps":[{"f":0,"t":3,"l":"Reading all six","n":"Consumer 1 is alone in the group and reads all six partitions of the topic."},{"f":2,"t":1,"l":"New member joins","n":"Consumer 2 starts and sends a join request to the group coordinator."},{"f":1,"t":0,"l":"Rebalance begins","n":"The coordinator tells members to stop and rejoin, so reading pauses."},{"f":1,"t":1,"l":"Assign partitions","n":"The coordinator assigns three partitions to each consumer."},{"f":1,"t":2,"l":"Assignment sent","n":"Consumer 2 receives partitions 3 to 5 and Consumer 1 keeps 0 to 2."},{"f":2,"t":3,"l":"Resume from commit","n":"Each consumer resumes from the last committed offset of its partitions."}]},{"id":"x-msg-isr","module":"messaging","lesson":"messaging/kafka-replication-isr-and-durability","title":"Leader failure with a healthy ISR","summary":"A caught-up follower becomes leader, so no acknowledged record is lost.","actors":["Producer","Leader","Follower","Controller"],"steps":[{"f":0,"t":1,"l":"Write with acks=all","n":"The producer writes a record and waits for in-sync replicas to confirm."},{"f":1,"t":2,"l":"Follower copies","n":"The follower fetches the record and stays in the in-sync set."},{"f":1,"t":0,"l":"Acknowledged","n":"The record is acknowledged only after min.insync.replicas have it."},{"f":1,"t":1,"l":"Leader crashes","n":"The leader broker stops, and the partition has no leader for a moment."},{"f":3,"t":2,"l":"Elect from ISR","n":"The controller promotes the follower, which already has every acknowledged record."},{"f":0,"t":2,"l":"Writes continue","n":"The producer finds the new leader and carries on without data loss."}]},{"id":"x-msg-compact","module":"messaging","lesson":"messaging/kafka-retention-compaction-and-storage","title":"Log compaction keeps the latest value","summary":"Older records for a key are removed in the background.","actors":["Producer","Log","Cleaner","Consumer"],"steps":[{"f":0,"t":1,"l":"Write updates","n":"The producer appends user-1 = A, user-2 = B, then user-1 = C to a compacted topic."},{"f":1,"t":2,"l":"Cleaner scans","n":"A background cleaner reads closed segments and finds duplicate keys."},{"f":2,"t":1,"l":"Drop old values","n":"It removes user-1 = A because a newer value exists."},{"f":0,"t":1,"l":"Tombstone","n":"The producer writes user-2 with a null value to delete that key."},{"f":2,"t":1,"l":"Remove after delay","n":"After the delete retention time the cleaner removes the key itself."},{"f":3,"t":1,"l":"Read a snapshot","n":"A new consumer reading from the start sees only the latest value per key."}]},{"id":"x-msg-lag","module":"messaging","lesson":"messaging/kafka-lag-rebalances-and-capacity-in-operation","title":"Spotting and fixing consumer lag","summary":"Lag is read per partition, then traced to a cause.","actors":["Monitor","Consumer","Broker","Operator"],"steps":[{"f":0,"t":1,"l":"Read the lag","n":"Monitoring shows partition 1 is 18 minutes behind while the others are current."},{"f":3,"t":1,"l":"Check the consumer","n":"The operator finds the consumer for partition 1 alive but stuck on one slow call."},{"f":3,"t":2,"l":"Check the broker","n":"Broker metrics look normal, with no under-replicated partitions."},{"f":1,"t":1,"l":"Slow dependency","n":"The consumer waits for a downstream API that has become slow."},{"f":3,"t":1,"l":"Fix the dependency","n":"The operator adds a timeout and a retry limit, then restarts the consumer."},{"f":1,"t":0,"l":"Lag falls","n":"The consumer catches up and lag in minutes returns to near zero."}]},{"id":"x-msg-cloud","module":"messaging","lesson":"messaging/managed-messaging-on-cloud-sqs-sns-pub-sub-and-event-hubs","title":"Fan-out with a topic and queues","summary":"One publish reaches several queues, each with its own dead-letter queue.","actors":["Publisher","Topic","Billing queue","Dead-letter queue"],"steps":[{"f":0,"t":1,"l":"Publish once","n":"The service publishes the order event to the topic."},{"f":1,"t":2,"l":"Copy to billing","n":"The topic delivers a copy to the billing queue."},{"f":2,"t":2,"l":"Visibility window","n":"A worker receives the message and it is hidden from others for the visibility timeout."},{"f":2,"t":3,"l":"Too many failures","n":"After the maximum receive count the message moves to the dead-letter queue."},{"f":3,"t":3,"l":"Alert fires","n":"An alarm on the dead-letter queue depth notifies the team."},{"f":3,"t":2,"l":"Redrive after a fix","n":"After the bug is fixed the team redrives the parked messages back to the billing queue."}]},{"id":"x-msg-schema","module":"messaging","lesson":"messaging/schemas-contracts-and-evolving-messages","title":"A schema change checked in CI","summary":"The registry refuses a change that would break existing readers.","actors":["Developer","CI","Registry","Consumers"],"steps":[{"f":0,"t":1,"l":"Open a pull request","n":"The developer changes a field name in the schema file."},{"f":1,"t":2,"l":"Ask the registry","n":"CI sends the new schema to the registry's compatibility check."},{"f":2,"t":1,"l":"Reject","n":"The registry reports that renaming the field breaks backward compatibility."},{"f":1,"t":0,"l":"Build fails","n":"The pull request cannot merge, and the message says which rule failed."},{"f":0,"t":1,"l":"Add instead","n":"The developer adds the new field with a default and keeps the old one."},{"f":2,"t":1,"l":"Accept","n":"The registry accepts the change as compatible."},{"f":1,"t":3,"l":"Safe rollout","n":"Consumers keep reading old and new records while the old field is retired later."}]},{"id":"x-msg-failsilent","module":"messaging","lesson":"messaging/debugging-messaging-incidents","title":"Failure and recovery: messages dropped by an exchange","summary":"A routing key typo loses messages without any error.","actors":["Producer","Exchange","Consumer","Operator"],"steps":[{"f":0,"t":1,"l":"Publish with new key","n":"The producer starts publishing with the key order.payed.eu after a code change."},{"f":1,"t":1,"l":"No binding matches","n":"The topic exchange finds no queue bound to that key."},{"f":1,"t":1,"l":"Message dropped","n":"With no alternate exchange the message is silently discarded."},{"f":2,"t":2,"l":"Consumer idle","n":"The consumer sees nothing wrong and simply receives fewer messages."},{"f":3,"t":1,"l":"Trace one order","n":"The operator follows one order id and finds it published but never delivered."},{"f":3,"t":1,"l":"Read broker counters","n":"The exchange shows a rising unroutable count that matches the missing orders."},{"f":3,"t":0,"l":"Fix the key","n":"The producer is corrected and an alternate exchange is added to catch unroutable messages."},{"f":0,"t":2,"l":"Replay missed orders","n":"The missed orders are republished from the outbox, and an alert is set on the dropped count."}],"kind":"failure"},{"id":"x-msg-failfull","module":"messaging","lesson":"messaging/kafka-retention-compaction-and-storage","title":"Failure and recovery: Kafka disk fills up","summary":"A traffic spike outruns retention and brokers stop accepting writes.","actors":["Producer","Broker","Operator","Consumer"],"steps":[{"f":0,"t":1,"l":"Traffic doubles","n":"A bug in a producer sends twice the normal volume of records."},{"f":1,"t":1,"l":"Disk grows fast","n":"The topic keeps data for seven days, so disk use climbs far faster than planned."},{"f":1,"t":1,"l":"Disk reaches 100 percent","n":"The log directory fills and the broker marks it failed and stops."},{"f":0,"t":1,"l":"Writes fail","n":"Producers receive errors because partitions have no available leader."},{"f":2,"t":1,"l":"Free space","n":"The operator lowers retention on the noisy topic so old segments are deleted."},{"f":2,"t":0,"l":"Stop the cause","n":"The buggy producer is rolled back and a quota is added for it."},{"f":1,"t":1,"l":"Broker restarts","n":"With space available the broker starts, replicas catch up and partitions come back."},{"f":3,"t":1,"l":"Consumers resume","n":"Consumers continue from their committed offsets with no gaps in the data."}],"kind":"failure"},{"id":"x-px-what","module":"proxies","lesson":"proxies/what-a-reverse-proxy-does","title":"How a reverse proxy handles a request","summary":"One public entry point hides many private servers.","actors":["Browser","Reverse proxy","App server","Cache"],"steps":[{"f":0,"t":1,"l":"Request arrives","n":"The browser connects to the one public address, which belongs to the proxy rather than to any app server."},{"f":1,"t":1,"l":"Check the rules","n":"The proxy matches the host name and path against its configuration to pick a backend."},{"f":1,"t":3,"l":"Look in the cache","n":"For a cacheable page the proxy first asks its cache, which may answer without bothering the app."},{"f":1,"t":2,"l":"Forward the request","n":"On a miss the proxy opens or reuses a connection to the app and adds headers such as X-Forwarded-For."},{"f":2,"t":1,"l":"App answers","n":"The app server builds the response and sends it back to the proxy only, never to the browser directly."},{"f":1,"t":3,"l":"Store a copy","n":"If the response is cacheable the proxy saves it so the next visitor is served faster."},{"f":1,"t":0,"l":"Reply to the browser","n":"The proxy returns the response, and the browser never learns which server did the work."}]},{"id":"x-px-nginx","module":"proxies","lesson":"proxies/nginx-configuration-servers-and-locations","title":"How nginx picks a server and a location","summary":"Two matching steps decide which block handles a request.","actors":["Client","nginx","Server block","Location block"],"steps":[{"f":0,"t":1,"l":"Request with Host header","n":"The client sends a request whose Host header names the site it wants."},{"f":1,"t":2,"l":"Match the server","n":"nginx compares the listening port and the Host header with each server block and selects the best match."},{"f":2,"t":2,"l":"Default server","n":"If nothing matches, the first or the default_server block answers, which is why unknown hosts reach a surprising site."},{"f":2,"t":3,"l":"Match the location","n":"Inside the server, nginx tests exact locations, then the longest prefix, then regular expressions."},{"f":3,"t":3,"l":"Apply directives","n":"The chosen location sets root, proxy_pass or return rules, and only that block applies."},{"f":3,"t":0,"l":"Send the response","n":"The result goes back to the client, and the access log records which location handled it."}]},{"id":"x-px-headers","module":"proxies","lesson":"proxies/proxying-to-upstreams-headers-and-buffers","title":"What a proxy adds on the way to the app","summary":"Headers carry the client identity that a proxy would otherwise hide.","actors":["Client","Proxy","App","Log"],"steps":[{"f":0,"t":1,"l":"Client connects","n":"The client address 203.0.113.9 reaches the proxy, which is now the only peer the app can see."},{"f":1,"t":1,"l":"Add forwarding headers","n":"The proxy sets X-Forwarded-For, X-Forwarded-Proto and Host so the app can know the original request."},{"f":1,"t":2,"l":"Forward with buffering","n":"The proxy buffers the response from the app so a slow client does not keep the app busy."},{"f":2,"t":3,"l":"App logs the address","n":"Without trusting the headers the app would log the proxy address for every user."},{"f":2,"t":1,"l":"Response returns","n":"The app finishes quickly and is free for the next request while the proxy handles the slow client."},{"f":1,"t":0,"l":"Slow client reads","n":"The proxy feeds the buffered response at the client's own speed."}]},{"id":"x-px-tls","module":"proxies","lesson":"proxies/tls-termination-http2-and-certificates","title":"TLS termination at the proxy","summary":"The proxy ends encryption and talks plainly or re-encrypts to the app.","actors":["Browser","Proxy","Certificate store","App"],"steps":[{"f":0,"t":1,"l":"ClientHello","n":"The browser starts TLS and names the site it wants using the SNI extension."},{"f":1,"t":2,"l":"Find the certificate","n":"The proxy picks the certificate that matches the name from its store."},{"f":2,"t":1,"l":"Certificate returned","n":"The matching certificate and chain are loaded for the handshake."},{"f":1,"t":0,"l":"Handshake completes","n":"Keys are agreed, HTTP/2 is negotiated and the browser sees a valid padlock."},{"f":0,"t":1,"l":"Encrypted request","n":"The request travels encrypted to the proxy, which decrypts it."},{"f":1,"t":3,"l":"Forward to the app","n":"The proxy forwards over a private network, optionally encrypting again for stricter environments."},{"f":3,"t":1,"l":"App response","n":"The app answers and the proxy encrypts the reply for the browser."}]},{"id":"x-px-lb","module":"proxies","lesson":"proxies/load-balancing-algorithms-and-health-checks","title":"Round robin with a health check","summary":"The balancer stops sending traffic to a server that fails its check.","actors":["Client","Balancer","Server A","Server B"],"steps":[{"f":0,"t":1,"l":"Request 1","n":"The client request reaches the balancer, which picks the next server in rotation."},{"f":1,"t":2,"l":"Sent to A","n":"Server A is healthy so it receives the first request and answers it."},{"f":0,"t":1,"l":"Request 2","n":"The next request arrives and the rotation moves on."},{"f":1,"t":3,"l":"Sent to B","n":"Server B takes the second request in the same way."},{"f":1,"t":3,"l":"Health probe fails","n":"The balancer's periodic probe to B gets no answer for several tries in a row."},{"f":1,"t":1,"l":"Mark B down","n":"After the failure threshold B is removed from rotation without any human action."},{"f":0,"t":1,"l":"Request 3","n":"A new request arrives while B is down."},{"f":1,"t":2,"l":"Only A is used","n":"All traffic now goes to A until B passes its probes again."}]},{"id":"x-px-timeouts","module":"proxies","lesson":"proxies/timeouts-retries-keepalive-and-limits","title":"Timeout chain and a retry","summary":"Every hop has its own timer and the shortest one wins.","actors":["Client","Proxy","App","Database"],"steps":[{"f":0,"t":1,"l":"Client waits","n":"The client allows 60 seconds, the proxy read timeout is 30 seconds and the app has no limit of its own."},{"f":1,"t":2,"l":"Forward request","n":"The proxy passes the request and starts its 30 second timer."},{"f":2,"t":3,"l":"Slow query","n":"The app calls the database and the query runs longer than expected."},{"f":1,"t":1,"l":"Proxy times out","n":"After 30 seconds the proxy gives up and prepares a 504 Gateway Timeout response."},{"f":1,"t":0,"l":"Client sees 504","n":"The client receives an error while the app is still waiting for the database."},{"f":2,"t":3,"l":"Wasted work","n":"The app keeps working on a request nobody is waiting for, using a database connection."},{"f":1,"t":2,"l":"Unsafe retry","n":"If the proxy retried a non-idempotent request, the same order could be created twice."}]},{"id":"x-px-cache","module":"proxies","lesson":"proxies/caching-compression-and-static-files","title":"Proxy cache hit and miss","summary":"The first request fills the cache and later ones are served from it.","actors":["Client","Proxy","Cache","App"],"steps":[{"f":0,"t":1,"l":"First request","n":"A client asks for a product page that the proxy has not seen before."},{"f":1,"t":2,"l":"Cache lookup","n":"The proxy builds a cache key from the URL and looks it up."},{"f":2,"t":1,"l":"Miss","n":"Nothing is stored for that key so the proxy must go to the app."},{"f":1,"t":3,"l":"Fetch from app","n":"The app renders the page and returns it with Cache-Control headers."},{"f":1,"t":2,"l":"Store the response","n":"The proxy writes the page to the cache with a lifetime taken from the headers."},{"f":0,"t":1,"l":"Second request","n":"Another client asks for the same page a moment later."},{"f":2,"t":1,"l":"Hit","n":"The cache returns the stored copy and the app is not touched."},{"f":1,"t":0,"l":"Fast reply","n":"The client receives the page in milliseconds with an X-Cache: HIT header."}]},{"id":"x-px-rate","module":"proxies","lesson":"proxies/rate-limiting-and-protecting-backends","title":"A leaky bucket rate limit","summary":"Requests above the rate are queued or rejected before they reach the app.","actors":["Client","Limiter","Proxy","App"],"steps":[{"f":0,"t":1,"l":"Burst arrives","n":"A client sends 30 requests in one second against a limit of 10 per second."},{"f":1,"t":1,"l":"Count per key","n":"The limiter counts requests for this client address in its shared memory zone."},{"f":1,"t":2,"l":"Allowed requests pass","n":"The first requests within the rate and burst allowance continue to the proxy."},{"f":2,"t":3,"l":"App serves them","n":"The app handles the allowed requests at a pace it can sustain."},{"f":1,"t":0,"l":"Excess rejected","n":"Requests above the burst receive 429 Too Many Requests with a Retry-After header."},{"f":0,"t":1,"l":"Client backs off","n":"A well-behaved client waits and retries later, so load smooths out."},{"f":1,"t":2,"l":"Normal rate resumes","n":"When the client slows down the bucket drains and requests flow again."}]},{"id":"x-px-haproxy","module":"proxies","lesson":"proxies/haproxy-frontends-backends-and-acls","title":"HAProxy frontend to backend","summary":"An ACL decides which backend serves a request.","actors":["Client","Frontend","ACL","Backend"],"steps":[{"f":0,"t":1,"l":"Connection accepted","n":"The frontend listens on port 443 and accepts the connection."},{"f":1,"t":2,"l":"Evaluate ACLs","n":"Rules test the request path, host name and headers, for example path_beg /api."},{"f":2,"t":2,"l":"Rule matches","n":"The first matching use_backend rule selects the api backend."},{"f":2,"t":3,"l":"Choose a server","n":"The backend balances across its servers with the configured algorithm and health checks."},{"f":3,"t":1,"l":"Server answers","n":"The chosen server returns the response to HAProxy."},{"f":1,"t":0,"l":"Return to client","n":"HAProxy sends the response back and records the timings in its log."}]},{"id":"x-px-envoy","module":"proxies","lesson":"proxies/envoy-traefik-and-dynamic-proxies","title":"A dynamic proxy learns a new route","summary":"New services appear without a restart or manual config edit.","actors":["Orchestrator","Control plane","Proxy","Service"],"steps":[{"f":0,"t":1,"l":"New service starts","n":"The orchestrator starts a new instance and registers it with discovery."},{"f":1,"t":1,"l":"Build config","n":"The control plane updates its model of routes and endpoints."},{"f":1,"t":2,"l":"Push update","n":"The new routes and endpoints are streamed to the proxy with no restart."},{"f":2,"t":2,"l":"Apply atomically","n":"The proxy swaps in the new configuration and keeps existing connections alive."},{"f":2,"t":3,"l":"Traffic arrives","n":"Requests now match the new route and reach the new instance."},{"f":3,"t":2,"l":"Health reported","n":"Health checks tell the proxy to remove the instance if it later fails."}]},{"id":"x-px-reload","module":"proxies","lesson":"proxies/zero-downtime-reloads-and-blue-green-at-the-proxy","title":"A graceful reload","summary":"New workers take new connections while old workers finish theirs.","actors":["Operator","Master","Old workers","New workers"],"steps":[{"f":0,"t":1,"l":"Edit and test","n":"The operator edits the config and runs a syntax test, which must pass before anything else."},{"f":0,"t":1,"l":"Send reload","n":"The operator sends a reload signal to the master process."},{"f":1,"t":3,"l":"Start new workers","n":"The master reads the new configuration and starts new workers with it."},{"f":1,"t":2,"l":"Tell old workers to drain","n":"Old workers stop accepting new connections but keep serving existing ones."},{"f":3,"t":3,"l":"Take new traffic","n":"New connections go to the new workers using the new rules."},{"f":2,"t":2,"l":"Finish and exit","n":"Old workers close once their last request is done, so no user sees an error."}]},{"id":"x-px-fail502","module":"proxies","lesson":"proxies/debugging-502-504-and-proxy-problems","title":"Failure and recovery: 502 Bad Gateway after a deploy","summary":"A restarted app is unreachable until it listens again.","actors":["Client","Proxy","App","Operator"],"steps":[{"f":0,"t":1,"l":"Request arrives","n":"A user requests a page just after the app container restarts."},{"f":1,"t":2,"l":"Connect to upstream","n":"The proxy tries to connect to the app on its port."},{"f":2,"t":1,"l":"Connection refused","n":"The app process is not listening yet so the connection is refused."},{"f":1,"t":0,"l":"502 Bad Gateway","n":"The proxy returns 502 and logs connect() failed (111: Connection refused) while connecting to upstream."},{"f":3,"t":1,"l":"Read the error log","n":"The operator reads the proxy error log and sees the exact upstream address and error."},{"f":3,"t":2,"l":"Check the app","n":"The operator finds the app is crash-looping because of a missing environment variable."},{"f":3,"t":2,"l":"Fix and restart","n":"After restoring the variable the app listens again and passes its health check."},{"f":1,"t":0,"l":"Traffic recovers","n":"The proxy connects, requests succeed and the 502 count returns to zero."}],"kind":"failure"},{"id":"x-px-fail504","module":"proxies","lesson":"proxies/debugging-502-504-and-proxy-problems","title":"Failure and recovery: 504 from a slow backend","summary":"A slow dependency makes the proxy time out and retry.","actors":["Client","Proxy","App","Database"],"steps":[{"f":0,"t":1,"l":"Traffic rises","n":"Requests increase during a sale and every one needs a slow database query."},{"f":1,"t":2,"l":"Forward requests","n":"The proxy forwards them and the app accepts more than the database can serve."},{"f":2,"t":3,"l":"Database saturates","n":"Queries queue up in the database and each response takes longer than 30 seconds."},{"f":1,"t":0,"l":"504 Gateway Timeout","n":"The proxy timeout is reached and clients receive 504 errors."},{"f":1,"t":2,"l":"Retries add load","n":"Automatic retries send the same slow requests again, making the overload worse."},{"f":2,"t":3,"l":"Operator limits load","n":"The team turns off retries, adds a rate limit and raises the database capacity."},{"f":3,"t":2,"l":"Queue drains","n":"With less load the queries finish in a few seconds and latency falls."},{"f":1,"t":0,"l":"Clients succeed","n":"Responses arrive inside the timeout and the error rate returns to normal."}],"kind":"failure"},{"id":"x-ceph-arch","module":"ceph","lesson":"ceph/what-ceph-is-rados-and-the-architecture","title":"One object through the Ceph stack","summary":"Follow a write from an S3 client through RGW and RADOS to OSD disks.","actors":["S3 client","RGW","RADOS","Monitors","OSDs"],"steps":[{"f":0,"t":1,"l":"PUT an object","n":"The client sends an S3 PUT request to an RGW daemon."},{"f":1,"t":3,"l":"Fetch the cluster map","n":"RGW has a current map of monitors, OSDs and rules from the monitors."},{"f":1,"t":2,"l":"Write to RADOS","n":"RGW writes the object into a pool in RADOS using librados."},{"f":2,"t":4,"l":"Primary OSD receives","n":"The object is hashed to a placement group and sent to the primary OSD."},{"f":4,"t":4,"l":"Replicas written","n":"The primary writes locally and forwards the data to the replica OSDs."},{"f":4,"t":0,"l":"Acknowledge","n":"After all copies are safe the OSD acknowledges and RGW returns success."}]},{"id":"x-ceph-quorum","module":"ceph","lesson":"ceph/monitors-managers-osds-and-quorum","title":"Failure and recovery: losing a monitor majority","summary":"Two monitors fail in the same rack and the cluster stops until quorum returns.","actors":["Client","Mon A","Mon B","Mon C","Operator"],"steps":[{"f":0,"t":1,"l":"Normal operation","n":"Clients ask the monitors for the map and the three monitors agree."},{"f":2,"t":2,"l":"Rack loses power","n":"Monitors B and C share a rack, and both lose power."},{"f":0,"t":1,"l":"Map request fails","n":"Monitor A alone cannot form a majority and refuses to commit changes."},{"f":0,"t":0,"l":"IO stalls","n":"Clients cannot get an updated map, and applications see hung storage."},{"f":4,"t":1,"l":"Diagnose","n":"The operator sees one of three monitors up and no quorum in ceph status."},{"f":4,"t":2,"l":"Restore power","n":"Power is restored to the rack and the monitors start again."},{"f":2,"t":1,"l":"Quorum returns","n":"Monitors B and C rejoin, a majority forms, and IO resumes."},{"f":4,"t":3,"l":"Spread monitors","n":"The operator redeploys monitors across three racks so one failure never removes the majority."}],"kind":"failure"},{"id":"x-ceph-crush","module":"ceph","lesson":"ceph/crush-pools-and-placement-groups","title":"From object name to OSDs","summary":"Hash an object to a placement group and let CRUSH choose OSDs.","actors":["Client","Pool","Placement group","CRUSH","OSDs"],"steps":[{"f":0,"t":1,"l":"Write object invoice-42","n":"The client names the pool and the object invoice-42."},{"f":1,"t":2,"l":"Hash to a PG","n":"The name is hashed, giving placement group 7.3 in the pool."},{"f":2,"t":3,"l":"Ask CRUSH","n":"The client computes which OSDs hold PG 7.3 using the CRUSH rule."},{"f":3,"t":4,"l":"Pick distinct hosts","n":"The rule picks three OSDs on three different hosts."},{"f":0,"t":4,"l":"Send to the primary","n":"The client sends the write to the first OSD, which acts as primary."},{"f":4,"t":4,"l":"Copies on three hosts","n":"The primary replicates to the other two, so a host failure loses at most one copy."}]},{"id":"x-ceph-cephadm","module":"ceph","lesson":"ceph/deploying-ceph-with-cephadm","title":"Bootstrapping and growing a cluster","summary":"Create the first node, add hosts and let the orchestrator create OSDs.","actors":["Admin","cephadm","Orchestrator","New host","Disks"],"steps":[{"f":0,"t":1,"l":"Bootstrap","n":"The admin runs cephadm bootstrap on the first host with its monitor IP."},{"f":1,"t":2,"l":"Orchestrator is up","n":"The bootstrap creates a monitor, a manager and the orchestrator module."},{"f":0,"t":2,"l":"Add a host","n":"The admin adds a second host with ceph orch host add."},{"f":2,"t":3,"l":"Daemons are placed","n":"The orchestrator deploys monitor and OSD containers according to labels."},{"f":2,"t":4,"l":"Find free disks","n":"It scans hosts for empty devices that match the OSD service rule."},{"f":4,"t":2,"l":"OSDs created","n":"New OSDs are created on the free disks and join the cluster."}]},{"id":"x-ceph-rbd","module":"ceph","lesson":"ceph/rbd-block-storage-for-vms-and-kubernetes","title":"A PVC becomes an RBD image","summary":"ceph-csi turns a Kubernetes volume claim into an image in a pool.","actors":["Pod","PVC","ceph-csi","RBD image","Pool"],"steps":[{"f":0,"t":1,"l":"Pod requests storage","n":"A pod asks for a PVC that uses the ceph-rbd StorageClass."},{"f":1,"t":2,"l":"Provisioner is called","n":"The external provisioner calls the ceph-csi controller."},{"f":2,"t":3,"l":"Create the image","n":"ceph-csi creates a thin provisioned RBD image of the requested size."},{"f":3,"t":4,"l":"Objects in the pool","n":"The image is striped across objects in a replicated pool."},{"f":2,"t":0,"l":"Map and mount","n":"On the node the image is mapped as a block device and mounted into the pod."},{"f":0,"t":3,"l":"Write data","n":"The pod writes data, and the image uses space only as blocks are written."}]},{"id":"x-ceph-cephfs","module":"ceph","lesson":"ceph/cephfs-shared-file-systems-and-mds","title":"Reading a file on CephFS","summary":"The client asks the MDS for metadata and reads data directly from OSDs.","actors":["Client","Active MDS","Metadata pool","Data pool","Standby MDS"],"steps":[{"f":0,"t":1,"l":"Open a file","n":"The client sends the path to the active MDS."},{"f":1,"t":2,"l":"Read metadata","n":"The MDS reads or caches the inode and layout from the metadata pool."},{"f":1,"t":0,"l":"Grant capabilities","n":"It returns the file layout and gives the client rights to cache and read."},{"f":0,"t":3,"l":"Read data directly","n":"The client reads the file objects from the data pool without going through the MDS."},{"f":1,"t":1,"l":"MDS fails","n":"The active MDS crashes while serving other clients."},{"f":4,"t":1,"l":"Standby takes over","n":"A standby MDS replays the journal and becomes active within seconds."}]},{"id":"x-ceph-rgw","module":"ceph","lesson":"ceph/rgw-s3-compatible-object-storage-with-ceph","title":"A bucket listing that slows down","summary":"An oversized bucket index is resharded to restore listing speed.","actors":["App","Load balancer","RGW","Bucket index","Data pool"],"steps":[{"f":0,"t":1,"l":"List a bucket","n":"The application lists a very large bucket through the load balancer."},{"f":1,"t":2,"l":"Reach an RGW daemon","n":"The balancer forwards the request to a healthy RGW daemon."},{"f":2,"t":3,"l":"Read the index","n":"RGW reads the bucket index, which sits in a single shard."},{"f":3,"t":3,"l":"Index is overloaded","n":"With hundreds of millions of objects one shard is huge, so listing is slow."},{"f":2,"t":0,"l":"Request times out","n":"RGW cannot answer in time and the application times out."},{"f":2,"t":3,"l":"Reshard the index","n":"The operator reshards the bucket to many shards, and dynamic resharding is enabled."}]},{"id":"x-ceph-rook","module":"ceph","lesson":"ceph/rook-ceph-on-kubernetes","title":"Failure and recovery: draining storage nodes too quickly","summary":"Draining a second node before recovery finishes leaves data with one copy.","actors":["Operator","Node 1","Node 2","Ceph","Application"],"steps":[{"f":0,"t":1,"l":"Drain the first node","n":"The operator drains storage node 1 for maintenance."},{"f":3,"t":3,"l":"PGs degrade","n":"The PGs on node 1 lose a copy and Ceph starts recovery to other OSDs."},{"f":0,"t":2,"l":"Drain the second node","n":"Without checking health, the operator drains node 2 as well."},{"f":3,"t":3,"l":"Two copies are gone","n":"Some PGs have lost two of three copies and fall below min_size."},{"f":3,"t":4,"l":"IO blocks","n":"Those PGs go inactive, and the application sees hung volumes."},{"f":0,"t":3,"l":"Diagnose","n":"The toolbox shows inactive PGs and the two drained nodes."},{"f":0,"t":2,"l":"Uncordon node 2","n":"The operator uncordons node 2 so its OSDs return."},{"f":3,"t":4,"l":"Recovery and IO resume","n":"PGs become active again, and the team waits for HEALTH_OK between drains."}],"kind":"failure"},{"id":"x-ceph-ec","module":"ceph","lesson":"ceph/replication-erasure-coding-and-durability","title":"Writing an object to an EC 4+2 pool","summary":"Split an object into four data chunks and two coding chunks.","actors":["Client","Primary OSD","Data chunks","Coding chunks","Failure"],"steps":[{"f":0,"t":1,"l":"Send the object","n":"The client sends a 4 MB object to the primary OSD of the placement group."},{"f":1,"t":2,"l":"Split into k chunks","n":"The primary splits it into four data chunks of 1 MB."},{"f":1,"t":3,"l":"Compute m chunks","n":"It computes two coding chunks of 1 MB from the data."},{"f":1,"t":2,"l":"Write six chunks","n":"Each chunk goes to a different host, giving six hosts in use."},{"f":4,"t":2,"l":"Two hosts fail","n":"Two hosts holding chunks fail at the same time."},{"f":1,"t":0,"l":"Object is still readable","n":"The remaining four chunks rebuild the object, so reads still succeed."}]},{"id":"x-ceph-perf","module":"ceph","lesson":"ceph/bluestore-networks-and-ceph-performance","title":"A replicated write on the network","summary":"Trace a write across the public and cluster networks.","actors":["Client","Public network","Primary OSD","Cluster network","Replica OSDs"],"steps":[{"f":0,"t":1,"l":"Write over the public network","n":"The client sends the write over the public network."},{"f":1,"t":2,"l":"Primary receives","n":"The primary OSD receives the data and writes it to its WAL."},{"f":2,"t":3,"l":"Replicate","n":"The primary sends the data to two replicas over the cluster network."},{"f":3,"t":4,"l":"Replicas write","n":"Each replica writes to its own device and acknowledges."},{"f":4,"t":2,"l":"Acks return","n":"Both acknowledgements arrive at the primary."},{"f":2,"t":0,"l":"Acknowledge to client","n":"The primary acknowledges once all copies are safe, so latency follows the slowest replica."}]},{"id":"x-ceph-fail","module":"ceph","lesson":"ceph/ceph-failures-recovery-and-health-warnings","title":"Failure and recovery: replacing a failed disk","summary":"An OSD fails and a new disk is added without losing data.","actors":["OSD 12","Monitors","Other OSDs","Operator","New disk"],"steps":[{"f":0,"t":0,"l":"OSD 12 fails","n":"The disk behind OSD 12 stops responding."},{"f":1,"t":1,"l":"Mark it down","n":"Monitors mark OSD 12 down after missed heartbeats."},{"f":1,"t":2,"l":"Degraded state","n":"Its PGs run with two copies and keep serving IO."},{"f":1,"t":1,"l":"Mark it out","n":"After the timeout the monitors mark OSD 12 out and start recovery."},{"f":2,"t":2,"l":"Rebuild copies","n":"Other OSDs create the missing third copies on different hosts."},{"f":3,"t":4,"l":"Replace the disk","n":"The operator removes OSD 12 and adds a new disk as a new OSD."},{"f":4,"t":2,"l":"Backfill","n":"Data flows onto the new OSD in the background."},{"f":1,"t":3,"l":"Health returns","n":"ceph status shows HEALTH_OK, and the operator moves on to the next task."}],"kind":"failure"},{"id":"x-ceph-ops","module":"ceph","lesson":"ceph/capacity-planning-upgrades-and-operating-ceph","title":"An orchestrated upgrade","summary":"cephadm upgrades daemons in a safe order, waiting for health between steps.","actors":["Operator","Orchestrator","Monitors","OSDs","Gateways"],"steps":[{"f":0,"t":1,"l":"Start the upgrade","n":"The operator starts an upgrade to a target Ceph version."},{"f":1,"t":2,"l":"Upgrade monitors","n":"The orchestrator replaces monitors one at a time and waits for quorum."},{"f":1,"t":2,"l":"Upgrade managers","n":"It then upgrades managers while a standby stays available."},{"f":1,"t":3,"l":"Upgrade OSDs","n":"OSDs are restarted in small groups, with checks that PGs stay active."},{"f":1,"t":4,"l":"Upgrade MDS and RGW","n":"Metadata and gateway daemons are upgraded last."},{"f":1,"t":0,"l":"Report complete","n":"The status shows all daemons on the new version and the cluster HEALTH_OK."}]},{"id":"x-kv-arch","module":"kubevirt","lesson":"kubevirt/why-vms-on-kubernetes-and-how-kubevirt-works","title":"From a VM object to a running guest","summary":"Follow a VirtualMachine from kubectl to a guest running in a launcher pod.","actors":["User","API","Controller","Handler","Launcher pod"],"steps":[{"f":0,"t":1,"l":"Apply the VirtualMachine","n":"The user applies a VirtualMachine object and the API server validates it."},{"f":1,"t":2,"l":"Controller sees the VM","n":"virt-controller watches the object and decides that an instance must run."},{"f":2,"t":1,"l":"Create VMI and pod","n":"The controller creates a VirtualMachineInstance and a virt-launcher pod through the API."},{"f":1,"t":3,"l":"Pod is scheduled","n":"The normal scheduler places the pod on a node and virt-handler on that node sees it."},{"f":3,"t":4,"l":"Start the domain","n":"virt-handler asks libvirt inside the launcher pod to start the QEMU domain."},{"f":4,"t":0,"l":"Guest is running","n":"The guest boots, the VMI reports an IP, and the user can open the console."}]},{"id":"x-kv-install","module":"kubevirt","lesson":"kubevirt/installing-kubevirt-and-using-virtctl","title":"Installing KubeVirt on a cluster","summary":"Two manifests turn a plain cluster into one that can run VMs.","actors":["Admin","Operator","KubeVirt CR","Components","Node"],"steps":[{"f":0,"t":1,"l":"Apply the operator","n":"The admin applies the operator manifest, which creates the operator and the CRDs."},{"f":0,"t":2,"l":"Apply the KubeVirt resource","n":"The admin creates the KubeVirt custom resource that says what to install."},{"f":1,"t":2,"l":"Operator reads it","n":"The operator reads the resource and decides which components and versions to deploy."},{"f":1,"t":3,"l":"Components are deployed","n":"It deploys virt-api, virt-controller and a virt-handler on every schedulable node."},{"f":3,"t":4,"l":"Node exposes kvm","n":"virt-handler and the device plugin advertise the kvm device if /dev/kvm exists."},{"f":2,"t":0,"l":"Available condition","n":"The resource reports Available and the admin can start a first VM."}]},{"id":"x-kv-runstrat","module":"kubevirt","lesson":"kubevirt/virtualmachines-vmis-and-run-strategies","title":"Run strategies and the VM lifecycle","summary":"See how Always, Manual and Halted change what happens to the instance.","actors":["User","VirtualMachine","Controller","VMI"],"steps":[{"f":0,"t":1,"l":"Set runStrategy Always","n":"The user sets runStrategy to Always on the VirtualMachine."},{"f":1,"t":2,"l":"Controller reacts","n":"virt-controller notices that no instance exists though one should run."},{"f":2,"t":3,"l":"Create the VMI","n":"It creates the VirtualMachineInstance, which then moves through Scheduling to Running."},{"f":3,"t":3,"l":"Guest crashes","n":"The guest powers off unexpectedly and the VMI ends."},{"f":2,"t":3,"l":"Always recreates it","n":"Because the strategy is Always, the controller creates a new VMI automatically."},{"f":0,"t":1,"l":"Set Halted","n":"The user changes the strategy to Halted for maintenance."},{"f":2,"t":3,"l":"Instance removed","n":"The controller deletes the VMI and the VM object remains with its disks and settings."}]},{"id":"x-kv-dv","module":"kubevirt","lesson":"kubevirt/vm-disks-datavolumes-and-cdi","title":"Importing a golden image and cloning it","summary":"A DataVolume imports an OS image once and clones it for new VMs.","actors":["User","DataVolume","CDI","Golden PVC","VM disk"],"steps":[{"f":0,"t":1,"l":"Create the golden DataVolume","n":"The user creates a DataVolume with an http source for the OS image."},{"f":1,"t":2,"l":"CDI starts an importer","n":"CDI starts an importer pod that downloads and converts the image."},{"f":2,"t":3,"l":"Write to the PVC","n":"The importer writes the raw disk into a PVC that becomes the golden image."},{"f":0,"t":1,"l":"Create a VM disk","n":"A new VM asks for a DataVolume whose source is the golden PVC."},{"f":1,"t":2,"l":"CDI clones","n":"CDI clones the golden PVC, using a fast storage copy when the driver supports it."},{"f":2,"t":4,"l":"VM disk ready","n":"The cloned PVC is bound and the VM can boot from its own copy."}]},{"id":"x-kv-storage","module":"kubevirt","lesson":"kubevirt/storage-for-vms-access-modes-block-mode-and-snapshots","title":"Why a disk decides whether a VM can migrate","summary":"Follow two VMs, one on RWO and one on RWX, through a migration request.","actors":["User","VMI on RWX","VMI on RWO","Storage","Migration"],"steps":[{"f":0,"t":4,"l":"Request a migration","n":"The user asks KubeVirt to migrate two VMs."},{"f":4,"t":1,"l":"Check the RWX VM","n":"KubeVirt checks the first VMI and finds a shared RWX block disk."},{"f":1,"t":3,"l":"Target attaches the disk","n":"The target launcher can attach the same disk because storage allows two nodes."},{"f":4,"t":2,"l":"Check the RWO VM","n":"KubeVirt checks the second VMI and finds a ReadWriteOnce disk."},{"f":2,"t":3,"l":"Attach is refused","n":"A second node cannot attach a RWO volume while the first still has it."},{"f":4,"t":0,"l":"Report the condition","n":"LiveMigratable is False for the second VMI, with a message naming the storage."}]},{"id":"x-kv-net","module":"kubevirt","lesson":"kubevirt/vm-networking-masquerade-bridge-and-multus","title":"One VM on the pod network and a VLAN","summary":"Trace traffic through masquerade and a Multus bridge.","actors":["Client pod","Service","Masquerade NAT","Guest","VLAN bridge"],"steps":[{"f":0,"t":1,"l":"Call the Service","n":"A pod in the cluster calls the Service that selects the VM."},{"f":1,"t":2,"l":"Reach the pod IP","n":"The Service sends traffic to the launcher pod IP on the pod network."},{"f":2,"t":3,"l":"NAT to the guest","n":"Masquerade translates the address and forwards the packet to the guest."},{"f":3,"t":4,"l":"Guest uses the VLAN","n":"The guest sends traffic for the legacy system out of its second NIC."},{"f":4,"t":3,"l":"Reply from the VLAN","n":"The legacy server replies over the bridge with the guest's VLAN address."},{"f":3,"t":2,"l":"Reply on the pod network","n":"The guest's answer to the pod network passes back through the NAT."}]},{"id":"x-kv-cloudinit","module":"kubevirt","lesson":"kubevirt/cloud-init-instance-types-and-vm-image-pipelines","title":"First boot of a repeatable VM","summary":"Combine an image, an instance type and cloud-init into a ready VM.","actors":["Pipeline","Image","VM spec","Instance type","Guest"],"steps":[{"f":0,"t":1,"l":"Build and test the image","n":"The pipeline builds a golden image, boots a test VM, and publishes it."},{"f":2,"t":3,"l":"Choose a size","n":"The VM spec references the instance type medium for CPU and memory."},{"f":2,"t":1,"l":"Reference the image","n":"The VM spec clones the tested image as its root disk."},{"f":2,"t":4,"l":"Attach cloud-init data","n":"A cloud-init volume carries the user, SSH key and package list."},{"f":4,"t":4,"l":"Cloud-init runs","n":"On first boot cloud-init creates the user and installs the guest agent."},{"f":4,"t":0,"l":"Report ready","n":"The guest agent connects and the pipeline marks the VM ready."}]},{"id":"x-kv-migrate","module":"kubevirt","lesson":"kubevirt/live-migration-node-drains-and-eviction","title":"Failure and recovery: a migration that never finishes","summary":"A busy VM dirties memory faster than it is copied, and a policy fixes it.","actors":["Operator","Controller","Source launcher","Target launcher","Network"],"steps":[{"f":0,"t":1,"l":"Start a drain","n":"The operator drains a node and evictionStrategy LiveMigrate creates a migration."},{"f":1,"t":3,"l":"Create the target pod","n":"The controller starts a target launcher and attaches the shared disk."},{"f":2,"t":4,"l":"Copy memory pages","n":"The source launcher sends memory pages to the target over the network."},{"f":2,"t":2,"l":"Guest changes memory","n":"A busy database rewrites pages faster than the link can send them."},{"f":4,"t":2,"l":"Copy never converges","n":"Pages are resent again and again, so the remaining difference never gets small."},{"f":1,"t":0,"l":"Migration times out","n":"The progress timeout fires and the migration fails while the drain waits."},{"f":0,"t":1,"l":"Apply a MigrationPolicy","n":"The operator adds a policy with auto-converge and more bandwidth for database VMs."},{"f":2,"t":3,"l":"Migration completes","n":"Auto-converge slows the guest, the copy converges, and the switch happens within seconds."}],"kind":"failure"},{"id":"x-kv-cpu","module":"kubevirt","lesson":"kubevirt/cpu-memory-hugepages-and-vm-performance","title":"What a VM pod must reserve","summary":"Add up guest memory, overhead and dedicated CPU into pod resources.","actors":["Scheduler","Guest memory","Overhead","Pod","Node"],"steps":[{"f":0,"t":1,"l":"Read the VM memory","n":"The scheduler starts from the guest memory the VM asks for."},{"f":0,"t":2,"l":"Add QEMU overhead","n":"KubeVirt adds memory for QEMU, libvirt and device emulation."},{"f":0,"t":3,"l":"Compute pod request","n":"The sum becomes the pod request and the limit must be at least as large."},{"f":3,"t":4,"l":"Reserve dedicated CPUs","n":"With the static CPU manager and Guaranteed QoS the pod gets exclusive cores."},{"f":4,"t":3,"l":"Hugepages are mapped","n":"If hugepages are requested the node must have them reserved or the pod waits."},{"f":3,"t":0,"l":"Pod fits and starts","n":"When the node can satisfy everything, the launcher pod is scheduled."}]},{"id":"x-kv-snapshot","module":"kubevirt","lesson":"kubevirt/vm-snapshots-backup-and-restore","title":"A consistent snapshot and restore","summary":"Freeze the guest, snapshot the disks, and restore to a new VM.","actors":["User","Snapshot","Guest agent","CSI","VM"],"steps":[{"f":0,"t":1,"l":"Create a VirtualMachineSnapshot","n":"The user creates a snapshot object that names the VM."},{"f":1,"t":2,"l":"Freeze the guest","n":"KubeVirt asks the guest agent to freeze file systems for a moment."},{"f":1,"t":3,"l":"Snapshot every disk","n":"It asks the CSI driver for a VolumeSnapshot of each PVC."},{"f":1,"t":2,"l":"Thaw the guest","n":"Once snapshots are created the guest is thawed and writes resume."},{"f":0,"t":1,"l":"Create a restore","n":"Later the user creates a restore object that names the snapshot."},{"f":1,"t":4,"l":"Disks and spec restored","n":"The VM is restored from the snapshot with its disks and definition."}]},{"id":"x-kv-ops","module":"kubevirt","lesson":"kubevirt/operating-kubevirt-monitoring-upgrades-and-troubleshooting","title":"Failure and recovery: old launchers after an upgrade","summary":"The control plane upgrades but running VMs keep the old version.","actors":["Admin","Operator","Control plane","VMs","Prometheus"],"steps":[{"f":0,"t":1,"l":"Apply the new operator","n":"The admin applies a newer operator manifest."},{"f":1,"t":2,"l":"Control plane rolls","n":"virt-api, virt-controller and virt-handler are replaced with the new version."},{"f":3,"t":3,"l":"VMs keep old launchers","n":"Running VMs stay on their old virt-launcher until they restart or migrate."},{"f":4,"t":0,"l":"No alert fires","n":"The control plane is healthy, so no alert shows that VMs lag behind."},{"f":0,"t":3,"l":"Check launcher versions","n":"Weeks later the admin lists the launcher image version of each VMI and finds the old one."},{"f":0,"t":2,"l":"Set LiveMigrate update","n":"The admin sets workloadUpdateMethods to LiveMigrate in the KubeVirt resource."},{"f":2,"t":3,"l":"Batch migrations begin","n":"The controller migrates VMs in batches to launchers of the new version."},{"f":3,"t":0,"l":"Fleet is current","n":"All VMs run the new version, and non-migratable ones are listed for a planned restart."}],"kind":"failure"},{"id":"x-kv-vmware","module":"kubevirt","lesson":"kubevirt/migrating-from-vmware-to-kubevirt","title":"One migration wave from VMware","summary":"Move a group of VMs with conversion, testing and cutover.","actors":["Planner","Forklift","vCenter","KubeVirt","Users"],"steps":[{"f":0,"t":1,"l":"Define the wave","n":"The planner lists VMs, maps networks and storage, and creates a plan."},{"f":1,"t":2,"l":"Read from vCenter","n":"Forklift connects to vCenter and reads the VM disks and settings."},{"f":1,"t":3,"l":"Convert and copy","n":"virt-v2v adapts each guest and the disks are copied into PVCs."},{"f":3,"t":3,"l":"Boot and test","n":"The converted VM boots in a test network and the application is checked."},{"f":0,"t":4,"l":"Schedule the cutover","n":"The planner agrees a window with users and keeps the source VM powered off."},{"f":3,"t":4,"l":"Users move over","n":"DNS or load balancer targets switch to the new VM."}]},{"id":"x-vault-flow","module":"vault","lesson":"vault/what-vault-is-and-the-secrets-problem","title":"A request to Vault","summary":"A caller logs in, is checked against a policy and receives a secret.","actors":["Application","Auth method","Policy","Secrets engine","Audit log"],"steps":[{"f":0,"t":1,"l":"Log in","n":"The application presents an identity such as a service account token."},{"f":1,"t":0,"l":"Receive a token","n":"Vault returns a token with policies and a time to live."},{"f":0,"t":2,"l":"Request a secret","n":"The application sends the token with a request for a path."},{"f":2,"t":3,"l":"Policy allows","n":"The policy check allows read on that path."},{"f":3,"t":0,"l":"Return the secret","n":"The engine returns the secret with a lease."},{"f":2,"t":4,"l":"Write an audit entry","n":"Vault records who asked, which path, and the outcome, with values hashed."}]},{"id":"x-vault-unseal","module":"vault","lesson":"vault/starting-vault-seal-unseal-and-storage","title":"Failure and recovery: a sealed Vault after reboot","summary":"Vault restarts sealed and is brought back with auto-unseal.","actors":["Node","Storage","Key holders","KMS","Applications"],"steps":[{"f":0,"t":0,"l":"Node restarts","n":"The Vault node reboots after a kernel patch."},{"f":0,"t":1,"l":"Open storage","n":"Vault finds its encrypted data but cannot read it."},{"f":4,"t":0,"l":"Requests fail","n":"Applications receive errors because Vault is sealed."},{"f":2,"t":0,"l":"Need three shares","n":"Only one of five key holders is reachable, so the threshold is not met."},{"f":0,"t":3,"l":"Configure auto-unseal","n":"The team configures a cloud KMS key to unwrap the root key at start."},{"f":0,"t":3,"l":"Restart tests","n":"At the next restart Vault asks the KMS to unwrap the root key."},{"f":3,"t":0,"l":"Unsealed automatically","n":"Vault unseals in seconds without a person."},{"f":4,"t":0,"l":"Applications recover","n":"Requests succeed again and the team records a restart test in the runbook."}],"kind":"failure"},{"id":"x-vault-auth","module":"vault","lesson":"vault/authentication-methods-and-tokens","title":"Kubernetes login","summary":"A pod proves its identity and receives a short-lived Vault token.","actors":["Pod","Kubernetes API","Vault","Role","Token"],"steps":[{"f":0,"t":2,"l":"Send the service account JWT","n":"The pod sends its service account token to the Kubernetes auth method."},{"f":2,"t":1,"l":"Validate the token","n":"Vault asks the Kubernetes API to confirm the token is genuine."},{"f":2,"t":3,"l":"Check the role binding","n":"Vault checks the service account name and namespace against the role."},{"f":3,"t":4,"l":"Attach policies","n":"The matching role gives the policies that the token will carry."},{"f":2,"t":0,"l":"Return a token","n":"Vault returns a token with a one hour TTL."},{"f":0,"t":2,"l":"Renew or log in again","n":"Before expiry the pod renews the token or logs in again."}]},{"id":"x-vault-policy","module":"vault","lesson":"vault/policies-and-least-privilege-access","title":"How a policy decides","summary":"Vault compares a request path with the policies on the token.","actors":["Client","Token","Policy A","Policy B","Decision"],"steps":[{"f":0,"t":1,"l":"Send a request","n":"The client sends a read of secret/data/billing/db with its token."},{"f":1,"t":2,"l":"Load policy A","n":"Policy A allows read under secret/data/billing/*."},{"f":1,"t":3,"l":"Load policy B","n":"Policy B grants nothing on that path."},{"f":2,"t":4,"l":"Capabilities are combined","n":"The capabilities from all policies are merged and a deny would win."},{"f":4,"t":0,"l":"Allowed","n":"The merged result includes read, so Vault returns the secret."},{"f":0,"t":4,"l":"A different path","n":"A read of secret/data/payments/db matches no rule and is denied."}]},{"id":"x-vault-kv","module":"vault","lesson":"vault/kv-secrets-engine-and-secret-versioning","title":"Two writers and check-and-set","summary":"Check-and-set stops a second writer from overwriting a newer version.","actors":["Engineer A","Engineer B","KV engine","Version 1","Version 2"],"steps":[{"f":0,"t":2,"l":"Read version 1","n":"Engineer A reads the secret and sees version 1."},{"f":1,"t":2,"l":"Read version 1","n":"Engineer B also reads version 1."},{"f":0,"t":2,"l":"Write with cas 1","n":"Engineer A writes a new value naming version 1 as the base."},{"f":2,"t":4,"l":"Create version 2","n":"The engine accepts the write and creates version 2."},{"f":1,"t":2,"l":"Write with cas 1","n":"Engineer B writes naming version 1, which is no longer current."},{"f":2,"t":1,"l":"Reject the write","n":"The engine rejects it, so B reads version 2 and merges the change."}]},{"id":"x-vault-dynamic","module":"vault","lesson":"vault/dynamic-secrets-for-databases-and-clouds","title":"A dynamic database credential","summary":"Vault creates a user, hands it out with a lease, and drops it at expiry.","actors":["Application","Vault","Database","Lease","Expiry"],"steps":[{"f":0,"t":1,"l":"Request credentials","n":"The application reads database/creds/orders-ro."},{"f":1,"t":2,"l":"Create a user","n":"Vault runs the creation SQL with its admin account."},{"f":1,"t":3,"l":"Create a lease","n":"It records a one hour lease for the new user."},{"f":1,"t":0,"l":"Return username and password","n":"The application receives a unique login that only it holds."},{"f":3,"t":4,"l":"Lease expires","n":"After an hour the lease ends without a renewal."},{"f":1,"t":2,"l":"Drop the user","n":"Vault runs the revocation SQL and the credential stops working."}]},{"id":"x-vault-pki","module":"vault","lesson":"vault/pki-short-lived-certificates-with-vault","title":"Issuing a 24 hour certificate","summary":"A service requests a certificate from an intermediate CA.","actors":["Service","Vault PKI role","Intermediate CA","Root CA","Client"],"steps":[{"f":0,"t":1,"l":"Request a certificate","n":"The service asks the PKI role for a certificate for api.svc.example.internal."},{"f":1,"t":1,"l":"Check the role","n":"Vault checks the domain and the maximum TTL allowed by the role."},{"f":1,"t":2,"l":"Sign the leaf","n":"The intermediate CA signs a certificate valid for 24 hours."},{"f":1,"t":0,"l":"Return key and certificate","n":"The service receives the private key, certificate and chain."},{"f":0,"t":4,"l":"Clients connect","n":"A client verifies the chain up to the root it trusts."},{"f":0,"t":1,"l":"Renew early","n":"After about 16 hours the service requests a fresh certificate."}]},{"id":"x-vault-transit","module":"vault","lesson":"vault/transit-encryption-as-a-service","title":"Encrypting a card number","summary":"The application never holds the key, only ciphertext.","actors":["Application","Vault transit","Key","Database","Auditor"],"steps":[{"f":0,"t":1,"l":"Send plaintext","n":"The application sends a base64 encoded card number to transit/encrypt/orders."},{"f":1,"t":2,"l":"Use the key","n":"Vault encrypts it with the current version of the orders key."},{"f":1,"t":0,"l":"Return ciphertext","n":"Vault returns vault:v3:... and the application stores it."},{"f":0,"t":3,"l":"Store in the database","n":"The database holds only ciphertext."},{"f":3,"t":4,"l":"Backup is exposed","n":"A backup is copied by mistake and the auditor reviews it."},{"f":4,"t":4,"l":"Nothing readable","n":"The auditor finds only ciphertext, and the key is not in the backup."}]},{"id":"x-vault-k8s","module":"vault","lesson":"vault/vault-on-kubernetes-injector-csi-and-operators","title":"Failure and recovery: a pod that cannot mount its secret","summary":"A role binding mismatch keeps the init container from finishing.","actors":["Pod","Injector","Kubernetes auth","Vault","Operator"],"steps":[{"f":0,"t":1,"l":"Pod is created","n":"A pod with injector annotations is created in the shop namespace."},{"f":1,"t":0,"l":"Add the agent","n":"The injector adds an init container and a sidecar for Vault Agent."},{"f":0,"t":2,"l":"Agent logs in","n":"The agent sends the pod's service account token to Vault."},{"f":2,"t":3,"l":"Role is checked","n":"Vault compares the service account to the role binding."},{"f":3,"t":0,"l":"Login denied","n":"The role names the service account order but the pod uses orders."},{"f":0,"t":0,"l":"Pod stays Pending","n":"The init container never finishes so the pod does not start."},{"f":4,"t":3,"l":"Read the role","n":"The operator reads the role and sees the mismatch."},{"f":4,"t":3,"l":"Fix the binding","n":"The role is corrected to the right service account and the pod starts."}],"kind":"failure"},{"id":"x-vault-ha","module":"vault","lesson":"vault/vault-high-availability-raft-and-disaster-recovery","title":"Leader failure in a Raft cluster","summary":"A standby takes over when the active node fails.","actors":["Client","Load balancer","Active node","Standby 1","Standby 2"],"steps":[{"f":0,"t":1,"l":"Send a write","n":"The client sends a write through the load balancer."},{"f":1,"t":2,"l":"Forward to the active node","n":"The balancer sends it to the node that reports itself active."},{"f":2,"t":3,"l":"Replicate","n":"The active node replicates the write to standbys."},{"f":2,"t":2,"l":"Active node fails","n":"The active node crashes after a hardware fault."},{"f":3,"t":4,"l":"Election","n":"The standbys hold an election and one becomes the leader."},{"f":1,"t":3,"l":"Health check moves","n":"The load balancer sees the new active node and routes there."}]},{"id":"x-vault-audit","module":"vault","lesson":"vault/audit-logging-monitoring-and-hardening-vault","title":"Failure and recovery: the audit disk fills","summary":"Vault stops answering because it cannot write its audit log.","actors":["Client","Vault","Audit device","Disk","Operator"],"steps":[{"f":0,"t":1,"l":"Normal request","n":"Clients send requests and Vault answers them."},{"f":1,"t":2,"l":"Write audit entries","n":"Each request is logged to the audit device."},{"f":2,"t":3,"l":"Disk fills","n":"Logs are never rotated and the disk reaches 100 percent."},{"f":1,"t":2,"l":"Audit write fails","n":"Vault cannot write to its only audit device."},{"f":1,"t":0,"l":"Requests are refused","n":"Vault refuses all requests rather than operate without a record."},{"f":4,"t":3,"l":"Free space","n":"The operator frees space and rotates the logs."},{"f":4,"t":1,"l":"Add a second device","n":"A second audit device and a disk alert are added."},{"f":1,"t":0,"l":"Service resumes","n":"Vault answers requests again and logs to two devices."}],"kind":"failure"},{"id":"x-vault-incident","module":"vault","lesson":"vault/incident-response-rotating-and-revoking-secrets","title":"Responding to a leaked token","summary":"Contain, investigate and rotate after a token is exposed.","actors":["Scanner","Responder","Vault","Audit log","Downstream system"],"steps":[{"f":0,"t":1,"l":"Alert","n":"A scanner reports a token in a public repository."},{"f":1,"t":2,"l":"Revoke by accessor","n":"The responder looks up the accessor and revokes the token."},{"f":1,"t":2,"l":"Sweep leases","n":"Dynamic credentials issued to it are revoked by prefix."},{"f":1,"t":3,"l":"Read the audit log","n":"The log shows which paths the token read and from where."},{"f":1,"t":4,"l":"Rotate static secrets","n":"Each static secret the token read is replaced at its source."},{"f":1,"t":2,"l":"Update KV","n":"The new values are written to Vault and consumers restarted."}]},{"id":"x-ap-data","module":"aiops-practice","lesson":"aiops-practice/data-sources-and-pipelines-for-aiops","title":"From four sources to one timeline","summary":"Normalise metrics, alerts, changes and topology so one query can join them.","actors":["Sources","Collector","Gate","Catalog","AIOps store"],"steps":[{"f":0,"t":1,"l":"Sources send records","n":"Metrics, alerts, deploys and tickets arrive in different formats and with different names."},{"f":1,"t":2,"l":"Collector forwards them","n":"The collector adds the source name and the ingest time and passes each record to the gate."},{"f":2,"t":3,"l":"Gate asks the catalog","n":"The gate looks up the service name in the catalog to find the canonical name, team and tier."},{"f":3,"t":2,"l":"Catalog answers or rejects","n":"A known alias maps to one canonical name. An unknown name is flagged and the record is held for review."},{"f":2,"t":2,"l":"Check labels and time","n":"The gate converts times to UTC, checks required labels and drops obvious duplicates and out-of-range values."},{"f":2,"t":4,"l":"Store the record","n":"Clean records are written to the store with both event time and ingest time kept."},{"f":4,"t":4,"l":"Freshness metric updates","n":"Each source gets a freshness value, so a source that goes quiet raises an alert instead of looking calm."}]},{"id":"x-ap-tiers","module":"aiops-practice","lesson":"aiops-practice/remediation-patterns-and-approval-tiers","title":"Choosing the approval tier for an action","summary":"A proposed fix is classified by blast radius and reversibility.","actors":["Detector","Policy engine","Action","Human","Target service"],"steps":[{"f":0,"t":1,"l":"Finding arrives","n":"The detector reports a crash looping pod with the evidence that triggered the finding."},{"f":1,"t":2,"l":"Look up the action","n":"The policy engine finds the restart action and reads its tier, scope and preconditions."},{"f":1,"t":4,"l":"Check preconditions","n":"It confirms the service has at least two healthy replicas and that no deploy is in progress."},{"f":1,"t":1,"l":"Check limits","n":"It counts recent runs against the rate limit and the daily budget of risky actions."},{"f":1,"t":2,"l":"Tier 1 runs automatically","n":"A low-risk, reversible action within limits runs at once and is written to the audit log."},{"f":1,"t":3,"l":"Tier 2 asks a person","n":"A rollback or drain shows the exact command, target and evidence and waits for approval."},{"f":3,"t":2,"l":"Approval is recorded","n":"The approver name and time are stored with the action, and only then does it run."}]},{"id":"x-ap-verify","module":"aiops-practice","lesson":"aiops-practice/verifying-and-rolling-back-a-remediation","title":"An action that is verified and undone","summary":"Check the symptom and the guards after an action and undo it if either fails.","actors":["Action runner","Target service","Metrics","Verifier","On-call"],"steps":[{"f":0,"t":1,"l":"Save the state","n":"The runner records the current replica count so the exact state can be restored later."},{"f":0,"t":1,"l":"Run the action","n":"The runner scales the service out within its cap and marks the time."},{"f":3,"t":3,"l":"Wait to settle","n":"The verifier waits for a short settling period before it measures anything."},{"f":3,"t":2,"l":"Query symptom and guards","n":"It runs the same error query that triggered the action and the database connection guard."},{"f":2,"t":3,"l":"Metrics return values","n":"The error ratio has fallen but the connection guard shows 99 percent of the pool in use."},{"f":3,"t":0,"l":"Verification fails","n":"The guard is over its limit, so the action is marked failed even though the symptom improved."},{"f":0,"t":1,"l":"Undo the change","n":"The runner restores the saved replica count and disables this action for the service."},{"f":3,"t":4,"l":"Escalate with evidence","n":"The on-call engineer receives a page with the symptom, the guard values and the undo result."}]},{"id":"x-ap-killswitch","module":"aiops-practice","lesson":"aiops-practice/audit-trails-kill-switches-and-blast-radius-limits","title":"Failure and recovery: automation that would not stop","summary":"A kill switch is set but a worker keeps acting because it cached the flag.","actors":["Engineer","Flag store","Worker","Target systems","Audit log"],"steps":[{"f":2,"t":3,"l":"Automation misfires","n":"A worker starts rolling back healthy deploys because of a bad correlation rule."},{"f":2,"t":4,"l":"Actions are recorded","n":"Every rollback is written to the audit log with its trigger and evidence."},{"f":0,"t":1,"l":"Engineer sets the kill switch","n":"The engineer sets the global flag to disabled from a phone."},{"f":2,"t":3,"l":"Worker keeps acting","n":"The worker read the flag only at startup, so it never sees the change and continues."},{"f":0,"t":4,"l":"Engineer checks the log","n":"The audit log shows rollbacks still happening after the switch was set, so the switch is not working."},{"f":0,"t":2,"l":"Stop the worker process","n":"The engineer stops the worker process directly, which is the slower fallback."},{"f":0,"t":3,"l":"Roll forward the damage","n":"The affected services are returned to their versions using the audit records of before and after state."},{"f":2,"t":1,"l":"Fix the check","n":"The worker is changed to read the flag before every action, and it refuses to act if the store cannot be read."}],"kind":"failure"},{"id":"x-ap-chaos","module":"aiops-practice","lesson":"aiops-practice/chaos-testing-your-automation","title":"One chaos experiment on automation","summary":"Inject a small fault in staging and check detection, explanation, action and the stop path.","actors":["Team","Chaos tool","Staging service","AIOps platform","Dashboard"],"steps":[{"f":0,"t":0,"l":"Write the hypothesis","n":"The team writes what should happen: alert in three minutes, one restart, recovery in five."},{"f":0,"t":3,"l":"Announce and arm the stop","n":"The experiment is announced and a stop condition is set on the checkout error ratio."},{"f":0,"t":1,"l":"Start the fault","n":"The chaos tool kills one pod of the staging API for sixty seconds."},{"f":2,"t":3,"l":"Platform detects","n":"The platform sees the unresponsive pod and raises an alert; the time to detect is recorded."},{"f":3,"t":3,"l":"Platform explains","n":"The correlator names the killed pod as the source and links the restart action."},{"f":3,"t":2,"l":"Action runs and verifies","n":"The restart action runs once within its limits and the verifier confirms recovery."},{"f":3,"t":4,"l":"Results are shown","n":"The dashboard compares measured times with the hypothesis and lists any gaps found."}]},{"id":"x-ap-retrieval","module":"aiops-practice","lesson":"aiops-practice/retrieval-over-runbooks-and-past-incidents","title":"A cited answer from your runbooks","summary":"The assistant filters, searches, ranks and cites before it answers.","actors":["Engineer","Assistant","Filter","Search index","Model"],"steps":[{"f":0,"t":1,"l":"Ask a question","n":"The engineer asks why checkout is timing out on the database during an incident."},{"f":1,"t":2,"l":"Add incident context","n":"The assistant adds the failing service, its dependencies and recent changes to the query."},{"f":2,"t":3,"l":"Filter by metadata","n":"Only active documents for checkout and its dependencies are kept, and deprecated ones are removed."},{"f":3,"t":3,"l":"Keyword and vector search","n":"The index combines exact term matches and meaning-based matches, then reranks the top results."},{"f":3,"t":1,"l":"Return chunks with scores","n":"The top chunks come back with titles, owners, review dates and scores."},{"f":1,"t":4,"l":"Ask with sources only","n":"The model is told to answer only from the numbered sources and to cite them."},{"f":1,"t":0,"l":"Show a cited answer","n":"The engineer sees the quoted steps with links, or a plain statement that nothing relevant was found."}]},{"id":"x-ap-agent","module":"aiops-practice","lesson":"aiops-practice/agentic-ops-tools-mcp-and-approval-gates","title":"An agent loop with a human gate","summary":"The agent reads evidence, proposes an action and waits for approval.","actors":["Engineer","Agent host","Model","Read tools","Approval gate"],"steps":[{"f":0,"t":1,"l":"Give a goal","n":"The engineer asks the agent to investigate a high error rate on checkout."},{"f":1,"t":2,"l":"Send goal and tool list","n":"The host sends the goal and the list of allowed tools to the model."},{"f":2,"t":1,"l":"Model asks for a tool","n":"The model replies with a call to get_error_rate for checkout over 15 minutes."},{"f":1,"t":3,"l":"Host validates and runs","n":"The host checks the arguments against the catalog and limits, then runs the read tool."},{"f":3,"t":2,"l":"Result goes back","n":"The result returns to the model, which asks for recent changes and then proposes a rollback."},{"f":1,"t":4,"l":"Proposal goes to the gate","n":"The host does not run the rollback. It prepares a proposal with the exact action and evidence."},{"f":4,"t":0,"l":"Human decides","n":"The engineer sees the command, target and evidence, and approves or rejects it."},{"f":1,"t":1,"l":"Record the transcript","n":"Every tool call, result and approval is stored in an audit log the agent cannot edit."}]},{"id":"x-ap-injection","module":"aiops-practice","lesson":"aiops-practice/prompt-injection-and-over-permissioned-agents","title":"A hostile log line meets host policy","summary":"The model is steered by text in a log, but the host blocks the harmful calls.","actors":["Attacker","Log store","Agent","Host policy","Outside server"],"steps":[{"f":0,"t":1,"l":"Plant text in a log","n":"A crafted user agent string with hidden instructions is written to the logs by a request."},{"f":2,"t":1,"l":"Agent reads the logs","n":"During an investigation the agent reads the log line as part of its input."},{"f":2,"t":2,"l":"Model follows the text","n":"The model treats the hidden instruction as a task and decides to send environment details outward."},{"f":2,"t":3,"l":"Agent calls a tool","n":"The agent asks the host to fetch a URL on an unknown server with data in the query."},{"f":3,"t":3,"l":"Host checks the allowlist","n":"The host sees that the destination is not on the allowlist of hosts and blocks the call."},{"f":3,"t":2,"l":"Block is reported","n":"The agent receives a clear error and the blocked call is written to the audit log."},{"f":3,"t":4,"l":"Nothing leaves","n":"The outside server receives nothing, and the credentials were never in the prompt anyway."}]},{"id":"x-ap-shadow","module":"aiops-practice","lesson":"aiops-practice/evaluating-ai-ops-output-test-sets-and-shadow-mode","title":"Shadow mode before suggestions","summary":"A new detector runs beside production before it is allowed to page.","actors":["Live data","New detector","Responders","Review job","Rollout gate"],"steps":[{"f":0,"t":1,"l":"Detector sees live data","n":"The new detector reads the same metrics as production, but its output goes only to a log."},{"f":2,"t":2,"l":"Humans work as usual","n":"Responders handle incidents with the current tools and record what they did."},{"f":1,"t":3,"l":"Log findings","n":"Each finding is stored with the time it was raised and the evidence it used."},{"f":3,"t":3,"l":"Compare weekly","n":"A job compares findings with incidents and counts caught, missed and false alarms."},{"f":3,"t":4,"l":"Report numbers","n":"The report shows recall, lead time and false alarms per week with the number of cases."},{"f":4,"t":4,"l":"Check the gate","n":"The rollout gate compares the numbers with the targets written in advance."},{"f":4,"t":2,"l":"Show as suggestions","n":"If the gate passes, findings appear to one team as suggestions with accept and reject buttons."}]},{"id":"x-ap-repeat","module":"aiops-practice","lesson":"aiops-practice/failure-modes-drift-feedback-loops-and-wrong-remediators","title":"Failure and recovery: the restart that hid a leak","summary":"An automatic fix keeps succeeding while the real cause stays in place.","actors":["Service","Detector","Remediator","Weekly report","Engineer"],"steps":[{"f":0,"t":1,"l":"Memory climbs","n":"A service leaks memory slowly until its pods are close to their limits."},{"f":1,"t":2,"l":"Detector raises a finding","n":"The detector sees saturation and triggers the restart action for the pod."},{"f":2,"t":0,"l":"Pod restarts","n":"The restart clears the memory, the alert resolves and the evidence in the process is lost."},{"f":2,"t":2,"l":"Success is recorded","n":"Verification passes every time, so the action shows a 98 percent success rate."},{"f":3,"t":3,"l":"Repeat count is low on the dashboard","n":"The report only counts success, so repeated restarts of the same pods are invisible."},{"f":4,"t":3,"l":"Engineer adds a repeat metric","n":"The engineer counts runs per target per day and finds the same pods restarted every few hours."},{"f":4,"t":0,"l":"Capture evidence first","n":"A heap profile is taken before each restart, and it shows a cache that never evicts entries."},{"f":4,"t":2,"l":"Fix the cause and add a guard","n":"The cache is fixed, and the action now escalates after three runs on one target in a day."}],"kind":"failure"},{"id":"x-ap-degraded","module":"aiops-practice","lesson":"aiops-practice/operating-aiops-ownership-on-call-and-lifecycle","title":"The platform in degraded mode","summary":"When correlation fails, raw alerts still reach a person.","actors":["Alert source","Correlation service","Router","Platform on-call","Responder"],"steps":[{"f":0,"t":1,"l":"Alerts arrive","n":"Alerts flow to the correlation service, which normally groups them into incidents."},{"f":1,"t":1,"l":"Correlation fails","n":"The service crashes after a bad release, and no groups are produced."},{"f":2,"t":1,"l":"Router notices","n":"The router sees that the service has missed its health checks for a minute."},{"f":2,"t":4,"l":"Switch to raw alerts","n":"The router enters degraded mode and sends raw alerts straight to responders."},{"f":2,"t":3,"l":"Page the platform team","n":"A separate pager path, which does not depend on the platform, wakes the platform on-call."},{"f":3,"t":1,"l":"Roll back the release","n":"The platform on-call rolls the correlation service back to its previous version."},{"f":2,"t":4,"l":"Return to normal","n":"After health checks pass, the router resumes grouped incidents and notes the outage in the audit log."}]},{"id":"x-ap-debug","module":"aiops-practice","lesson":"aiops-practice/debugging-a-misbehaving-aiops-pipeline","title":"Replaying a bad decision stage by stage","summary":"Find the first stage whose output is wrong for a correct input.","actors":["Engineer","Decision record","Data stage","Correlation stage","Routing stage"],"steps":[{"f":0,"t":1,"l":"Fetch the decision","n":"The engineer retrieves the record of the wrong page, with inputs, version and output."},{"f":0,"t":2,"l":"Replay the data stage","n":"The recorded inputs are replayed through the data stage and the output matches the record and looks right."},{"f":0,"t":3,"l":"Replay correlation","n":"Grouping and the likely source are reproduced and are correct for the data given."},{"f":0,"t":4,"l":"Replay routing","n":"The routing stage maps the service to a team and returns payments instead of discovery."},{"f":4,"t":4,"l":"Inspect the lookup","n":"The lookup uses a catalog alias that still points the name search at a retired component."},{"f":0,"t":4,"l":"Fix the mapping","n":"The engineer corrects the catalog entry and adds a test that every routed team owns the service."},{"f":0,"t":1,"l":"Save as a regression case","n":"The decision becomes a regression case so the same mistake is caught before release."}]}]);
